export const VOLUMES = {"vol1":{"volume_id":"vol1","index":1,"title":"光影圣殿","subtitle":"七大美德与七宗原罪","theme_color":"#8C4A32","estimated_minutes":5,"intro":"这里不审判欲望。七宗原罪是失控的驱力，七大美德是清醒的秩序——同一种能量，只差一个阀门。请凭真实的第一感受作答，不必挑选「更好的自己」。","dimensions":["sin_pride","virtue_humility","sin_greed","virtue_charity","sin_lust","virtue_chastity","sin_envy","virtue_kindness","sin_gluttony","virtue_temperance","sin_wrath","virtue_patience","sin_sloth","virtue_diligence"],"questions":[{"id":"v1_q01","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"pride_humility","is_sensitive":true,"weight":1.1,"prompt":"一桌人已经第三次绕回同一个话题，谁也说服不了谁，而你早就看清分歧卡在哪里。此刻你更像——","scale":{"left":"把话讲透，哪怕要重复三遍","right":"礼貌点头，把力气留给别处","sdHigh":"right"},"effects":{"sin_pride":[-2,2],"virtue_humility":[2,-2],"big5_assert":[1.4,-1],"cog_independent":[0.6,1.2]},"context":""},{"id":"v1_q02","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"pride_humility","is_sensitive":true,"weight":1.4,"prompt":"如果可以提前选定一种人生结局，你更愿意承受哪一种？","options":[{"key":"A","text":"被身边所有人真心喜欢，但在他们眼中你始终只是「一个很好的人」","effects":{"sin_pride":-2,"virtue_humility":1.5,"mot_belonging":1.6,"dark_narc":-1.2},"social_desirability":2},{"key":"B","text":"被少数真正懂行的人高度敬畏，但你常年独自待在无人打扰的高处","effects":{"sin_pride":2,"virtue_humility":-1.5,"mot_belonging":-1.6,"dark_narc":1.2},"social_desirability":0}]},{"id":"v1_q03","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"wrath_patience","is_sensitive":true,"weight":1.3,"context":"你们几个业余凑起来的乐队排了三个月，你把整首歌的编曲重做了一版。排练时主唱听完，只回了一句：「这个方向是不是有点太想当然了。」","prompt":"听到这句话的头三秒，你身体里最先冒出来的东西是——","options":[{"key":"A","text":"一句已经到嘴边的话，措辞挑得很准，能让他在下次排练时不太好受","effects":{"sin_wrath":2,"virtue_patience":-1.6,"def_attack":1.4,"big5_rumination":0.6},"social_desirability":0},{"key":"B","text":"胸口一沉，先怀疑是不是自己确实没接住这首歌要的东西","effects":{"sin_wrath":-1,"virtue_patience":1,"big5_rumination":1.8,"def_fawn":0.8},"social_desirability":1},{"key":"C","text":"一阵很凉的笑意，同时已经在心里把这个合作重新归了一次类","effects":{"sin_wrath":1.2,"virtue_patience":0.4,"dark_psycho":1.4,"def_detach":1.2},"social_desirability":0},{"key":"D","text":"想先把吉他放下，去阳台站一会儿，等这阵劲儿过去再回来看","effects":{"sin_wrath":-1.8,"virtue_patience":1.8,"def_sublimate":1,"big5_rumination":-0.8},"social_desirability":3}]},{"id":"v1_q04","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"greed_charity","is_sensitive":true,"weight":1.4,"prompt":"手头的储备已经够体面地活上两年。此时有一笔额外的、并不影响生活的收入到账，你更接近哪种反应？","options":[{"key":"A","text":"心里那根弦先松了一下，随即开始盘算它还该变成什么别的形态","effects":{"sin_greed":2,"virtue_charity":-1.2,"mot_security":1.6,"mot_mastery":0.8},"social_desirability":0},{"key":"B","text":"很自然地把其中一部分挪给最近正需要的人或事，不太需要下决心","effects":{"sin_greed":-1.6,"virtue_charity":2,"light_humanism":1.2,"mot_belonging":0.6},"social_desirability":3},{"key":"C","text":"先不动它，让它在账上静静待着，看看自己会不会真的需要它","effects":{"sin_greed":0.6,"virtue_charity":0.4,"mot_security":1,"cog_ambiguity":0.8},"social_desirability":1},{"key":"D","text":"立刻想到一个一直想试却没舍得的花法，先犒赏一下这几个月的辛苦","effects":{"sin_greed":-0.6,"virtue_charity":0,"mot_hedonism":1.8,"virtue_temperance":-0.8},"social_desirability":1}]},{"id":"v1_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"lust_chastity","is_sensitive":true,"weight":0.85,"prompt":"凌晨一点，你刷到一段极对胃口的内容，明天上午有一个不能迟到的会。你通常——","scale":{"left":"给自己划一条线，看完这一段就关","right":"顺着那股劲儿滑下去，几点睡交给身体决定","sdHigh":"left"},"effects":{"sin_lust":[-2,2],"virtue_chastity":[2,-2],"virtue_temperance":[1.4,-1.4],"mot_hedonism":[-1,1.6]}},{"id":"v1_q06","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"envy_kindness","is_sensitive":true,"weight":1.4,"context":"一个和你同时入行、起点几乎一样的朋友突然拿到了你一直想要的那个机会。他在朋友圈发了张很克制的照片，配文只有两个字：谢谢。","prompt":"你刷到这条动态时，脑子里最先自动跑起来的判断是——","options":[{"key":"A","text":"这波里运气的权重到底占了多少，换成我是不是也能接到","effects":{"sin_envy":1.8,"virtue_kindness":-1,"mot_mastery":1.2,"cog_logic":0.6},"social_desirability":0},{"key":"B","text":"他这一年确实在某些我看不见的地方下了苦功，值得","effects":{"sin_envy":-1.6,"virtue_kindness":1.8,"light_humanism":1,"big5_compassion":0.8},"social_desirability":3},{"key":"C","text":"先替他高兴三秒，然后立刻点开自己的待办清单找到该补的那块","effects":{"sin_envy":0.4,"virtue_kindness":1.2,"mot_mastery":1.6,"def_sublimate":1.2},"social_desirability":2},{"key":"D","text":"把手机扣过去，不太想让这条消息继续待在视线里","effects":{"sin_envy":1.2,"virtue_kindness":-0.4,"big5_rumination":1.4,"def_detach":0.8},"social_desirability":1}]},{"id":"v1_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"gluttony_temperance","is_sensitive":true,"weight":0.85,"prompt":"一个没什么特别原因的疲惫夜晚，你的手通常会伸向——","scale":{"left":"一杯热水，然后早点把自己放倒","right":"外卖、购物车或者短视频，总要吃点什么才睡得着","sdHigh":"left"},"effects":{"sin_gluttony":[-2,2],"virtue_temperance":[2,-2],"mot_hedonism":[-1.2,1.6],"big5_rumination":[-0.8,1.2]}},{"id":"v1_q08","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"wrath_patience","is_sensitive":true,"weight":1.25,"context":"家族聚会上，你妈替你把最近两年的事讲了一遍——工作、房子、身体，讲得比你自己清楚，也比你自己乐观。亲戚们一边点头一边看你。","prompt":"那一瞬间，你脑子里最先闪过的念头是——","options":[{"key":"A","text":"等她说完，我要用一句很轻的话把这件事的版本拿回来","effects":{"sin_wrath":1.6,"virtue_patience":-1,"def_attack":1.6,"big5_assert":1.4},"social_desirability":0},{"key":"B","text":"算了，她开心就行，为这个开口显得很小气，也扫兴","effects":{"sin_wrath":-1.4,"virtue_patience":1.4,"def_fawn":1.4,"big5_compliance":1.6},"social_desirability":2},{"key":"C","text":"记住这个场面，以后所有需要她出面的事，我都会多留一手","effects":{"sin_wrath":0.8,"virtue_patience":0.2,"dark_mach":1.8,"covert_control":1.2},"social_desirability":0},{"key":"D","text":"一阵发闷，想立刻借口下楼走走，离开这个客厅","effects":{"sin_wrath":-0.4,"virtue_patience":0.6,"def_detach":1.6,"big5_rumination":1.4},"social_desirability":1}]},{"id":"v1_q09","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"sloth_diligence","is_sensitive":true,"weight":1.4,"prompt":"你决定用三个月时间把一件长期拖着的私事彻底办完——学一门语言、修好一段身体、整理完父母的老房子。第一周很顺，第二周开始就没有任何反馈了。你最真实的反应是——","options":[{"key":"A","text":"把它拆成很小的日常动作，靠机制的稳定运转把自己带过去","effects":{"sin_sloth":-2,"virtue_diligence":2,"big5_order":1.4,"big5_industry":1.4},"social_desirability":3},{"key":"B","text":"先想办法把那 20% 真正决定结果的部分挑出来，其余尽量简省","effects":{"sin_sloth":1,"virtue_diligence":0.6,"cog_global":1.4,"dark_mach":0.6},"social_desirability":1},{"key":"C","text":"进度开始频繁停滞，越拖越不想打开它，晚上又会为此睡不好","effects":{"sin_sloth":1.8,"virtue_diligence":-1.8,"big5_rumination":1.4,"big5_industry":-1.2},"social_desirability":0},{"key":"D","text":"先找一个人一起做，靠对外承诺和别人的节奏把自己拴住","effects":{"sin_sloth":-0.4,"virtue_diligence":1,"mot_belonging":1.2,"big5_social":0.8},"social_desirability":2}]},{"id":"v1_q10","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"pride_humility","is_sensitive":true,"weight":1.4,"context":"老周做了八年木工，是这一带公认手艺最好的师傅。上周他带的一个学徒在几个老主顾面前，指出他一张椅子上的榫眼打歪了，而且说得对。","prompt":"你猜老周接下来最可能的样子是——","options":[{"key":"A","text":"当场认下这条，把榫眼重新开一遍，但那天之后话少了很多","effects":{"sin_pride":-2,"virtue_humility":2,"big5_open":1,"light_humanism":0.8},"social_desirability":3},{"key":"B","text":"表面平静地接住，心里那一下很难受，会反复回放这个场面","effects":{"sin_pride":1,"virtue_humility":0,"big5_rumination":1.6,"dark_narc":0.8},"social_desirability":1},{"key":"C","text":"先接住，但很快用一句更全面的判断把话语权重新收回自己手里","effects":{"sin_pride":1.6,"virtue_humility":-0.8,"big5_assert":1.4,"covert_control":1},"social_desirability":0},{"key":"D","text":"嘴上说没关系，之后下意识地减少和这个年轻人单独搭手的机会","effects":{"sin_pride":1.4,"virtue_humility":-1.6,"dark_mach":1.2,"def_project":1},"social_desirability":0}]},{"id":"v1_q11","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"greed_charity","is_sensitive":false,"weight":1.4,"prompt":"以下两种「做得对」，哪一种更贴近你愿意付出的代价？","options":[{"key":"A","text":"把一个只对自己有效的机会，分一半给更需要它的人","effects":{"sin_greed":-1.6,"virtue_charity":1.8,"light_humanism":1.4,"mot_belonging":1},"social_desirability":3},{"key":"B","text":"先把机会稳稳拿到手，等自己站住了再回头拉别人一把","effects":{"sin_greed":1.6,"virtue_charity":-0.6,"mot_mastery":1.6,"mot_security":1.2},"social_desirability":1}]},{"id":"v1_q12","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"envy_kindness","is_sensitive":true,"weight":0.85,"prompt":"一位关系不错的朋友，拿到了你暗暗努力了很多年也没拿到的东西。你为他高兴的那部分，大概占多少？","scale":{"left":"几乎全部，那点酸我一秒就压下去了","right":"有，但不多，剩下大部分是说不清的堵","sdHigh":"left"},"effects":{"sin_envy":[-2,2],"virtue_kindness":[2,-2],"big5_compassion":[1.2,-1],"def_project":[-0.8,1]}},{"id":"v1_q13","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"lust_chastity","is_sensitive":true,"weight":1.25,"context":"凌晨十二点四十，一条本来只想看一眼的消息，把你带进了一个很容易上头的话题。手机屏幕的光落在天花板上。","prompt":"这一刻你身体里最诚实的反应是——","options":[{"key":"A","text":"整个人被点着了，睡意瞬间消失，想继续往下走","effects":{"sin_lust":2,"virtue_chastity":-1.6,"mot_hedonism":1.8,"virtue_temperance":-1.2},"social_desirability":0},{"key":"B","text":"有一瞬间的冲动，然后把它当成一个信号记下来就睡了","effects":{"sin_lust":0.2,"virtue_chastity":1,"virtue_temperance":1.2,"cog_logic":0.8},"social_desirability":2},{"key":"C","text":"已经很累，但还是继续滑，像是在借这点刺激撑住自己","effects":{"sin_lust":1.4,"virtue_chastity":-0.8,"sin_gluttony":1.2,"big5_rumination":1.2},"social_desirability":0},{"key":"D","text":"把手机翻过去，替自己按下一个明确的结束键","effects":{"sin_lust":-1.6,"virtue_chastity":1.8,"virtue_temperance":1.6,"big5_order":0.8},"social_desirability":3}]},{"id":"v1_q14","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"gluttony_temperance","is_sensitive":false,"weight":1.4,"prompt":"连续加班两周后的第一个完整休息日，你更可能怎么过？","options":[{"key":"A","text":"把攒了两周的馋和懒一次性兑现，吃到撑，然后什么都不干","effects":{"sin_gluttony":1.8,"virtue_temperance":-1.6,"mot_hedonism":1.8,"big5_order":-1},"social_desirability":0},{"key":"B","text":"补觉、散步、做顿饭，把身体的节奏一点点调回来","effects":{"sin_gluttony":-1.4,"virtue_temperance":1.8,"big5_order":1.2,"big5_alert":0.6},"social_desirability":3},{"key":"C","text":"立刻安排一件新鲜的、没试过的事，不想让这天被浪费","effects":{"sin_gluttony":0.4,"virtue_temperance":0.2,"mot_hedonism":1.4,"big5_open":1.6},"social_desirability":1},{"key":"D","text":"照常打开电脑，休息日和工作日在我这没什么本质区别","effects":{"sin_gluttony":-1,"virtue_temperance":0.8,"virtue_diligence":1.6,"big5_industry":1.4},"social_desirability":2}]},{"id":"v1_q15","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"wrath_patience","is_sensitive":true,"weight":0.85,"prompt":"一个曾经让你很难堪的人，两年后在一次饭局上跟你笑着敬酒，像什么都没发生过。你心里的那条账——","scale":{"left":"早就翻篇了，人是会变的","right":"还留着，只是不再需要他为它付什么","sdHigh":"left"},"effects":{"sin_wrath":[-2,2],"virtue_patience":[2,-2],"def_detach":[-1,1],"big5_rumination":[-1.2,1.2]}},{"id":"v1_q16","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"sloth_diligence","is_sensitive":false,"weight":1.4,"prompt":"一个没有任何人期待你产出结果的周末，你更担心发生哪种情况？","options":[{"key":"A","text":"两天就这么过去了，回想起来一片空白，什么都没留下","effects":{"sin_sloth":-1.2,"virtue_diligence":1.6,"big5_industry":1.4,"big5_order":0.8},"social_desirability":2},{"key":"B","text":"又把自己排满，连休息都变成一项需要交付的任务","effects":{"sin_sloth":0.8,"virtue_diligence":0.6,"big5_order":1.6,"big5_alert":1},"social_desirability":1},{"key":"C","text":"被一种「该做点正事」的愧疚追着，最后什么也没做成","effects":{"sin_sloth":1.6,"virtue_diligence":-1,"big5_rumination":1.6,"def_fawn":0.6},"social_desirability":0}]},{"id":"v1_q17","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"greed_charity","is_sensitive":true,"weight":1.4,"context":"大学时和你成绩、家境都差不多的室友，昨天发了一张新房钥匙的照片，配文只有「小目标达成，感谢好运」。你们上一次聊天是半年前。","prompt":"你猜他按下发送键之前，心里最真实的那一层是——","options":[{"key":"A","text":"终于可以发这一条了。这一步我等太久，也该让一些人看看。","effects":{"sin_greed":1.8,"virtue_charity":-0.8,"sin_pride":1.2,"mot_mastery":1.4},"social_desirability":0},{"key":"B","text":"犹豫了很久，怕看起来像在炫耀，删掉又重写了一遍。","effects":{"sin_greed":0.4,"virtue_charity":1.2,"big5_alert":1.4,"mot_belonging":1.2},"social_desirability":3},{"key":"C","text":"这些年的代价只有自己知道，发出来算是给自己一个交代。","effects":{"sin_greed":-1.6,"virtue_charity":1.8,"light_humanism":1.2,"lv_anchor":1.2},"social_desirability":2},{"key":"D","text":"他根本没想那么多，就是随手拍了张照，发给最熟的那几个人看","effects":{"sin_greed":1.4,"virtue_charity":-1.2,"dark_narc":1.6,"big5_social":0.8},"social_desirability":1}]},{"id":"v1_q18","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"sloth_diligence","is_sensitive":false,"weight":0.85,"prompt":"一项没有人会检查、也不影响任何评价的收尾工作摆在面前。你的实际状态是——","scale":{"left":"还是按标准做完，我自己知道它够不够好","right":"做到能跑通就收手，剩下的力气留给真正被看见的事","sdHigh":"left"},"effects":{"sin_sloth":[-2,2],"virtue_diligence":[2,-2],"big5_industry":[1.6,-1.4],"light_kant":[1,-0.8]}},{"id":"v1_q19","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"envy_kindness","is_sensitive":true,"weight":1.2,"context":"你妈在电话里顺口提了一句：隔壁和你从小一起长大的那个，今年升了，家里已经张罗着请客了。","prompt":"挂掉电话之后，心里最真实的那一下是——","options":[{"key":"A","text":"一阵很具体的酸，手心有点发凉，然后才回过神去说一句恭喜","effects":{"sin_envy":2,"virtue_kindness":-1,"big5_rumination":1.2,"mot_mastery":1.4},"social_desirability":0},{"key":"B","text":"真心替他高兴，但也忍不住开始想他这几年到底做对了哪几件事","effects":{"sin_envy":-1.8,"virtue_kindness":1.8,"big5_open":1,"mot_mastery":0.8},"social_desirability":3},{"key":"C","text":"先判断了一下这件事对我妈接下来会怎么说有什么影响，情绪很淡","effects":{"sin_envy":-0.4,"virtue_kindness":0.2,"dark_psycho":1,"cog_logic":1.4},"social_desirability":1},{"key":"D","text":"忽然不太想再聊下去，想找个安静的地方一个人待一会儿","effects":{"sin_envy":0.8,"virtue_kindness":-0.2,"def_detach":1.4,"att_avoidance":1},"social_desirability":1}]},{"id":"v1_q20","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"lust_chastity","is_sensitive":true,"weight":1.4,"context":"一个报酬高得离谱的机会找上门，代价是要长期游走在规则边缘，出事的概率不高，但一旦出事无法回头。","prompt":"你更接近哪种处理方式？","options":[{"key":"A","text":"先算清楚最坏结果，只要那个结果我能兜住，就可以谈","effects":{"sin_lust":1.2,"virtue_chastity":-0.6,"dark_psycho":1.8,"big5_alert":-0.4},"social_desirability":0},{"key":"B","text":"几乎不用想就拒了，脏钱会让之后所有的日子都变轻","effects":{"sin_lust":-1.8,"virtue_chastity":1.8,"light_kant":1.8,"val_moral":1.2},"social_desirability":3},{"key":"C","text":"会认真谈一次，把边界明确写清楚，能切干净就做一部分","effects":{"sin_lust":0.4,"virtue_chastity":0.8,"cog_ambiguity":1,"dark_mach":1.4},"social_desirability":2},{"key":"D","text":"先接下来，真到了那一步再决定要不要踩过去","effects":{"sin_lust":1.8,"virtue_chastity":-1.6,"cog_speed":1.4,"val_moral":-1.2},"social_desirability":0}]},{"id":"v1_q21","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"gluttony_temperance","is_sensitive":true,"weight":0.85,"prompt":"回想那些「明明知道该停却没停」的时刻，它们更多出现在——","scale":{"left":"很少，我的刹车基本都在线","right":"白天越是被安排，夜里越容易报复性地不肯睡","sdHigh":"left"},"effects":{"sin_gluttony":[-2,2],"virtue_temperance":[2,-2],"def_fawn":[-1,1.2],"mot_autonomy":[-0.8,1.4]}},{"id":"v1_q22","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"pride_humility","is_sensitive":true,"weight":1.4,"context":"你花了三个月做的东西，被一个外行用非常外行的话公开否定，而且他很有影响力，场面安静了两秒。","prompt":"这两秒钟里，你最想守住的其实是——","options":[{"key":"A","text":"把道理讲到所有人都听懂，让那句否定当场站不住脚","effects":{"sin_pride":1.8,"virtue_humility":-1.4,"big5_assert":1.6,"def_attack":1},"social_desirability":0},{"key":"B","text":"不急着争，先问清他到底在担心什么，也许里面真有一句对的","effects":{"sin_pride":-1.8,"virtue_humility":1.8,"big5_open":1.2,"big5_compliance":1},"social_desirability":3},{"key":"C","text":"表面的体面，笑一下把场面接过去，之后单独找他用结果说话","effects":{"sin_pride":0.8,"virtue_humility":0.4,"covert_control":1.6,"dark_mach":1.4},"social_desirability":2},{"key":"D","text":"自己的判断，即使没人支持，我也知道这东西的分量在哪","effects":{"sin_pride":1.2,"virtue_humility":0.2,"cog_independent":1.8,"mot_autonomy":1},"social_desirability":1}]}]},"vol10":{"volume_id":"vol10","index":10,"title":"秩序与混沌","subtitle":"D&D 九宫格阵营与十二叙事原型底色","theme_color":"#7A4B3A","estimated_minutes":4,"intro":"这一卷不设道德评分表。它只问一件事：当没有摄像头、没有旁人、也看不见后果的时候，你相信什么在维持这个世界——是白纸黑字的规矩，还是此刻站在你面前的这个人。两种答案都有代价，也都有尊严。","dimensions":["dd_order","dd_good"],"questions":[{"id":"v10_q01","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"alignment_order","is_sensitive":false,"weight":1.4,"context":"雨夜十一点，城郊那条直路上一个摄像头都没有。前方路口亮着红灯，五百米内看不到一辆车、一个人。一个外卖骑手从你身边绕过去闯了灯，水花溅了你一裤腿。","prompt":"绿灯还要等四十秒，你站在原地。此刻你更接近哪一种做法？","options":[{"key":"A","text":"快步跟过去，扶住那辆歪在雨里的电动车，帮他把汤码回去。","effects":{"dd_order":-1.4,"dd_good":1.7,"wv_social":0.9},"social_desirability":2},{"key":"B","text":"左右看完确实没车就走过去。灯是用来防碰撞的，此刻这条路上没有碰撞。","effects":{"dd_order":-1.8,"dd_good":-1.2,"cog_independent":1.1},"social_desirability":1},{"key":"C","text":"等完这四十秒。规则不是给摄像头看的，没人盯着的时候，它才真的算数。","effects":{"dd_order":1.9,"dd_good":1.2,"light_kant":1},"social_desirability":2},{"key":"D","text":"照样等，但拍下车牌回家提一单——这条规矩对每个人都该一样重。","effects":{"dd_order":1.7,"dd_good":-1.2,"big5_assert":0.9},"social_desirability":1}]},{"id":"v10_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"alignment_good","is_sensitive":true,"weight":0.85,"prompt":"菜市场收摊前，摊主一边跟隔壁聊天一边给你找钱，多找了二十块。你拎着菜走出去十几米，低头才发现。","scale":{"left":"转身走回去，把那二十块放回秤台边","right":"接着走。这是他自己算错，不是我伸手拿的","sdHigh":"left"},"effects":{"dd_good":[1.8,-1.6],"dd_order":[1.3,-1.2],"val_moral":[1.2,-1],"sin_greed":[-0.9,1.1]}},{"id":"v10_q03","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"alignment_good","is_sensitive":true,"weight":1.4,"context":"你的一位老朋友失业三个月了，一直没跟家里说。今晚他带你去他女朋友家吃饭，饭桌上她随口说起他最近总加班到很晚，他笑着点头。","prompt":"桌下他的膝盖轻轻碰了碰你。你接下来那句话会往哪边走？","options":[{"key":"A","text":"顺着他的话编圆，回头把这事记下来——下次他开口借钱，我有依据。","effects":{"dd_order":-1.2,"dd_good":-1.2,"dark_mach":1.1},"social_desirability":0},{"key":"B","text":"顺着他说下去。这是他的事，什么时候说是他的权利，我只负责不当场拆台。","effects":{"dd_order":-1.5,"dd_good":1.8,"mot_belonging":1},"social_desirability":1},{"key":"C","text":"照实说一句「他最近没上班，具体你问他」，剩下的交给他自己。","effects":{"dd_order":1.9,"dd_good":-1.3,"light_kant":1.1},"social_desirability":2},{"key":"D","text":"把话岔开，聊点别的。我没有撒谎，也不替他决定哪一天该开口。","effects":{"dd_order":1.3,"dd_good":1.4,"cog_ambiguity":1},"social_desirability":3}]},{"id":"v10_q04","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"alignment_good","is_sensitive":true,"weight":1.3,"context":"晚高峰的地铁站台，一个男人因为裤脚被拖把碰到，对着保洁阿姨越说越大声，手指几乎戳到她脸上。周围人都低头看手机。","prompt":"你离他们只有三步，第一秒身体先做出的是——","options":[{"key":"A","text":"走过去站到阿姨侧前半步，一句话不说，就那么平视着他。","effects":{"dd_order":1.2,"dd_good":1.9,"big5_assert":1.1},"social_desirability":3},{"key":"B","text":"先录下来再叫站台工作人员——没记录的事，最后就是各说各话。","effects":{"dd_order":1.9,"dd_good":-1.2,"big5_compliance":0.9},"social_desirability":2},{"key":"C","text":"心里一紧，但把耳机音量调大，加快脚步走进车门。","effects":{"dd_order":-1.2,"dd_good":-1.5,"def_detach":1.1},"social_desirability":1},{"key":"D","text":"直接开口：「人家拖地，你的鞋挡着道了」，语气比他还冲。","effects":{"dd_order":-1.3,"dd_good":1.3,"sin_wrath":1.2},"social_desirability":0}]},{"id":"v10_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"alignment_order","is_sensitive":true,"weight":0.85,"prompt":"老房子的拆迁意向书下来了。家族群里，几位长辈已经商量好怎么分，没人问过一直住在里面照顾奶奶的那个人。轮到你表态时，你心里最想做的更接近——","scale":{"left":"顺着大家的意思，「你们定就好，我没什么意见」","right":"把话挑明：「这七年是谁在照顾，得先听我说完」","sdHigh":"left"},"effects":{"dd_order":[1.6,-1.4],"dd_good":[-1.4,1.6],"big5_compliance":[1.2,-1],"mot_autonomy":[-1,1.2]}},{"id":"v10_q06","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"alignment_order","is_sensitive":true,"weight":1.4,"context":"公司内网的考勤系统有个谁都知道、也没人修的漏洞：补卡申请可以自己审批。这个月你迟到过三次，其中两次确实是自己的问题，扣的钱不算少。","prompt":"页面上那个「自己批自己」的按钮，你会按下它吗？","options":[{"key":"A","text":"三次全补。这套制度本来就没打算跟人讲道理，能过就过。","effects":{"dd_order":-1.9,"dd_good":-1.5,"sin_greed":1},"social_desirability":0},{"key":"B","text":"关掉页面，走正常的补卡流程，批不批由组长自己判断。","effects":{"dd_order":1.9,"dd_good":1.3,"light_kant":1},"social_desirability":2},{"key":"C","text":"照扣，然后把三次截图发给组长，请全组按同一套标准来。","effects":{"dd_order":1.9,"dd_good":-1.2,"val_standard":1},"social_desirability":1},{"key":"D","text":"三次都补，然后把入口告诉全组——凭什么只有我一个人知道。","effects":{"dd_order":-1.2,"dd_good":1.2,"mot_belonging":0.9},"social_desirability":1}]},{"id":"v10_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"alignment_order","is_sensitive":true,"weight":0.85,"prompt":"你和朋友合伙买了台三万多的机器接私活。三个月后他说不做了，设备留给你，那半年的钱「就当帮兄弟一把」。你看着那台还在折旧的机器——","scale":{"left":"「行，机器我留着，钱的事算了」，就当交了一次学费","right":"把账摊开：「按市价折旧折一半，这个数我们今天说清楚」","sdHigh":"left"},"effects":{"dd_order":[-1.5,1.4],"dd_good":[1.2,-1.3],"light_kant":[-1,0.9],"def_detach":[1.1,-0.8]}},{"id":"v10_q08","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"alignment_good","is_sensitive":true,"weight":1.25,"context":"凌晨两点，你下楼扔垃圾，看见一个男人蹲在楼下的电动车旁，手里捏着一截铁片，车锁已经撬开一半，车灯在暗处闪着。","prompt":"他抬头，正好也看见了你。这一秒，你身体里最先动起来的是哪一股？","options":[{"key":"A","text":"退回楼道，打 110，再把单元门反锁——他选的路，后果自负。","effects":{"dd_order":1.9,"dd_good":-1.2,"mot_security":1},"social_desirability":1},{"key":"B","text":"捂住口袋快步走开。半夜这种事，本来就轮不到我来管。","effects":{"dd_order":-1.2,"dd_good":-1.8,"def_detach":0.9},"social_desirability":1},{"key":"C","text":"冲上去吼一句「你干什么」，声音大得整栋楼都听得见。","effects":{"dd_order":-1.6,"dd_good":1.3,"sin_wrath":1},"social_desirability":0},{"key":"D","text":"停住，慢慢举起手机对准他，喊一句「我已经拍了」。","effects":{"dd_order":1.2,"dd_good":1.4,"big5_assert":1.1},"social_desirability":2}]},{"id":"v10_q09","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"alignment_order","is_sensitive":true,"weight":1.4,"context":"医院检验科前排队四十多人，取号屏上还有二十七个。一个抱着发烧孩子的母亲走到你面前，说她只差一张抽血单，问能不能插在你前面。","prompt":"你身后还站着三十多个人。你此刻会怎么处理？","options":[{"key":"A","text":"请她去找护士台，那里有急症通道，比我这里排队要快得多。","effects":{"dd_order":1.9,"dd_good":1.3,"cog_logic":1},"social_desirability":3},{"key":"B","text":"摇头。后面三十几个人里，抱着孩子的可能不止她一个。","effects":{"dd_order":1.5,"dd_good":-1.4,"val_boundary":1},"social_desirability":1},{"key":"C","text":"让她站我前面，但先回头问一声身后的人，有人不同意就作罢。","effects":{"dd_order":1.2,"dd_good":1.8,"big5_compassion":1.1},"social_desirability":2},{"key":"D","text":"让她过去。规矩是给活人用的，孩子这会儿烧到三十九度。","effects":{"dd_order":-1.7,"dd_good":1.6,"wv_social":-0.8},"social_desirability":2}]},{"id":"v10_q10","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"alignment_good","is_sensitive":false,"weight":0.85,"prompt":"凌晨一点，你刷到一条转发过千的众筹：一个陌生父亲说孩子要动手术，还差八万。照片有点糊，没有病历，也没有医院的名字。","scale":{"left":"划过去。我救不了每一个刷到的人，也不知道这是不是真的","right":"随手转五十块。真的假的我都认了，就当这一下没白刷","sdHigh":"right"},"effects":{"dd_good":[-1.5,1.6],"dd_order":[1.3,-1.2],"light_faith":[-1,1.2],"cog_logic":[1.1,-0.9]}},{"id":"v10_q11","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"alignment_order","is_sensitive":true,"weight":1.4,"context":"二手房过户前一夜，中介压低声音跟你说，成交价可以写成两份，税能少交五万多，这条街上一直这么办。你妈在旁边点头，说这笔钱本来是留给装修的。","prompt":"笔就放在桌上，你最后落笔的那份是——","options":[{"key":"A","text":"「写两份吧。」我妈为这五万攒了三年，我没法当着她的面把这份钱推回去。","effects":{"dd_order":-1.7,"dd_good":1.6,"mot_belonging":1},"social_desirability":2},{"key":"B","text":"「按真实价格签，那五万我自己补。」省下来的钱，往后每晚都得替它担一次心。","effects":{"dd_order":1.9,"dd_good":1.3,"light_kant":1},"social_desirability":3},{"key":"C","text":"「按真价签。省下的是给我装修的钱，真要出事，站进去的是我。」","effects":{"dd_order":1.6,"dd_good":-1.3,"val_standard":1.1},"social_desirability":1},{"key":"D","text":"「写两份吧。规矩要真管得住，这条街上早就没人这么干了。」","effects":{"dd_order":-1.9,"dd_good":-1.4,"cog_independent":1},"social_desirability":0}]},{"id":"v10_q12","type":"stealth_scale","stealth_mode":"projection","layer":"stealth","mirror_key":"alignment_good","is_sensitive":true,"weight":0.85,"prompt":"朋友聚会，一个人成了全场玩笑的靶子，连他的口音、他的新工作都被拿出来讲。他自己也在笑。笑声停下来的时候，你坐在哪里？","scale":{"left":"跟着笑。气氛已经到这儿了，认真起来反而扫兴","right":"把话头挪开，或者干脆坐到他旁边去接着聊","sdHigh":"right"},"effects":{"dd_good":[-1.5,1.6],"dd_order":[1.3,-1.3],"big5_compassion":[-1,1.2],"val_boundary":[1,-0.8]}},{"id":"v10_q13","type":"forced_choice","stealth_mode":"normalization","layer":"stealth","mirror_key":"alignment_good","is_sensitive":true,"weight":1.4,"context":"外卖放到你家门口，是一份你没点的餐：整只烤鸭配两个菜，小票上写着另一个单元的门牌号，价钱是你平时一顿的三倍。系统显示「已送达」。","prompt":"骑手已经走远，那份餐还在你手里。你打算怎么办？","options":[{"key":"A","text":"先拍照存证，两个小时没人来认，就当平台送了我一顿。","effects":{"dd_order":1.3,"dd_good":-1.2,"cog_logic":0.9},"social_desirability":1},{"key":"B","text":"直接吃。这一单的钱平台早就赚平了，它记在损耗里，不记在谁头上。","effects":{"dd_order":-1.9,"dd_good":-1.7,"cog_independent":1},"social_desirability":1},{"key":"C","text":"拍照发给平台客服，让他们联系那个单元真正的收件人。","effects":{"dd_order":1.8,"dd_good":1.5,"light_kant":1},"social_desirability":3},{"key":"D","text":"拎到那个单元门口敲门问一句，是谁家点的就还回去。","effects":{"dd_order":-1.2,"dd_good":1.9,"big5_compassion":1},"social_desirability":2}]},{"id":"v10_q14","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"alignment_values","is_sensitive":false,"weight":1.3,"prompt":"下面八件事，挑出你最不能容忍别人破坏的三件，最不能忍的排第一。不是它们「应该」重要，而是真的发生了你会当场站起来。","values":[{"key":"broken_promise_rule","label":"说好的规矩，被有权力的人一句话推翻","effects":{"dd_order":1.9,"dd_good":1.2}},{"key":"punching_down","label":"成年人把气撒在不能还手的人身上","effects":{"dd_order":1.2,"dd_good":1.9}},{"key":"public_humiliation","label":"有人当众羞辱一个刚说错话的年轻人","effects":{"dd_order":1.3,"dd_good":1.6}},{"key":"locked_by_process","label":"一个人被流程卡在原地，周围没有一个人肯通融","effects":{"dd_order":-1.5,"dd_good":1.6}},{"key":"ungrateful","label":"你帮过的人，转过身就当没这回事","effects":{"dd_order":1.3,"dd_good":-1.4}},{"key":"only_one_following","label":"所有人都在钻空子，只有你还在按流程走","effects":{"dd_order":1.5,"dd_good":-1.3}},{"key":"decided_for_you","label":"有人替你做了决定，还一口一个为你好","effects":{"dd_order":-1.7,"dd_good":-1.2}},{"key":"words_moved_upstairs","label":"你私下说过的话，被人原样搬到了台面上","effects":{"dd_order":-1.3,"dd_good":-1.5}}]},{"id":"v10_q15","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"alignment_cost","is_sensitive":false,"weight":1.3,"prompt":"假设你手里有一百点，只能投给你住的这条街。没有一分是白给的：投在哪里，就等于承认你相信什么在支撑它。","items":[{"key":"rule_no_exception","label":"一条连制定者也不能例外的规矩","dim":"dd_order","base":0,"gain":1},{"key":"open_ledger","label":"每一笔账都能被任何人查到的账本","dim":"dd_order","base":0,"gain":1},{"key":"process_owner","label":"出事之后有人按流程负责到底的通道","dim":"dd_order","base":0,"gain":1},{"key":"step_down","label":"给一时过不去的人留一个不被追问的台阶","dim":"dd_good","base":0,"gain":1},{"key":"count_the_silent","label":"把没人替其说话的那部分人算进去","dim":"dd_good","base":0,"gain":1},{"key":"show_up","label":"哪家出了事，第一个到场的那份余力","dim":"dd_good","base":0,"gain":1}]},{"id":"v10_q16","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"alignment_order","is_sensitive":true,"weight":1.4,"context":"小区群里发起联名，要求物业禁止一位老人半夜在垃圾桶边收纸箱，「影响形象，也有消防隐患」。接龙已经排到四十多户，你的头像排在后面。","prompt":"轮到你了。这条接龙，你接不接？","options":[{"key":"A","text":"不接，也不说话。别人家的事，轮不到我替他们表态。","effects":{"dd_order":-1.2,"dd_good":-1.5,"def_detach":1},"social_desirability":1},{"key":"B","text":"接，但加一句：先跟老人谈，给他一个固定时段和堆放点。","effects":{"dd_order":1.9,"dd_good":1.4,"cog_ambiguity":0.8},"social_desirability":3},{"key":"C","text":"不接，回一句：他没堵消防通道，那些纸箱是他这个月的菜钱。","effects":{"dd_order":-1.3,"dd_good":1.8,"big5_assert":1.1},"social_desirability":2},{"key":"D","text":"接。半夜翻桶的声音我确实听过很多次，我的睡眠也是真的。","effects":{"dd_order":1.5,"dd_good":-1.9,"val_boundary":1.1},"social_desirability":0}]}]},"vol11":{"volume_id":"vol11","index":11,"title":"哲人底色","subtitle":"八大哲学流派与海特六大道德基础","theme_color":"#4D5D4E","estimated_minutes":5,"intro":"这一卷不测你读过多少书。它想看清的是：当一件不好的事真的落在你身上，你会用哪一套语言把它解释过去；以及别人踩到哪条线上时，你心里最原始的那一下会先亮起来。请凭第一感觉作答，不必挑更体面的那个答案。","dimensions":["phil_stoic","phil_existential","phil_absurd","phil_cynic","phil_pragmatic","phil_epicurean","phil_nihilism","phil_humanist","mft_care","mft_fairness","mft_loyalty","mft_authority","mft_sanctity","mft_liberty"],"questions":[{"id":"v11_q01","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"phil_stoic","is_sensitive":true,"weight":1.4,"context":"你用了两年、几乎所有的周末，还有一部分积蓄做一件事。就在快收成的前一个月，一条你完全没有参与决定权的政策变动，让它归了零。","prompt":"哭过或者没哭过之后，最先把你从地上扶起来的是哪一种念头？","options":[{"key":"A","text":"结果本来就不完全归我，归我的只有此刻站成什么样，和接下来先做完哪件小事","effects":{"phil_stoic":2,"def_intellectual":1.2,"lv_suffering":1.2,"phil_absurd":-1.2},"social_desirability":2},{"key":"B","text":"没有人承诺过剧本。旧的那本撕了，那就由我重写一版，写砸了也算我自己的","effects":{"phil_existential":2,"mot_autonomy":1.4,"lv_anchor":0.8,"phil_nihilism":-1.2},"social_desirability":3},{"key":"C","text":"推上去的东西总会滚下来。先笑一下，然后去吃一顿很烫很辣的东西","effects":{"phil_absurd":2,"phil_epicurean":1.7,"lv_suffering":-1.2,"phil_stoic":-1.2},"social_desirability":1},{"key":"D","text":"认真到这个地步还是被这样拿走，以后别再把整颗心押在任何一件事上","effects":{"phil_cynic":2,"phil_nihilism":1.4,"light_faith":-1.4,"lv_suffering":-0.8},"social_desirability":0}]},{"id":"v11_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"phil_pragmatic","is_sensitive":true,"weight":0.85,"context":"一个合作了两年的人，把你私下只讲给他听过的一个想法原样拿去用了，署名是他。","prompt":"接下来那几天，你反复回到的其实是哪一层？","scale":{"left":"怎么止损、以后怎么防，他为什么这么做我并不太关心","right":"他当时到底在怕什么、缺什么，才会伸这只手","sdHigh":"left"},"effects":{"phil_pragmatic":[2,-2],"phil_humanist":[-2,2],"phil_cynic":[1.6,-1.6],"mft_care":[-1.2,1.6],"light_faith":[-1,1]}},{"id":"v11_q03","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"phil_humanist","is_sensitive":true,"weight":1.4,"context":"三个人在异国的小城，行程第二天。一个人坚持要去看那座来回六小时的美术馆，另一个人想留在广场晒太阳。你其实更想留下，但你知道那位朋友为这趟旅行攒了很久的钱。","prompt":"你说出口的那句话，更接近——","options":[{"key":"A","text":"「少数服从多数吧。你们去哪我去哪，我没什么特别的偏好」","effects":{"phil_cynic":2,"mft_authority":-1.6,"mft_liberty":1.2,"wv_nature":-1.2},"social_desirability":0},{"key":"B","text":"「那就去。六小时而已，回来剩下的时间再分，谁也不亏」","effects":{"phil_pragmatic":2,"wv_causal":1.2,"cog_global":0.8,"phil_cynic":-1},"social_desirability":2},{"key":"C","text":"「你们定，我都可以。去哪儿都比在原地站着讲道理强」，然后闭嘴","effects":{"phil_stoic":1.8,"cog_logic":1.2,"mft_liberty":1.2,"phil_absurd":0.8},"social_desirability":1},{"key":"D","text":"「他攒了半年就为这个。广场明天还在，他的假期不在了」","effects":{"phil_humanist":2,"mft_care":1.4,"wv_nature":1.2,"phil_cynic":-1.2},"social_desirability":3}]},{"id":"v11_q04","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"mft_loyalty","is_sensitive":true,"weight":1.25,"context":"一桌朋友吃饭，一个认识很多年的人把你当年最狼狈的那件事，当成笑料讲给刚认识的人听。桌上有两个人笑出了声。","prompt":"笑声响起来的那三秒，你身体先做了什么？","options":[{"key":"A","text":"先跟着笑一下，把场面接住，然后整晚没再和他多说一句话","effects":{"mft_loyalty":-1.8,"phil_cynic":1.2,"wv_nature":-1,"val_boundary":1.2},"social_desirability":0},{"key":"B","text":"直接说「这个不好笑」，声音不大，但桌上的人都听见了","effects":{"mft_liberty":1.8,"mft_loyalty":-1,"light_kant":1.2,"sin_pride":0.8},"social_desirability":2},{"key":"C","text":"等他讲完，很平静地补一句：那件事当时对我并不轻","effects":{"mft_care":1.8,"mft_loyalty":1.4,"light_kant":1.2,"virtue_humility":0.8},"social_desirability":3},{"key":"D","text":"心里一下凉了，开始清点这个人到底知道我多少件事","effects":{"mft_loyalty":-1.6,"phil_cynic":1.6,"dark_mach":1.2,"wv_nature":-1},"social_desirability":1}]},{"id":"v11_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"mft_sanctity","is_sensitive":true,"weight":0.85,"context":"外婆过世后的第一个清明，家里按老规矩摆了一桌东西。一个年轻亲戚把供着的那只旧碗拿起来当烟灰缸，说反正也没人用了。","prompt":"你站在旁边，身体里最先冒出来的东西是什么？","scale":{"left":"只是一只旧碗，他没有恶意，人也比碗重要","right":"说不清为什么，胃里先紧了一下，就是不能这样","sdHigh":"right"},"effects":{"mft_sanctity":[-2,2],"mft_liberty":[1.6,-1.6],"phil_humanist":[1.4,-1.4],"phil_cynic":[1.2,-1.2],"mft_care":[1,-0.8]}},{"id":"v11_q06","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"mft_liberty","is_sensitive":true,"weight":1.4,"context":"小区突然贴出通知：为了「统一管理」，所有电动车必须停到八百米外的集中点，晚十点后不得进出。没征求过任何人意见，理由只有一句：上面要求。","prompt":"业主群吵成一片，你更愿意站在哪一边——","options":[{"key":"A","text":"该守的守，但车我照停楼下，谁来说就把道理跟他说完","effects":{"mft_liberty":2,"mft_authority":-1.8,"sin_pride":1.2,"phil_cynic":1.2},"social_desirability":1},{"key":"B","text":"先联合几户按程序推翻它：找物业、找街道、留书面记录","effects":{"phil_pragmatic":1.8,"mft_authority":1,"cog_logic":1.2,"mft_liberty":1.2},"social_desirability":3},{"key":"C","text":"停哪里都行，我只觉得「统一管理」这四个字很好笑","effects":{"phil_cynic":2,"phil_absurd":1.2,"mft_authority":-1.2,"light_faith":-1.2},"social_desirability":0},{"key":"D","text":"规定再蠢也是规定，我照做，省下的力气用在别的地方","effects":{"mft_authority":2,"mft_liberty":-1.8,"phil_stoic":1.4,"wv_social":0.8},"social_desirability":2}]},{"id":"v11_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"mft_authority","is_sensitive":true,"weight":0.85,"context":"你住的楼有一条规矩：夜里十一点后出入要登记。那天你抱着发烧的孩子从医院回来，已经一点多，值班室黑着灯，桌上摊着登记本。","prompt":"你在门口停了半秒，然后会——","scale":{"left":"把值班的人叫醒，登记完再上楼，规矩就是规矩","right":"直接上楼，孩子等不了，规矩本来就该让开","sdHigh":"left"},"effects":{"mft_authority":[2,-2],"mft_care":[-1.4,1.8],"phil_pragmatic":[-1.2,1.4],"light_kant":[1.2,-1.4]}},{"id":"v11_q08","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"phil_existential","is_sensitive":true,"weight":1.3,"context":"一场吵到后半段的对话里，对方忽然说：「和你在一起的这几年，我一直在将就。」你知道这句有一半是气话，但另一半可能是真的。","prompt":"那句话落地的一秒，你脑子里先亮起来的是哪一句？","options":[{"key":"A","text":"原来这几年在他那里是这个版本，那我们把话讲开，怎么改一起说","effects":{"phil_existential":2,"mft_care":1.2,"def_intellectual":1,"lv_suffering":0.8},"social_desirability":3},{"key":"B","text":"有点想笑：两个人都觉得自己在将就，还都以为自己在忍","effects":{"phil_absurd":1.8,"phil_cynic":1.2,"phil_epicurean":1,"mft_care":-0.8},"social_desirability":1},{"key":"C","text":"一阵很冷的安静，什么都感觉不到，只想先把这场对话结束","effects":{"phil_stoic":1.8,"phil_nihilism":1.2,"mft_care":-1.2,"def_intellectual":0.8},"social_desirability":0},{"key":"D","text":"心口疼了一下，先想的是他这几年到底憋了多少没说出口的","effects":{"mft_care":1.8,"phil_humanist":1.6,"phil_stoic":-1,"wv_nature":0.8},"social_desirability":2}]},{"id":"v11_q09","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"mft_fairness","is_sensitive":true,"weight":1.4,"context":"两年前你借给一位很好的朋友一笔钱，说好三个月。他提过两次「下个月一定」，然后再没提。昨天你刷到他晒了块表，配文是「该对自己好一点」。","prompt":"你把手机放下，第一件想做的事更接近哪一种？","options":[{"key":"A","text":"把当初的转账记录找出来发给他，附一句：这笔我们该结一下了","effects":{"mft_fairness":2,"light_kant":1.2,"sin_pride":0.8,"phil_pragmatic":1},"social_desirability":2},{"key":"B","text":"算了。人都会给自己找理由，我以后不再借，也不用演一场戏","effects":{"phil_cynic":2,"phil_nihilism":1.2,"mft_fairness":-1.2,"lv_anchor":0.8},"social_desirability":0},{"key":"C","text":"不催。他真宽裕了自己会想起来，想不起来就当花钱买个明白","effects":{"mft_loyalty":1.8,"phil_cynic":1.2,"mft_fairness":-1.6,"virtue_charity":1},"social_desirability":3},{"key":"D","text":"先算清这笔钱在我这里还剩多少分量，再用不撕破的方式拿回来","effects":{"phil_pragmatic":2,"mft_fairness":1.2,"dark_mach":1.2,"mft_loyalty":-0.8},"social_desirability":1}]},{"id":"v11_q10","type":"stealth_scale","stealth_mode":"projection","layer":"stealth","mirror_key":"phil_nihilism","is_sensitive":false,"weight":0.85,"context":"凌晨三点，你醒着，房间很静。你忽然很清楚地想到：一百年后，今天这些事不会有人记得，连名字都不会。","prompt":"你躺着没有动，那个念头先在你身上变成了什么？","scale":{"left":"一阵说不出的轻松，像有人替我卸掉了一块东西","right":"一阵发凉，然后更想抓紧眼前这几个还活着的人","sdHigh":"right"},"effects":{"phil_nihilism":[1.8,-1.8],"phil_epicurean":[1.6,-1.6],"phil_absurd":[1.6,-1.6],"phil_humanist":[-1.8,1.8],"lv_anchor":[-1.2,1.2]}},{"id":"v11_q11","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"phil_absurd","is_sensitive":false,"weight":1.4,"context":"一场决定明年方向的会上，所有人都在点头通过一个你私下算过、明显撑不住的方案。你提了两句，主持人说「先按这个走」，然后继续往下讲。","prompt":"笔停在纸面上，你心里先冒出来的是哪种声音？","options":[{"key":"A","text":"该说的我说到了，剩下的交给现实，半年后数据会替我说完","effects":{"phil_pragmatic":1.8,"def_intellectual":1.2,"mft_authority":1,"phil_absurd":0.8},"social_desirability":2},{"key":"B","text":"不行，我要把话说完，哪怕这一屋子人今晚都不高兴","effects":{"mft_liberty":1.8,"sin_pride":1.4,"phil_stoic":1,"mft_authority":-1.4},"social_desirability":1},{"key":"C","text":"有点想笑：这样一个东西，也要所有人一起点头才算数","effects":{"phil_absurd":2,"phil_cynic":1.4,"cog_global":1.2,"mft_authority":-1.2},"social_desirability":0},{"key":"D","text":"既然定了，我就做得尽量像样，别让后面接手的人受苦","effects":{"phil_stoic":1.8,"mft_care":1.6,"def_sublimate":1.2,"mft_liberty":-0.8},"social_desirability":3}]},{"id":"v11_q12","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"phil_epicurean","is_sensitive":true,"weight":1.2,"context":"凌晨一点，你躺在床上刷到一条动态：一个和你同龄、起点差不多的人，晒出了刚拿到的东西——一套房，或者一本书的封面，或者一张全家福。屏幕的光落在天花板上。","prompt":"手机举在半空的那三秒，你先感觉到的是什么？","options":[{"key":"A","text":"一阵很具体的酸，手心发凉，然后把手机扣在胸口没再动","effects":{"phil_nihilism":1.6,"phil_stoic":-1.4,"lv_anchor":-1.2,"mot_purpose":1},"social_desirability":0},{"key":"B","text":"笑了一下：他过他的，我过我这一晚，起来给自己煮碗面","effects":{"phil_epicurean":2,"phil_absurd":1.2,"lv_suffering":-1.2,"phil_nihilism":-1},"social_desirability":2},{"key":"C","text":"睡不着了，索性打开电脑，把拖了三个月的事做掉一小块","effects":{"phil_pragmatic":1.8,"mot_purpose":1.4,"phil_epicurean":-1.2,"def_sublimate":1},"social_desirability":3},{"key":"D","text":"忽然觉得这些都没意义，早起、加班、存钱，最后都一样","effects":{"phil_nihilism":2,"phil_cynic":1.2,"phil_epicurean":-0.8,"lv_anchor":0.6},"social_desirability":1}]},{"id":"v11_q13","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"phil_cynic","is_sensitive":true,"weight":0.85,"context":"你帮过一个朋友很大的忙：介绍工作、垫过钱、在他最难的时候陪着。两年后他过得很好，但提起你时，说的都是「也就那样」。","prompt":"那个下午你一个人坐了很久，最后落下来的结论是？","scale":{"left":"大多数人就是这样，善意要省着用，以后只留给很少几个人","right":"他有他的处境，我不打算因为这一句改掉自己的做法","sdHigh":"right"},"effects":{"phil_cynic":[2,-2],"phil_humanist":[-1.8,1.8],"light_faith":[-1.4,1.4],"mft_care":[-1,1.2],"wv_nature":[-1.2,1.2]}},{"id":"v11_q14","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"mft_care","is_sensitive":true,"weight":1.4,"context":"你最好的朋友下周办婚礼。三天前，你在一间餐厅门口看见他的未婚妻和另一个人牵着手走出来，那个人不是他。他这两天还在群里发喜糖的照片。","prompt":"这件事现在压在你手里，你会怎么处理？","options":[{"key":"A","text":"当晚就告诉他，原话讲清，不添一句判断。他有权知道，早比晚好","effects":{"mft_care":2,"mft_sanctity":1.6,"light_kant":1.2,"mft_loyalty":-0.8},"social_desirability":3},{"key":"B","text":"先去找那个人把话说死：三天内自己讲清楚，否则我来讲","effects":{"phil_pragmatic":1.8,"dark_mach":1.2,"mft_loyalty":1.2,"mft_fairness":1},"social_desirability":2},{"key":"C","text":"不说。婚礼是他的选择，我去掀这件事，最后被恨的人是我","effects":{"phil_cynic":1.8,"mft_care":-1.6,"mft_sanctity":-1.4,"mft_loyalty":-1.4},"social_desirability":0},{"key":"D","text":"只跟他说一句：婚礼前有没有什么想跟我讲的。剩下的等他自己开口","effects":{"phil_humanist":1.6,"mft_care":1.2,"mft_sanctity":1,"cog_ambiguity":1.2},"social_desirability":1}]},{"id":"v11_q15","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"mft_liberty","is_sensitive":true,"weight":0.85,"context":"家族群里，几位长辈已经替你商量好了明年的事——工作、房子，甚至和谁见面。他们说得热闹，最后一句是「我们都是为你好」。","prompt":"你打完一行字又删掉，最终的决定更接近——","scale":{"left":"领这份情，但事情按我的来，我会说清楚，不怕他们不高兴","right":"顺着他们的安排走，争这些太累，家里和气更重要","sdHigh":"left"},"effects":{"mft_liberty":[1.8,-1.8],"mft_authority":[-1.8,1.8],"phil_existential":[1.6,-1.4],"mot_autonomy":[1.4,-1.2],"phil_stoic":[-0.8,1]}},{"id":"v11_q16","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"mft_fairness","is_sensitive":false,"weight":1.25,"context":"排了四十分钟的队，前面忽然插进来一个中年男人，手里拎着药袋，眼睛下面两团青黑。后面有人小声骂了一句。","prompt":"看到他插进去的那一刻，你的第一反应是——","options":[{"key":"A","text":"直接开口：后面一队人都在排，请你到后面去","effects":{"mft_fairness":2,"sin_pride":1,"mft_care":-1.2,"phil_stoic":1},"social_desirability":2},{"key":"B","text":"算了，让他先。他手上还拎着药，我这四十分钟不算什么","effects":{"mft_care":2,"phil_humanist":1.2,"mft_fairness":-1.6,"phil_absurd":0.8},"social_desirability":3},{"key":"C","text":"看向收银台，让这件事由店里的人来开口处理","effects":{"phil_pragmatic":1.8,"mft_fairness":1.2,"dark_mach":1,"mft_care":-0.6},"social_desirability":1},{"key":"D","text":"心里骂了一句，嘴上什么也没说，但这半天的好心情没了","effects":{"phil_cynic":1.6,"mft_fairness":1,"lv_suffering":-1,"mft_care":-0.8},"social_desirability":0}]},{"id":"v11_q17","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"phil_stoic","is_sensitive":false,"weight":1.4,"context":"父亲把攒了十几年的养老钱，投进了同乡介绍的一个「稳赚不赔」的项目。你查过，那东西的合同里全是洞。他不听劝，还说你不懂人情。","prompt":"你坐在他对面，最想先做的是哪一件？","options":[{"key":"A","text":"不再争对错，先把能追回的部分一步步追回来，追不回的认了","effects":{"phil_stoic":2,"phil_pragmatic":1.4,"cog_logic":1,"mft_authority":0.8},"social_desirability":3},{"key":"B","text":"该说的说完，剩下的他自己承担。人总要为自己的判断付账","effects":{"phil_cynic":1.8,"phil_nihilism":1.2,"mft_care":-1.4,"val_boundary":1},"social_desirability":0},{"key":"C","text":"先不劝。他需要一个「我还有用」的感觉，这不只是钱的事","effects":{"phil_humanist":2,"mft_care":1.6,"wv_nature":1.2,"phil_pragmatic":-0.8},"social_desirability":2},{"key":"D","text":"吵到底。哪怕今晚翻脸，也得让他把这笔钱拿回来","effects":{"mft_care":1.6,"mft_authority":-1.6,"phil_stoic":-1.2,"sin_pride":1},"social_desirability":1}]},{"id":"v11_q18","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"mft_loyalty","is_sensitive":true,"weight":1.4,"context":"相处半年后，对方提出：既然要认真，就把手机互相开放，随时可以看。「没什么可藏的，才算真的坦诚。」他说得很平静。","prompt":"这句话让你心里先起了一层什么，你更接近哪一种？","options":[{"key":"A","text":"给。他要的是安心，这份安心我给得起，但我大概不会真去翻他的","effects":{"mft_loyalty":2,"mft_care":1.2,"mft_liberty":-1.2,"virtue_humility":0.8},"social_desirability":2},{"key":"B","text":"不给。不是有什么要藏，是两个人之间得留一块不属于彼此的地方","effects":{"mft_liberty":2,"phil_existential":1.6,"mft_loyalty":-1.4,"sin_pride":1},"social_desirability":1}]},{"id":"v11_q19","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"moral_foundations","is_sensitive":true,"weight":1.3,"prompt":"下面八件事，都是别人可以对你做的「越界」。请挑出你最不能容忍的三件，最不能忍的那件放第一。","values":[{"key":"care","label":"有人当着一屋子人，羞辱一个完全没法还手的人","effects":{"mft_care":1.6,"phil_humanist":0.8,"light_humanism":0.6}},{"key":"fairness","label":"同一件事，别人做没事，你做就被拿出来罚","effects":{"mft_fairness":1.6,"val_moral":0.8,"light_kant":0.5}},{"key":"loyalty","label":"你替他扛下的事，他转头说是自己做的","effects":{"mft_loyalty":1.6,"mft_fairness":0.6,"mft_care":0.4}},{"key":"authority","label":"有人当着所有人，把你当成一个不懂规矩的人来教训","effects":{"mft_authority":1.6,"sin_pride":0.6,"wv_social":0.5}},{"key":"sanctity","label":"有人拿你家里最不能碰的那件事，当笑话讲给外人听","effects":{"mft_sanctity":1.6,"mft_loyalty":0.6,"lv_anchor":0.5}},{"key":"liberty","label":"有人替你把你接下来三年安排好了，还说这都是为你好","effects":{"mft_liberty":1.6,"phil_existential":0.8,"mot_autonomy":0.6}},{"key":"truth","label":"有人用一套漂亮的话，把明明发生过的事说成没发生","effects":{"phil_cynic":1.4,"val_moral":0.6,"mft_fairness":0.5}},{"key":"waste","label":"有人把十分钟能解决的事，拖成一场谁也不肯先动的对峙","effects":{"phil_pragmatic":1.4,"cog_logic":0.5,"phil_absurd":0.4}}]},{"id":"v11_q20","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"philo_energy","is_sensitive":false,"weight":1.3,"prompt":"一百点，只能分给下面六样东西。没有哪一样是「应该」要的，只有此刻真的缺的那样，才值得多放一点。","items":[{"key":"stoic","label":"在失控的场面里不慌的那点定力","dim":"phil_stoic","base":0,"gain":1},{"key":"existential","label":"亲手改写意义的那支笔","dim":"phil_existential","base":0,"gain":1},{"key":"epicurean","label":"把普通一晚过得像样的一点力气","dim":"phil_epicurean","base":0,"gain":1},{"key":"humanist","label":"还愿意相信人的那点软","dim":"phil_humanist","base":0,"gain":1},{"key":"fairness","label":"对所有人一样清楚的规则","dim":"mft_fairness","base":0,"gain":1},{"key":"liberty","label":"不被任何人替你决定的那块地方","dim":"mft_liberty","base":0,"gain":1}]}]},"vol12":{"volume_id":"vol12","index":12,"title":"底层执念","subtitle":"九型人格核心恐惧与三大本能副型","theme_color":"#7D4E57","estimated_minutes":6,"intro":"这一卷不给你贴类型号。它只关心：深夜睡不着、钱不够用、被人轻轻推开的那几个时刻，你身上哪一根弦最先响。九种恐惧，三种本能，没有一种是病——它们都曾经在某一年救过你。","dimensions":["enn_1","enn_2","enn_3","enn_4","enn_5","enn_6","enn_7","enn_8","enn_9","inst_sp","inst_sx","inst_so"],"questions":[{"id":"v12_q01","type":"forced_choice","stealth_mode":"mirror","layer":"stealth","mirror_key":"enn_4","is_sensitive":true,"weight":1.4,"context":"凌晨三点，房间里只剩路由器的绿灯亮着。手机屏已经暗了，你没睡着，也不算醒着。","prompt":"下面四种最坏的可能，哪一种一旦在脑子里坐实，会让你整个人凉下去？","options":[{"key":"A","text":"你这一生没留下任何只有你能留下的东西，和地铁里每一张模糊的脸没有区别","effects":{"enn_4":2,"mot_purpose":1,"dark_narc":1},"social_desirability":1},{"key":"B","text":"哪天你倒下，通讯录翻到底，也找不出一个能把银行卡密码和猫托付过去的人","effects":{"enn_6":2,"inst_sp":1.5,"att_anxiety":1.2},"social_desirability":2},{"key":"C","text":"有一天你连把一件事想清楚的力气都没有了，脑子里那几间房一间一间灭灯","effects":{"enn_5":2,"def_detach":1.2,"mot_autonomy":0.8},"social_desirability":1},{"key":"D","text":"你已经很多年没有真正想要过什么，别人问起，你只能说出他期待的那个答案","effects":{"enn_9":2,"def_fawn":1.2,"big5_compliance":1},"social_desirability":1}]},{"id":"v12_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"enn_1","is_sensitive":true,"weight":0.85,"prompt":"你给一个重要的人写了一段很长的话，可能是道歉，也可能是终于说出口的那件事。按下发送后的二十分钟，你在做什么？","scale":{"left":"放下手机去做别的，话已经说出去，剩下的归他","right":"把那段话在脑子里又读了三遍，找有没有哪一句会被理解成别的意思","sdHigh":"left"},"effects":{"enn_1":[-2,2],"big5_rumination":[-1.2,1.6],"schema_approval":[-0.6,1],"att_anxiety":[-0.8,1.2]}},{"id":"v12_q03","type":"forced_choice","stealth_mode":"ipsative","layer":"stealth","mirror_key":"enn_3","is_sensitive":true,"weight":1.4,"context":"部门调整，一个来了半年、资历比你浅的人接走了你做了三年的那摊事，理由写的是「让他练练」。","prompt":"散会后你在洗手间站了两分钟。镜子里冒出来的那句话，更接近哪一句？","options":[{"key":"A","text":"问题不在他，在我——我交出去的东西，已经有一阵连我自己都不想署名","effects":{"enn_1":1.8,"big5_rumination":1.2,"dark_narc":-0.8},"social_desirability":1},{"key":"B","text":"这三年我替所有人补过窟窿、垫过时间，真到这一天，没人替我说一句","effects":{"enn_2":2,"mot_belonging":1.2,"sin_wrath":0.8},"social_desirability":0},{"key":"C","text":"我的全部价值都挂在「有用」两个字上，一旦被换掉，我就什么都不是","effects":{"enn_3":2,"dark_narc":1,"schema_defect":1},"social_desirability":0},{"key":"D","text":"拍板的人从头到尾没问过我一句，我在这套规则里连个位置都没有","effects":{"enn_8":2,"big5_assert":1.2,"covert_control":0.8},"social_desirability":2}]},{"id":"v12_q04","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"inst_sp","is_sensitive":false,"weight":0.85,"prompt":"工资到账的短信和三条自动扣款几乎同时进来。你打开银行 App，通常会做到哪一步？","scale":{"left":"看一眼余额，够这个月用就关掉","right":"把最近三个月每一笔都翻出来对一遍，找出是哪里漏了","sdHigh":"left"},"effects":{"inst_sp":[-2,2],"mot_security":[-1.4,1.6],"big5_alert":[-0.8,1.2],"enn_6":[-0.6,0.8]}},{"id":"v12_q05","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"enn_4","is_sensitive":true,"weight":1.25,"context":"零点四十，你刷到前任发的照片：新家阳台上一盆你没见过的植物，配文只有一个句号。","prompt":"手指停在屏幕上的那三秒，你身上最先发生的是什么？","options":[{"key":"A","text":"把照片放大，看阳台的瓷砖、窗外的楼、玻璃上有没有第二个人影","effects":{"enn_4":1.8,"inst_sx":1.6,"big5_alert":1.2},"social_desirability":0},{"key":"B","text":"心跳快了一下，然后立刻划走，起身去厨房洗了个杯子","effects":{"enn_4":-1.2,"def_detach":1.8,"inst_sx":-1.2},"social_desirability":2},{"key":"C","text":"截图存进相册，说不清为什么，但就是不想让它从眼前消失","effects":{"enn_4":1.4,"att_anxiety":1.2,"big5_rumination":1.2},"social_desirability":1},{"key":"D","text":"忽然很想找个人说话，打开通讯录，从上往下滑了两遍","effects":{"inst_sx":1.4,"mot_belonging":1.6,"att_anxiety":1},"social_desirability":1}]},{"id":"v12_q06","type":"forced_choice","stealth_mode":"ipsative","layer":"stealth","mirror_key":"enn_6","is_sensitive":true,"weight":1.4,"context":"周六晚上你翻到三个好友的合照，同一家店、同一晚。群里上一次说话是十天前，没人提过这件事。","prompt":"你把手机放下，又拿起来。此刻你更可能是哪一种？","options":[{"key":"A","text":"在群里发一句「下次记得叫我呀」加个笑脸，然后真的不再主动开口","effects":{"enn_6":1.6,"inst_so":1.4,"def_fawn":1},"social_desirability":2},{"key":"B","text":"直接问一句「你们上周聚了？怎么没叫我」，问完把手机放下去做别的","effects":{"enn_6":-1.2,"big5_assert":1.4,"big5_alert":-0.8},"social_desirability":1},{"key":"C","text":"不问，但接下来一阵子，他们再约你时，你总能找到一个推掉的理由","effects":{"enn_6":1.2,"def_detach":1.2,"inst_so":-1.2,"att_avoidance":1},"social_desirability":0},{"key":"D","text":"先在脑子里把最近两次聊天回放一遍，找自己哪句话可能说得不合适","effects":{"enn_6":1.8,"schema_defect":1.2,"def_fawn":1.2},"social_desirability":1}]},{"id":"v12_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"inst_so","is_sensitive":false,"weight":0.85,"prompt":"一个不算熟的饭局散场，大家在路边互相扫码。你的手机伸出去了几次？","scale":{"left":"只加散场前真正聊得来的那一两个，其余笑笑就过去了","right":"基本上一圈都扫了，还会顺手记下每个人在忙什么","sdHigh":"right"},"effects":{"inst_so":[-2,2],"big5_social":[-1.6,1.6],"mot_belonging":[-1,1.2],"enn_3":[-0.8,0.8]}},{"id":"v12_q08","type":"forced_choice","stealth_mode":"normalization","layer":"stealth","mirror_key":"enn_3","is_sensitive":true,"weight":1.4,"context":"你花两小时随手帮朋友改了一份东西，他发朋友圈说是「大神手笔」，底下三十多个赞。","prompt":"你刷到这条的时候，心里第一念更接近——","options":[{"key":"A","text":"有点心虚，想在评论区补一句「其实我没花多少时间」，把话说实","effects":{"enn_1":1.6,"virtue_humility":1.2,"light_kant":0.8},"social_desirability":2},{"key":"B","text":"收着，顺手截图存进自己的作品集，这种机会本来就不该浪费","effects":{"enn_3":1.8,"mot_mastery":1.2,"dark_narc":0.8},"social_desirability":1},{"key":"C","text":"有点别扭，他夸的那个人，好像和我认识的我并不是同一个","effects":{"enn_4":1.6,"schema_defect":1.2,"dark_narc":0.6},"social_desirability":1},{"key":"D","text":"说不上什么感觉，反正是顺手帮忙，他能高兴一下也挺好","effects":{"enn_9":1.4,"enn_3":-1.2,"def_fawn":0.8},"social_desirability":2}]},{"id":"v12_q09","type":"stealth_scale","stealth_mode":"ipsative","layer":"explicit","mirror_key":"enn_9","is_sensitive":false,"weight":0.85,"context":"四个人站在路口讨论去哪吃，已经站了二十分钟。有人开始说「都行」，有人开始刷手机。","prompt":"这种时候，你身上那根弦更靠近哪一端？","scale":{"left":"直接拍板走进最近那家，不好吃下次再换","right":"说一句「我都行」，然后等一个看起来最想说话的人先开口","sdHigh":"left"},"effects":{"enn_9":[-2,2],"big5_compliance":[-1.2,1.4],"big5_assert":[1.4,-1.2],"mot_autonomy":[1.2,-0.8]}},{"id":"v12_q10","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"enn_8","is_sensitive":true,"weight":1.25,"context":"晚高峰地铁，一个人从后面挤过来，手肘撞在你胸口，还回头白了你一眼说「看着点」。","prompt":"身体先于脑子反应的那一下，你做了什么？","options":[{"key":"A","text":"立刻撞回去半步，声音抬起来：撞我的是你，你还白我一眼","effects":{"enn_8":2,"def_attack":1.6,"big5_assert":1.2,"enn_9":-1.2},"social_desirability":0},{"key":"B","text":"什么都没说，但站定不动，眼睛一直看着他，直到他先转开","effects":{"enn_8":1.2,"big5_assert":0.8,"sin_pride":0.8},"social_desirability":1},{"key":"C","text":"侧身让开，心里说算了，但手心在抖，到站前一句话都不想说","effects":{"enn_9":1.6,"enn_8":-1.4,"big5_rumination":1.2},"social_desirability":2},{"key":"D","text":"掏出手机对着他，说你再讲一遍，先把证据留下来再说","effects":{"covert_control":1.6,"def_intellectual":1,"enn_8":0.6},"social_desirability":1}]},{"id":"v12_q11","type":"forced_choice","stealth_mode":"ipsative","layer":"stealth","mirror_key":"enn_7","is_sensitive":false,"weight":1.4,"context":"一个机会落到你面前：钱多一倍，但要搬去另一个城市签两年，中间几乎请不了长假。","prompt":"你用来推掉它的四条理由，底下各压着一种怕。哪一条最像你？","options":[{"key":"A","text":"接下来两年就被写死了，谁知道两年后我还想不想过这种日子","effects":{"enn_7":2,"mot_autonomy":1.4,"def_detach":0.8},"social_desirability":1},{"key":"B","text":"这边有人是真的需要我，我要是走了，他这阵子会很难过下去","effects":{"enn_2":2,"mot_belonging":1.4,"def_fawn":1},"social_desirability":2},{"key":"C","text":"去了等于把现在的成绩清零，还要重新证明一次我是谁","effects":{"enn_3":1.8,"sin_pride":1,"mot_mastery":1},"social_desirability":1},{"key":"D","text":"条件是他们定的，规则也是他们定的，我不喜欢被人这么安排","effects":{"enn_8":1.8,"big5_assert":1.2,"mot_autonomy":1},"social_desirability":0}]},{"id":"v12_q12","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"enn_5","is_sensitive":true,"weight":0.85,"context":"周日晚上八点，一个熟人打来电话。不是急事，你知道他一开口就会聊四十分钟。","prompt":"手机在你手里震着，你会怎么处理？","scale":{"left":"接起来，一边听一边把该做的家务做完","right":"让它响完，过两分钟回一条「刚在忙，怎么了」","sdHigh":"left"},"effects":{"enn_5":[-2,2],"def_detach":[-1.4,1.6],"big5_social":[1.4,-1.4],"enn_2":[1.2,-1],"mot_autonomy":[-1.2,1.2]}},{"id":"v12_q13","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"ennea_energy","is_sensitive":true,"weight":1.3,"prompt":"一百点「我不能失去」的分量，只能发给下面六样。分得越多，说明它真的消失时你越撑不住。点数要分完，一项也不能剩。","items":[{"key":"shelter","label":"一个写着自己名字的住处，和随时能动的现金","dim":"inst_sp","base":0,"gain":1},{"key":"one_person","label":"一个人知道我所有底细还愿意留下","dim":"inst_sx","base":0,"gain":1},{"key":"circle","label":"一个圈子里有我的位置，有人会想起我","dim":"inst_so","base":0,"gain":1},{"key":"needed","label":"有人真的需要我，我对某个人不可替代","dim":"enn_2","base":0,"gain":1},{"key":"no_push","label":"我说不的时候，没有人敢硬来","dim":"enn_8","base":0,"gain":1},{"key":"no_storm","label":"日子平顺，不用面对撕破脸的场面","dim":"enn_9","base":0,"gain":1}]},{"id":"v12_q14","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"ennea_values","is_sensitive":false,"weight":1.3,"prompt":"如果只能拿十年去换三样东西，请按顺序点选。第一个位置，你留给哪一样？","values":[{"key":"own_work","label":"一件只有我做得出来的东西","effects":{"enn_4":1.6,"mot_purpose":0.8,"enn_3":0.6}},{"key":"no_report","label":"不必向任何人报备的日程","effects":{"inst_sp":1.2,"mot_autonomy":1.4,"enn_8":0.4}},{"key":"still_here","label":"一个十年后还在的人","effects":{"inst_sx":1.6,"mot_belonging":1,"enn_6":0.8}},{"key":"remembered","label":"这个名字被这个行业记住","effects":{"enn_3":1.8,"inst_so":1.2,"sin_pride":0.6}},{"key":"calm_body","label":"一副不再紧绷的身体和神经","effects":{"inst_sp":1.8,"enn_7":0.6,"big5_alert":-0.8}},{"key":"trusted","label":"一句「这事交给你我放心」","effects":{"enn_1":1.6,"enn_6":1.2,"virtue_diligence":1}},{"key":"my_terms","label":"所有事都按我的条件来","effects":{"enn_8":1.8,"mot_autonomy":1,"dark_narc":0.6}},{"key":"full_house","label":"一屋子人，谁都不用假装","effects":{"inst_so":1.6,"enn_9":1.2,"big5_compassion":0.8}}]},{"id":"v12_q15","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"inst_sx","is_sensitive":true,"weight":0.85,"context":"你和一个人聊到凌晨两点，说了一些从来没对别人说过的事。第二天醒来，光从窗帘缝里进来。","prompt":"你躺着还没睁眼。第一个念头是什么？","scale":{"left":"想马上再见到他，昨晚那种浓度让人有点上瘾","right":"有一点想收回来，昨晚给出去太多了","sdHigh":"left"},"effects":{"inst_sx":[2,-2],"att_avoidance":[-1.6,1.8],"def_detach":[-1.2,1.4],"big5_compassion":[1.2,-0.8]}},{"id":"v12_q16","type":"forced_choice","stealth_mode":"mirror","layer":"stealth","mirror_key":"enn_4","is_sensitive":true,"weight":1.4,"context":"医院走廊，你陪妈妈等一张复查报告。旁边一位阿姨一直在讲女儿在哪座城市、年薪多少。你妈听着，忽然转头问你一句：「你那个工作，还行吧？」","prompt":"那句话落地之后，你最怕被自己看见的是什么？","options":[{"key":"A","text":"你的体面是一层层补上去的，中间有一块地方空着，一戳就塌","effects":{"enn_3":1.8,"dark_narc":1,"schema_defect":1.2},"social_desirability":0},{"key":"B","text":"你忙着给她倒水、把外套叠好，其实是怕自己在这张长椅上没位置","effects":{"enn_2":1.8,"inst_so":1.2,"def_fawn":1},"social_desirability":1},{"key":"C","text":"你早就想站起来走开，只是没走，甚至不敢承认自己一直想走","effects":{"enn_9":1.8,"big5_compliance":1.2,"def_detach":1},"social_desirability":0},{"key":"D","text":"你一直觉得自己和这条走廊里的人不是同一类，这念头既让你骄傲又孤单","effects":{"enn_4":1.8,"sin_pride":0.8,"att_avoidance":0.8},"social_desirability":1}]},{"id":"v12_q17","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"enn_1","is_sensitive":false,"weight":1.2,"context":"早上出门，你发现对门又把两袋垃圾堆在你家门边的墙角。这已经是这个月第三次。","prompt":"你站在门口，手上还拎着要丢的袋子。哪个动作最先出现？","options":[{"key":"A","text":"敲门，把话说清楚：这袋麻烦你拿进去，这个月第三次了","effects":{"enn_1":1.8,"big5_assert":1.2,"sin_wrath":0.8},"social_desirability":1},{"key":"B","text":"自己顺手带下楼，心里记下这家人，以后不再打招呼","effects":{"enn_9":1.4,"enn_1":-1.2,"def_detach":0.8},"social_desirability":2},{"key":"C","text":"拍照，发给物业，附一句「麻烦按规定处理一下」","effects":{"covert_control":1.6,"enn_1":1,"def_intellectual":0.8},"social_desirability":2},{"key":"D","text":"什么都不做，但接下来一整天，一想到那两袋东西就烦躁","effects":{"enn_1":1.4,"big5_rumination":1.6,"sin_wrath":1},"social_desirability":0}]},{"id":"v12_q18","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"enn_2","is_sensitive":true,"weight":0.85,"context":"夜里十一点半，一个关系不错但很久没联系的人发来两个字：在吗。","prompt":"你看到这条消息的那一秒，身体里的反应更接近？","scale":{"left":"先回了「在」，然后一直等他说下去，今晚剩下的时间基本都交给他","right":"先看了眼时间，回一句「在，怎么了」，心里希望不是什么大事","sdHigh":"left"},"effects":{"enn_2":[2,-2],"def_fawn":[1.6,-1.4],"mot_belonging":[1.2,-1],"big5_compassion":[1,-0.6]}},{"id":"v12_q19","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"inst_sp","is_sensitive":true,"weight":1.3,"context":"体检报告刷出来，其他都正常，只有一栏标着一个向上的箭头，写着「建议复查」。号只能约到下周三。","prompt":"看到那个箭头的三秒里，你脑子里最先跑起来的是哪一件事？","options":[{"key":"A","text":"立刻打开搜索框，把所有最坏的可能一条条看过去，看到凌晨","effects":{"enn_6":1.8,"big5_alert":1.4,"big5_rumination":1.2},"social_desirability":0},{"key":"B","text":"把页面关掉，先睡，真要有什么事也得下周才知道","effects":{"enn_7":1.6,"def_detach":1.4,"inst_sp":-1.2},"social_desirability":1},{"key":"C","text":"开始算钱：真要治，存款够几个月，工作怎么请假，家里怎么说","effects":{"inst_sp":1.8,"mot_security":1.4,"def_intellectual":0.8},"social_desirability":2},{"key":"D","text":"忽然很想告诉一个人，哪怕只是发一句「我今天查出点问题」","effects":{"mot_belonging":1.6,"inst_sx":1.2,"att_anxiety":1},"social_desirability":1}]},{"id":"v12_q20","type":"forced_choice","stealth_mode":"ipsative","layer":"stealth","mirror_key":"enn_1","is_sensitive":false,"weight":1.4,"context":"三个人吃饭，账单上多了一道谁都没点的菜，四十六块。服务员站在旁边等着刷卡。","prompt":"这时候你心里那本账，最先翻出来的是什么？","options":[{"key":"A","text":"把服务员叫过来核对，这道菜去掉——不是为这四十多块，是这账不对","effects":{"enn_1":1.8,"big5_assert":1,"sin_wrath":0.6},"social_desirability":2},{"key":"B","text":"算了，别为四十多块让一顿饭变了味，照单付掉，谁也不提","effects":{"enn_9":1.6,"enn_1":-1.2,"virtue_patience":1.2},"social_desirability":3},{"key":"C","text":"当场不说，回去在群里发一个精确到小数点的数字，把自己那份减掉","effects":{"covert_control":1.6,"enn_6":1.2,"big5_alert":0.8},"social_desirability":1},{"key":"D","text":"主动多付一点，把这点差别抹平，谁也不必再提这件事","effects":{"enn_2":1.6,"def_fawn":1.2,"sin_pride":0.6},"social_desirability":2}]},{"id":"v12_q21","type":"forced_choice","stealth_mode":"ipsative","layer":"stealth","mirror_key":"inst_sp","is_sensitive":true,"weight":1.4,"context":"你手里有一笔钱，刚好够一套小房子的首付，也刚好够你辞职空一年。","prompt":"你在纸上算了三遍。最后落在哪一句上？","options":[{"key":"A","text":"先把地基钉死，房子买了，往后十年我就有一个退不掉的坐标","effects":{"inst_sp":1.8,"enn_7":-1.4,"mot_security":1.2},"social_desirability":2},{"key":"B","text":"空一年，先把自己从那台机器里捞出来，钱以后还能再挣","effects":{"enn_7":1.8,"mot_autonomy":1.4,"inst_sp":-1.4},"social_desirability":1},{"key":"C","text":"劈成两半，一半按住不动，一半买时间，两边都不彻底","effects":{"enn_6":1.4,"big5_alert":1,"inst_sp":0.6},"social_desirability":2},{"key":"D","text":"两个都先不选，放着，等一个更清楚的说法自己出现","effects":{"enn_6":1.2,"enn_9":1.2,"big5_rumination":0.8},"social_desirability":1}]},{"id":"v12_q22","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"inst_sx","is_sensitive":true,"weight":1.4,"context":"在一起三个月，某天他忽然说：我总觉得有一块地方，你不让我进去。","prompt":"这句话落在桌上的时候，你心里更接近——","options":[{"key":"A","text":"他说得对，可那块地方是我最后一块自己的地盘，我不想交出去","effects":{"enn_5":1.8,"mot_autonomy":1.4,"att_avoidance":1.2},"social_desirability":1},{"key":"B","text":"有点慌，立刻解释「我没有」，然后把最近所有的事都告诉他","effects":{"enn_2":1.6,"att_anxiety":1.4,"def_fawn":1.2},"social_desirability":1},{"key":"C","text":"心里一沉：又来了，每次快到这一步，就会有人要得更多","effects":{"att_avoidance":1.8,"inst_sx":-1.2,"def_detach":1.2},"social_desirability":0},{"key":"D","text":"觉得被看见了，甚至有点感动，我自己都没发现我一直这样","effects":{"enn_4":1.4,"inst_sx":1.2,"big5_compassion":1},"social_desirability":2}]}]},"vol13":{"volume_id":"vol13","index":13,"title":"童年剧本","subtitle":"十大隐形人生陷阱与早期图式","theme_color":"#5E5066","estimated_minutes":5,"intro":"这一卷不追究谁对谁错。有些台词在你还没学会说话时就被念过，后来它们学会了自己播放，在深夜、在饭桌上、在对方晚回消息的那半小时里。十八个普通场景只做一件事：把那段还在自动重播的旧录音找出来，听清它究竟在说什么。","dimensions":["schema_abandonment","schema_deprivation","schema_defect","schema_mistrust","schema_isolation","schema_std","schema_sacrifice","schema_approval","schema_entitlement","schema_negativity"],"questions":[{"id":"v13_q01","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"schema_sacrifice","is_sensitive":false,"weight":0.85,"prompt":"周六早上，伴侣把两天的行程排得满满当当，兴致很高地问你「都准备好了吧」——而你其实只想在家躺着。","scale":{"left":"当场说实话，把行程砍掉一半，哪怕他会有点失望","right":"笑着答应下来，把自己的状态压到最下面，两天全程配合","sdHigh":"left"},"effects":{"schema_sacrifice":[-1.8,2],"def_fawn":[-1,1.2],"val_boundary":[1.2,-1]}},{"id":"v13_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"schema_deprivation","is_sensitive":true,"weight":0.85,"prompt":"深夜十一点半，你刚经历完一件很难受的事。手机握在手里，通讯录翻了两屏。","scale":{"left":"真有一两个人，我会直接打过去，把话说明白","right":"翻到最后还是锁了屏，说了也只是被敷衍两句","sdHigh":"left"},"effects":{"schema_deprivation":[-1.8,2],"att_avoidance":[-1,1.2],"mot_belonging":[-1,0.9]}},{"id":"v13_q03","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"schema_mistrust","is_sensitive":false,"weight":1.4,"context":"一起合租过两年的阿哲开口借一笔钱，大约是你两个月工资，说三个月后还，没提利息，也没提借条。","prompt":"转账页面停在输入金额那一格，你心里那杆秤最后偏向哪一边？","options":[{"key":"A","text":"借，不设期限也不要借条。他开这个口已经很难，这两年我信得过","effects":{"schema_mistrust":-2,"light_humanism":1.2,"virtue_kindness":0.8},"social_desirability":3},{"key":"B","text":"借，但分两次给。先给一半看他怎么处理这件事，剩下的再谈","effects":{"schema_mistrust":1.7,"covert_control":1.4,"def_intellectual":0.8},"social_desirability":0},{"key":"C","text":"直说自己也有压力，能拿出一个不心疼的数，剩下的明说没有","effects":{"schema_mistrust":-1.7,"val_boundary":1.4,"def_intellectual":0.9},"social_desirability":2},{"key":"D","text":"嘴上先应着，回头用「最近手头也紧」把这件事慢慢拖过去","effects":{"schema_mistrust":1.8,"def_fawn":1,"covert_control":1.2},"social_desirability":1}]},{"id":"v13_q04","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"schema_entitlement","is_sensitive":false,"weight":1.4,"context":"六个人吃完饭，账单里有一瓶六百八的红酒，是其中两个人点的，你一口没喝。服务员把账单放在桌子中间。","prompt":"你把账单拿过来，一眼看见那瓶自己一口没喝的红酒，心里那个念头是：","options":[{"key":"A","text":"把那瓶酒单独划出来记在那两人头上，剩下的平摊，谁也不欠谁","effects":{"schema_entitlement":-1.7,"val_boundary":1.2,"light_kant":1},"social_desirability":2},{"key":"B","text":"什么也不提，按人头平摊，几十块钱的事不值得让一桌人尴尬","effects":{"schema_entitlement":-1.7,"big5_compliance":1.2,"virtue_kindness":1},"social_desirability":3},{"key":"C","text":"照单平摊，心里却记了一笔：我一口没喝，凭什么替别人买单","effects":{"schema_entitlement":1.7,"big5_rumination":1.4,"def_detach":1},"social_desirability":1},{"key":"D","text":"既然规则是平摊，就按规则用一次，顺手给自己加杯想试的酒","effects":{"schema_entitlement":1.9,"sin_greed":1.3,"light_kant":-1},"social_desirability":0}]},{"id":"v13_q05","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"schema_approval","is_sensitive":true,"weight":1.4,"context":"年夜饭桌上，你姑姑端着酒杯说：「你看你表弟，房子都买了，你也该定下来了。」","prompt":"一桌人的笑意还没落下来，你嘴里先出去的那句话，骨子里是什么味道？","options":[{"key":"A","text":"把话岔开，给她夹一筷子菜，说大过年的，先聊点高兴的事","effects":{"schema_approval":1.8,"def_fawn":1.2,"big5_compliance":1},"social_desirability":1},{"key":"B","text":"顺着她的话说表弟确实厉害，再平静地讲自己在按什么节奏走","effects":{"schema_approval":-1.6,"val_boundary":1.4,"virtue_humility":1},"social_desirability":2},{"key":"C","text":"笑着把这两年的成绩报一遍给她听，让全桌都知道你也没闲着","effects":{"schema_approval":2,"sin_pride":1.3,"schema_std":0.8},"social_desirability":3},{"key":"D","text":"低头吃饭，一晚上都在想自己哪里不如人，散场后在车里坐很久","effects":{"schema_approval":1.7,"schema_std":1.3,"big5_rumination":1.2},"social_desirability":0}]},{"id":"v13_q06","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"schema_abandonment","is_sensitive":true,"weight":1.25,"context":"周三下午，对方发来一句「晚上回来我们谈谈」，之后再没有别的消息。","prompt":"到晚上推门之前，你脑子里跑得最快的是哪一幕？","options":[{"key":"A","text":"把这半年的事过了一遍，先找出自己最可能做错的那三件","effects":{"schema_abandonment":1.9,"big5_rumination":1.4,"def_fawn":1},"social_desirability":1},{"key":"B","text":"有点慌，但马上告诉自己：谈就谈，最坏的结果我已经想清楚","effects":{"schema_abandonment":1.6,"schema_negativity":1.4,"big5_alert":1},"social_desirability":0},{"key":"C","text":"照常把手上的事做完，等晚上听他说，没发生的事想也没用","effects":{"schema_abandonment":-1.9,"big5_alert":-0.9,"mot_autonomy":1},"social_desirability":3},{"key":"D","text":"心里先凉了一下，然后开始默默算：如果分开，房子怎么分","effects":{"schema_abandonment":1.6,"schema_mistrust":1.4,"def_detach":1.2},"social_desirability":1}]},{"id":"v13_q07","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"schema_isolation","is_sensitive":true,"weight":1.4,"context":"你和一个朋友聊了大半年要一起做的副业。上个星期他开业了，你是从别人转发的海报上看到的。合伙人不是你。","prompt":"那张海报你已经点开过第三次了。","options":[{"key":"A","text":"点了个赞，然后告诉自己往后这类事不用再等，也别多想","effects":{"schema_isolation":1.8,"def_detach":1.2,"att_avoidance":1},"social_desirability":0},{"key":"B","text":"心里有点难受，但第二天照常约他吃饭，一个字都不问","effects":{"schema_isolation":-1.6,"mot_belonging":1.2,"big5_compassion":0.9},"social_desirability":2},{"key":"C","text":"直接问他当时是怎么想的，不猜也不憋着，语气还挺轻松","effects":{"schema_isolation":-1.9,"val_boundary":1.4,"mot_belonging":1.2},"social_desirability":3},{"key":"D","text":"把这个人的分档往下调了一格，不说破，但往后有钱的事不会再找他","effects":{"schema_isolation":1.7,"def_detach":1.3,"schema_mistrust":0.9},"social_desirability":1}]},{"id":"v13_q08","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"schema_negativity","is_sensitive":true,"weight":0.85,"prompt":"凌晨两点，你摸到脖子上有个小硬块——不疼，也不会自己消掉。今晚剩下的几个小时，你打算怎么过完？","scale":{"left":"搜索框已经打开，最坏的那种病从头看到尾，天亮前没合眼","right":"记在备忘录里，白天去挂个号，今晚先把觉睡完","sdHigh":"right"},"effects":{"schema_negativity":[2,-1.8],"big5_alert":[1.4,-1.2],"big5_rumination":[1.3,-0.9]}},{"id":"v13_q09","type":"stealth_scale","stealth_mode":"projection","layer":"stealth","mirror_key":"schema_std","is_sensitive":true,"weight":0.85,"prompt":"你爸在电话里说，隔壁老张的儿子今年带父母去了趟欧洲，说完停了一下，然后问你最近忙不忙，语气很轻。","scale":{"left":"顺着他的话聊两句，说说自己这半年过得怎么样","right":"挂了电话就开始算自己还差多少，一晚上都不太想说话","sdHigh":"left"},"effects":{"schema_std":[-1.6,2],"schema_approval":[-1,1.2],"big5_rumination":[-0.8,1.1]}},{"id":"v13_q10","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"schema_abandonment","is_sensitive":true,"weight":1.25,"context":"凌晨的急诊，你一个人挂着水。第一瓶快见底了，走廊里只有推车的轮子声。","prompt":"护士把表推过来，指了指第一栏：「紧急联系人，后面那格写关系。」","options":[{"key":"A","text":"一个不算太熟的朋友。他不会觉得我麻烦，也不会问太多","effects":{"schema_abandonment":1.9,"schema_deprivation":1.2,"def_fawn":1},"social_desirability":1},{"key":"B","text":"家里人。填完就发定位过去，说清楚我在几楼几床","effects":{"schema_abandonment":-1.8,"mot_belonging":1.2,"att_anxiety":-0.8},"social_desirability":3},{"key":"C","text":"空着交了回去。这种事我自己能处理，不必半夜叫醒谁","effects":{"schema_abandonment":1.7,"att_avoidance":1.4,"def_detach":1.2},"social_desirability":1},{"key":"D","text":"一个一定会来的人，然后在等他的四十分钟里把音量开到最大","effects":{"schema_abandonment":1.6,"att_anxiety":1.4,"big5_alert":1},"social_desirability":2}]},{"id":"v13_q11","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"schema_deprivation","is_sensitive":true,"weight":1.4,"context":"在一起三年，纪念日那天他加班到十点，进门时手里拎着一袋便利店的关东煮，说「今天太忙了，明天补」。","prompt":"你接过那袋东西，心里浮起来的念头更接近下面哪一种？","options":[{"key":"A","text":"说没关系，热了一起吃。那点落差我自己消化掉就好","effects":{"schema_deprivation":1.7,"schema_sacrifice":1,"def_fawn":1},"social_desirability":2},{"key":"B","text":"告诉他我今天想要的不只是关东煮，并且说清楚想要什么","effects":{"schema_deprivation":-1.8,"val_boundary":1.4,"light_kant":1},"social_desirability":1},{"key":"C","text":"什么也不说，接下来一周都淡淡的，等他自己发现哪里不对","effects":{"schema_deprivation":1.8,"schema_mistrust":1,"covert_control":0.8},"social_desirability":0},{"key":"D","text":"其实没觉得缺什么，两个人在厨房吃完，还觉得这样也挺好","effects":{"schema_deprivation":-1.7,"mot_belonging":1.2,"big5_compassion":1.2},"social_desirability":3}]},{"id":"v13_q12","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"schema_entitlement","is_sensitive":false,"weight":0.85,"prompt":"三个月前买的耳机坏了，保修刚过十四天。店员语气很客气，说按规定只能自费修。","scale":{"left":"我在这家店买了五年，就为了这十四天跟我讲规定？","right":"算了，规定写在那里，这十四天我自己认","sdHigh":"right"},"effects":{"schema_entitlement":[2,-1.8],"val_boundary":[1.4,-1],"big5_compliance":[-1,1.2]}},{"id":"v13_q13","type":"forced_choice","stealth_mode":"mirror","layer":"explicit","mirror_key":"schema_defect","is_sensitive":true,"weight":1.4,"context":"小学三年级那次家长会，老师当着所有人的面念了你的名字和名次。你妈回家的路上一直没说话。","prompt":"这个画面留到今天，长成了你身上的一种反应：","options":[{"key":"A","text":"记得很清楚，那种脸热到现在还会在我开口发言前冒出来","effects":{"schema_defect":2,"big5_rumination":1.4,"schema_approval":1},"social_desirability":1},{"key":"B","text":"记得，但我已经不拿她那把尺子量自己，那是她的焦虑","effects":{"schema_defect":-1.7,"val_boundary":1.4,"schema_std":-1.2},"social_desirability":3},{"key":"C","text":"细节已经模糊了，只知道我到现在都怕被人当众点评一句","effects":{"schema_defect":1.7,"schema_approval":1.2,"big5_alert":1},"social_desirability":1},{"key":"D","text":"记得。而且我对自己孩子那张成绩单，比我妈当年还在意","effects":{"schema_defect":1.6,"schema_std":1.4,"covert_control":0.9},"social_desirability":0}]},{"id":"v13_q14","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"schema_mistrust","is_sensitive":false,"weight":1.4,"context":"一位共事多年的朋友拉你合伙做点事，合同是他自己拟的，递过来时说「我们之间不用这么麻烦」。","prompt":"你把那份合同翻到最后一页，其实在翻之前就知道自己会不会签。","options":[{"key":"A","text":"签。他敢把话说成这样，说明他压根没给自己留后手","effects":{"schema_mistrust":-1.8,"light_humanism":1.4,"virtue_kindness":0.9},"social_desirability":3},{"key":"B","text":"笑着签，同时找个懂行的朋友把条款过一遍，该改的直接提","effects":{"schema_mistrust":1.6,"def_intellectual":1.4,"covert_control":0.9},"social_desirability":2},{"key":"C","text":"越熟越要把话说在前面，坐下来把分成和退出谈清楚再落笔","effects":{"schema_mistrust":-1.6,"val_boundary":1.4,"light_kant":1.2},"social_desirability":2},{"key":"D","text":"嘴上应着，回头找个理由拖着不签，事归事，人归人","effects":{"schema_mistrust":1.9,"def_fawn":1,"dark_mach":0.8},"social_desirability":0}]},{"id":"v13_q15","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"schema_isolation","is_sensitive":true,"weight":1.2,"context":"部门聚餐，你坐在长桌最靠里的位置。一整顿饭你都在听，散场时有人说了句「下次再约」。","prompt":"回去的路上，这件事会以什么方式留在你身上？","options":[{"key":"A","text":"有点闷。到家把这顿饭从头到尾复盘一遍，想自己哪句说错了","effects":{"schema_isolation":1.8,"big5_rumination":1.4,"schema_defect":0.9},"social_desirability":1},{"key":"B","text":"没觉得是事。本来就不是一路人，明天照常上班，该笑就笑","effects":{"schema_isolation":1.7,"def_detach":1.3,"att_avoidance":1},"social_desirability":2},{"key":"C","text":"第二天主动约了桌上聊得最来的同事喝咖啡，把这条线接上","effects":{"schema_isolation":-1.9,"mot_belonging":1.4,"val_boundary":1},"social_desirability":2},{"key":"D","text":"散场时多留了十分钟，帮着把账结了、酒拎回去，反正顺路","effects":{"schema_isolation":-1.7,"schema_sacrifice":1.3,"big5_compliance":1.2},"social_desirability":3}]},{"id":"v13_q16","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"schema_defect","is_sensitive":true,"weight":0.85,"prompt":"洗完澡，镜子上全是雾。你抬手抹开一块，正好是自己的脸。","scale":{"left":"盯着看很久，把每一处松、每一处不对称都挑出来","right":"看一眼就走，镜子里没什么值得多看的","sdHigh":"right"},"effects":{"schema_defect":[2,-1.6],"big5_rumination":[1.2,-0.9],"schema_std":[1,-0.6]}},{"id":"v13_q17","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"schema_values","is_sensitive":true,"weight":1.3,"context":"小时候那个房间早就拆了。缺的东西没法补，可你现在还在替它付账。","prompt":"如果时间能倒回去，你最想先补上哪三样，按先后排出来。","values":[{"key":"steady","label":"一个会一直留在原地的大人","effects":{"schema_abandonment":1.6,"mot_belonging":1,"att_anxiety":0.8}},{"key":"ask","label":"有人认真问过一句「你今天怎么样」","effects":{"schema_deprivation":1.6,"big5_compassion":0.8,"mot_belonging":0.8}},{"key":"accept","label":"不用表现好也能被留下的那种接纳","effects":{"schema_defect":1.6,"schema_approval":0.8,"virtue_humility":0.6}},{"key":"word","label":"一个说话算话的大人","effects":{"schema_mistrust":1.6,"light_kant":0.8,"val_moral":0.6}},{"key":"room","label":"一个不用装也能待着的房间","effects":{"schema_isolation":1.6,"def_detach":0.6,"mot_belonging":0.8}},{"key":"enough","label":"有人说过「你已经够好了」","effects":{"schema_std":1.6,"schema_approval":0.8,"big5_compassion":0.6}},{"key":"hold","label":"有人先照顾过我一次","effects":{"schema_sacrifice":1.6,"big5_compassion":0.8,"mot_belonging":0.6}},{"key":"allow","label":"被允许无理取闹一次","effects":{"schema_entitlement":1.6,"sin_pride":0.8,"mot_autonomy":0.6}}]},{"id":"v13_q18","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"schema_energy","is_sensitive":true,"weight":1.3,"context":"有些力气每天都在花，却从来不进日程表，也不算在任何一项支出里。","prompt":"现在把这一百点「隐形力气」分下去——你会看清自己其实在养什么。","items":[{"key":"alert","label":"提前预演最坏的那种结局","dim":"schema_negativity","base":0,"gain":1},{"key":"prove","label":"反复确认自己有没有被讨厌","dim":"schema_approval","base":0,"gain":1},{"key":"exit","label":"在每段关系里先留好退路","dim":"schema_mistrust","base":0,"gain":1},{"key":"caretake","label":"先照顾别人的情绪再轮到自己","dim":"schema_sacrifice","base":0,"gain":1},{"key":"polish","label":"把已经够好的东西再改一遍","dim":"schema_std","base":0,"gain":1},{"key":"cover","label":"遮住自己觉得不够好的那部分","dim":"schema_defect","base":0,"gain":1}]}]},"vol14":{"volume_id":"vol14","index":14,"title":"财富潜意识","subtitle":"四大金钱脚本与五种时间观","theme_color":"#8A6D3B","estimated_minutes":5,"intro":"这一卷不测你会不会赚钱。它只测一件事：钱在你身上最先唤起的反应——是想躲开，是抬头看，是拿它当尺子，还是攥着不敢松手。顺带看看你和时间的关系：力气放在已经过去的、正在发生的，还是还没来的日子上。十八个场景没有标准答案，也不存在所谓正确的金钱观。","dimensions":["money_avoid","money_worship","money_status","money_vigilance","time_past_neg","time_past_pos","time_present_hed","time_present_fate","time_future"],"questions":[{"id":"v14_q01","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"money_status","is_sensitive":false,"weight":1.4,"context":"六个人一顿吃掉七百多，人均不算便宜。结账时，那位收入明显比你宽裕的朋友先把卡递了过去，说这顿算他的，别扫兴。走出餐厅，夜风有点凉。","prompt":"沿着这条路往地铁站走，你心里最先起来的那句是——","options":[{"key":"A","text":"回家路上就在算：下次得挑同等价位的地方回请一次，不然心里过不去","effects":{"money_status":1.8,"money_vigilance":1.2,"sin_pride":1,"val_standard":0.8},"social_desirability":1},{"key":"B","text":"大方道谢收下，记住他最近在找的那张小众唱片，下次送他不必拼价格","effects":{"money_status":-1.6,"virtue_charity":1.2,"mot_belonging":1,"money_vigilance":-0.8},"social_desirability":3},{"key":"C","text":"心里松了口气，把这顿省下的钱当晚就转进那个专门存着的账户","effects":{"money_vigilance":1.6,"time_future":1.4,"mot_security":1.2,"money_status":-0.8},"social_desirability":2},{"key":"D","text":"没多想，只提议再往前走两步，去那家还开着的店坐一会儿，今晚还没散","effects":{"time_present_hed":1.8,"money_avoid":1.2,"mot_hedonism":1.4},"social_desirability":1}]},{"id":"v14_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"money_avoid","is_sensitive":true,"weight":0.85,"context":"十一点四十，客厅只剩冰箱在响。手机又亮了一下：本期账单可申请分期，最长十二期。","prompt":"这条短信你已经划掉过两次。今晚屏幕又亮起来，你的手指停在上面。","scale":{"left":"点开，把总额、利息和还款日一笔一笔看清楚","right":"再放一晚，明天脑子清醒了再处理","sdHigh":"left"},"effects":{"money_avoid":[-2,2],"money_vigilance":[1.4,-1.2],"big5_alert":[-0.4,1],"time_future":[1.4,-1.2]}},{"id":"v14_q03","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"money_vigilance","is_sensitive":false,"weight":1.25,"context":"和朋友吃完结账，小票上少算了一道一百多的硬菜。收银台后面排着队，服务生正低头核对下一桌的单子。","prompt":"你把小票折了一下，最先动的是——","options":[{"key":"A","text":"把那张单子递回去，指着菜名说这道没算，让他重开一张","effects":{"money_vigilance":1.8,"val_moral":1.2,"virtue_charity":1},"social_desirability":3},{"key":"B","text":"没回去，但把这件事记住了，下次来多点一道，把这份抹平","effects":{"money_vigilance":0.8,"val_moral":0.6,"mot_belonging":1,"sin_greed":-0.6},"social_desirability":2},{"key":"C","text":"收好走人，一百多对这家店不算什么，就当系统出错","effects":{"money_vigilance":-1.8,"val_moral":-1.4,"sin_greed":1},"social_desirability":0},{"key":"D","text":"心里有点不舒服：连自己家的账都算不明白，这店开不长","effects":{"money_vigilance":1.4,"big5_alert":1.2,"val_standard":1,"virtue_charity":-0.8},"social_desirability":1}]},{"id":"v14_q04","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"time_past_pos","is_sensitive":false,"weight":0.85,"prompt":"随机播放跳出一首十几年前的老歌，前奏三个音，你就知道是哪一首。","scale":{"left":"那几年整块回来了，连当时坐在谁旁边、窗外几点钟都记得","right":"听两句就划过去了，那时候的我，现在不太想回去","sdHigh":"left"},"effects":{"time_past_pos":[2,-2],"time_past_neg":[-1.2,1.6],"mot_belonging":[1,-0.6],"big5_rumination":[0.8,-0.4]}},{"id":"v14_q05","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"time_present_fate","is_sensitive":false,"weight":1.4,"context":"车牌摇号结果出来，第三十八次没中。群里有人发了一句「命里有时终须有」，下面一排人在笑。","prompt":"你把页面关掉，抬头看了一眼窗外。这一刻，你心里更靠近哪一种说法？","options":[{"key":"A","text":"这东西本来就不由我，中不中都得过日子，关了就不想了","effects":{"time_present_fate":1.8,"wv_causal":1.2,"def_detach":1,"mot_mastery":-1.2},"social_desirability":2},{"key":"B","text":"三十八次说明路子错了：换个区、换种方式，先把规则重读一遍","effects":{"time_present_fate":-1.6,"time_future":1.6,"mot_mastery":1.4,"big5_industry":1},"social_desirability":3},{"key":"C","text":"名额就那么多，普通人排到天荒地老也轮不上，早看明白了","effects":{"time_present_fate":1.4,"lv_suffering":1.2,"sin_envy":0.8,"def_detach":0.8},"social_desirability":1},{"key":"D","text":"回了句玩笑，顺手约了晚上吃火锅，把这事当个段子讲出去","effects":{"time_present_hed":1.6,"lv_suffering":-1.2,"mot_hedonism":1,"wv_causal":0.6},"social_desirability":2}]},{"id":"v14_q06","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"money_worship","is_sensitive":false,"weight":0.85,"context":"婚宴中场，隔壁桌两个人一直在算：这一桌多少钱、酒是什么牌子、新郎家做什么生意。","prompt":"你端着杯子听了几句，冰块化了一半。哪一种说法更接近你私下信奉的？","scale":{"left":"钱确实是这个世界最硬的通行证，只是很少有人肯这么说","right":"我更想知道这两个人以后怎么过，一桌多少钱跟他们过得好不好无关","sdHigh":"right"},"effects":{"money_worship":[2,-2],"money_status":[1.2,-1.2],"lv_happiness":[-1.2,1.2],"sin_greed":[1,-1]}},{"id":"v14_q07","type":"forced_choice","stealth_mode":"normalization","layer":"stealth","mirror_key":"money_avoid","is_sensitive":true,"weight":1.4,"context":"周四晚上八点，房东发来消息说这房子他打算卖了，这两天中介会带人来看。第二天你正吃着饭，门铃响了，进来三个人，其中一个一进门就拿卷尺量阳台。","prompt":"中介收着卷尺，笑着问：要是接着租，一个月能出到多少。你放下筷子，答的是——","options":[{"key":"A","text":"说自己还没算过，让他们先随便看，转身进厨房把池子里泡着的碗一个个洗完","effects":{"money_avoid":1.8,"def_detach":0.8,"mot_security":-0.8,"big5_order":0.6},"social_desirability":2},{"key":"B","text":"把心里那个数字报出去，顺带问清违约金怎么算、房子卖了还能住到几月份","effects":{"money_avoid":-2,"big5_alert":0.8,"mot_security":1.4,"big5_order":1},"social_desirability":3},{"key":"C","text":"笑着把话绕过去，反过来问他们这房子现在一平挂多少、已经挂了多长时间","effects":{"money_status":1.6,"big5_alert":1,"cog_speed":0.8},"social_desirability":1},{"key":"D","text":"当晚把附近在租的房子全翻一遍，列成一张表，第二天想清楚了再回他话","effects":{"money_avoid":-1.6,"time_future":1.8,"big5_order":1},"social_desirability":0}]},{"id":"v14_q08","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"time_present_hed","is_sensitive":true,"weight":0.85,"context":"十二点四十，外卖软件里只剩那一家还开着，满减差八块。冰箱里有鸡蛋和半棵白菜。明早七点要起床，闹钟已经设好了。","prompt":"手指停在外卖页那个「去结算」的按钮上，久久没有按下去。","scale":{"left":"点了，今天已经够累，这顿算补给自己的，明天的事明天再想","right":"关掉软件去煮两个蛋，二十分钟也就过去了，钱和睡眠都省下来","sdHigh":"right"},"effects":{"time_present_hed":[2,-1.8],"time_future":[-1.6,1.8],"mot_hedonism":[1.4,-1],"big5_industry":[-0.8,1]}},{"id":"v14_q09","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"money_worship","is_sensitive":false,"weight":1.4,"context":"周六回家，你妈从柜子里搬出一桶油和一袋米，说银行的人讲得清楚：二十万存三年，年化四点五，还送这些。她把合同推到你面前，问你要不要也存一点。","prompt":"你翻着那几张纸，脑子里冒出来的念头，和纸面上印的字不在一条线上：","options":[{"key":"A","text":"先把风险等级和赎回条款翻出来，再问她这笔钱三年之内到底会不会用上","effects":{"money_worship":-1.8,"big5_alert":1,"mot_security":1.2,"big5_order":0.6},"social_desirability":3},{"key":"B","text":"心里其实有些服气：一年利息九千，比我加班一年攒下的还多，稳就是本事","effects":{"money_worship":2,"sin_greed":0.8,"mot_security":0.8},"social_desirability":0},{"key":"C","text":"劝她别全押在一处，留出三万能随时取的，剩下的再分，别为那点利息锁死","effects":{"money_worship":-1.6,"mot_security":1.2,"big5_alert":0.8},"social_desirability":2},{"key":"D","text":"笑她一桶油就被收买了，转头自己打开手机，翻同类产品的收益排行看了半小时","effects":{"money_worship":1.6,"sin_greed":0.9,"big5_open":0.6},"social_desirability":1}]},{"id":"v14_q10","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"money_avoid","is_sensitive":true,"weight":1.25,"context":"家族群里表弟发了婚礼请帖，艾特了所有人。你想起三年前他借的那三千，说好两个月还，中间提过两次，后来谁都没再提。","prompt":"手机还在手上，消息往上翻到那笔转账那一行，三秒之内你动了：","options":[{"key":"A","text":"先回一句恭喜，红包照旧包，那三千一个字不提——今天不该由我先开口","effects":{"money_avoid":1.8,"virtue_kindness":1.2,"mot_belonging":1},"social_desirability":3},{"key":"B","text":"把转账记录截了图发过去，跟一句：这个月我也紧，那三千你先还我","effects":{"money_avoid":-1.8,"big5_order":0.8,"val_standard":0.8},"social_desirability":1},{"key":"C","text":"在群里抢了个红包就退出去，请帖的事，打算拖到婚礼前三天再说","effects":{"money_avoid":1.6,"def_detach":1,"cog_speed":0.8},"social_desirability":0},{"key":"D","text":"翻出这月还剩多少，红包按老规矩包足，亲戚面前这份礼数一点不能短","effects":{"money_status":1.6,"mot_belonging":1.2,"virtue_charity":0.9},"social_desirability":2}]},{"id":"v14_q11","type":"stealth_scale","stealth_mode":"projection","layer":"stealth","mirror_key":"time_past_neg","is_sensitive":true,"weight":0.85,"context":"凌晨两点十七，你在二手平台上看见自己去年卖掉的那台相机，挂在同一个人手里，标价比你卖时高了两千。底下有九个人点了想要。","prompt":"你把那张照片放大，又缩小，屏幕的光照在脸上。","scale":{"left":"想起当时为什么卖：那笔钱填了家里哪个窟窿，那年账是怎么转开的","right":"想的是现在把它接回来，钱还能再挣，这台机器只有一台，错过就没了","sdHigh":"left"},"effects":{"time_past_neg":[2,-1.6],"time_present_hed":[-1.6,1.8],"mot_hedonism":[-1.2,1.4],"mot_belonging":[0.8,-0.6]}},{"id":"v14_q12","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"money_status","is_sensitive":false,"weight":1.4,"context":"你妈在电话里说，表姐家孩子满月，你表哥包了三千。她补了一句：你看着办，别让人觉得你在外面过得不行。","prompt":"挂了电话，转账页面停在金额那一栏，光标一直闪。你手上在掂的分量，其实是——","options":[{"key":"A","text":"按表哥的数目包过去，这种事上先低一头，往后年年都得低着那一头","effects":{"money_status":1.8,"sin_pride":1,"mot_belonging":0.8},"social_desirability":1},{"key":"B","text":"包两千，比表哥少一档但不难看，剩下的钱留着交下个季度的房租","effects":{"money_status":1.6,"mot_security":1,"big5_order":0.6},"social_desirability":2},{"key":"C","text":"包一千，孩子满月跟我包多少钱没关系，我妈那边我自己去说清楚","effects":{"money_status":-1.8,"mot_autonomy":1.2,"val_standard":1},"social_desirability":3},{"key":"D","text":"翻出当年自己办事收的礼簿，照着上面的数目一笔笔回过去，不多不少","effects":{"money_vigilance":1.8,"time_past_pos":1.6,"val_standard":0.8},"social_desirability":2}]},{"id":"v14_q13","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"time_future","is_sensitive":true,"weight":0.85,"context":"缴费单从窗口打出来，拖到地上还卷了一圈，父亲在病房里睡着。护士说下周还要再做一次。你哥在走廊尽头打电话，声音压得很低。","prompt":"排队的人还没挪到你，你靠着走廊那面墙，脑子里先翻起来的是哪一叠纸？","scale":{"left":"这几年为看病花出去的每一笔，谁垫过、谁还没还，都记得清清楚楚","right":"过去的先不算，接下来三个月要准备多少、从哪凑，才叫正事","sdHigh":"right"},"effects":{"time_past_neg":[2,-1.6],"time_future":[-1.6,1.8],"lv_suffering":[1.4,-0.6],"mot_security":[-0.6,1.2]}},{"id":"v14_q14","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"money_worship","is_sensitive":false,"weight":1.4,"context":"小区门口新开的店，扫码进群送一板鸡蛋。队伍绕了两圈，前面有退休的教授，也有抱着孩子的年轻妈妈，都在算这一板值七块八。","prompt":"你站在队尾，听见前面有人笑着说时间不值钱。你心里更认下面哪一句。","options":[{"key":"A","text":"钱是最实在的东西：七块八攥在手里是硬的，体面那东西摸不着也换不来米","effects":{"money_worship":1.8,"val_standard":1,"lv_happiness":-0.8},"social_desirability":0},{"key":"B","text":"一板鸡蛋换一个微信号，店家不亏我也不亏，各人算各人心里那本账","effects":{"money_vigilance":1.8,"big5_alert":0.8,"cog_speed":0.8},"social_desirability":2},{"key":"C","text":"排着排着想起小时候跟奶奶排队领鸡蛋，那时候队伍里全是熟人，谁也不急","effects":{"time_past_pos":1.8,"mot_belonging":1.2,"lv_happiness":0.8},"social_desirability":1},{"key":"D","text":"没排队，进去按原价买了一板：七块八换二十分钟，这笔账我觉得值","effects":{"money_worship":-1.6,"mot_autonomy":1.2,"lv_happiness":0.6},"social_desirability":3}]},{"id":"v14_q15","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"time_past_neg","is_sensitive":true,"weight":1.3,"context":"搬家收拾到柜子最底层，一张旧当票从柜脚下面滑出来，纸已经发黄，日期是七年前。押的东西你还有印象，是一块表，表带断过一次。","prompt":"你蹲在地上，把它从灰里捡起来的那三秒，身体已经先做了动作：","options":[{"key":"A","text":"捏在手里看了三秒，直接塞进垃圾袋：那两年的账，不想再从头翻一遍","effects":{"time_past_neg":1.8,"def_detach":1.2,"lv_suffering":0.8},"social_desirability":1},{"key":"B","text":"拍了张照存进相册，打开计算器按现在的利息重算，看当年到底亏掉多少","effects":{"money_vigilance":1.8,"time_past_neg":1.6,"big5_alert":0.6},"social_desirability":2},{"key":"C","text":"坐在还没拆开的纸箱上发了会儿呆，想起那年冬天连暖气都不敢开","effects":{"time_past_neg":1.6,"lv_suffering":1.2,"mot_security":1},"social_desirability":1},{"key":"D","text":"笑了一声就撕成两半扔掉，那种日子没什么好回想，苦就是苦，不掺别的","effects":{"time_past_pos":-1.8,"def_detach":1.2,"mot_autonomy":0.8},"social_desirability":2}]},{"id":"v14_q16","type":"stealth_scale","stealth_mode":"projection","layer":"stealth","mirror_key":"time_future","is_sensitive":false,"weight":0.85,"context":"你算了一下，卡里的钱不上班大概能撑七个月。地铁进站，上来一群刚下班的人，脸上都是那种说不清的表情，包带压着西装。","prompt":"「七个月」这个数字在脑子里转，你把手机锁了屏，隔了两秒又按亮。","scale":{"left":"七个月是可以排的：每月花多少、第几个月必须接上，先列出来","right":"七个月就是七个月，先过好这周，真到那天总有办法，到时候再说","sdHigh":"left"},"effects":{"time_future":[1.8,-1.6],"time_present_fate":[-1.8,1.6],"mot_security":[1.2,-0.8],"big5_alert":[0.8,-0.6]}},{"id":"v14_q17","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"money_values","is_sensitive":false,"weight":1.3,"context":"你在废纸上算了一笔账：如果突然多出十万，先填掉该填的窟窿，真正能自己支配的大概七万。桌上摆着八张纸条，每张写着一种花法，纸角被风扇吹起来。","prompt":"只能从这八种里挑三样，按你最想先动的那三样依次点选。","values":[{"key":"debt","label":"把欠的账一次还清，从此不用看还款日","effects":{"money_vigilance":1.6,"mot_security":1.2,"time_future":1.6}},{"key":"parents","label":"给爸妈换台舍不得买的空调，再做次体检","effects":{"time_past_pos":1.6,"mot_belonging":1.2,"virtue_kindness":1}},{"key":"retrain","label":"报一个能换赛道的课，把周末全砸进去","effects":{"time_future":1.6,"mot_mastery":1.2,"big5_industry":0.8}},{"key":"replace","label":"换掉用了六年的手机，和开机三分钟的电脑","effects":{"time_present_hed":1.6,"mot_hedonism":1.2,"big5_order":0.6}},{"key":"travel","label":"去一个一直想去的地方，把年假一次用完","effects":{"time_present_hed":1.6,"mot_hedonism":1,"mot_autonomy":0.8}},{"key":"invest","label":"买一只指数基金放着，十年之内都不看","effects":{"money_worship":1.6,"time_future":1.6,"mot_security":0.8}},{"key":"cash","label":"留成随时能取的现金，别的什么都不做","effects":{"money_vigilance":1.6,"mot_security":1.4,"money_avoid":1.6}},{"key":"roof","label":"修好老家那个漏雨的屋顶，留一条退路","effects":{"time_past_pos":1.6,"mot_belonging":1.2,"lv_anchor":0.8}}]},{"id":"v14_q18","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"money_energy","is_sensitive":false,"weight":1.3,"context":"每月工资到账那晚，手机里一堆事等着你：账单、定投、要出的礼、想买但不急的包。你手上只剩一百点注意力，分完就睡。","prompt":"把这一百点注意力分到这六件事上，加起来正好一百，多一点少一点都不行。","items":[{"key":"track","label":"把这月的账一笔笔对完，看钱到底去了哪儿","dim":"money_vigilance","base":0,"gain":1},{"key":"plan","label":"看一眼定投，把下个月自动划走的日子排好","dim":"time_future","base":0,"gain":1},{"key":"face","label":"想清楚这个月哪些场合要出钱、该包多少","dim":"money_status","base":0,"gain":1},{"key":"skip","label":"把账单短信一删，等哪天心情好了再一起看","dim":"money_avoid","base":0,"gain":1},{"key":"treat","label":"算算还能拿出多少，去吃一顿像样的","dim":"time_present_hed","base":0,"gain":1},{"key":"earn","label":"只盯进账：怎么让下个月多出两千块","dim":"money_worship","base":0,"gain":1}]}]},"vol15":{"volume_id":"vol15","index":15,"title":"冲突剧场","subtitle":"TKI 五种冲突模式与 PAC 沟通自我态","theme_color":"#9A5643","estimated_minutes":4,"intro":"冲突发生后的头三十秒，往往不是你决定的。这一卷只看那三十秒：在话出口之前，你的身体先做了什么——把位置摆明，先把场面接住，还是先退开一步。五种模式、三种自我态，没有哪一种更高级，只有它在这一场里是否合用。","dimensions":["tki_competing","tki_collaborating","tki_compromising","tki_avoiding","tki_accommodating","pac_parent","pac_adult","pac_child"],"questions":[{"id":"v15_q01","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"tki_competing","is_sensitive":true,"weight":1.4,"context":"你加班到十点回家。厨房水槽里堆着中午的碗，对方靠在沙发上看剧。你说了一句「碗能不能顺手洗掉」，他抬了下头，回了一句。","prompt":"那句话落地的两秒里，你嘴里最先冲出来的是哪一句？","options":[{"key":"A","text":"「我衣服是堆了三天，我说的今天是这口碗。两件事别混着算，我们只谈这一件。」","effects":{"pac_adult":1.8,"tki_collaborating":1.6,"cog_independent":0.8,"light_kant":0.6},"social_desirability":3},{"key":"B","text":"「我一天到晚挑毛病？那这个月你洗过几次碗，现在就把数摆出来。」","effects":{"tki_competing":1.9,"pac_parent":1.6,"def_attack":1.2,"sin_wrath":0.8},"social_desirability":0},{"key":"C","text":"「行，那我洗。」说完走去拧开水龙头，背对着他把碗一个个冲干净。","effects":{"tki_accommodating":1.9,"pac_child":1.4,"def_fawn":1.2,"big5_compliance":1},"social_desirability":1},{"key":"D","text":"「算了，你继续看吧。」把包放下，转身进卧室关上门，今晚不再多说一个字。","effects":{"tki_avoiding":1.9,"pac_child":1.2,"def_detach":1.4,"big5_rumination":0.8},"social_desirability":1}]},{"id":"v15_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"tki_compromising","is_sensitive":false,"weight":0.85,"prompt":"合租的人把你放在阳台的两箱书挪进了储物间，腾出地方放他的健身器材。你回来时他说：「至于吗，又不是给你扔了。」这件事你最后处理的方式更接近——","scale":{"left":"把书搬回来，然后跟他把公共区域怎么用一条条说清楚，写下来贴在冰箱上。","right":"自己重新找个角落收好，之后重要的东西都收回房间，这件事不再提起。","sdHigh":"left"},"effects":{"tki_compromising":[1.9,-1.4],"tki_collaborating":[1.6,-1.4],"tki_accommodating":[-1.2,1.8],"big5_compliance":[-1,1.2]}},{"id":"v15_q03","type":"stealth_scale","stealth_mode":"projection","layer":"stealth","mirror_key":"pac_parent","is_sensitive":true,"weight":0.85,"prompt":"你和伴侣说好不办婚礼，只把两边亲戚聚一顿。你妈知道后在电话里哭了半小时，说亲戚都通知了，你让她以后怎么见人。挂了电话，屋里很安静——你心里最响的那一句，带着怎样的语气？","scale":{"left":"婚是我们两个人的事，亲戚那边我一家一家去解释，她难受几天会过去。","right":"她说得对，亲戚都通知了，我这样确实不像话，是我们太只顾自己了。","sdHigh":"left"},"effects":{"pac_parent":[-1.6,1.9],"pac_adult":[1.8,-1.2],"tki_accommodating":[-1,1.4],"att_anxiety":[-0.6,0.9]}},{"id":"v15_q04","type":"forced_choice","stealth_mode":"ipsative","layer":"stealth","mirror_key":"pac_adult","is_sensitive":true,"weight":1.4,"context":"周会上，一个跨部门的人当着二十几个人说：「这方案上次就是因为你们组拖了半个月才黄，以后这种事别再交给你们。」你清楚延期是因为他们那边改了四轮需求。","prompt":"会议室安静了两秒。你最先开口的那一句是——","options":[{"key":"A","text":"「延期是事实，原因是需求改了四轮，我这儿有记录。会后我把时间线发群里，大家一起看。」","effects":{"pac_adult":1.9,"tki_collaborating":1.6,"tki_avoiding":-1.2,"cog_independent":0.8},"social_desirability":3},{"key":"B","text":"「上次是谁半夜十一点还在改你们的需求？您要不要现在把这句话说完整？」","effects":{"tki_competing":1.8,"pac_parent":1.2,"big5_assert":1.4,"def_attack":1},"social_desirability":0},{"key":"C","text":"「嗯，我们这边确实也有做得不够的地方，我回去再核一下。」然后没再抬头。","effects":{"tki_accommodating":1.7,"pac_child":1.4,"tki_avoiding":1.2,"big5_compliance":1},"social_desirability":1},{"key":"D","text":"没接话，把本子合上；会后写了一份三页的时间线，抄送给了在场的所有人。","effects":{"tki_avoiding":1.6,"covert_control":1.6,"def_intellectual":1.2,"pac_parent":-1},"social_desirability":2}]},{"id":"v15_q05","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"tki_avoiding","is_sensitive":false,"weight":1.25,"context":"深夜的地铁，你旁边的人把手机外放，音量很大，放的是一段吵架录音。整节车厢没人说话，有人换了个座位。","prompt":"那三十秒里，你身体先动的是——","options":[{"key":"A","text":"起身走到车厢另一头，宁可站着，也不想把今晚搭进去。","effects":{"tki_avoiding":2,"def_detach":1.2,"big5_compliance":1,"pac_child":-0.6},"social_desirability":2},{"key":"B","text":"转头直接说：「麻烦戴个耳机，谢谢。」说完就转回来。","effects":{"pac_adult":1.8,"big5_assert":1.4,"tki_competing":1.4,"tki_avoiding":-1.2},"social_desirability":3},{"key":"C","text":"掏出自己的耳机塞上，心里骂了一路，下车还在想。","effects":{"tki_avoiding":1.6,"big5_rumination":1.6,"sin_wrath":1.2,"tki_competing":-0.8},"social_desirability":1},{"key":"D","text":"站起来去找车头那边的乘务员，说前面有人在放声音。","effects":{"covert_control":1.8,"pac_adult":1.2,"tki_compromising":1,"tki_competing":-0.6},"social_desirability":2}]},{"id":"v15_q06","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"tki_collaborating","is_sensitive":false,"weight":0.85,"prompt":"一个认识十年的朋友，每次约饭都迟到四十分钟以上，今天已经是第三次。你在店里坐了四十分钟，服务员来问了两遍要不要先点。你心里的做法更接近——","scale":{"left":"他到了先不点菜，把这件事摊开说：能不能做到准时，做不到以后就换个方式约。","right":"算了，他这个人一直这样，来了就好好吃，别把一晚上弄坏。","sdHigh":"left"},"effects":{"tki_collaborating":[1.9,-1.4],"tki_accommodating":[-1.4,1.8],"pac_adult":[1.4,-1],"big5_compliance":[-1,1.2]}},{"id":"v15_q07","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"tki_accommodating","is_sensitive":true,"weight":1.4,"context":"这周六说好去你爸妈家吃饭，你妈从周三就开始准备。周四晚上，对方接了个电话，说他最好的朋友这周末从外地过来。挂了电话他说：「要不这周先不去你家了，他一年就来一次。」你说这事上礼拜就定好了，他回你一句。","prompt":"那句话是：「你就是这样，什么事都得按你的来。」这句反咬落下之后，你嘴里最先出来的是哪一句？","options":[{"key":"A","text":"「什么都得按我的来？那你数数，今年有几次是我最后让的。」","effects":{"tki_competing":1.9,"pac_parent":1.4,"def_attack":1,"sin_wrath":0.6},"social_desirability":1},{"key":"B","text":"「上礼拜三我就跟我妈说了，她准备了三天。这次你先陪你朋友，我自己回去。」","effects":{"tki_collaborating":1.7,"pac_adult":1.8,"tki_compromising":1,"light_kant":0.6},"social_desirability":3},{"key":"C","text":"「好，那就不去了，我跟我妈说一声。」然后真去说了，语气很平常。","effects":{"tki_accommodating":1.9,"pac_child":1.4,"def_fawn":1,"big5_compliance":1},"social_desirability":1},{"key":"D","text":"「随你吧。」转身进厨房把水龙头开到最大，剩下的晚上没怎么说话。","effects":{"tki_avoiding":1.9,"pac_child":1.2,"def_detach":1.2,"big5_rumination":0.8},"social_desirability":0}]},{"id":"v15_q08","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"tki_compromising","is_sensitive":true,"weight":0.85,"prompt":"家族群里三十多个人。你姑姑把你去年辞职的事翻出来，配了张截图，@你妈说「孩子这么折腾，你也不管管」。下面几个长辈陆续回了个「唉」。你的手指停在输入框上，更接近哪一种真实反应——","scale":{"left":"「姑姑，这事我私下跟您说清楚，别在群里让我妈难做。」发完把手机扣在桌上。","right":"「都是一家人，说两句就说两句。」回了个笑脸，之后几天没再点开那个群。","sdHigh":"left"},"effects":{"tki_compromising":[1.8,-1.2],"tki_competing":[1.3,-1.1],"pac_adult":[1.5,-1],"tki_avoiding":[-1,1.5]}},{"id":"v15_q09","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"pac_child","is_sensitive":true,"weight":1.2,"context":"家庭群里，你妈发了一张你小时候的照片，配文「那时候多听话」。一圈亲戚在下面接着说话，有人已经开始讲段子了。","prompt":"那条消息弹出来之后的三秒，你最先做出来的是——","options":[{"key":"A","text":"笑一下，跟着回一句「对，那会儿确实听话」，把这一轮轻轻绕过去。","effects":{"tki_accommodating":1.6,"pac_child":1.6,"def_fawn":1.2,"big5_compliance":0.8},"social_desirability":2},{"key":"B","text":"不接，直接私聊她：「妈，这种照片以后别往群里发了。」","effects":{"pac_adult":1.9,"tki_competing":1,"big5_assert":0.8,"tki_avoiding":-0.8},"social_desirability":3},{"key":"C","text":"「我那会儿听话，现在怎么就不听了？」当场把话顶回去。","effects":{"tki_competing":1.9,"pac_child":1.4,"sin_wrath":1.2,"pac_parent":0.6},"social_desirability":0},{"key":"D","text":"把群设成免打扰，接下来大半天没在里面说过一句话。","effects":{"tki_avoiding":1.8,"pac_child":0.8,"def_detach":1.2,"big5_rumination":0.8},"social_desirability":1}]},{"id":"v15_q10","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"tki_competing","is_sensitive":false,"weight":1.4,"context":"去年你把用了六年的胶片相机借给朋友拍婚礼。还回来时镜头有道细划痕，他没提。今年保养时师傅说这道划痕修不了，逆光会挂光。","prompt":"你把师傅的话截图发过去，他回：「这么久了才说，谁知道是不是我弄的。」你打出去的第一段话是——","options":[{"key":"A","text":"「行，那我认了。以后我的东西不再外借，这事到此为止。」","effects":{"tki_avoiding":1.9,"def_detach":1.4,"big5_rumination":0.8,"pac_adult":-0.6},"social_desirability":2},{"key":"B","text":"「不是钱的问题。那台相机跟了我六年，我只是想让你知道这件事。」","effects":{"pac_adult":1.8,"tki_collaborating":1.6,"light_kant":0.8,"tki_competing":-0.8},"social_desirability":3},{"key":"C","text":"「这台我用了六年。你说的那句『谁知道』，我记下了。」","effects":{"tki_competing":1.9,"def_attack":1.4,"sin_wrath":1,"tki_accommodating":-1.1},"social_desirability":0},{"key":"D","text":"「算了算了，是我想多了，你别往心里去。」然后自己把这条咽下去","effects":{"tki_accommodating":1.9,"def_fawn":1.4,"pac_child":1.2,"big5_compliance":1},"social_desirability":1}]},{"id":"v15_q11","type":"stealth_scale","stealth_mode":"normalization","layer":"stealth","mirror_key":"tki_avoiding","is_sensitive":false,"weight":0.85,"prompt":"楼上连着三晚十一点半还在挪家具、拖椅子。你上去敲门，开门的人听完，说：「我们家就这样，你要是受不了，当初就别租这层。」楼道的灯有点闪，你更可能停在哪种位置——","scale":{"left":"「那我们把时间说清楚：十一点以后尽量别挪，其他时候我不干涉。」站在门口把话说完。","right":"「哦，好。」点一下头就下楼，回家把耳塞翻出来。","sdHigh":"left"},"effects":{"tki_avoiding":[-1.8,1.9],"pac_adult":[1.7,-1.2],"tki_competing":[1.3,-1],"big5_compliance":[-1,1.2]}},{"id":"v15_q12","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"pac_parent","is_sensitive":false,"weight":1.4,"context":"合租的人这两个礼拜没倒过一次垃圾，门口那袋已经满了。你说了句「这个该倒了」，他头也没抬，回了一句。","prompt":"「你上次也没倒啊，别装得那么干净。」这话进来之后，你先说的是哪一句？","options":[{"key":"A","text":"「我上次是忘了，这袋我现在倒。从这周起排个班，贴在冰箱上。」","effects":{"pac_adult":1.8,"tki_collaborating":1.6,"tki_compromising":1.2,"light_kant":0.6},"social_desirability":3},{"key":"B","text":"「我装得干净？那你把这两周门口的东西认一下，哪袋是你的。」","effects":{"tki_competing":1.8,"sin_wrath":1,"def_attack":1.2,"pac_parent":0.8},"social_desirability":0},{"key":"C","text":"「你这人怎么总是这样，说了多少遍了。」说完自己拎下楼去扔。","effects":{"pac_parent":1.9,"tki_accommodating":1.2,"sin_pride":0.8,"def_attack":-0.6},"social_desirability":1},{"key":"D","text":"「算了。」把垃圾拎下楼，回来关上门，之后他那份不再管。","effects":{"tki_avoiding":1.8,"def_detach":1.2,"pac_parent":0.6,"big5_rumination":0.8},"social_desirability":2}]},{"id":"v15_q13","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"tki_accommodating","is_sensitive":false,"weight":1.4,"context":"三个人自驾进山，开车的朋友坚持走他查的小路，结果封路，绕了两个小时，天快黑了。后座那位开始抱怨，开车的人把话头转过来：「你当时也没说不行啊。」","prompt":"这一句反咬落下的时候，你嘴里最先出来的是什么样的声音？","options":[{"key":"A","text":"「现在算谁的错没用。先看还有几条路能到，天黑前把今晚的住处定下来。」","effects":{"pac_adult":1.8,"tki_collaborating":1.7,"cog_independent":0.6,"pac_child":-0.6},"social_desirability":3},{"key":"B","text":"「我说了走国道，你说那条路风景好。现在风景看够了吗？」","effects":{"tki_competing":1.9,"def_attack":1.2,"sin_wrath":1,"pac_parent":0.6},"social_desirability":0},{"key":"C","text":"「行，怪我，当时我该拦住你的。」往后座靠回去，不再开口。","effects":{"tki_accommodating":1.9,"pac_child":1.4,"def_fawn":1.2,"big5_compliance":0.8},"social_desirability":2},{"key":"D","text":"「你们定吧，我开车就行。」说完把座椅放低，戴上耳机闭上眼。","effects":{"tki_avoiding":1.8,"def_detach":1.4,"tki_compromising":-1.2,"big5_rumination":0.6},"social_desirability":1}]},{"id":"v15_q14","type":"forced_choice","stealth_mode":"normalization","layer":"stealth","mirror_key":"tki_compromising","is_sensitive":false,"weight":1.4,"context":"你租的车位被一辆不认识的车占了，挡风玻璃上留了电话，打了三次没人接。四十分钟后他从电梯里出来，你说「这是我租的车位」，他上下看了你一眼。","prompt":"「我就停一会儿，这楼里谁不停啊，你急什么。」这句反咬之后，你回的是哪一句？","options":[{"key":"A","text":"「您停可以，但我马上要用车。以后留个能接的电话，今天就这样。」","effects":{"tki_compromising":1.9,"pac_adult":1.7,"light_kant":0.6,"tki_competing":-1},"social_desirability":3},{"key":"B","text":"「我打了四十分钟电话。挪不挪？不挪我现在叫物业下来。」","effects":{"tki_competing":1.9,"big5_assert":1.2,"def_attack":1,"tki_accommodating":-1},"social_desirability":1},{"key":"C","text":"「行，那我停远一点。」把车开出去停到马路边，回来没再看他。","effects":{"tki_accommodating":1.8,"def_fawn":1.2,"big5_compliance":1,"pac_child":1},"social_desirability":2},{"key":"D","text":"「你这话挺有意思。」笑了一下，拍下车牌和车位编号发给物业。","effects":{"covert_control":1.8,"tki_competing":1.2,"pac_adult":1,"def_attack":-0.8},"social_desirability":1}]},{"id":"v15_q15","type":"pyramid_top3","stealth_mode":"ipsative","layer":"stealth","mirror_key":"conflict_values","is_sensitive":false,"weight":1.3,"context":"一场本来不算大的争执，最后没吵完就散了。回家的路上，你脑子里反复回放的往往不是观点对错，而是对方的态度。八种让人受不了的做法，只能留下三样最刺的。","prompt":"冲突里你最受不了对方做的事，哪三件排在最前？请按顺序点选。","values":[{"key":"dismiss","label":"把你的诉求说成「你太敏感了」","effects":{"tki_competing":1.5,"pac_adult":0.5}},{"key":"shutoff","label":"一言不发，转身走开或者干脆关机","effects":{"tki_avoiding":1.5,"att_anxiety":0.5}},{"key":"lecture","label":"用长辈语气告诉你「你应该反省一下自己」","effects":{"pac_parent":1.5,"tki_competing":0.5}},{"key":"flip","label":"把整件事绕回你自己也有问题","effects":{"tki_competing":1.4,"def_attack":0.5}},{"key":"rehearse","label":"翻出三年前的旧账一并算","effects":{"tki_compromising":1.4,"big5_rumination":0.5}},{"key":"coldface","label":"当场不吭声，之后几天用冷脸罚你","effects":{"tki_avoiding":1.4,"covert_control":0.5}},{"key":"plead","label":"突然开始赔笑，说自己什么都行","effects":{"tki_accommodating":1.5,"def_fawn":0.5}},{"key":"crowd","label":"把第三个人拉进来，让别人评理","effects":{"tki_collaborating":-1.4,"def_attack":0.5}}]},{"id":"v15_q16","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"conflict_energy","is_sensitive":false,"weight":1.3,"context":"一场已经冷了四十分钟的争执，两个人都还在客厅。现在给你一百点力气，接下来往哪儿使，基本就写出了你在这类局面里的本能。","prompt":"把一百点分到这六件事上。不必均分，也不必体面。","items":[{"key":"competing","label":"把道理说赢，把立场守住","dim":"tki_competing","base":0,"gain":1},{"key":"collaborating","label":"把两边真正卡住的东西摸出来","dim":"tki_collaborating","base":0,"gain":1},{"key":"compromising","label":"各退一步，先把今晚过完","dim":"tki_compromising","base":0,"gain":1},{"key":"avoiding","label":"找个事走开，等它自己变淡","dim":"tki_avoiding","base":0,"gain":1},{"key":"accommodating","label":"先让他顺心，把自己的话咽回去","dim":"tki_accommodating","base":0,"gain":1},{"key":"pac_adult","label":"把语气拉平，只说具体这件事","dim":"pac_adult","base":0,"gain":1}]}]},"vol16":{"volume_id":"vol16","index":16,"title":"神经边缘","subtitle":"高敏感 × 刺激寻求的四象限","theme_color":"#3B6B6E","estimated_minutes":4,"intro":"这一卷问的不是你内向还是外向，而是你的神经系统在什么音量下最好用：多少刺激算刚好，多少开始过载；别人的情绪涌进来时，你是被填满还是被冲垮。四象限里没有更健康的一格，只有你此刻站的那一格。","dimensions":["hsp_sensory","hsp_emotional","hss_novelty","hss_intensity"],"questions":[{"id":"v16_q01","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"neuro_festival","is_sensitive":false,"weight":1.4,"context":"跨城看一场音乐节，散场时已经十一点半。人群从铁马口往外涌，耳朵里还留着一层嗡响，T 恤贴在背上，回酒店的地铁要坐十四站。","prompt":"走出场地那两百米，你身上最先启动的是哪一样？","options":[{"key":"A","text":"耳机不戴，专挑人少的巷子走，让耳鸣自己退下去，谁说话都先不回","effects":{"hsp_sensory":1.8,"hss_intensity":-1.6,"big5_social":-1,"virtue_temperance":0.7},"social_desirability":2},{"key":"B","text":"还不想回酒店，跟着人流钻进夜市，找更吵的地方把耳朵继续填满","effects":{"hss_intensity":1.9,"hss_novelty":1.7,"hsp_sensory":-1.7,"hsp_emotional":-1.6,"mot_hedonism":1},"social_desirability":1},{"key":"C","text":"先发定位问同行的人走到哪了，散场之后一个人走的那段路最难受","effects":{"hsp_emotional":1.7,"hss_novelty":-1.6,"big5_social":1.1,"att_anxiety":0.9},"social_desirability":2},{"key":"D","text":"在出口回头站了半分钟，心里已经在查下一场在哪，眼睛还有点热","effects":{"hsp_emotional":1.8,"hss_novelty":1.6,"big5_aesthetic":1.1,"big5_rumination":0.7},"social_desirability":3}]},{"id":"v16_q02","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","mirror_key":"neuro_office","is_sensitive":true,"weight":1.4,"context":"开放工位第三排，中央空调在你头顶一格一格换风，声音不高，一直没停。下午三点，同一行字你已经读了三遍，还是读成了别的东西。","prompt":"接下来这半小时，你会怎么把它过掉？","options":[{"key":"A","text":"从包里翻出降噪耳机戴上，提示音也关掉，先把这一小时的安静买回来","effects":{"hsp_sensory":1.9,"hss_intensity":-1.6,"hss_novelty":-1.6,"big5_order":0.8},"social_desirability":3},{"key":"B","text":"真正耗人的不是这声音，是隔壁组那个刚被说完话的人，一整天低着头","effects":{"hsp_emotional":1.8,"hss_intensity":-1.7,"big5_rumination":0.9,"big5_alert":0.8},"social_desirability":3},{"key":"C","text":"把这声音当背景照样写下去，周围有点动静反而更进得去，别人的情绪也不太沾","effects":{"hsp_sensory":-1.8,"hsp_emotional":-1.6,"hss_intensity":1.7,"virtue_temperance":0.9},"social_desirability":1},{"key":"D","text":"起身下楼走一圈，买杯冰的，换个场景再回来，坐着硬扛没有用","effects":{"hss_novelty":1.8,"cog_speed":1,"mot_hedonism":0.9,"big5_order":-0.8},"social_desirability":2}]},{"id":"v16_q03","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"neuro_mall","is_sensitive":false,"weight":0.85,"context":"一层中庭在推新品，四五个柜台同时开着试香纸。你从电梯下来，一股甜混着一股木质调一起进鼻子，后面还压着爆米花的味道。","prompt":"走过那四十米的时候，你身上发生的是——","scale":{"left":"不到十米就开始发晕，得先绕到侧门出去站一会儿，缓过来再往里走","right":"在柜台前停下来，让人再喷第三款，想知道混在一起会变成什么","sdHigh":"right"},"effects":{"hsp_sensory":[2,-2],"hss_novelty":[-1.7,1.7],"hss_intensity":[-1.6,1.7],"big5_aesthetic":[-0.7,1.2]}},{"id":"v16_q04","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"neuro_crash","is_sensitive":false,"weight":1.25,"context":"连轴四天：两场活动、一次通宵改稿、一顿推不掉的饭。周五晚上十点你终于到家，灯没开，包还挂在门口。","prompt":"进门那三秒，身体先去够的是什么？","options":[{"key":"A","text":"直接躺到地板上，等黑暗把耳朵里那层嗡声盖住，什么也不想再听","effects":{"hsp_sensory":1.9,"hss_intensity":-1.7,"big5_social":-1,"def_detach":0.8},"social_desirability":2},{"key":"B","text":"把音响拧开，音量推到能感觉地板在震，先让身体从麻里醒过来","effects":{"hss_intensity":1.9,"hsp_sensory":1.6,"hsp_emotional":-1.6,"mot_hedonism":1},"social_desirability":0},{"key":"C","text":"坐在地上给最熟的那个人发一句「到了」，等一句回话才去洗澡","effects":{"hsp_emotional":1.7,"hss_novelty":-1.6,"att_anxiety":1,"big5_social":0.9},"social_desirability":3},{"key":"D","text":"站在玄关把攒了三天的消息一条条回完，然后问谁还醒着想出去吃口热的","effects":{"hss_novelty":1.7,"hss_intensity":1.6,"hsp_sensory":-1.6,"mot_hedonism":0.9},"social_desirability":1}]},{"id":"v16_q05","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"neuro_night","is_sensitive":false,"weight":1.4,"context":"凌晨一点十分，楼下有辆改装车停在路口等灯，低音一声一声往上顶，玻璃跟着轻轻响。你明天七点要起。","prompt":"躺在床上听它，最先浮上来的反应是哪一个？","options":[{"key":"A","text":"翻身把窗关严，再塞上耳塞，只求那三十秒快点过完，明天还得早起","effects":{"hsp_sensory":1.8,"hss_intensity":-1.7,"big5_order":0.9,"mot_security":0.8},"social_desirability":2},{"key":"B","text":"爬起来走到窗边往下看，一边觉得吵得心慌，一边又很想听它起步","effects":{"hss_intensity":1.8,"hss_novelty":1.7,"hsp_sensory":1.6,"big5_open":0.9},"social_desirability":1},{"key":"C","text":"忽然想到开车的人大概也睡不着，这城市里半夜醒着的人比想的多","effects":{"hsp_emotional":1.8,"hss_novelty":-1.6,"lv_suffering":0.8,"big5_rumination":0.8},"social_desirability":3},{"key":"D","text":"干脆起来下楼买瓶水，顺便看看这个点的街上都还有些什么样的人","effects":{"hss_novelty":1.9,"hsp_sensory":-1.6,"hsp_emotional":-1.6,"cog_speed":1,"mot_hedonism":0.9},"social_desirability":1}]},{"id":"v16_q06","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"neuro_hotpot","is_sensitive":true,"weight":1.4,"context":"六个人的局，坐在最里面那桌。牛油锅在中间滚，蒸汽把眼镜糊住，隔壁桌在划拳，服务员端着盘子从你背后过。已经聊到第三个小时。","prompt":"聊到第三个小时，你身体里冒出来的第一个动作是什么？","options":[{"key":"A","text":"把椅子往外挪半米，别让蒸汽一直扑在脸上，再要一杯冰水压一压","effects":{"hsp_sensory":1.9,"hss_intensity":-1.6,"big5_order":0.8,"virtue_temperance":0.7},"social_desirability":2},{"key":"B","text":"脱掉外套挽起袖子，让锅底再加一档辣，声音也跟着放大一起喊","effects":{"hss_intensity":1.9,"hss_novelty":1.7,"hsp_sensory":-1.7,"mot_hedonism":1,"sin_gluttony":0.9},"social_desirability":1},{"key":"C","text":"注意到对面那个一直没怎么动筷子的人，等会儿想单独问一句他怎么了","effects":{"hsp_emotional":1.9,"hss_novelty":-1.6,"big5_rumination":0.8,"lv_suffering":0.7},"social_desirability":3},{"key":"D","text":"悄悄看了眼表，算着还有多久能走，这些话每一年都是同一套讲法","effects":{"hss_intensity":-1.7,"hsp_emotional":-1.7,"big5_social":-1,"def_detach":0.9},"social_desirability":1}]},{"id":"v16_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"neuro_cinema","is_sensitive":false,"weight":0.85,"context":"零点场，影厅只坐了七个人。预告片一结束，音效直接从后脑砸下来，前排有人低呼了一声，你手里的可乐在晃。","prompt":"接下来的九十分钟，你的注意力主要挂在什么地方？","scale":{"left":"角色伸手去开那扇门的时候，我先替她怕了，一整场都在她身上","right":"越吓越来劲，字幕一出来就在想，有没有更狠的一部可以接着看","sdHigh":"right"},"effects":{"hsp_sensory":[1.9,-1.9],"hsp_emotional":[1.7,-1.7],"hss_intensity":[-1.6,1.8],"def_detach":[-0.8,0.9]}},{"id":"v16_q08","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"neuro_commute","is_sensitive":false,"weight":1.4,"context":"早高峰，你被挤在车门边。对面有人外放着短视频，隔一个人身上有很重的烟味，广播在报一个你没听过的站名。还有六站。","prompt":"这六站里，你身上最可能浮出来的是哪一种状态？","options":[{"key":"A","text":"把耳机音量往上推，闭上眼，只留一小块自己的地方，谁也别碰我","effects":{"hsp_sensory":1.8,"hss_novelty":-1.6,"hss_intensity":-1.6,"big5_social":-0.9},"social_desirability":1},{"key":"B","text":"反而看得很起劲：谁身上有酒味、谁刚哭过一眼就认得，六站不够猜","effects":{"hss_novelty":1.9,"hsp_sensory":1.6,"big5_open":1,"big5_social":0.8},"social_desirability":3},{"key":"C","text":"被那股烟味和短视频的声音一起磨着，胃开始不舒服，只想马上下车","effects":{"hsp_sensory":1.9,"hsp_emotional":1.6,"hss_intensity":-1.7,"big5_alert":0.8},"social_desirability":1},{"key":"D","text":"站着一动不动，什么也没进脑子，到站、下车、上扶梯，一路自动播放","effects":{"hss_intensity":1.7,"hsp_emotional":-1.7,"hsp_sensory":-1.6,"def_detach":1.2},"social_desirability":2}]},{"id":"v16_q09","type":"stealth_scale","stealth_mode":"mirror","layer":"explicit","mirror_key":"neuro_intimacy","is_sensitive":true,"weight":0.85,"context":"他比平时晚回来四十分钟，进门把包放下就坐在床边，鞋也没脱。你端着一杯水进去，他抬了下眼，说「没事，就是有点累」。","prompt":"那杯水放到他手边之后，你这套接收器开到了几档？","scale":{"left":"那句「没事」我一下就听出来了，胸口跟着往下沉，他还没讲我已经在替他难受","right":"他说没事我就先按没事办，等他想讲再讲，我这边的情绪不太会跟着走","sdHigh":"left"},"effects":{"hsp_emotional":[2,-2],"hsp_sensory":[1.8,-1.8],"hss_intensity":[1.6,-1.6],"att_anxiety":[1.2,-1.1],"def_detach":[-1.2,1.2]}},{"id":"v16_q10","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"neuro_travel","is_sensitive":false,"weight":1.4,"context":"到清迈的第二天，原定去的那座庙在修。包车司机说可以改去一个「本地人才去」的市场，也可能白跑一趟。车门开着，同行的人都在看你。","prompt":"司机的钥匙还插在锁孔里，你心里的方向盘先往哪边打？","options":[{"key":"A","text":"白跑也算一趟，让司机往那个市场开，原来那张行程表今天作废","effects":{"hss_novelty":1.9,"hss_intensity":1.6,"big5_open":1,"big5_order":-0.9},"social_desirability":2},{"key":"B","text":"先查那个市场多大、几点收摊，确认不是一片空地，再决定上不上车","effects":{"hss_novelty":-1.7,"cog_ambiguity":-1.1,"big5_order":1.2,"mot_security":0.9},"social_desirability":2},{"key":"C","text":"站在太阳底下忽然有点撑不住，喇叭声一阵阵往脑子里钻，只想回酒店","effects":{"hsp_sensory":1.9,"hss_novelty":-1.6,"hss_intensity":-1.7,"big5_social":-1},"social_desirability":1},{"key":"D","text":"干脆分开走，晚上在夜市碰头，谁也别为谁改掉自己想去的地方","effects":{"hss_novelty":1.7,"mot_autonomy":1.2,"big5_assert":1,"cog_ambiguity":0.8},"social_desirability":1}]},{"id":"v16_q11","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"neuro_bath","is_sensitive":true,"weight":1.3,"context":"冬天，朋友拉你去泡汤。从热水池里出来那一下，室外零下四度，旁边就是冷水池，池边结了层薄霜。刚才有人下去十几秒就爬了上来，肩膀是红的。","prompt":"光脚站在池边的那几秒，哪个念头先动的手？","options":[{"key":"A","text":"直接下去，让那口冷气一口气冲到头顶，上来的时候整个人是醒的","effects":{"hss_intensity":1.9,"hsp_sensory":1.6,"mot_hedonism":1,"big5_open":0.8},"social_desirability":0},{"key":"B","text":"蹲下来先用手试水温，试了两次，还是缩回去转身回了热水池那边","effects":{"hsp_sensory":1.8,"hss_intensity":-1.7,"big5_alert":1,"mot_security":0.8},"social_desirability":2},{"key":"C","text":"站在池边看别人下去，一边想笑一边有点羡慕，脚始终没往前挪","effects":{"hsp_emotional":1.7,"hss_intensity":-1.6,"big5_social":-0.8,"def_detach":0.7},"social_desirability":1},{"key":"D","text":"冷一下热一下来回三四轮，直到耳朵嗡嗡的、有点发晕才肯停下来","effects":{"hss_intensity":1.9,"hsp_sensory":1.7,"sin_gluttony":0.9,"virtue_temperance":-0.9},"social_desirability":0}]},{"id":"v16_q12","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"neuro_ktv","is_sensitive":false,"weight":1.4,"context":"朋友三十岁生日，包了个小包厢。歌放得很大，麦克风偶尔啸叫，桌上七八个空瓶，寿星已经唱哑了，一直把麦往你手里塞。","prompt":"麦到你手上时，这四分钟你打算唱成什么样？","options":[{"key":"A","text":"接了唱，唱完再主动点一首更吵的，把整桌人的声音一起往上顶","effects":{"hss_intensity":1.8,"big5_social":1.2,"big5_assert":1,"hsp_sensory":-1.6},"social_desirability":1},{"key":"B","text":"笑着摆手推掉，坐到最靠门那个位置，替大家倒酒、分蛋糕、拍照","effects":{"hsp_sensory":1.7,"big5_social":-1,"big5_assert":-1,"hss_intensity":-1.7},"social_desirability":3},{"key":"C","text":"只唱一首很慢的，唱的时候整个包厢安静下来，唱完就把麦递回去","effects":{"hsp_emotional":1.8,"big5_aesthetic":1.1,"big5_assert":0.7,"hss_intensity":-1.6},"social_desirability":2},{"key":"D","text":"拿过麦但不唱，把原唱开着当主持，一桌人挨个点歌、互相起哄","effects":{"hss_novelty":1.7,"big5_social":1.2,"big5_assert":1.1,"hsp_sensory":-1.6},"social_desirability":1}]},{"id":"v16_q13","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"neuro_insomnia","is_sensitive":false,"weight":0.85,"context":"凌晨三点二十，你已经醒着四十分钟。冰箱的压缩机一会儿响一下，心跳在枕头里听得很清楚。七点的闹钟还挂着。","prompt":"那四十分钟里，躺着的那具身体在忙什么？","scale":{"left":"数得出身体每一处不对劲：肩、牙关、心跳，越听越清楚，也就越睡不着","right":"忽然觉得这个点挺好，索性不睡了，起来做点白天根本做不了的事","sdHigh":"right"},"effects":{"hsp_sensory":[2,-1.8],"hss_novelty":[-1.6,1.7],"hss_intensity":[-1.7,1.7],"big5_rumination":[1.2,-0.8],"cog_speed":[-1.1,1.1]}},{"id":"v16_q14","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"neuro_values","is_sensitive":false,"weight":1.3,"context":"周五下班前，有人问你周末打算怎么过。你愣了一下，脑子里先浮上来的不是日程，是几种完全不同的两天。假设这八样都在桌上，只能留下三样。","prompt":"一个理想的周末由什么组成？请按顺序点选三样。","values":[{"key":"quiet_room","label":"一整天不出门，房间里只有雨声","effects":{"hsp_sensory":1.7,"big5_social":-0.7,"hss_intensity":-1.7}},{"key":"front_row","label":"挤到最前排，鼓点打在胸口上","effects":{"hss_intensity":1.7,"hsp_sensory":1.7,"big5_social":0.7}},{"key":"strange_city","label":"一个人在没去过的城市走一整天","effects":{"hss_novelty":1.7,"mot_autonomy":0.7,"hsp_emotional":-1.7}},{"key":"close_talk","label":"和最亲的两三个人聊到凌晨三点","effects":{"hsp_emotional":1.7,"big5_social":0.7,"hss_intensity":-1.7}},{"key":"night_market","label":"钻进很吵的夜市，从街头吃到街尾","effects":{"hss_intensity":1.7,"sin_gluttony":0.7,"hsp_sensory":-1.7}},{"key":"one_way_ticket","label":"临时买张票就走，到了再想去哪儿","effects":{"hss_novelty":1.7,"big5_order":-0.7,"hss_intensity":1.7}},{"key":"long_bath","label":"泡很久的澡，然后早早睡下","effects":{"hsp_sensory":1.7,"virtue_temperance":0.7,"hss_intensity":-1.7}},{"key":"sad_film","label":"看一部会难受很久的电影，独自消化","effects":{"hsp_emotional":1.7,"big5_aesthetic":0.7,"hss_novelty":-1.7}}]},{"id":"v16_q15","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"neuro_energy","is_sensitive":false,"weight":1.3,"context":"你有个完全空的周六，从睁眼到睡前没有任何安排，手机可以关机，谁也不会来找你。一百点精力摆在桌上，分完才知道自己在什么音量下恢复得最快。","prompt":"把一百点精力分到这六件事上，你会怎样切这一刀？","items":[{"key":"quiet","label":"一间安静到能听见冰箱电流声的屋子","dim":"hsp_sensory","base":0,"gain":1},{"key":"crowd","label":"很响很挤的现场，灯光一直打在脸上","dim":"hss_intensity","base":0,"gain":1},{"key":"strange","label":"没去过的城市，不做攻略，到了再说","dim":"hss_novelty","base":0,"gain":1},{"key":"confide","label":"把攒了很久的话，对一个人讲到见底","dim":"hsp_emotional","base":0,"gain":1},{"key":"body","label":"热水、长睡、走很远，先把身体养回来","dim":"hsp_sensory","base":0,"gain":1},{"key":"late","label":"到凌晨还不想回家，让今天再长一点","dim":"hss_intensity","base":0,"gain":1}]},{"id":"v16_q16","type":"stealth_scale","stealth_mode":"pressure","layer":"stealth","mirror_key":"neuro_cart","is_sensitive":true,"weight":0.85,"context":"在一起第三年，你们在超市里为一件很小的事僵住。他说了句「随你」，推着车往前走了两步。头顶的音箱在放一首很轻的歌，走道里只有你们两个人。","prompt":"推着车跟在他后面那半分钟，你的反应从哪一层先起来？","scale":{"left":"他一说「随你」我心里就发紧，开始回想这两天哪里出了错，越想越沉","right":"他真要随我，那就照我的来，这种小事翻一遍只会更麻烦","sdHigh":"right"},"effects":{"hsp_emotional":[1.9,-1.7],"hsp_sensory":[1.9,-1.6],"def_detach":[-1.1,1.1],"hss_intensity":[-1.6,1.6]}}]},"vol2":{"volume_id":"vol2","index":2,"title":"性格底色","subtitle":"大五人格的十个微观子维","theme_color":"#4A6B5D","estimated_minutes":5,"intro":"这一卷不谈好坏，只测绘硬件。没有更好的性格，只有更适合的生态位。请在「你通常如此」和「你希望自己如此」之间，选择前者。","dimensions":["big5_open","big5_aesthetic","big5_order","big5_industry","big5_social","big5_assert","big5_compassion","big5_compliance","big5_alert","big5_rumination"],"questions":[{"id":"v2_q01","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_open","is_sensitive":false,"weight":0.85,"prompt":"一场谈话突然拐进了一个你完全陌生的领域，对方开始用它自己的黑话讲得很起劲。你的状态更接近——","scale":{"left":"立刻被勾住，想把这套陌生逻辑拆开来看看","right":"耐心听完，但心里更想回到熟悉的地带","sdHigh":"left"},"effects":{"big5_open":[2,-2],"cog_ambiguity":[1.4,-1.2],"big5_alert":[-0.8,0.8]}},{"id":"v2_q02","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"big5_aesthetic","is_sensitive":false,"weight":1.4,"prompt":"如果要用一整天来换一种体验，你更愿意换到哪一种？","options":[{"key":"A","text":"在一间安静的美术馆里，被某件作品按在原地很久，说不清为什么","effects":{"big5_aesthetic":2,"big5_open":1.2,"sin_lust":0.4,"cog_logic":-0.8},"social_desirability":2},{"key":"B","text":"把一个复杂问题彻底拆开、重装，直到它跑得又快又稳","effects":{"big5_aesthetic":-1.2,"big5_open":1,"cog_global":1.2,"big5_industry":1.4},"social_desirability":2},{"key":"C","text":"和一群很久没见的人待在一起，从下午一直聊到店里打烊","effects":{"big5_aesthetic":-0.6,"big5_social":1.8,"mot_belonging":1.4,"big5_assert":0.6},"social_desirability":1}]},{"id":"v2_q03","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_order","is_sensitive":false,"weight":0.85,"prompt":"出门旅行前的那一晚，你的房间通常是——","scale":{"left":"东西按清单摆好，几点出门都在脑子里排过一遍","right":"大致抓几件就走，到了再看缺什么","sdHigh":"left"},"effects":{"big5_order":[2,-2],"cog_speed":[-1.4,1.4],"big5_alert":[1.2,-1]}},{"id":"v2_q04","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_industry","is_sensitive":false,"weight":1.4,"context":"一件事做到第 80%，剩下的收尾最枯燥也最不出彩，而新的、更有趣的事已经在敲门了。","prompt":"你身体里最先出现的倾向是——","options":[{"key":"A","text":"先把尾巴收干净再开新的，半成品堆着我会一直不踏实","effects":{"big5_industry":2,"big5_order":1.6,"virtue_diligence":1.2,"big5_open":-0.8},"social_desirability":3},{"key":"B","text":"让新的先跑起来，旧的等有情绪了再回去收拾","effects":{"big5_industry":-1.2,"big5_order":-1,"sin_sloth":1.2,"big5_open":1.4},"social_desirability":0},{"key":"C","text":"给自己定一个硬期限，然后在这个期限里把它收掉","effects":{"big5_industry":1.4,"big5_order":1.2,"cog_speed":-0.6,"dark_mach":0.6},"social_desirability":2},{"key":"D","text":"把收尾工作丢给更擅长的人，我只做最前面那段","effects":{"big5_industry":-1.8,"dark_mach":1.2,"mot_mastery":0.8,"big5_compliance":-0.8},"social_desirability":0}]},{"id":"v2_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_social","is_sensitive":false,"weight":0.85,"prompt":"一场持续了三个小时的多人聚会接近尾声。此刻你的电量——","scale":{"left":"越聊越亮，还想再找几个人续摊","right":"只剩百分之十，脑子里已经在想怎么礼貌地先走","sdHigh":"left"},"effects":{"big5_social":[2,-2],"mot_autonomy":[-1,1.4],"att_avoidance":[-1,1.2]}},{"id":"v2_q06","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"big5_assert","is_sensitive":true,"weight":1.2,"context":"十几个人的饭桌上，话题正好停在一个你极其熟悉、也极有判断的领域，而场面开始冷下来。","prompt":"那个冷场出现的第一秒，你的反应是——","options":[{"key":"A","text":"顺着话头就接过去，把场面重新点着，这个位置我很熟","effects":{"big5_assert":2,"big5_social":1.4,"dark_narc":0.8,"big5_compliance":-1},"social_desirability":1},{"key":"B","text":"心里有个完整的观点，但犹豫了两秒，别人先开口了","effects":{"big5_assert":-1.4,"big5_rumination":1.2,"def_fawn":0.8,"big5_social":-0.4},"social_desirability":1},{"key":"C","text":"安静看着，等有人把话递到我面前来，我再开口也不迟","effects":{"big5_assert":-1,"big5_social":-1.2,"att_avoidance":1,"cog_logic":0.8},"social_desirability":1},{"key":"D","text":"抛一个问题出去，让最会讲的人接，我负责听","effects":{"big5_assert":0.4,"big5_social":0.6,"covert_control":1.2,"big5_compliance":0.8},"social_desirability":2}]},{"id":"v2_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_compassion","is_sensitive":false,"weight":0.85,"prompt":"朋友在电话里哭，说的是一件在客观上确实有他自己责任的事。你最先浮现的动作是——","scale":{"left":"先安静听他把委屈倒完，道理等他缓过来再说","right":"忍不住先把问题出在哪讲清楚，讲清楚了他就不难受了","sdHigh":"left"},"effects":{"big5_compassion":[2,-2],"def_intellectual":[-1.2,1.6],"big5_compliance":[0.8,-0.6]}},{"id":"v2_q08","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"big5_compliance","is_sensitive":true,"weight":1.4,"prompt":"两种不舒服，哪一种你更能忍受？","options":[{"key":"A","text":"为了维持表面的和气，把自己真正想说的话咽回去","effects":{"big5_compliance":1.8,"def_fawn":1.4,"sin_wrath":-1,"big5_rumination":1},"social_desirability":2},{"key":"B","text":"把话说明白，哪怕当场气氛变得很僵，之后几天都不舒服","effects":{"big5_compliance":-1.8,"def_attack":1.4,"big5_assert":1.4,"sin_wrath":1},"social_desirability":1}]},{"id":"v2_q09","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_alert","is_sensitive":true,"weight":0.85,"prompt":"一件事进展得太顺利了，顺利到没有任何障碍。你心里那个声音更接近——","scale":{"left":"很安心，事情本来就该这样","right":"反而开始不安，总觉得哪里埋着一个我还没看见的坑","sdHigh":"left"},"effects":{"big5_alert":[-1.8,2],"big5_rumination":[-1,1.4],"cog_ambiguity":[0.8,-1]}},{"id":"v2_q10","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"big5_rumination","is_sensitive":true,"weight":1.25,"context":"晚上十一点四十，你突然想起傍晚在朋友聚会上说的一句话。当时没人接，现在越想越觉得那句话可能让人不舒服。","prompt":"接下来二十分钟，你最可能的状态是——","options":[{"key":"A","text":"在脑子里反复重播那个场面，连别人当时的表情都拿出来分析","effects":{"big5_rumination":2,"big5_alert":1.4,"att_anxiety":1.2,"big5_compassion":0.4},"social_desirability":1},{"key":"B","text":"想一下，判断没什么大事，翻个身就睡过去了，第二天也未必记得","effects":{"big5_rumination":-1.8,"big5_alert":-1,"def_detach":1.2,"att_avoidance":0.8},"social_desirability":2},{"key":"C","text":"干脆发条消息解释一下，不然这一夜都过不去，非说清楚不可","effects":{"big5_rumination":1.2,"att_anxiety":1.6,"def_fawn":1.4,"big5_compassion":0.6},"social_desirability":1},{"key":"D","text":"把这件事当成一个待办记下来，明天直接问他一句就好","effects":{"big5_rumination":-0.8,"cog_logic":1.2,"big5_order":1,"def_intellectual":0.8},"social_desirability":3}]},{"id":"v2_q11","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_open","is_sensitive":false,"weight":0.85,"prompt":"一个你原本坚信的判断，被新出现的证据正面推翻了。你的第一感受是——","scale":{"left":"有点兴奋，又有一块地图被补上了","right":"先不太舒服，需要一点时间才能重新接受这件事","sdHigh":"left"},"effects":{"big5_open":[1.8,-1.8],"sin_pride":[-1,1.2],"cog_independent":[1,-0.8]}},{"id":"v2_q12","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"big5_order","is_sensitive":false,"weight":1.35,"context":"这是你计划了半年的长途旅行，第二天的转机航班临时取消，原本排好的行程全部要重来。同行的人已经开始问「那现在怎么办」。","prompt":"你接下来的样子最可能是——","options":[{"key":"A","text":"迅速重排一遍，混乱只会存在很短一段时间","effects":{"big5_order":2,"big5_industry":1.2,"cog_speed":0.4,"big5_alert":0.4},"social_desirability":3},{"key":"B","text":"表面照旧，心里会为那段被夺走的秩序难受到晚上","effects":{"big5_order":1.4,"big5_rumination":1.6,"big5_alert":1,"def_detach":-0.4},"social_desirability":1},{"key":"C","text":"索性全部推翻，就地换一套完全不同的玩法","effects":{"big5_order":-0.6,"big5_open":1.6,"cog_diverge":1.2,"big5_industry":-0.8},"social_desirability":1}]},{"id":"v2_q13","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_aesthetic","is_sensitive":false,"weight":0.85,"prompt":"走进一个陌生的房间，你最先注意到的通常是——","scale":{"left":"整体的气质：光线、比例、气味，一进门就有感觉","right":"具体的东西：几把椅子、插座在哪、出口通向哪里","sdHigh":"left"},"effects":{"big5_aesthetic":[1.8,-1.8],"cog_global":[1,-1.2],"big5_alert":[-0.8,1.2]}},{"id":"v2_q14","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_industry","is_sensitive":false,"weight":1.4,"prompt":"关于「坚持」这件事，下面哪一句更像你真实的经验？","options":[{"key":"A","text":"坚持靠的是把它变成日常的一部分，靠意志力硬撑撑不了太久","effects":{"big5_industry":1.8,"big5_order":1.6,"virtue_diligence":1.2,"cog_global":0.4},"social_desirability":3},{"key":"B","text":"坚持靠的是一件事足够有意思，够有意思我就能一直做下去","effects":{"big5_industry":-0.6,"big5_open":1.6,"mot_hedonism":1,"virtue_diligence":0.2},"social_desirability":2},{"key":"C","text":"坚持靠的是有人在等我的结果，没有人等我就会散掉","effects":{"big5_industry":0.2,"mot_belonging":1.6,"att_anxiety":1,"big5_order":-0.4},"social_desirability":1},{"key":"D","text":"坚持靠的是把它变成一个不能失败的事，我会给自己造这种局","effects":{"big5_industry":1.4,"dark_mach":1.4,"mot_mastery":1.6,"big5_alert":1},"social_desirability":1}]},{"id":"v2_q15","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_assert","is_sensitive":true,"weight":0.85,"prompt":"一群人讨论到一半，你发现大家正在往一个你觉得明显不对的方向走。你的实际动作是——","scale":{"left":"直接把我的判断摆出来，哪怕现在是少数","right":"先跟着走一段，看看是不是我自己判断错了","sdHigh":"left"},"effects":{"big5_assert":[1.8,-1.8],"cog_independent":[1.4,-1.6],"big5_compliance":[-1.2,1.4]}},{"id":"v2_q16","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"big5_rumination","is_sensitive":true,"weight":1.4,"prompt":"如果一定要选一种，你更愿意接受哪一种自己？","options":[{"key":"A","text":"情绪起伏明显，但每一次都能尝到活着的那种浓度","effects":{"big5_rumination":1.8,"big5_compassion":1.4,"big5_aesthetic":1.2,"big5_alert":0.8},"social_desirability":1},{"key":"B","text":"情绪非常稳，别人很难让你失衡，但也很少真的被什么击中","effects":{"big5_rumination":-1.8,"def_detach":1.4,"big5_alert":-0.8,"big5_compassion":-1},"social_desirability":2}]},{"id":"v2_q17","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"big5_compassion","is_sensitive":true,"weight":0.85,"prompt":"同一件事，两个版本的说法：一个是真心的抱怨，一个是精心修饰的邀功。你通常多快能分辨出来？","scale":{"left":"几乎立刻，语气里那一点不对劲就很明显","right":"常要等事情走过一段，回头才发现哪里不对","sdHigh":"left"},"effects":{"big5_compassion":[1.6,-1.2],"big5_alert":[1,-1.2],"def_project":[-0.6,1]}},{"id":"v2_q18","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_social","is_sensitive":false,"weight":1.35,"prompt":"如果给你一个完全没人认识你的城市、一整天的空白时间，你更愿意——","options":[{"key":"A","text":"找一家本地人最常去的小店，试着和老板聊起来","effects":{"big5_social":1.8,"big5_assert":1,"mot_hedonism":1,"big5_open":0.8},"social_desirability":1},{"key":"B","text":"一个人随便走，不带目的地，走到哪算哪","effects":{"big5_social":-1.2,"mot_autonomy":1.8,"big5_open":1.4,"cog_ambiguity":1},"social_desirability":2},{"key":"C","text":"找个安静的咖啡馆，把一直没时间想的事想清楚","effects":{"big5_social":-1.6,"cog_logic":1.4,"def_intellectual":1,"mot_autonomy":1},"social_desirability":2},{"key":"D","text":"把这一天用来做一件早就计划好、一直没执行的事","effects":{"big5_social":-0.8,"big5_industry":1.8,"big5_order":1.2,"mot_mastery":0.8},"social_desirability":2}]},{"id":"v2_q19","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"big5_compliance","is_sensitive":true,"weight":0.85,"prompt":"一个你很喜欢的人提出了一个你其实不太想答应的请求。你的第一反应通常是——","scale":{"left":"先答应下来，事后再想怎么办","right":"直接说不，然后花力气把这份不舒服解释清楚","sdHigh":"left"},"effects":{"big5_compliance":[1.8,-1.8],"def_fawn":[1.6,-1.2],"att_anxiety":[1,-0.8]}},{"id":"v2_q20","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"big5_alert","is_sensitive":true,"weight":1.25,"context":"伴侣今天回家后话很少，你问了两句，对方说「没事，我有点累」。之后一直戴着耳机，睡前也没有像往常那样靠过来。","prompt":"那两句「没事」之后的半小时，你身体里发生的是——","options":[{"key":"A","text":"胃先紧了，脑子里已经开始列出所有可能出问题的清单","effects":{"big5_alert":2,"big5_rumination":1.8,"att_anxiety":1.2,"big5_compassion":0.4},"social_desirability":1},{"key":"B","text":"没多想，让对方自己待着，继续做手上那点事","effects":{"big5_alert":-1.6,"big5_rumination":-1.2,"def_detach":1.2,"cog_logic":0.8},"social_desirability":2},{"key":"C","text":"先回想了一下最近有没有踩到什么，确认没问题就放下了","effects":{"big5_alert":0.8,"cog_logic":1.6,"def_intellectual":1,"big5_order":0.8},"social_desirability":3},{"key":"D","text":"开始在心里预演怎么问，把今晚所有走向都演练一遍","effects":{"big5_alert":1.4,"big5_industry":1.4,"covert_control":1,"big5_rumination":0.8},"social_desirability":2}]}]},"vol3":{"volume_id":"vol3","index":3,"title":"博弈暗面","subtitle":"光明三角、黑暗三角与隐性掌控","theme_color":"#9C7A3C","estimated_minutes":5,"intro":"这一卷关于利益与善意撞在一起的那一刻。请不必急着做那个「更好的人」——成人世界的每一次配合、每一次让步、每一次出手，都有它真实的算法。","dimensions":["dark_mach","dark_narc","dark_psycho","light_humanism","light_kant","light_faith","covert_control"],"questions":[{"id":"v3_q01","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"dark_mach","is_sensitive":true,"weight":0.85,"prompt":"在开始一段重要的合作之前，你会花多少精力先摸清对方真正在意的东西？","scale":{"left":"几乎不刻意做，边走边了解就够了","right":"基本都会先摸清楚，才敢先把自己的底交出去","sdHigh":"left"},"effects":{"dark_mach":[-2,2],"covert_control":[-1.4,1.8],"light_faith":[1.2,-1.2],"cog_global":[0.6,0.8]}},{"id":"v3_q02","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"dark_mach","is_sensitive":true,"weight":1.4,"context":"三个朋友合伙开的小店开了半年。今晚算账，其中一个人说「我出的力最多」，另一个人说「我垫的钱最多」。桌上的账本摊开，谁都没先说话。","prompt":"那段安静里，你脑子里转的是——","options":[{"key":"A","text":"这两个人谁在真出力、谁在搭便车，还有谁不能被得罪","effects":{"dark_mach":2,"covert_control":1.4,"cog_global":1,"light_faith":-1},"social_desirability":0},{"key":"B","text":"这几个人里有没有真的值得长期并肩的，先看谁说话算数","effects":{"dark_mach":1,"light_faith":1.2,"cog_global":0.8,"mot_belonging":0.8},"social_desirability":2},{"key":"C","text":"怎么把我那份做得足够清楚，让别人主动认下这块","effects":{"dark_mach":0.4,"mot_mastery":1.8,"light_humanism":0.6,"big5_industry":1},"social_desirability":3},{"key":"D","text":"有点累，这种场面里每句客气话都要花力气接住","effects":{"dark_mach":-0.8,"big5_social":-1.4,"att_avoidance":1.2,"def_detach":1},"social_desirability":1}]},{"id":"v3_q03","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"dark_psycho","is_sensitive":true,"weight":1.25,"context":"你介绍一位朋友进了你所在的圈子接一个活儿，算是一份人情。他连着三次交的东西都不能用，今天这一次，直接让你在中间人面前失了分寸。","prompt":"你知道这件事之后的第一秒，脑子里最清晰的那个念头是——","options":[{"key":"A","text":"这个人不能再往这类事情里带了，得尽快把关系理清","effects":{"dark_psycho":2,"dark_mach":1,"big5_compassion":-1.2,"mot_mastery":1},"social_desirability":0},{"key":"B","text":"先弄清他到底怎么了，认识这么多年不该被一次低谷判死","effects":{"dark_psycho":-1.6,"light_humanism":1.8,"big5_compassion":1.6,"big5_compliance":0.6},"social_desirability":3},{"key":"C","text":"先把损失补回来，情绪和责任的事情之后再算","effects":{"dark_psycho":1.2,"cog_logic":1.6,"def_intellectual":1,"light_kant":0.4},"social_desirability":2},{"key":"D","text":"一股火直冲上来，想当场把话说得他抬不起头","effects":{"dark_psycho":0.6,"sin_wrath":1.8,"def_attack":1.6,"big5_rumination":0.8},"social_desirability":0}]},{"id":"v3_q04","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"dark_narc","is_sensitive":true,"weight":0.85,"prompt":"你做了一件确实很漂亮的事，但它被安静地归档了，没有掌声也没有人被惊动。你心里——","scale":{"left":"几乎不需要外部确认，我自己知道它有多好","right":"会有明显的失落，我需要有人看见它才算数","sdHigh":"left"},"effects":{"dark_narc":[-2,2],"mot_mastery":[-0.6,1.2],"light_humanism":[0.8,-0.6],"big5_assert":[-1,1.4]}},{"id":"v3_q05","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"light_kant","is_sensitive":true,"weight":1.4,"context":"一个极其关键的谈判桌上，你发现对方有一个信息盲区。只要你保持沉默，这份合同会以对你更有利的条件签下；说出来，你会损失一大笔。","prompt":"你更可能的选择是——","options":[{"key":"A","text":"保持沉默，商业谈判本就各凭本事，没人有义务替对方补课","effects":{"light_kant":-2,"dark_mach":1.8,"val_moral":-1.4,"light_humanism":-0.8},"social_desirability":0},{"key":"B","text":"把这一点说出来，生意可以少赚，但不能建立在一段隐瞒上","effects":{"light_kant":2,"val_moral":1.6,"dark_mach":-1.4,"light_humanism":1.2},"social_desirability":3}]},{"id":"v3_q06","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"light_faith","is_sensitive":true,"weight":0.85,"prompt":"一个刚认识不久、对你很客气周到的人，你默认他背后的动机更接近——","scale":{"left":"他大概本身就是这样的人，先按善意接住","right":"这份周到里有它的来处，先看清楚再决定给多少","sdHigh":"left"},"effects":{"light_faith":[2,-2],"big5_alert":[-1.2,1.6],"dark_mach":[-1.4,1.6],"light_humanism":[1,-0.4]}},{"id":"v3_q07","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"covert_control","is_sensitive":true,"weight":1.4,"context":"一个十几人的朋友群要张罗一次长线旅行。群主名义上是组织者，但路线、预算、住宿、谁跟谁住，最后都是你在定。","prompt":"关于这个局面，你内心更接近哪一种？","options":[{"key":"A","text":"名分不重要，只要事情按我的节奏推进，我就舒服","effects":{"covert_control":2,"dark_mach":1.4,"mot_autonomy":1.2,"big5_assert":-0.6},"social_desirability":0},{"key":"B","text":"这种状态让我不舒服，我要么拿到名分要么退出来","effects":{"covert_control":-1.2,"big5_assert":1.8,"val_moral":1.2,"mot_autonomy":1},"social_desirability":3},{"key":"C","text":"顺着这个局面往前走，反正功劳最终会算在做事的人身上","effects":{"covert_control":1,"big5_industry":1.4,"light_faith":1,"dark_narc":0.6},"social_desirability":2},{"key":"D","text":"我会把这些推动都留痕，让它们在未来某个时刻可以被证明","effects":{"covert_control":1.4,"dark_mach":1.6,"cog_logic":1,"big5_order":0.8},"social_desirability":1}]},{"id":"v3_q08","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"dark_mach","is_sensitive":true,"weight":1.25,"context":"小区维权这件事上，一个你平时并不喜欢、见面只点头的邻居，私下帮你补齐了最关键的一份材料，还在群里替你说了话，事后没提。","prompt":"知道这件事的第一秒，你心里最先冒出来的是——","options":[{"key":"A","text":"他为什么帮我，这件事他打算怎么用","effects":{"dark_mach":2,"light_faith":-1.6,"big5_alert":1.2,"covert_control":1},"social_desirability":0},{"key":"B","text":"有点惭愧，我之前对他的判断可能太潦草了","effects":{"dark_mach":-1.4,"light_faith":1.8,"light_humanism":1.4,"big5_compassion":1},"social_desirability":3},{"key":"C","text":"记住了，这份我之后会还回去，账要清","effects":{"dark_mach":0.6,"light_kant":1.2,"val_moral":1,"big5_order":0.8},"social_desirability":2},{"key":"D","text":"松了口气，终于有人接住了，先不想那么多","effects":{"dark_mach":-0.8,"big5_rumination":-1,"def_detach":0.8,"att_anxiety":-0.6},"social_desirability":2}]},{"id":"v3_q09","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"dark_psycho","is_sensitive":true,"weight":0.85,"prompt":"当你必须做一个会让某个人很难受、但对整体更好的决定时，你的实际状态是——","scale":{"left":"会犹豫很久，很难按下那个键","right":"能按下去，事后也许会难受，但当时不会有太多阻力","sdHigh":"left"},"effects":{"dark_psycho":[-1.8,2],"big5_compassion":[1.6,-1.6],"def_detach":[-1,1.4],"big5_compliance":[1.2,-1.2]}},{"id":"v3_q10","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"light_humanism","is_sensitive":false,"weight":1.4,"context":"家里只够支撑一个人的长期照护：一位是身体更差、需要人盯着的长辈，一位是刚出状况、孩子还小的表亲。两个都开口了，都很难。","prompt":"你更可能给出的意见是——","options":[{"key":"A","text":"按实际紧急程度和可恢复性来，人情不该进入这类判断","effects":{"light_humanism":-1.2,"cog_logic":1.6,"dark_psycho":1.4,"val_moral":-0.8},"social_desirability":1},{"key":"B","text":"先顾身体更差的那位。另一位我坦白说清：这次只能靠你们自己了","effects":{"light_humanism":1.4,"big5_compassion":1.2,"light_kant":0.6,"val_moral":0.8},"social_desirability":3},{"key":"C","text":"把两个人的真实处境完整摆到台面上，让家里长辈自己承担选择","effects":{"light_humanism":1.2,"light_kant":1.4,"big5_compliance":-0.8,"covert_control":-0.4},"social_desirability":2},{"key":"D","text":"先顾情况更急的那位，另一位我私下想办法帮他找出路","effects":{"light_humanism":0.6,"dark_mach":1.2,"big5_compassion":1,"covert_control":0.8},"social_desirability":1}]},{"id":"v3_q11","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"dark_narc","is_sensitive":true,"weight":0.85,"prompt":"在一场你并不擅长的活动里，你被安排成了一个不重要的角色。这种感觉对你来说——","scale":{"left":"无所谓，换个场合我照样有我的位置","right":"会一直不太舒服，我很需要处在被看见的位置","sdHigh":"left"},"effects":{"dark_narc":[-1.8,2],"big5_assert":[-1,1.4],"mot_mastery":[-0.4,1],"cog_logic":[0.6,-0.4]}},{"id":"v3_q12","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"light_faith","is_sensitive":true,"weight":1.4,"context":"两个曾经帮过你的人，如今在同一件事上立场完全相反，都希望站到你这边。","prompt":"你更可能怎么处理？","options":[{"key":"A","text":"按事情本来的对错站，谁帮过我都是另一本账","effects":{"light_faith":0.6,"light_kant":1.8,"val_moral":1.6,"big5_compliance":-1},"social_desirability":3},{"key":"B","text":"先拖着不表态，让两边都觉得我还站在他这边","effects":{"light_faith":-1.2,"dark_mach":1.8,"covert_control":1.4,"val_moral":-1},"social_desirability":0},{"key":"C","text":"谁在我最难的时候真的在场，我心里有数","effects":{"light_faith":1.2,"mot_belonging":1.6,"val_moral":-0.6,"att_anxiety":0.8},"social_desirability":2}]},{"id":"v3_q13","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"covert_control","is_sensitive":true,"weight":0.85,"prompt":"关于「知道所有细节」，你的真实感受是——","scale":{"left":"不必全都知道，交给别人我也会比较放心","right":"关键环节我不掌握，就会睡不踏实","sdHigh":"left"},"effects":{"covert_control":[-1.8,2],"big5_order":[-1,1.6],"big5_rumination":[-0.8,1.2],"att_anxiety":[-0.6,1]}},{"id":"v3_q14","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"dark_narc","is_sensitive":true,"weight":1.2,"context":"一个聚会上，有人讲了一个你早就知道、而且知道得比他更透的话题，全场都在点头。","prompt":"那一刻你身体里最先的反应是——","options":[{"key":"A","text":"忍不住想在他讲完之前，把一个更精确的点插进去","effects":{"dark_narc":1.8,"sin_pride":1.4,"big5_assert":1.6,"big5_compliance":-1},"social_desirability":0},{"key":"B","text":"听得挺开心，他讲得不错，补不补充都无所谓","effects":{"dark_narc":-1.6,"virtue_humility":1.6,"light_humanism":1.2,"big5_compliance":1},"social_desirability":3},{"key":"C","text":"在心里把他讲的和我理解的过了一遍，找出了几处偏差","effects":{"dark_narc":0.4,"cog_logic":1.4,"cog_independent":1,"big5_assert":0.2},"social_desirability":1},{"key":"D","text":"这个话题我比他熟，等他讲完我接一下场就行","effects":{"dark_narc":1,"covert_control":1.4,"big5_assert":0.8,"dark_mach":0.8},"social_desirability":1}]},{"id":"v3_q15","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"light_humanism","is_sensitive":true,"weight":1.4,"prompt":"你需要一个人替你完成一件不太体面、但不会被追责的小事。你会怎么找人？","options":[{"key":"A","text":"把真实情况和风险完全讲清楚，让他自己决定要不要接","effects":{"light_humanism":2,"light_kant":1.8,"val_moral":1.2,"dark_mach":-1.2},"social_desirability":3},{"key":"B","text":"找一个最不容易拒绝我的，把话说得轻一些","effects":{"light_humanism":-1.6,"light_kant":-1.4,"dark_mach":1.2,"covert_control":0.8},"social_desirability":0},{"key":"C","text":"干脆自己一个人做完，不把任何无关的人卷进来","effects":{"light_humanism":1.4,"light_kant":1,"mot_autonomy":1.2,"big5_compliance":-0.6},"social_desirability":2},{"key":"D","text":"找一个正好需要这份人情的人，彼此都心知肚明","effects":{"light_humanism":-0.8,"dark_mach":1.4,"dark_psycho":0.6,"light_kant":-0.4},"social_desirability":1}]},{"id":"v3_q16","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"light_kant","is_sensitive":true,"weight":0.85,"prompt":"你曾经为了一个更好的结果，说过一次不完整的真话。事后回想，你更接近——","scale":{"left":"后悔，那件事到现在还硌在我心里","right":"不太后悔，那个场合里完整说出来只会伤到更多人","sdHigh":"left"},"effects":{"light_kant":[2,-2],"val_moral":[1.6,-1.4],"dark_mach":[-1,1.6],"cog_ambiguity":[-0.6,1.2]}},{"id":"v3_q17","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"dark_psycho","is_sensitive":true,"weight":1.35,"context":"合作了三年的伙伴被发现私下把核心资源往自己那边挪，数额不大，但性质很明确。","prompt":"你猜大多数清醒的人最终会怎么处理？","options":[{"key":"A","text":"彻底切断，不留余地，也不给他再解释第二次的机会","effects":{"dark_psycho":1.8,"covert_control":1,"big5_compliance":-1.4,"att_avoidance":1},"social_desirability":0},{"key":"B","text":"先谈一次，把规则重新划清，之后按新规则继续合作","effects":{"dark_psycho":-0.8,"light_faith":1.2,"big5_compliance":1,"cog_logic":1},"social_desirability":2},{"key":"C","text":"表面继续，慢慢把资源收回，让他自己意识到位置变了","effects":{"dark_psycho":1,"dark_mach":1.8,"covert_control":1.6,"light_kant":-0.6},"social_desirability":1},{"key":"D","text":"先弄清他为什么会这么做，再决定要不要追究","effects":{"dark_psycho":-1.2,"big5_compassion":1.6,"light_humanism":1.4,"def_intellectual":1},"social_desirability":3}]},{"id":"v3_q18","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"dark_mach","is_sensitive":true,"weight":0.85,"prompt":"一段关系里，你更习惯的姿态是——","scale":{"left":"有什么说什么，真实的粗糙好过漂亮的安排","right":"会下意识地安排节奏、把握分寸，让关系朝我舒服的方向走","sdHigh":"left"},"effects":{"dark_mach":[-1.8,1.8],"covert_control":[-1.4,2],"light_kant":[1.2,-1],"big5_compliance":[-0.8,0.4]}}]},"vol4":{"volume_id":"vol4","index":4,"title":"三观罗盘","subtitle":"世界观、人生观与价值观的九维坐标","theme_color":"#2A5C55","estimated_minutes":6,"intro":"这里测绘的是你的哲学操作系统：你如何解释世界，如何安放痛苦，以及哪些东西在你这里不可交易。最后一题，请用仅有一百点的人生给它排序。","dimensions":["wv_nature","wv_causal","wv_social","lv_happiness","lv_suffering","lv_anchor","val_moral","val_boundary","val_standard"],"questions":[{"id":"v4_q01","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"wv_nature","is_sensitive":false,"weight":0.85,"prompt":"一个陌生人在深夜的街上，主动问你要不要帮忙提一下手里的重物。你的默认解读更接近——","scale":{"left":"他就是顺手，人多数时候是善意的","right":"先礼貌拒绝，我不太习惯把未知当成安全","sdHigh":"left"},"effects":{"wv_nature":[2,-2],"light_faith":[1.6,-1.4],"big5_alert":[-1,1.4]}},{"id":"v4_q02","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"wv_causal","is_sensitive":false,"weight":1.4,"prompt":"回看你这几年最大的一次转折，你更愿意把它归因于——","options":[{"key":"A","text":"自己在几个关键时刻做出的选择，哪怕当时看不清","effects":{"wv_causal":1.8,"cog_independent":1.2,"mot_autonomy":1.2,"light_faith":0.4},"social_desirability":2},{"key":"B","text":"时代、运气，以及一些我来不及参与、也改不动的安排","effects":{"wv_causal":-1.8,"cog_ambiguity":1,"light_faith":0.8,"big5_rumination":0.6},"social_desirability":1},{"key":"C","text":"几个具体的人，在我不认识他们的那些年里替我开了门","effects":{"wv_causal":-0.6,"mot_belonging":1.4,"light_faith":1.4,"att_anxiety":0.6},"social_desirability":2}]},{"id":"v4_q03","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"wv_social","is_sensitive":false,"weight":0.85,"prompt":"同一件事，规则上不允许，但所有人都在做，而且做了确实更有效率。你的态度更接近——","scale":{"left":"规则既然定在这，我不会第一个去破","right":"规则是给平均值定的，具体情况该具体判断","sdHigh":"left"},"effects":{"wv_social":[1.8,-1.8],"light_kant":[1.4,-1.2],"cog_ambiguity":[-1,1.2],"dark_mach":[-0.8,1.2]}},{"id":"v4_q04","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"lv_happiness","is_sensitive":false,"weight":1.4,"context":"你的邻居四十岁，辞掉了年薪很高的工作，去开了一家只有六张桌子的小馆子。所有人都说他疯了。","prompt":"你觉得他真正换来的东西是——","options":[{"key":"A","text":"一种每天都能自己说了算的生活，哪怕收入少了三分之二","effects":{"lv_happiness":-1.4,"mot_autonomy":1.8,"lv_anchor":-1.2,"mot_hedonism":1},"social_desirability":2},{"key":"B","text":"一件真正属于他、可以一直做到老的作品，哪怕小","effects":{"lv_happiness":1.6,"mot_purpose":1.8,"mot_mastery":1.2,"lv_suffering":1},"social_desirability":3},{"key":"C","text":"一次深思熟虑过的赌，他算过自己到底能撑多久才敢下注","effects":{"lv_happiness":0.4,"cog_logic":1.6,"mot_security":0.8,"lv_anchor":0.4},"social_desirability":2},{"key":"D","text":"终于不用再扮演那个被所有人需要的角色，可以安静一点","effects":{"lv_happiness":-1.8,"big5_social":-1.4,"lv_anchor":1.6,"att_avoidance":1.2},"social_desirability":1}]},{"id":"v4_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"lv_suffering","is_sensitive":true,"weight":0.85,"prompt":"一段确实很难熬的日子过去之后，你的真实总结更接近——","scale":{"left":"它确实给了我一些别处拿不到的东西","right":"苦难就是苦难，我不打算给它附加意义","sdHigh":"left"},"effects":{"lv_suffering":[2,-2],"mot_purpose":[1.2,-1],"light_faith":[0.8,-0.4],"big5_rumination":[0.4,-0.6]}},{"id":"v4_q06","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"lv_anchor","is_sensitive":false,"weight":1.4,"prompt":"如果你被放到一个没有人认识你、也没有任何头衔的地方待一年，你更担心的是——","options":[{"key":"A","text":"失去舞台，我可能真的会不知道自己还是谁，那才是最怕的","effects":{"lv_anchor":-2,"dark_narc":1.2,"mot_mastery":1.2,"big5_assert":0.8},"social_desirability":0},{"key":"B","text":"其实不太担心，我一直有一部分是不需要被任何人看见的","effects":{"lv_anchor":2,"mot_autonomy":1.4,"big5_social":-1.2,"att_avoidance":0.8},"social_desirability":3},{"key":"C","text":"担心和重要的人失去共同的生活节奏，慢慢就无话可说了","effects":{"lv_anchor":-0.8,"mot_belonging":1.8,"att_anxiety":1.2,"big5_compassion":0.8},"social_desirability":2},{"key":"D","text":"担心这一年什么都没留下，安静地过去，像没发生过","effects":{"lv_anchor":-0.6,"mot_purpose":1.6,"big5_rumination":1.2,"sin_sloth":-0.8},"social_desirability":1}]},{"id":"v4_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"val_moral","is_sensitive":true,"weight":0.85,"prompt":"一个决定让多数人受益，代价是某个具体的人要承担本不该他承担的损失。你的实际态度是——","scale":{"left":"不能这么做，正确的方式不该靠牺牲某个人来成立","right":"多数人的收益更重要，只能尽量补偿那一个人","sdHigh":"left"},"effects":{"val_moral":[2,-2],"light_kant":[1.6,-1.6],"cog_logic":[-0.8,1.4],"light_humanism":[1.2,-0.8]}},{"id":"v4_q08","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"val_boundary","is_sensitive":true,"weight":1.4,"context":"一份待遇很好、同事也都体面的工作，唯一的问题是它要求你长期待在一个你不能自己决定的节奏里。","prompt":"这份工作对你来说更接近——","options":[{"key":"A","text":"可以做，只要回报足够，就等于我用自己的时间做了交换","effects":{"val_boundary":-1.8,"mot_security":1.6,"mot_mastery":1.2,"mot_autonomy":-1.2},"social_desirability":1},{"key":"B","text":"做不了太久，我对「被安排」这件事有生理性的排斥","effects":{"val_boundary":1.8,"mot_autonomy":2,"big5_order":-0.8,"att_avoidance":0.8},"social_desirability":2}]},{"id":"v4_q09","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"val_standard","is_sensitive":false,"weight":0.85,"prompt":"评价一个你很尊敬的同行时，你心里最先给出的那一栏分数是哪一项？","scale":{"left":"他做的东西够不够有效、够不够有用","right":"他做事的方式够不够干净、够不够讲究","sdHigh":"right"},"effects":{"val_standard":[-1.8,2],"light_kant":[-1,1.4],"cog_logic":[1.2,-0.6]}},{"id":"v4_q10","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"wv_social","is_sensitive":true,"weight":1.2,"context":"你亲眼看到一个熟悉的人插队，理由是「我真的赶时间」，而队伍里有一位明显更需要的老人。","prompt":"你看到这一幕的第一秒，心里冒出来的东西是——","options":[{"key":"A","text":"一股很清楚的不舒服，规则被破掉这件事本身就让我难受","effects":{"wv_social":1.8,"light_kant":1.6,"sin_wrath":0.8,"val_moral":1.2},"social_desirability":3},{"key":"B","text":"先判断他是不是真的急，如果真有急事就算了","effects":{"wv_social":-0.8,"big5_compassion":1.2,"cog_ambiguity":1,"val_standard":-0.6},"social_desirability":2},{"key":"C","text":"心里不快，但不会开口，事后再看要不要提一句","effects":{"wv_social":0.4,"big5_compliance":1.4,"def_fawn":0.8,"sin_wrath":-0.6},"social_desirability":1},{"key":"D","text":"马上开口，不管他有什么理由，这个位置得先吐出来","effects":{"wv_social":1.4,"big5_assert":1.6,"def_attack":1.4,"sin_wrath":1.2},"social_desirability":1}]},{"id":"v4_q11","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"wv_causal","is_sensitive":false,"weight":0.85,"prompt":"那些长期做得很好的人，你认为他们更主要靠的是——","scale":{"left":"一套稳定、可复制的自我管理系统","right":"在几个关键节点上赶上了他们自己也无法复制的运气","sdHigh":"left"},"effects":{"wv_causal":[1.8,-1.8],"big5_industry":[1.4,-0.8],"cog_logic":[0.8,-0.6]}},{"id":"v4_q12","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"lv_happiness","is_sensitive":false,"weight":1.4,"prompt":"如果只能保留下一种体验，并且维持十年，你更愿意是——","options":[{"key":"A","text":"一直在做一件越来越难、但越来越像自己的事","effects":{"lv_happiness":1.8,"mot_mastery":1.6,"mot_purpose":1.2,"mot_hedonism":-1},"social_desirability":3},{"key":"B","text":"一直在换地方、换口味、换遇见的人，密度很高","effects":{"lv_happiness":-1.8,"mot_hedonism":2,"big5_open":1.2,"mot_security":-1},"social_desirability":1},{"key":"C","text":"一直有一小群人，晚饭时会在同一张桌子旁等你","effects":{"lv_happiness":0.4,"mot_belonging":2,"val_boundary":-1,"att_anxiety":0.4},"social_desirability":2}]},{"id":"v4_q13","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"val_boundary","is_sensitive":true,"weight":0.85,"prompt":"关于「稳定」，你内心的真实排序是——","scale":{"left":"稳定很贵，它值得我把一部分可能性先换掉","right":"稳定更像一种提前的妥协，我宁愿留着不确定的部分","sdHigh":"left"},"effects":{"val_boundary":[-1.8,2],"mot_security":[2,-1.6],"mot_autonomy":[-1.4,1.8],"cog_ambiguity":[-1,1.4]}},{"id":"v4_q14","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"val_moral","is_sensitive":true,"weight":1.35,"context":"带过你的前辈陈姐发现，一起合伙的另外两个人正用一种不违约但明显不体面的方式，把她那份分红一点点挪进公账里。","prompt":"你猜她最终最可能做的事是——","options":[{"key":"A","text":"先把账目留好，再选一个对自己最安全的时机把这件事摆出去","effects":{"val_moral":1.4,"dark_mach":1.6,"covert_control":1.2,"light_kant":0.8},"social_desirability":1},{"key":"B","text":"直接找那两个人对质，把话说清楚，哪怕后果不可控","effects":{"val_moral":1.4,"light_kant":1.8,"big5_assert":1.6,"cog_speed":1},"social_desirability":3},{"key":"C","text":"先私下提醒别的出资人，让他们自己想办法保住那份","effects":{"val_moral":0.8,"light_humanism":1.6,"big5_compassion":1.2,"covert_control":0.6},"social_desirability":2},{"key":"D","text":"不碰，这时候出手对自己风险太大，先把自己挪出这条船","effects":{"val_moral":-1.2,"mot_security":1.8,"dark_psycho":1,"big5_alert":1.2},"social_desirability":0}]},{"id":"v4_q15","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"val_standard","is_sensitive":false,"weight":0.85,"prompt":"朋友做了一件对你很好、但对别人不太公平的事。你更在意的是——","scale":{"left":"他对我的那份好，我会记着","right":"他处理别人的方式，正好说明他以后会怎么处理我","sdHigh":"right"},"effects":{"val_standard":[-1.4,2],"light_kant":[-1,1.4],"mot_belonging":[1.4,-0.8],"big5_alert":[-0.6,1],"wv_nature":[0.8,-0.8]}},{"id":"v4_q16","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"lv_anchor","is_sensitive":false,"weight":0.85,"prompt":"一件让你真正有成就感的事，通常发生在——","scale":{"left":"别人看得见的地方，反馈本身很重要","right":"只有我自己知道的那个房间里","sdHigh":"right"},"effects":{"lv_anchor":[-1.8,2],"dark_narc":[1.6,-1.2],"mot_mastery":[1,0.4],"big5_social":[1,-0.8]}},{"id":"v4_q17","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"lv_suffering","is_sensitive":true,"weight":1.4,"prompt":"两种人生，你更愿意走哪一条？","options":[{"key":"A","text":"一路相对平顺，很少被折断，也没做过什么真正难的事","effects":{"lv_suffering":-1.8,"mot_hedonism":1.4,"mot_security":1.4,"mot_purpose":-1.2},"social_desirability":1},{"key":"B","text":"有过几次非常艰难的断裂，但每次之后都更接近自己","effects":{"lv_suffering":1.8,"mot_purpose":1.6,"big5_rumination":1,"mot_mastery":1.2},"social_desirability":3}]},{"id":"v4_q18","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"wv_nature","is_sensitive":false,"weight":0.85,"prompt":"当你把一件重要的事交给别人时，你心里默认的那条基线是——","scale":{"left":"他会尽力，我可以放心","right":"他会按他的优先级来处理，我得留一手","sdHigh":"left"},"effects":{"wv_nature":[1.8,-1.8],"light_faith":[1.6,-1.6],"covert_control":[-1.4,1.6]}},{"id":"v4_q19","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"lv_happiness","is_sensitive":false,"weight":0.85,"prompt":"一个非常普通的周三晚上，你更希望它是——","scale":{"left":"有内容、有推进，睡前能说出今天做成了什么","right":"有滋味、有松弛，睡前身体是放松的","sdHigh":"left"},"effects":{"lv_happiness":[1.8,-1.8],"mot_mastery":[1.4,-1],"mot_hedonism":[-1.4,1.8]}},{"id":"v4_q20","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"values","is_sensitive":false,"weight":1.3,"prompt":"假设你这一生只能守住三样东西，请把最重要的排在第一。不是因为它们「应该」重要，而是因为失去它你真的会疼。","values":[{"key":"freedom","label":"自由","effects":{"mot_autonomy":1.4,"val_boundary":1.2,"wv_causal":0.4}},{"key":"dignity","label":"尊严","effects":{"mot_mastery":1,"sin_pride":0.8,"val_standard":1.2}},{"key":"wealth","label":"财富","effects":{"mot_security":1.4,"sin_greed":0.8,"mot_mastery":1}},{"key":"intimacy","label":"亲密","effects":{"mot_belonging":1.6,"att_anxiety":0.6,"val_boundary":-0.8}},{"key":"security","label":"安全","effects":{"mot_security":1.4,"cog_ambiguity":-1,"big5_alert":0.8}},{"key":"breakthrough","label":"突破","effects":{"mot_mastery":1.8,"big5_industry":0.8,"dark_psycho":0.4}},{"key":"fairness","label":"公平","effects":{"val_moral":1.2,"light_kant":1.4,"wv_social":1}},{"key":"ease","label":"松弛","effects":{"mot_hedonism":1.4,"lv_happiness":-1,"lv_suffering":-0.8}}]}]},"vol5":{"volume_id":"vol5","index":5,"title":"思维棱镜","subtitle":"认知风格与决策算法的六道棱面","theme_color":"#3B4D70","estimated_minutes":4,"intro":"这一卷不测量情绪，也不评判道德。它只测绘你大脑处理信息、做判断、解决难题的那台机器——你怎样把混乱的世界压缩成一个可以行动的结论。","dimensions":["cog_global","cog_diverge","cog_logic","cog_ambiguity","cog_independent","cog_speed"],"questions":[{"id":"v5_q01","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_global","is_sensitive":false,"weight":0.85,"prompt":"接到一个全新领域的任务，你把书翻开的第一个动作是——","scale":{"left":"先读目录和结论，把这件事的骨架搞清楚","right":"直接从第一个具体案例开始，边做边建立理解","sdHigh":"left"},"effects":{"cog_global":[2,-2],"big5_open":[1,-0.8],"cog_speed":[-0.6,1]}},{"id":"v5_q02","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"cog_diverge","is_sensitive":false,"weight":1.4,"context":"家里一位长辈的病已经反复三年，常规办法都试过了，全家开始陷入疲惫，谁都不再提「接下来怎么办」。","prompt":"你更愿意把接下来的力气放在——","options":[{"key":"A","text":"先列出十条从来没人试过的路子，哪怕八条最后是荒唐的","effects":{"cog_diverge":2,"big5_open":1.4,"cog_global":0.8,"cog_speed":-0.4},"social_desirability":2},{"key":"B","text":"把所有可能的风险点排一遍，先把最坏的那个堵上","effects":{"cog_diverge":-1.8,"big5_alert":1.6,"big5_order":1.2,"cog_ambiguity":-1.2},"social_desirability":3},{"key":"C","text":"找一个完全不懂医的朋友聊一次，看他怎么理解这件事","effects":{"cog_diverge":1.6,"big5_open":1.6,"light_humanism":0.6,"cog_independent":0.8},"social_desirability":2},{"key":"D","text":"先承认这条路走不通，然后认真讨论要不要换一种活法","effects":{"cog_diverge":-0.8,"dark_psycho":1.4,"cog_speed":1.2,"mot_mastery":-0.6},"social_desirability":1}]},{"id":"v5_q03","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_logic","is_sensitive":false,"weight":0.85,"prompt":"两个候选人条件几乎一样，但你心里对其中一个有说不清的好感。你的实际处理是——","scale":{"left":"把好感放到一边，回到可比较的维度上做决定","right":"相信那点说不清，它通常捕捉到了数据没覆盖的东西","sdHigh":"left"},"effects":{"cog_logic":[1.8,-1.8],"cog_speed":[-0.8,1],"big5_compassion":[-0.8,1.2]}},{"id":"v5_q04","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_ambiguity","is_sensitive":false,"weight":1.4,"prompt":"你打算换一座城市生活，两个月过去了，仍有三分之一的变量没定：住哪、做什么、要不要先斩后奏。家里人希望你月底给一个明确说法。你的状态更接近——","options":[{"key":"A","text":"先给一份带明确分支的图，把那三成写成可选路径，先往前走","effects":{"cog_ambiguity":1.8,"cog_speed":1,"big5_order":-0.4,"cog_global":1},"social_desirability":2},{"key":"B","text":"会很不舒服，没有确定的前提我很难给出任何承诺","effects":{"cog_ambiguity":-1.8,"big5_order":1.6,"big5_alert":1.2,"cog_speed":-1.2},"social_desirability":1},{"key":"C","text":"去找能拍板的人，先把那三成压下来，再谈路线","effects":{"cog_ambiguity":-1.4,"big5_assert":1.4,"covert_control":1,"cog_logic":1},"social_desirability":2},{"key":"D","text":"索性先做一个小实验，用真实反馈把那三成自己削掉","effects":{"cog_ambiguity":1.4,"cog_speed":1.6,"cog_diverge":1,"big5_industry":0.8},"social_desirability":3}]},{"id":"v5_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_independent","is_sensitive":true,"weight":0.85,"prompt":"一个圈子里公认的「正确做法」，你隐约觉得有问题，但你说不出完整的理由。你通常——","scale":{"left":"先照做，多数人这么做总有它的道理","right":"会先按自己的判断试一次，哪怕要独自承担后果","sdHigh":"left"},"effects":{"cog_independent":[-1.8,2],"big5_compliance":[1.6,-1.4],"sin_pride":[-0.6,1.2]}},{"id":"v5_q06","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"cog_speed","is_sensitive":false,"weight":1.2,"context":"一个重要机会，今天下午六点前必须决定，跳进去是三个月的重投入。你现在掌握的信息大概占到六成。","prompt":"看到那条消息后的第一反应是——","options":[{"key":"A","text":"先答应下来，六成就够了，剩下的边做边补，不必等万事齐备","effects":{"cog_speed":2,"cog_ambiguity":1.4,"dark_psycho":0.8,"big5_alert":-1},"social_desirability":1},{"key":"B","text":"立刻开始要把剩下那四成尽量敲出来，即使要拖到最后一刻","effects":{"cog_speed":-1.6,"big5_order":1.4,"big5_alert":1,"cog_logic":1},"social_desirability":3},{"key":"C","text":"先找两三个判断力可靠的人各问一圈，问完再自己定下来","effects":{"cog_speed":-0.8,"cog_independent":-0.6,"big5_compliance":1,"light_faith":1},"social_desirability":2},{"key":"D","text":"心里已经有一个答案，但还是会拖到最后十分钟才回","effects":{"cog_speed":-1,"sin_sloth":1.2,"big5_rumination":1,"cog_logic":0.4},"social_desirability":1}]},{"id":"v5_q07","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"cog_global","is_sensitive":false,"weight":1.4,"context":"两个人在同一场线下活动结束后，被问「怎么样」。一个人先说了三个具体细节，另一个人先说了这场活动的核心问题是什么。","prompt":"你觉得这两个人里，谁更可能在半年后走得更高？","options":[{"key":"A","text":"说细节的那位，他对真实发生的事有手感","effects":{"cog_global":-1.8,"cog_logic":1.2,"big5_order":1.2,"big5_alert":0.8},"social_desirability":2},{"key":"B","text":"说核心问题的那位，他能把经验变成可复用的判断","effects":{"cog_global":1.8,"cog_diverge":1,"mot_mastery":1.2,"big5_open":0.8},"social_desirability":3},{"key":"C","text":"不好说，这两个能力在不同阶段各有各的用","effects":{"cog_global":0.4,"cog_ambiguity":1.4,"big5_compliance":0.6,"cog_logic":0.4},"social_desirability":1}]},{"id":"v5_q08","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_diverge","is_sensitive":false,"weight":0.85,"prompt":"一轮头脑风暴结束，桌上通常留下的是——","scale":{"left":"很多张写着荒唐点子的纸，我们的问题是想不出","right":"两条能落地的方案，我们的问题是不够多","sdHigh":"left"},"effects":{"cog_diverge":[1.8,-1.8],"big5_open":[1.2,-0.8],"cog_logic":[-0.6,1]}},{"id":"v5_q09","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"cog_logic","is_sensitive":true,"weight":1.4,"prompt":"两种错误，你更能容忍自己犯哪一种？","options":[{"key":"A","text":"分析完全正确，但漏掉了那个说不清、却真正决定成败的感受","effects":{"cog_logic":1.8,"cog_global":0.6,"big5_compassion":-1,"light_humanism":-0.4},"social_desirability":1},{"key":"B","text":"感受全对了，但没做任何量化验证，最后被一个具体数字推翻","effects":{"cog_logic":-1.8,"cog_ambiguity":1.2,"big5_alert":-0.8,"light_humanism":1},"social_desirability":1}]},{"id":"v5_q10","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_ambiguity","is_sensitive":false,"weight":0.85,"prompt":"一次旅行，你更愿意选择哪种方式？","scale":{"left":"大致定好，剩下的到那看情况，喜欢被意外带走","right":"每一段都排好，不喜欢把时间交给不确定","sdHigh":"left"},"effects":{"cog_ambiguity":[2,-2],"big5_order":[-1.6,1.8],"big5_open":[1,-0.8]}},{"id":"v5_q11","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"cog_independent","is_sensitive":true,"weight":1.35,"context":"整个行业都在往一个方向跑，几乎所有聪明人都在说这是对的，但一些最基础的事实你还没法用现有说法解释。","prompt":"你猜那些最后真正做成了的人，当时更可能在做什么？","options":[{"key":"A","text":"先跟着跑，等方向明朗了再加速，不浪费力气去反抗","effects":{"cog_independent":-1.8,"big5_compliance":1.4,"mot_security":1.2,"cog_speed":0.4},"social_desirability":1},{"key":"B","text":"一边看着主流，一边在没人看的角落里默默做另一套","effects":{"cog_independent":1.8,"cog_diverge":1.4,"covert_control":0.8,"mot_autonomy":1},"social_desirability":3},{"key":"C","text":"公开提出疑问，哪怕会被当成不懂行的人","effects":{"cog_independent":1.4,"big5_assert":1.6,"sin_pride":0.8,"light_kant":0.6},"social_desirability":2},{"key":"D","text":"把两边都押一点，反正站在哪边都不该押满","effects":{"cog_independent":-0.6,"cog_ambiguity":1.2,"dark_mach":1.2,"big5_alert":0.8},"social_desirability":1}]},{"id":"v5_q12","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_speed","is_sensitive":false,"weight":0.85,"prompt":"面对一个需要立刻回应的机会，你的犹豫通常发生在——","scale":{"left":"几乎不犹豫，先接住再说，错了再改","right":"越想越多，往往等我想清楚的时候窗口已经关了","sdHigh":"left"},"effects":{"cog_speed":[1.8,-1.8],"sin_sloth":[-1,1.4],"big5_rumination":[-1,1.4],"big5_alert":[-0.8,1.2]}},{"id":"v5_q13","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_global","is_sensitive":false,"weight":1.4,"context":"一件事上，你妈和你伴侣给出的意见完全相反：一位说你考虑得太远、不落地；另一位说你太计较眼前、缺高度。","prompt":"你的真实反应是——","options":[{"key":"A","text":"两边说的都对，我大概是站在中间那种人，谁的话都得听一半","effects":{"cog_global":1.2,"big5_open":1.2,"virtue_humility":1.4,"big5_industry":0.6},"social_desirability":3},{"key":"B","text":"先判断谁的说法更接近事实，另一个可能只是立场不同","effects":{"cog_global":0.6,"cog_independent":1.6,"cog_logic":1.2,"virtue_humility":0.2},"social_desirability":2},{"key":"C","text":"不管谁怎么说，我更相信自己做出来的结果最终会说明一切。","effects":{"cog_global":0.8,"sin_pride":1.4,"mot_autonomy":1.2,"big5_compliance":-1},"social_desirability":1},{"key":"D","text":"干脆分别问清他们真实的顾虑，把衡量的标准先对齐","effects":{"cog_logic":1.4,"covert_control":1,"big5_compliance":0.6,"big5_order":0.8},"social_desirability":2}]},{"id":"v5_q14","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"cog_diverge","is_sensitive":false,"weight":0.85,"prompt":"一个极度聪明但想法天马行空、常常不落地的同事，你内心对他更接近——","scale":{"left":"很喜欢和他待在一起，他能打开我没想到的地方","right":"聊起来有意思，但真做事我不会带上他","sdHigh":"left"},"effects":{"cog_diverge":[1.6,-1.6],"cog_logic":[-0.8,1.2],"big5_open":[1,-0.6]}},{"id":"v5_q15","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"cog_logic","is_sensitive":false,"weight":1.2,"context":"谈了一半的合作方突然停顿了一下，语气有一点点变，说的内容没有任何问题。","prompt":"那个停顿出现的瞬间，你更可能——","options":[{"key":"A","text":"立刻捕捉到了，并且会绕着这个停顿再探一探","effects":{"cog_logic":-1.4,"big5_compassion":1.4,"cog_independent":0.6,"covert_control":0.6},"social_desirability":2},{"key":"B","text":"没太注意，我主要在处理他说的内容本身","effects":{"cog_logic":1.6,"big5_compassion":-0.8,"cog_global":0.8,"big5_alert":-0.8},"social_desirability":1},{"key":"C","text":"注意到了，但当场不会碰，留到后面再验证","effects":{"cog_logic":0.6,"covert_control":1.4,"big5_alert":1,"def_intellectual":0.8},"social_desirability":3},{"key":"D","text":"会把这个停顿存下来，它比后面的内容更值得记","effects":{"cog_logic":-0.6,"big5_compassion":1,"big5_rumination":1.2,"light_humanism":0.8},"social_desirability":2}]},{"id":"v5_q16","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"cog_independent","is_sensitive":true,"weight":1.4,"prompt":"当你的判断和一群你尊敬的人完全相反，你身体里的第一反应指向哪边？","options":[{"key":"A","text":"按自己的判断走，错了我认，但不试我不会安心","effects":{"cog_independent":1.8,"mot_autonomy":1.6,"big5_assert":1.2,"big5_compliance":-1.4},"social_desirability":2},{"key":"B","text":"先按大家的走，同时留一条自己的小路，看哪边先有结果","effects":{"cog_independent":0.8,"cog_ambiguity":1.2,"covert_control":1.4,"dark_mach":0.8},"social_desirability":2},{"key":"C","text":"把判断交出去，这么多人都这么想，我大概率漏了什么","effects":{"cog_independent":-1.8,"big5_compliance":1.8,"virtue_humility":1.2,"big5_alert":0.6},"social_desirability":3}]},{"id":"v5_q17","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_speed","is_sensitive":false,"weight":0.85,"prompt":"你已经写了一半的东西，突然发现一开始的框架就不对。你的习惯是——","scale":{"left":"推倒重来，越早越好，沉没成本不算成本","right":"会在原框架上打补丁，重写太疼了","sdHigh":"left"},"effects":{"cog_speed":[1.4,-1.4],"dark_psycho":[1,-0.6],"big5_order":[-0.6,1],"cog_global":[0.8,-0.4]}},{"id":"v5_q18","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"cog_ambiguity","is_sensitive":false,"weight":1.4,"prompt":"一件事你只做到 70 分，就可以交出去了，但你隐约觉得还有更好的解法。你的实际选择是——","options":[{"key":"A","text":"交出去，70 分已经够用，剩下的 30 分也许根本没人需要","effects":{"cog_ambiguity":1.2,"cog_speed":1.6,"mot_hedonism":0.6,"big5_industry":-0.4},"social_desirability":1},{"key":"B","text":"再花点时间追那个解法，不追出来我会一直惦记着这件事","effects":{"cog_ambiguity":-1.2,"big5_industry":1.6,"mot_mastery":1.4,"sin_pride":0.8},"social_desirability":3},{"key":"C","text":"先交出去，同时把那个念头记在本子上，等有空了再说","effects":{"cog_ambiguity":0.4,"big5_order":1.4,"cog_speed":0.8,"covert_control":0.6},"social_desirability":2},{"key":"D","text":"心里一直有个更好的版本，但也就一直放在那儿，没动","effects":{"cog_ambiguity":1.6,"big5_industry":-1.2,"sin_sloth":1.4,"cog_speed":-0.8},"social_desirability":0}]}]},"vol6":{"volume_id":"vol6","index":6,"title":"欲望引擎","subtitle":"六大深层生命驱动力","theme_color":"#B5653D","estimated_minutes":5,"intro":"这一卷要回答的问题是：什么能让你眼底发光。不要回答「应该」让你满足的东西，回答在凌晨三点还能把你叫醒的那一个。有两道题，你只有一百点燃料。","dimensions":["mot_autonomy","mot_mastery","mot_belonging","mot_security","mot_purpose","mot_hedonism"],"questions":[{"id":"v6_q01","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"motors","is_sensitive":false,"weight":1.3,"prompt":"假设你手里有一百点「生命燃料」，只能分配给你此刻最想补给的东西。每一分都要有代价。","items":[{"key":"autonomy","label":"自己说了算的时间","dim":"mot_autonomy","base":0,"gain":1},{"key":"mastery","label":"拿到更大的结果","dim":"mot_mastery","base":0,"gain":1},{"key":"belonging","label":"被深深理解的连接","dim":"mot_belonging","base":0,"gain":1},{"key":"security","label":"稳固的退路与秩序","dim":"mot_security","base":0,"gain":1},{"key":"purpose","label":"做有回响的事","dim":"mot_purpose","base":0,"gain":1},{"key":"hedonism","label":"鲜活的感官与松弛","dim":"mot_hedonism","base":0,"gain":1}]},{"id":"v6_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_autonomy","is_sensitive":false,"weight":0.85,"prompt":"一条很稳、回报也很好、但需要你长期按别人节奏生活的路。你走在这条路上的实际状态是——","scale":{"left":"挺好，节奏清楚我反而更专注","right":"赚到了也在耗，总有一种说不清的闷","sdHigh":"left"},"effects":{"mot_autonomy":[-2,2],"mot_security":[1.6,-1.2],"val_boundary":[-1.2,1.6]}},{"id":"v6_q03","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"mot_mastery","is_sensitive":false,"weight":1.4,"prompt":"两个项目，你更愿意接哪一个？","options":[{"key":"A","text":"难度极高、失败概率一半，但做成之后会彻底改写你的位置","effects":{"mot_mastery":2,"mot_security":-1.4,"dark_psycho":1,"cog_ambiguity":1},"social_desirability":2},{"key":"B","text":"稳定推进、九成能成，做完没人会特别提起，但你的履历很干净","effects":{"mot_mastery":-1.4,"mot_security":1.8,"big5_order":1.2,"big5_alert":0.8},"social_desirability":3}]},{"id":"v6_q04","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"mot_belonging","is_sensitive":true,"weight":1.2,"context":"凌晨一点，你刚结束一段连轴的工作，手机里有很多新消息，但没有一条是你特别想点开的那个人发来的。","prompt":"那一瞬间你最真实的感觉是——","options":[{"key":"A","text":"很想有一个人，此刻就知道我今天有多累，不需要我说","effects":{"mot_belonging":2,"att_anxiety":1.4,"big5_compassion":1,"big5_rumination":0.8},"social_desirability":2},{"key":"B","text":"还好，安静挺好的，反正明天还有事要做，不必现在就想清楚","effects":{"mot_belonging":-1.6,"mot_autonomy":1.4,"att_avoidance":1.2,"def_detach":1},"social_desirability":1},{"key":"C","text":"有点空，但这种空会很快被第二天的事情填满，也就过去了","effects":{"mot_belonging":0.4,"mot_mastery":1.4,"def_intellectual":1,"mot_hedonism":-0.4},"social_desirability":2},{"key":"D","text":"干脆给自己找点事做，别让这种情绪有地方待着，也别多想","effects":{"mot_belonging":-0.8,"def_sublimate":1.6,"mot_purpose":1.2,"att_avoidance":0.8},"social_desirability":3}]},{"id":"v6_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_security","is_sensitive":false,"weight":0.85,"prompt":"关于「退路」，你的真实状态是——","scale":{"left":"手上得有至少两条能立刻走的路，我才会安心","right":"留太多退路本身就是一种不信任，我更愿意把自己逼到没有退路","sdHigh":"left"},"effects":{"mot_security":[2,-2],"big5_alert":[1.4,-1.2],"big5_rumination":[1,-0.8]}},{"id":"v6_q06","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"mot_purpose","is_sensitive":false,"weight":1.4,"context":"你爸的老同事在一家单位做了十年，做到中层，收入不错。第八年的时候他曾经短暂地想过：这些事对我以外的人，真的有什么意义吗？","prompt":"你猜后来他最可能走上了哪一条路？","options":[{"key":"A","text":"把那点念头收起来，日子照样过得很好，只是偶尔在夜里想起","effects":{"mot_purpose":-1.6,"mot_security":1.6,"def_sublimate":0.4,"big5_rumination":1},"social_desirability":1},{"key":"B","text":"开始在下班后做一个很小的、只对自己有意义的项目","effects":{"mot_purpose":1.8,"big5_industry":1.2,"mot_autonomy":1,"def_sublimate":1.2},"social_desirability":3},{"key":"C","text":"用那点念头做筹码，换了一个更大、更能影响人的位置","effects":{"mot_purpose":1,"mot_mastery":1.6,"dark_mach":1.2,"dark_narc":1},"social_desirability":2},{"key":"D","text":"干脆辞职去做那件事，哪怕要重新从很低的地方开始","effects":{"mot_purpose":1.6,"mot_autonomy":1.8,"mot_security":-1.6,"dark_psycho":1},"social_desirability":2}]},{"id":"v6_q07","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_hedonism","is_sensitive":false,"weight":0.85,"prompt":"一笔计划外的闲钱和一个完整的周末同时出现。你更想用它换——","scale":{"left":"一次非常好的体验：好餐厅、好位置、好天气","right":"把它存起来，或者换成一个更长久的东西","sdHigh":"right"},"effects":{"mot_hedonism":[2,-2],"mot_security":[-1.4,1.6],"big5_aesthetic":[1.2,-0.4],"virtue_temperance":[-1,1.2]}},{"id":"v6_q08","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"mot_autonomy","is_sensitive":true,"weight":1.4,"context":"两份工作摆在面前：一份给你极高的自由度，做什么、怎么做、什么时候做都由你定，但收入只有另一份的六成，而且没人给你兜底。","prompt":"你更可能选——","options":[{"key":"A","text":"自由度更高的那份，钱可以少赚，时间不能不给","effects":{"mot_autonomy":2,"mot_security":-1.6,"val_boundary":1.4,"big5_order":-0.6},"social_desirability":2},{"key":"B","text":"收入更稳的那份，自由是有了余裕之后才能谈的东西","effects":{"mot_autonomy":-1.6,"mot_security":2,"sin_greed":0.6,"lv_happiness":0.4},"social_desirability":3},{"key":"C","text":"先选稳的，用三年时间攒够可以买断自由的那笔钱","effects":{"mot_autonomy":1.2,"mot_security":1.4,"dark_mach":0.8,"cog_global":0.8},"social_desirability":2},{"key":"D","text":"两份都不选，我会自己造一个能同时满足这两件事的位置","effects":{"mot_autonomy":1.6,"mot_mastery":1.4,"sin_pride":1,"dark_psycho":0.8},"social_desirability":1}]},{"id":"v6_q09","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"mot_belonging","is_sensitive":true,"weight":0.85,"prompt":"一个人如果拥有极高的成就，但没有一段真正亲密的关系，你更倾向于认为——","scale":{"left":"那他大概在某个很深的夜里是空的","right":"成就本身就能填满一个人，亲密不是必需品","sdHigh":"left"},"effects":{"mot_belonging":[1.8,-1.8],"mot_mastery":[-1,1.4],"att_avoidance":[-1.2,1.4]}},{"id":"v6_q10","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"motors","is_sensitive":true,"weight":1.3,"context":"你已经被一件事困了三年：它体面、稳定、无可指摘，但每天早上醒来，你都要花一点力气说服自己去。","prompt":"现在把一百点「离开它的勇气」分配下去——你究竟在怕失去什么？分值越高，说明你越舍不得。","items":[{"key":"autonomy","label":"怕变成没人管的野人","dim":"mot_autonomy","base":0,"gain":1,"reverse":true},{"key":"mastery","label":"怕前功尽弃、从头再来","dim":"mot_mastery","base":0,"gain":1},{"key":"belonging","label":"怕失去这群熟悉的人","dim":"mot_belonging","base":0,"gain":1},{"key":"security","label":"怕断了收入与体面","dim":"mot_security","base":0,"gain":1},{"key":"purpose","label":"怕这三年其实毫无意义","dim":"mot_purpose","base":0,"gain":1},{"key":"hedonism","label":"怕丢掉现在这份舒服","dim":"mot_hedonism","base":0,"gain":1}]},{"id":"v6_q11","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_hedonism","is_sensitive":false,"weight":1.4,"prompt":"你会为了哪一种「浪费」而心甘情愿？","options":[{"key":"A","text":"一个下午什么都没做，只是坐在窗边看光移动","effects":{"mot_hedonism":1.8,"big5_aesthetic":1.4,"virtue_temperance":-0.4,"big5_industry":-1.2},"social_desirability":2},{"key":"B","text":"为了一顿很好的饭，跨半个城市排两个小时","effects":{"mot_hedonism":1.6,"sin_gluttony":1.2,"big5_open":0.8,"virtue_temperance":-1},"social_desirability":1},{"key":"C","text":"把整个周末给一个人，什么都不产出","effects":{"mot_hedonism":0.6,"mot_belonging":1.8,"att_anxiety":0.6,"mot_mastery":-0.8},"social_desirability":2},{"key":"D","text":"我不太会浪费，那些时间我都会换成别的东西","effects":{"mot_hedonism":-1.6,"mot_mastery":1.4,"big5_industry":1.6,"cog_global":0.4},"social_desirability":3}]},{"id":"v6_q12","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_mastery","is_sensitive":false,"weight":0.85,"prompt":"看到同龄人拿到了你也在追的东西，你心里那股力的方向通常是——","scale":{"left":"立刻回到自己的清单上，把今天该做的先做完","right":"先在心里反复比较，甚至有点不想打开手机","sdHigh":"left"},"effects":{"mot_mastery":[1.8,-1.2],"sin_envy":[-1.4,1.6],"def_sublimate":[1.2,-0.6]}},{"id":"v6_q13","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"mot_purpose","is_sensitive":false,"weight":1.4,"prompt":"两种「留下点什么」，你更想要哪一种？","options":[{"key":"A","text":"做出一个会被很多人长期使用、但没人记得是谁做的东西","effects":{"mot_purpose":1.8,"light_humanism":1.4,"dark_narc":-1.4,"virtue_humility":1.2},"social_desirability":3},{"key":"B","text":"做出一个被少数极懂的人高度认可、并且明确署你名号的东西","effects":{"mot_purpose":1,"dark_narc":1.6,"mot_mastery":1.4,"sin_pride":1},"social_desirability":1},{"key":"C","text":"不做东西，把身边几个人真正照顾好，这就够了","effects":{"mot_purpose":-0.6,"mot_belonging":1.8,"light_humanism":1,"mot_mastery":-1.2},"social_desirability":2}]},{"id":"v6_q14","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"mot_security","is_sensitive":false,"weight":1.2,"context":"一个你很信任的人突然告诉你，你父母正在考虑把这套住了二十年的房子卖掉，手续还没定，但已经在找人问了。","prompt":"听到这个消息的第一秒，你先想到的是——","options":[{"key":"A","text":"卖了以后他们住哪儿，先把这个问清楚，别的事往后放","effects":{"mot_security":2,"big5_alert":1.6,"cog_logic":1,"mot_autonomy":-0.4},"social_desirability":2},{"key":"B","text":"反而有点松了口气，也许这是个推所有人往前走的理由","effects":{"mot_security":-1.6,"mot_autonomy":1.6,"cog_ambiguity":1,"big5_open":1.2},"social_desirability":1},{"key":"C","text":"立刻开始在脑子里筛选哪些事要保住、哪些人要先去说","effects":{"mot_security":0.8,"dark_mach":1.8,"covert_control":1.2,"big5_assert":0.6},"social_desirability":1},{"key":"D","text":"先愣一下，脑子里出现的第一个画面是这间屋子里的那些年","effects":{"mot_security":-0.4,"mot_purpose":1.4,"big5_rumination":1.4,"mot_belonging":0.8},"social_desirability":3}]},{"id":"v6_q15","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_autonomy","is_sensitive":true,"weight":0.85,"prompt":"关于「被需要」，你更接近——","scale":{"left":"被很多人需要让我觉得这一天是满的","right":"被太多人需要会让我想关掉手机，独自待一会儿","sdHigh":"left"},"effects":{"mot_autonomy":[-1.6,2],"mot_belonging":[1.8,-1.4],"big5_social":[1.2,-1.2]}},{"id":"v6_q16","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"mot_security","is_sensitive":false,"weight":1.35,"context":"你姐夫有个习惯：不管收入多少，账上永远留着相当于十八个月生活的现金，宁可让它躺在那里贬值。","prompt":"你觉得他真正在守的是什么？","options":[{"key":"A","text":"一种随时可以说不的权利，钱买的其实是这个，别的都是附带","effects":{"mot_security":0.8,"mot_autonomy":1.8,"val_boundary":1.2,"big5_alert":0.4},"social_desirability":3},{"key":"B","text":"一种从很早以前就留下来的匮乏感，钱只是暂时压住了它","effects":{"mot_security":2,"big5_alert":1.8,"big5_rumination":1.2,"def_fawn":0.4},"social_desirability":1},{"key":"C","text":"一次还没发生的风险，他只是在为那个不确定买单","effects":{"mot_security":1.6,"cog_logic":1.2,"big5_order":1,"def_intellectual":0.8},"social_desirability":2}]},{"id":"v6_q17","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_purpose","is_sensitive":false,"weight":0.85,"prompt":"如果没人知道是你做的，你还会不会做那件事？","scale":{"left":"会，意义本身不依赖署名","right":"说实话会打折扣，被看见也是我做它的一部分","sdHigh":"left"},"effects":{"mot_purpose":[1.8,-1.2],"dark_narc":[-1.6,1.6],"light_humanism":[1.2,-0.6]}},{"id":"v6_q18","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"mot_belonging","is_sensitive":true,"weight":1.4,"prompt":"你和一个人关系很近，但对方最近明显把你排在了他的优先级后面。你的实际反应更接近——","options":[{"key":"A","text":"会反复想是哪里出了变化，忍不住先去确认","effects":{"mot_belonging":1.6,"att_anxiety":2,"big5_rumination":1.6,"def_fawn":0.8},"social_desirability":1},{"key":"B","text":"把距离默默拉远一点，不问了，也不等了","effects":{"mot_belonging":-1.4,"att_avoidance":1.8,"def_detach":1.4,"big5_compliance":-0.6},"social_desirability":1},{"key":"C","text":"直接问一次，把话说清楚，然后看他的回答决定去留","effects":{"mot_belonging":1.2,"big5_assert":1.6,"light_kant":1,"att_anxiety":-0.4},"social_desirability":3},{"key":"D","text":"自己去找点别的事做，人和人的距离本来就有季节性","effects":{"mot_belonging":-0.4,"mot_autonomy":1.4,"cog_ambiguity":1,"att_avoidance":0.8},"social_desirability":2}]}]},"vol7":{"volume_id":"vol7","index":7,"title":"亲密防线","subtitle":"依恋模式与六大心理防御机制","theme_color":"#6D5472","estimated_minutes":5,"intro":"这一卷关心的是：当关系靠得太近、或你被真正伤到的那一刻，你的潜意识会先弹出哪一个保护罩。它通常比你的理智快零点三秒。","dimensions":["att_anxiety","att_avoidance","def_intellectual","def_detach","def_sublimate","def_attack","def_fawn","def_project"],"questions":[{"id":"v7_q01","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"att_anxiety","is_sensitive":true,"weight":0.85,"prompt":"一条发给重要的人的消息，已经过了四个小时没有回。中间你看过手机几次？","scale":{"left":"一次都没有，我知道他在忙","right":"很多次，而且会开始反复看自己上一条是不是说得不对","sdHigh":"left"},"effects":{"att_anxiety":[-2,2],"big5_rumination":[-1.2,1.8],"def_fawn":[-0.8,1.2],"big5_alert":[-0.6,1]}},{"id":"v7_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"att_avoidance","is_sensitive":true,"weight":0.85,"prompt":"一段关系走到了非常好的阶段，对方开始把很多私人的事交给你。你身体里出现的第一反应是——","scale":{"left":"心里是暖的，我想更靠近他一点","right":"有一点点想退，太近的时候我会需要一点自己的空间","sdHigh":"left"},"effects":{"att_avoidance":[-2,2],"big5_social":[1,-1.2],"mot_autonomy":[-1.4,1.6],"big5_compassion":[1,-0.8]}},{"id":"v7_q03","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"def_intellectual","is_sensitive":true,"weight":1.4,"context":"你在一次重要的场合被当面否定了，回家的路上，胸口一直闷着。","prompt":"接下来的两个小时里，你更可能做的事是——","options":[{"key":"A","text":"把整件事拆开分析，找出他在逻辑上站不住的地方，一条条列出来","effects":{"def_intellectual":2,"cog_logic":1.4,"big5_rumination":0.8,"def_detach":0.6},"social_desirability":2},{"key":"B","text":"什么也不想，直接去跑步、去收拾房间，让身体先累下来","effects":{"def_sublimate":2,"def_intellectual":-1,"big5_industry":1,"big5_rumination":-0.8},"social_desirability":3},{"key":"C","text":"把这件事讲给一个很信任的人听，讲到情绪出来为止","effects":{"def_intellectual":-1.6,"mot_belonging":1.6,"big5_compassion":1.2,"att_anxiety":0.6},"social_desirability":2},{"key":"D","text":"干脆打开电脑干活，用下一件事把这整段时间彻底填满","effects":{"def_detach":1.6,"def_sublimate":1,"big5_industry":1.4,"big5_rumination":-0.4},"social_desirability":1}]},{"id":"v7_q04","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"def_detach","is_sensitive":true,"weight":1.25,"context":"你刚收到一个很坏的消息，手指还在发抖，人卡在电梯里。电梯门还没开，身后站着两个你并不熟的同事。","prompt":"那十几秒里，你身体自动接管的方式是——","options":[{"key":"A","text":"一下子什么感觉都没有了，像隔着一层玻璃在看自己","effects":{"def_detach":2,"big5_compassion":-0.8,"att_avoidance":1.2,"def_intellectual":0.6},"social_desirability":1},{"key":"B","text":"眼泪先上来了，完全压不住，只能低头假装看手机","effects":{"def_detach":-1.8,"big5_compassion":1.6,"att_anxiety":1.4,"big5_rumination":0.8},"social_desirability":0},{"key":"C","text":"脑子立刻开始处理：接下来要打几个电话、做什么决定","effects":{"def_intellectual":1.6,"def_detach":0.8,"big5_order":1.2,"cog_logic":0.8},"social_desirability":3},{"key":"D","text":"一股火先出来，想找一个人问清楚为什么会这样","effects":{"def_attack":1.8,"sin_wrath":1.4,"big5_assert":1,"def_detach":-0.6},"social_desirability":1}]},{"id":"v7_q05","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"def_fawn","is_sensitive":true,"weight":0.85,"prompt":"你走进一个房间，发现里面两个人正在低声争一件事，你一进门他们就停了。你的第一动作是——","scale":{"left":"当作没看见，继续做自己的事","right":"立刻开始读空气，判断自己是不是那个话题","sdHigh":"left"},"effects":{"def_fawn":[-1.8,2],"big5_compassion":[0.8,1.4],"att_anxiety":[-0.8,1.6],"big5_alert":[-0.4,0.8]}},{"id":"v7_q06","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"def_attack","is_sensitive":true,"weight":1.4,"context":"家族群里，有人用一个明显扭曲过的说法描述了你去年做的一个决定，而且这段话被好几位长辈接着往下说了。","prompt":"你更可能的选择是——","options":[{"key":"A","text":"当场在群里打断，把原话说清楚，语气会明显变硬","effects":{"def_attack":2,"big5_assert":1.6,"sin_wrath":1.2,"big5_compliance":-1.2},"social_desirability":1},{"key":"B","text":"群里不接，之后单独找那个人，把这件事处理掉","effects":{"def_attack":0.4,"covert_control":1.6,"dark_mach":1,"big5_compliance":-0.4},"social_desirability":3},{"key":"C","text":"先忍着，等下把完整的事实写成一段长文字发出去","effects":{"def_intellectual":1.6,"light_kant":1.2,"big5_order":1,"def_attack":-0.8},"social_desirability":2},{"key":"D","text":"几乎没反应，我大概会在心里把这个人彻底划掉","effects":{"def_attack":-1.4,"def_detach":1.8,"att_avoidance":1.2,"sin_wrath":0.6},"social_desirability":1}]},{"id":"v7_q07","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"def_project","is_sensitive":true,"weight":0.85,"prompt":"别人夸你的时候，你内心深处最先冒出来的判断通常是——","scale":{"left":"他大概是真的这么觉得，我先收下","right":"他可能只是客气，或者想让我做点什么","sdHigh":"left"},"effects":{"def_project":[-2,2],"big5_alert":[-1.2,1.6],"light_faith":[1.4,-1.4],"sin_pride":[0.4,-0.8]}},{"id":"v7_q08","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"att_avoidance","is_sensitive":true,"weight":1.4,"context":"你的高中同桌和一个人相处了半年，对方开始提到明年一起住。他笑着说好，那天晚上一个人在楼下走了很久。","prompt":"你觉得他那一刻最真实的感受是——","options":[{"key":"A","text":"很高兴，同时有一种什么东西正在结束的慌，说不清是舍不得还是怕","effects":{"att_avoidance":2,"mot_autonomy":1.4,"def_detach":1,"big5_rumination":0.8},"social_desirability":1},{"key":"B","text":"只是在算实际的事：钱、位置、通勤、两个人的习惯能不能合","effects":{"att_avoidance":0.6,"def_intellectual":1.8,"cog_logic":1.2,"att_anxiety":-0.4},"social_desirability":2},{"key":"C","text":"有点想哭，他一直想要的就是这个，只是没想到真的来了","effects":{"att_avoidance":-1.8,"mot_belonging":1.8,"att_anxiety":1,"big5_compassion":1.2},"social_desirability":3}]},{"id":"v7_q09","type":"impulse_3s","stealth_mode":"impulse","layer":"explicit","mirror_key":"def_attack","is_sensitive":true,"weight":1.25,"context":"在一场争吵里，对方忽然扔出一句：「你在乎的从来只有你自己。」你知道这句话不完全是事实，但你也没法说它全错。","prompt":"这句话落地的那一秒，你的第一反应是——","options":[{"key":"A","text":"立刻反击，用一句更准的话扎回去，让他也疼一下","effects":{"def_attack":2,"sin_wrath":1.8,"big5_assert":1.2,"big5_compassion":-1},"social_desirability":0},{"key":"B","text":"整个人一下空了，所有话都堵住了，只想离开房间","effects":{"def_detach":1.8,"def_fawn":0.8,"big5_rumination":1.4,"def_attack":-1.4},"social_desirability":1},{"key":"C","text":"先承认那部分是真的，然后问他这次具体是哪件事让他这么想","effects":{"def_intellectual":1.2,"light_kant":1.4,"big5_compassion":1.6,"def_attack":-1.6},"social_desirability":3},{"key":"D","text":"马上道歉，先把他的情绪稳住，剩下的之后再说","effects":{"def_fawn":2,"att_anxiety":1.6,"big5_compliance":1.4,"def_attack":-1.2},"social_desirability":2}]},{"id":"v7_q10","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"def_sublimate","is_sensitive":false,"weight":0.85,"prompt":"一段很难受的日子过去后，你回头看，那段时间你的产出往往是——","scale":{"left":"反而很高，痛苦被我烧成了燃料","right":"几乎停摆，我做不到一边疼一边做事","sdHigh":"left"},"effects":{"def_sublimate":[2,-2],"big5_industry":[1.4,-1],"big5_rumination":[-0.6,1.2]}},{"id":"v7_q11","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"att_anxiety","is_sensitive":true,"weight":1.4,"context":"你和一个人很好，好到你已经习惯了他每天都会出现。今天他没有出现，也没有说为什么。","prompt":"你实际的应对方式是——","options":[{"key":"A","text":"会等到很晚，然后把手机放在看得到的地方，反复拿起又放下","effects":{"att_anxiety":2,"big5_rumination":1.8,"def_fawn":1,"mot_belonging":1.2},"social_desirability":1},{"key":"B","text":"照常过自己的晚上，他不出现一定有不出现的理由","effects":{"att_anxiety":-1.8,"att_avoidance":1.2,"mot_autonomy":1.2,"light_faith":1},"social_desirability":3},{"key":"C","text":"会主动发一条很轻的消息过去，然后盯着屏幕看他的反应","effects":{"att_anxiety":1.2,"big5_assert":1,"def_intellectual":0.6,"light_kant":0.6},"social_desirability":2},{"key":"D","text":"不问，也不会等，但心里开始给这段关系悄悄降级","effects":{"att_anxiety":0.8,"att_avoidance":1.6,"def_detach":1.4,"big5_compliance":-0.6},"social_desirability":1}]},{"id":"v7_q12","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"def_fawn","is_sensitive":true,"weight":0.85,"prompt":"你和一个情绪起伏比较大的人长期相处。你在这段关系里的真实位置更接近——","scale":{"left":"我会被他的情绪带着走，先处理他的状态再说自己","right":"我会守住自己的节奏，他的情绪是他的功课","sdHigh":"right"},"effects":{"def_fawn":[2,-2],"att_anxiety":[1.4,-1.2],"big5_compliance":[1.6,-1.4],"big5_compassion":[1.2,-0.6]}},{"id":"v7_q13","type":"forced_choice","stealth_mode":"ipsative","layer":"explicit","mirror_key":"def_intellectual","is_sensitive":true,"weight":1.4,"prompt":"两种「难过」，你更常经历的是——","options":[{"key":"A","text":"情绪很浓，但我说不清它到底是什么，只能等它过去","effects":{"def_intellectual":-1.8,"big5_compassion":1.4,"big5_rumination":1.2,"cog_logic":-1},"social_desirability":1},{"key":"B","text":"情绪不浓，但我能在脑子里把它解释得非常清楚，甚至有点得意","effects":{"def_intellectual":1.8,"cog_logic":1.4,"def_detach":0.8,"big5_compassion":-1.2},"social_desirability":2}]},{"id":"v7_q14","type":"stealth_scale","stealth_mode":"projection","layer":"explicit","mirror_key":"def_project","is_sensitive":true,"weight":0.85,"prompt":"一个朋友最近对你有些冷淡。你心里最有分量的那个解释是——","scale":{"left":"他大概最近自己过得不容易","right":"他是不是在什么地方对我不满了","sdHigh":"left"},"effects":{"def_project":[-1.8,2],"att_anxiety":[-1.2,1.6],"big5_compassion":[1.2,-0.6],"big5_alert":[-0.6,1]}},{"id":"v7_q15","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"def_detach","is_sensitive":true,"weight":0.85,"prompt":"在一场真正让你难过的电影或消息之后，你通常需要多久才能重新感觉到自己？","scale":{"left":"其实没走远，情绪一直在，我只是在压它","right":"很快就能抽出来，像换了个人一样继续","sdHigh":"left"},"effects":{"def_detach":[-1.8,2],"big5_compassion":[1.2,-1.2],"def_intellectual":[-0.6,1]}},{"id":"v7_q16","type":"forced_choice","stealth_mode":"projection","layer":"explicit","mirror_key":"att_anxiety","is_sensitive":true,"weight":1.35,"context":"认识十年的发小和伴侣在一起五年，关系稳定。伴侣最近换了一份要频繁出差的工作。","prompt":"你猜她接下来最可能的样子是——","options":[{"key":"A","text":"表面支持，但心里会开始数对方不在的日子，越想越不安","effects":{"att_anxiety":2,"big5_rumination":1.6,"def_fawn":0.8,"mot_belonging":1.2},"social_desirability":1},{"key":"B","text":"会认真谈一次边界：多久见一次、怎么保持联系、哪些事必须同步","effects":{"att_anxiety":-0.6,"light_kant":1.4,"big5_order":1.2,"big5_assert":1},"social_desirability":3},{"key":"C","text":"其实有点松了口气，多出来的一段时间她可以做自己的事","effects":{"att_anxiety":-1.4,"att_avoidance":1.8,"mot_autonomy":1.4,"def_detach":0.8},"social_desirability":1},{"key":"D","text":"会把更多精力放回工作，反正这段时间也没别的安排","effects":{"att_anxiety":-0.4,"def_sublimate":1.6,"mot_mastery":1.4,"att_avoidance":0.6},"social_desirability":2}]},{"id":"v7_q17","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"def_attack","is_sensitive":true,"weight":0.85,"prompt":"有人踩到了你非常在意的那条线。你通常的反应节奏是——","scale":{"left":"当场就会把态度放到脸上，让对方立刻知道","right":"当时几乎没反应，事后在心里演练很多遍才把话说完","sdHigh":"right"},"effects":{"def_attack":[2,-1.8],"big5_assert":[1.4,-1.4],"big5_rumination":[-1,1.6],"sin_wrath":[1.2,-0.6]}},{"id":"v7_q18","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"def_sublimate","is_sensitive":false,"weight":1.4,"prompt":"一个人如果被生活反复捶打，你最希望他最后长出的是哪一种能力？","options":[{"key":"A","text":"把那些东西变成作品、手艺或者身体的力量","effects":{"def_sublimate":1.8,"mot_purpose":1.2,"big5_industry":1,"lv_suffering":0.8},"social_desirability":3},{"key":"B","text":"能把它说清楚、理解透，然后放下","effects":{"def_intellectual":1.8,"cog_logic":1.2,"def_detach":0.6,"lv_suffering":0.6},"social_desirability":2},{"key":"C","text":"敢于当场不让那些东西再发生一次","effects":{"def_attack":1.6,"big5_assert":1.4,"sin_wrath":0.8,"mot_autonomy":1},"social_desirability":1},{"key":"D","text":"还能继续相信人，继续愿意靠近别人","effects":{"light_faith":1.8,"big5_compassion":1.6,"mot_belonging":1.2,"def_fawn":-0.8},"social_desirability":3}]}]},"vol8":{"volume_id":"vol8","index":8,"title":"高压剧场","subtitle":"暗箱投射、极端底线与面具镜像校验","theme_color":"#3F4C54","estimated_minutes":6,"intro":"这一卷是整套测评的试金石。所有情境都发生在你最不体面的那些时刻：连续失眠、被背刺、退路断掉。这里没有正确答案，只有你在没有力气伪装时会做的事情。","dimensions":["sin_pride","virtue_humility","sin_greed","virtue_charity","sin_wrath","virtue_patience","dark_mach","dark_narc","dark_psycho","light_kant","light_faith","light_humanism","big5_compliance","big5_assert","big5_alert","big5_rumination","att_anxiety","att_avoidance","def_intellectual","def_detach","def_attack","def_fawn","def_project","mot_security","mot_autonomy","mot_belonging","mot_mastery"],"questions":[{"id":"v8_q01","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","kind":"pressure","mirror_key":"wrath_patience","is_sensitive":true,"weight":1.4,"context":"你为一场婚礼筹备了三个月，所有细节都定好了。仪式前两小时，另一半的家人临时决定把流程整个换掉，还在群里说「这是我们商量过的」。你已经连续三周没睡好。","prompt":"此刻你最可能做的事是——","options":[{"key":"A","text":"当场把话说开，语气很难听，事后可能会后悔但当下必须说","style":"burst","effects":{"sin_wrath":2,"virtue_patience":-1.8,"def_attack":1.8,"big5_assert":1.4},"social_desirability":0},{"key":"B","text":"一句话不说，把这件事从我的责任里彻底拿掉，之后谁问都不接","style":"cutoff","effects":{"sin_wrath":0.8,"def_detach":1.8,"att_avoidance":1.6,"virtue_patience":-0.4},"social_desirability":1},{"key":"C","text":"表情不变，先按新流程走完，同时开始清理这个人在往后的所有位置","style":"cold","effects":{"sin_wrath":1,"dark_psycho":1.8,"dark_mach":1.6,"def_detach":1},"social_desirability":1},{"key":"D","text":"硬撑着走完，回家之后整个人塌下来，开始怀疑是不是自己一直不行","style":"collapse","effects":{"sin_wrath":-0.8,"big5_rumination":1.8,"def_fawn":1.2,"big5_alert":1.4},"social_desirability":2}]},{"id":"v8_q02","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","kind":"pressure","mirror_key":"att_avoidance","is_sensitive":true,"weight":1.35,"context":"你花了两年才肯把这件事交给一个人，结果那个人在最关键的节点上，把你的软肋当成了一次谈判筹码。","prompt":"你接下来的第一年是——","options":[{"key":"A","text":"彻底关掉，不再给任何人这种权限，我也许会一直这样","style":"cutoff","effects":{"att_avoidance":2,"def_detach":1.8,"light_faith":-1.4,"mot_autonomy":1.2},"social_desirability":1},{"key":"B","text":"会一次一次去找类似的人，直到有一个人证明他不一样","style":"burst","effects":{"att_anxiety":2,"big5_rumination":1.6,"def_fawn":0.8,"att_avoidance":-1},"social_desirability":1},{"key":"C","text":"安静地重新规划，把所有关系都按风险等级重新排一遍","style":"cold","effects":{"dark_mach":1.2,"covert_control":1.6,"def_intellectual":1.4,"att_avoidance":1},"social_desirability":2},{"key":"D","text":"很长时间都缓不过来，会反复回想自己当初哪里看错了","style":"collapse","effects":{"att_anxiety":1.4,"big5_rumination":1.8,"def_project":1.2,"light_faith":-1},"social_desirability":2}]},{"id":"v8_q03","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","kind":"pressure","mirror_key":"mot_security","is_sensitive":true,"weight":1.35,"context":"三件事撞在同一周：手上的事彻底黄了、银行卡因为一次误操作被冻结、老家打来电话说急需一笔钱。而你能开口的人，一个都不在。","prompt":"接下来的七十二小时，你的身体会先做哪一件事？","options":[{"key":"A","text":"把所有能变现的东西列出来，一通一通电话打过去，先把窟窿堵住","style":"cold","effects":{"mot_security":1.8,"cog_logic":1.4,"dark_psycho":1.2,"big5_alert":1},"social_desirability":2},{"key":"B","text":"整个人停住，什么都不做，躺在床上看天花板，等这件事自己变轻","style":"collapse","effects":{"mot_security":1.2,"big5_rumination":1.6,"def_detach":1.2,"sin_sloth":1.4},"social_desirability":1},{"key":"C","text":"翻遍通讯录，去找那个最不该找、但此刻唯一还能开口问的人","style":"burst","effects":{"mot_belonging":1.6,"att_anxiety":1.4,"big5_compliance":1.2,"mot_autonomy":-1},"social_desirability":2},{"key":"D","text":"先谁也不说，把自己关起来，等想清楚一条完整的路再开口","style":"cutoff","effects":{"mot_autonomy":1.6,"att_avoidance":1.4,"covert_control":1,"def_intellectual":0.8},"social_desirability":3}]},{"id":"v8_q04","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"pride_humility","is_sensitive":true,"weight":0.85,"context":"一大家子在饭桌上，你正讲一件自己很熟的事。一个刚上大学的表弟打断你，说你刚才那句讲错了，而且他说得对。桌上七八个人都停下来看你。","prompt":"那一瞬间，你心里最真实的一句是——","scale":{"left":"他说得对，我当场就改口，别的都是小事","right":"这个场合一旦在这儿被改口，往后我在这张桌上说的话就不作数了","sdHigh":"left"},"effects":{"sin_pride":[-2,2],"virtue_humility":[2,-2],"dark_narc":[-1.2,1.6],"big5_assert":[-1,1]}},{"id":"v8_q05","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"greed_charity","is_sensitive":true,"weight":0.85,"context":"一个你带过的新人，现在正需要你手里唯一的那个名额。给他，你要再等一年。","prompt":"你心里最诚实的那个答案是——","scale":{"left":"先给自己，我这一年也等不起","right":"给他，我还能再熬一年，他可能熬不了","sdHigh":"right"},"effects":{"sin_greed":[2,-1.8],"virtue_charity":[-1.8,2],"light_humanism":[-1.2,1.6],"mot_security":[1.4,-1]}},{"id":"v8_q06","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"dark_mach","is_sensitive":true,"weight":0.85,"context":"你已经确认了那个人的把柄，只要在合适的场合放出去，你能一次解决掉三年的麻烦。你也在想，这样做之后自己会变成什么样。","prompt":"你更接近的状态是——","scale":{"left":"会算准时机用出去，能用一次解决三年的事没理由不用","right":"会留着，但大概率永远不会用，我不想变成需要用它的人","sdHigh":"right"},"effects":{"dark_mach":[2,-2],"light_kant":[-1.6,1.8],"covert_control":[1.6,-1.2],"light_humanism":[-1.2,1.2]}},{"id":"v8_q07","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"att_anxiety","is_sensitive":true,"weight":0.85,"context":"凌晨两点，你发现自己被一个重要的人从一个小群里移出去了。没有任何解释。","prompt":"接下来的十分钟你会做的事是——","scale":{"left":"先睡，明天再说，这件事不值得我现在处理","right":"马上开始翻聊天记录，找出自己哪句话说错了","sdHigh":"left"},"effects":{"att_anxiety":[-2,2],"big5_rumination":[-1.6,2],"def_fawn":[-1,1.4],"def_project":[-0.8,1.2]}},{"id":"v8_q08","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"att_avoidance","is_sensitive":true,"weight":0.85,"context":"有人在你最狼狈的那个晚上，什么都没有问，直接来了。他就站在门口，手里拎着东西。","prompt":"你的第一反应是——","scale":{"left":"让他进来，那一刻我很需要有人在","right":"本能地想说我没事，先把门关一半","sdHigh":"left"},"effects":{"att_avoidance":[-2,2],"mot_belonging":[1.6,-1.2],"def_detach":[-1.2,1.4],"big5_compassion":[1.2,-1]}},{"id":"v8_q09","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"def_fawn","is_sensitive":true,"weight":0.85,"context":"一个掌握你评价的人在饭桌上开了一个让你很难堪的玩笑，全桌都在笑，包括你不太熟的人。","prompt":"你的身体会先做哪一件事？","scale":{"left":"跟着笑一下，把这个场面接过去","right":"表情会变，会让他知道这句话不合适","sdHigh":"left"},"effects":{"def_fawn":[2,-1.8],"big5_compliance":[1.6,-1.4],"big5_assert":[-1.4,1.6],"sin_wrath":[-0.8,1.2]}},{"id":"v8_q10","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"def_intellectual","is_sensitive":true,"weight":0.85,"context":"你刚刚失去了一个对你意义非常大的东西。它不会回来了。房间里很安静。","prompt":"一个小时之后，你的状态更接近——","scale":{"left":"在脑子里把它拆成几个阶段，理解它为什么会发生","right":"什么都想不了，只是坐在那，感觉像被抽走了一块","sdHigh":"left"},"effects":{"def_intellectual":[2,-2],"def_detach":[1.4,-1.2],"big5_compassion":[-1.2,1.6],"big5_rumination":[-0.4,1]}},{"id":"v8_q11","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"big5_compliance","is_sensitive":true,"weight":0.85,"context":"你已经很累了，但一个你不想得罪的人又提出了一个新的要求，这件事本可以明天做。","prompt":"对话停在那里，最后从你嘴里出去的那句更接近——","scale":{"left":"好的，我现在就弄","right":"明天一早给你，今晚我做不了了","sdHigh":"left"},"effects":{"big5_compliance":[1.8,-1.8],"def_fawn":[1.4,-1.2],"big5_assert":[-1.2,1.6],"att_anxiety":[0.8,-0.8]}},{"id":"v8_q12","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"light_kant","is_sensitive":true,"weight":0.85,"context":"有一个可以让整件事翻盘的机会，代价是要在一个不重要的细节上说一句不完整的话，没有人会发现。","prompt":"你会——","scale":{"left":"会说，这个细节不重要，结果更重要","right":"不会说，一旦开了这个口，之后所有事都会松","sdHigh":"right"},"effects":{"light_kant":[-2,2],"val_moral":[-1.8,1.8],"dark_mach":[1.6,-1.4],"cog_ambiguity":[1.2,-0.8]}},{"id":"v8_q13","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"mot_security","is_sensitive":true,"weight":0.85,"context":"你有一个可以立刻离开现在生活方式的窗口，只有三天。走了就没有退路，留下就再等三年。","prompt":"你更可能——","scale":{"left":"留，我的人生不能没有一条退路","right":"走，退路本身就是一种慢性消耗","sdHigh":"left"},"effects":{"mot_security":[2,-1.8],"mot_autonomy":[-1.8,2],"big5_alert":[1.4,-1.2],"dark_psycho":[-0.8,1.4]}},{"id":"v8_q14","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"def_attack","is_sensitive":true,"weight":0.85,"context":"有人在公开场合把你的一次失败描述成了你的性格问题，措辞很体面，但意思很清楚。","prompt":"你的第一秒是——","scale":{"left":"当场就接回去，把他的话原样拆开","right":"表面没动，回去之后在心里把这个人划掉","sdHigh":"right"},"effects":{"def_attack":[1.8,-1.6],"def_detach":[-1.4,1.8],"sin_wrath":[1.2,-0.6],"big5_assert":[1.2,-1]}},{"id":"v8_q15","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","kind":"pressure","mirror_key":"def_detach","is_sensitive":true,"weight":1.35,"context":"你被最信任的两个人同时瞒了一件事，这件事已经持续了半年，而今天他们决定一起告诉你。","prompt":"你听完之后的第一个动作是——","options":[{"key":"A","text":"把两个人一起赶出去，把门关上，把手机也关掉","style":"cutoff","effects":{"def_detach":2,"att_avoidance":1.6,"light_faith":-1.4,"sin_wrath":0.6},"social_desirability":1},{"key":"B","text":"当场把话全部说完，一句不留，可能说得非常狠","style":"burst","effects":{"sin_wrath":1.8,"def_attack":1.8,"big5_assert":1.2,"big5_compassion":-0.8},"social_desirability":0},{"key":"C","text":"非常平静地把每一件事的时间点问清楚，像是在整理一份材料","style":"cold","effects":{"def_intellectual":1.8,"def_detach":1.4,"cog_logic":1,"dark_psycho":0.8},"social_desirability":3},{"key":"D","text":"说不出话，先回房间，过了很久才发现自己在发抖","style":"collapse","effects":{"big5_rumination":1.8,"att_anxiety":1.4,"def_fawn":0.6,"def_attack":-1.2},"social_desirability":2}]},{"id":"v8_q16","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","kind":"pressure","mirror_key":"dark_narc","is_sensitive":true,"weight":1.3,"context":"你在这件事上一个人扛了两年，最难的部分全是你做的。今天它成了，所有公开的说法里都没有你的名字。","prompt":"你最可能做的事是——","options":[{"key":"A","text":"找一个合适的场合，把关键细节讲出来，让别人知道是谁做的","style":"burst","effects":{"dark_narc":1.8,"sin_pride":1.4,"big5_assert":1.6,"virtue_humility":-1},"social_desirability":1},{"key":"B","text":"不说了，但会在心里记很久，之后不再交付出这个量级的力气","style":"cutoff","effects":{"dark_narc":0.6,"def_detach":1.6,"mot_mastery":-1.2,"big5_rumination":1.2},"social_desirability":2},{"key":"C","text":"开始重新安排下一件事的资源，让自己成为那个无法被绕过的人","style":"cold","effects":{"dark_narc":1.2,"covert_control":1.8,"dark_mach":1.4,"mot_mastery":1.4},"social_desirability":2},{"key":"D","text":"一个人待了很久，开始怀疑是不是自己本来就没那么重要","style":"collapse","effects":{"dark_narc":0.8,"big5_rumination":1.8,"big5_alert":1.2,"virtue_humility":0.8},"social_desirability":3}]},{"id":"v8_q17","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","kind":"pressure","mirror_key":"def_attack","is_sensitive":true,"weight":1.3,"context":"你被一个曾经公开羞辱过你的人，现在反过来请求帮忙，姿态放得很低，而这件事确实只有你能做。","prompt":"你会怎么处理？","options":[{"key":"A","text":"帮，但要让他清楚记住是我帮的，而且只有这一次","style":"cold","effects":{"dark_mach":1.4,"covert_control":1.4,"dark_narc":0.8,"light_humanism":0.4},"social_desirability":2},{"key":"B","text":"不帮。把当初他说的那句话原样还给他，一个字都不用多加","style":"burst","effects":{"sin_wrath":1.8,"def_attack":1.6,"light_humanism":-1.2,"virtue_patience":-1.2},"social_desirability":0},{"key":"C","text":"不接，也不回，把他放进一个再也不会被打开的抽屉","style":"cutoff","effects":{"def_detach":1.8,"sin_wrath":0.4,"att_avoidance":1.2,"light_humanism":-0.6},"social_desirability":1},{"key":"D","text":"帮了。一边帮一边在心里算这已经是第几次，帮完那天晚上一句话都不想说","style":"collapse","effects":{"light_humanism":0.6,"virtue_patience":-0.4,"def_fawn":1.6,"big5_rumination":1.4},"social_desirability":1}]},{"id":"v8_q18","type":"stealth_scale","stealth_mode":"mirror","layer":"stealth","mirror_key":"mot_autonomy","is_sensitive":true,"weight":0.85,"context":"所有人都劝你留下来，条件优厚、前途清晰、所有人都会说你做了正确的选择。只有你自己知道，每天早上醒来那三分钟的沉默正在变长。","prompt":"你最后会——","scale":{"left":"留下，那些沉默会慢慢变成生活本来的样子","right":"走，宁可承担一段很长时间的混乱","sdHigh":"left"},"effects":{"mot_autonomy":[-2,2],"mot_security":[1.4,-1.6],"val_boundary":[-1.4,1.8],"lv_anchor":[0.6,-1]}}]},"vol9":{"volume_id":"vol9","index":9,"title":"认知星盘","subtitle":"荣格八维认知功能栈与阴影位","theme_color":"#2F5266","estimated_minutes":5,"intro":"这一卷不问你有多聪明，只看你如何加工世界：靠什么理解一件事，靠什么判断一个人，靠什么确认自己没走偏。八种认知功能没有高下，只有此刻谁在台前、谁被留在后台的阴影位。","dimensions":["jung_te","jung_ti","jung_fe","jung_fi","jung_ne","jung_ni","jung_se","jung_si"],"questions":[{"id":"v9_q01","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_fi","is_sensitive":true,"weight":1.4,"context":"上周六你们为一件很小的事吵到凌晨一点，谁也没说服谁，各自背过身睡了。第二天早上洗衣机在转，两个人在同一个厨房里绕开对方。","prompt":"水壶烧开的那两分钟里，你脑子里最先启动的是哪一种处理方式？","options":[{"key":"A","text":"把昨晚每句话逐句复原，找出他哪一段其实前后矛盾、根本站不住","effects":{"jung_ti":2,"jung_fe":-0.9,"cog_logic":1.2,"big5_rumination":0.8},"social_desirability":1},{"key":"B","text":"先弄清自己心里那道坎到底是什么：我究竟在哪一句上觉得被冒犯","effects":{"jung_fi":2,"jung_ti":-0.8,"val_moral":0.9,"att_anxiety":0.7},"social_desirability":2},{"key":"C","text":"想他昨晚是不是也没睡好，先倒一杯他喝的东西递过去，把气氛化开","effects":{"jung_fe":2,"jung_ti":-0.6,"big5_compassion":1.3,"big5_compliance":0.7},"social_desirability":3},{"key":"D","text":"直接把规矩定下来：这类事以后再发生，谁负责哪一步，别又耗一整晚","effects":{"jung_te":2,"jung_fi":-0.8,"big5_order":1.2,"big5_assert":0.9},"social_desirability":2}]},{"id":"v9_q02","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_si","is_sensitive":false,"weight":0.85,"prompt":"凌晨两点四十，你已经躺了三个小时，手机扣在床头。你没在想工作，脑子却自己开始放东西。它放的是——","scale":{"left":"白天那些具体画面：谁说话时手在抖、那杯没喝完的茶、楼道里换掉的地砖","right":"一条线，顺着它一直往前推，推到三年后这件事会变成什么形状","sdHigh":"right"},"effects":{"jung_si":[2,-2],"jung_ni":[-2,2],"cog_global":[-1.4,1.4],"big5_rumination":[1.2,-0.6]}},{"id":"v9_q03","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","mirror_key":"jung_te","is_sensitive":true,"weight":1.4,"context":"公司账上的钱只够发这个月工资。周一早上九点，白板上还写着原定三个月的路线图，老板说了句「你们看着办」就出去了。","prompt":"白板笔递到你手里，你先擦掉的是哪一块？","options":[{"key":"A","text":"先砍掉三件最贵又不产钱的事，剩下的人按能交付的日期重排一遍","effects":{"jung_te":2,"jung_ne":-0.9,"big5_order":1.3,"cog_speed":0.9},"social_desirability":2},{"key":"B","text":"先看屋里这七八张脸：谁会被裁、谁家里刚添了孩子，怎么分才不至于塌","effects":{"jung_fe":2,"jung_te":-1.1,"big5_compassion":1.3,"mot_belonging":0.9},"social_desirability":3},{"key":"C","text":"不等讨论完，先把自己手上那条最快能换钱的线当天跑起来，边跑边改","effects":{"jung_se":2,"jung_ne":-0.8,"big5_industry":1.4,"cog_speed":1.1},"social_desirability":1},{"key":"D","text":"把原来那条路整个扔掉，问一句：不做现在这个产品，我们还有什么能活","effects":{"jung_ne":1.9,"jung_si":-1.1,"cog_diverge":1.3,"big5_open":1.2},"social_desirability":2}]},{"id":"v9_q04","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"jung_se","is_sensitive":false,"weight":1.25,"context":"夏天傍晚，你在便利店门口等雨停。一个外卖员的车在积水里滑倒，后座的餐盒散了一地，后面排队的喇叭开始响。","prompt":"雨还在下，你的脚动之前，身体已经先做了什么？","options":[{"key":"A","text":"已经蹲下去了，先把还封着的那几盒捞起来，别让雨水顺着缝泡进去","effects":{"jung_se":2,"jung_fi":-0.6,"big5_compassion":1.2,"def_sublimate":0.7},"social_desirability":3},{"key":"B","text":"先看他有没有摔伤，再抬头看按喇叭的是谁、周围有谁举着手机","effects":{"jung_fe":2,"jung_ti":-0.8,"big5_alert":1.4,"cog_speed":0.7},"social_desirability":2},{"key":"C","text":"心里先浮上一句「他今天大概已经跑了两百单」，眼睛有点热，人还站在檐下","effects":{"jung_fi":2,"jung_se":-1.1,"big5_compassion":1.3,"mot_belonging":0.6},"social_desirability":1},{"key":"D","text":"一下想起去年同样的路口也下着雨，也有人这样倒地，那次没有人管","effects":{"jung_si":2,"jung_se":-1.3,"big5_rumination":1.2,"def_detach":0.7},"social_desirability":1}]},{"id":"v9_q05","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"jung_fi","is_sensitive":true,"weight":1.4,"context":"你表姐结婚九年，两个孩子。上周她打电话说想离，理由给得很轻：「就是不想再演了。」电话那头她在剥橘子，你能听见皮被撕开的声音。","prompt":"挂了电话之后，你心里冒出来的那句话更接近哪一句？","options":[{"key":"A","text":"先算清楚：房子怎么分、两个孩子跟谁、她九年没上班还剩多少挣钱的能力","effects":{"jung_te":2,"jung_fi":-1,"cog_logic":1.2,"mot_security":1},"social_desirability":2},{"key":"B","text":"「不想再演了」这句是真的。一个人不该为了让别人放心，把自己一点点耗干","effects":{"jung_fi":2,"jung_te":-1.2,"val_moral":1.1,"big5_compassion":0.9},"social_desirability":2},{"key":"C","text":"这九年我看着她一路过来，每次都是同一句话同一种忍法，这次大概也一样","effects":{"jung_si":2,"jung_ne":-0.9,"big5_rumination":1.1,"cog_global":-0.7},"social_desirability":1},{"key":"D","text":"第二天直接开车过去，把她从那个家里拉出来吃顿饭，看看她现在什么样子","effects":{"jung_se":2,"jung_si":-0.8,"big5_assert":1.2,"def_sublimate":0.8},"social_desirability":3}]},{"id":"v9_q06","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_ne","is_sensitive":false,"weight":0.85,"context":"十一点半，一个大学同学发来六十秒语音：他要辞掉干了六年的事，去开一家店。语音里能听见他在走动。","prompt":"听完第一遍，你脑子里长出来、并且已经分岔的，是哪一类东西？","scale":{"left":"他那家店能长成的五六种样子，还有三条完全不同的岔路","right":"他这一步是被什么推着走的，以及两年后他大概会站在哪里","sdHigh":"right"},"effects":{"jung_ne":[2,-2],"jung_ni":[-2,2],"cog_diverge":[1.3,-1.1],"big5_open":[1.4,-0.6]}},{"id":"v9_q07","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_ni","is_sensitive":false,"weight":1.4,"context":"中介带你看了第四套房子，进门第一句是「这套再不定，下周就没了」。你站在客厅中央，窗外的塔吊正在转。","prompt":"你手上没有笔，心里那本账却已经翻开了。它先算哪一笔？","options":[{"key":"A","text":"忽然看清这扇窗定下了什么：未来十年的早晨、通勤、和谁坐在一起吃饭","effects":{"jung_ni":2,"jung_se":-0.8,"cog_global":1.4,"mot_security":0.8},"social_desirability":2},{"key":"B","text":"掏出手机问清单价、物业费、同户型近半年的成交价，以及这套挂了多少天","effects":{"jung_te":2,"jung_ni":-0.9,"big5_order":1.3,"cog_logic":1},"social_desirability":2},{"key":"C","text":"不问了，走到阳台上摸一摸栏杆，听楼下是什么声音，先在这站上五分钟","effects":{"jung_se":2,"jung_ni":-1.1,"big5_aesthetic":1.3,"mot_hedonism":0.8},"social_desirability":1},{"key":"D","text":"盯住他那句「下周就没了」往下问：这个说法从哪来，他哪一句开始接不住","effects":{"jung_ti":2,"jung_fe":-0.9,"cog_independent":1.3,"big5_alert":0.9},"social_desirability":1}]},{"id":"v9_q08","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"jung_fe","is_sensitive":true,"weight":1.3,"context":"你搬进新租的房子已经一个月。搬家那天你谁也没叫，想着往后慢慢约。这周你翻了翻日历，暖房这件事好像已经过了那个当口，没人再提。","prompt":"你把日历合上，头三秒里，你心里冒出来的是——","options":[{"key":"A","text":"「原来不主动开口，我在别人那里就真的不存在。」这句话很轻地压下来","effects":{"jung_fi":2,"jung_fe":-1,"big5_rumination":1.3,"att_anxiety":1.2},"social_desirability":0},{"key":"B","text":"先复盘这条线是怎么松的：这一个月我一次也没说请他们来，大概是我自己先退了","effects":{"jung_ti":2,"jung_fi":-0.8,"def_intellectual":1.1,"cog_logic":1},"social_desirability":2},{"key":"C","text":"在群里发一张客厅的照片，说「找一天来坐坐」，然后再看谁接话","effects":{"jung_fe":2,"jung_fi":-1.2,"covert_control":0.8,"big5_compliance":1.3},"social_desirability":2},{"key":"D","text":"不发了，把这事放下。下周末自己找个地方待一整天，谁也不约","effects":{"jung_se":2,"jung_ni":-0.8,"big5_assert":1.3,"def_detach":0.7},"social_desirability":3}]},{"id":"v9_q09","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_se","is_sensitive":false,"weight":0.85,"context":"出差回来你去做了个按摩。房间里只有空调声和精油的味道，技师的手按在肩胛骨下面那一块，很疼。","prompt":"疼的那几十秒里，你的注意力落在什么地方？","scale":{"left":"全在那一块疼上，跟着呼吸，别的什么也没有想","right":"顺着这块僵往回推：这半年我到底怎么活的，不解决明年会在哪儿疼","sdHigh":"left"},"effects":{"jung_se":[2,-2],"jung_ni":[-2,2],"big5_alert":[-0.6,1],"def_intellectual":[-0.8,1]}},{"id":"v9_q10","type":"forced_choice","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_ti","is_sensitive":false,"weight":1.4,"context":"周五下午，甲方在群里发来一条六十秒语音，转成文字四百多字，里面有三处彼此打架的要求，末尾一句「你们先按这个做」。","prompt":"文档打开之后，你从哪里下手？","options":[{"key":"A","text":"把三处打架的地方一条条摘出来，先弄明白他到底要哪一种，再决定做不做","effects":{"jung_ti":2,"jung_te":-0.8,"cog_logic":1.4,"big5_order":0.8},"social_desirability":2},{"key":"B","text":"按能交付的样子重排：这周做什么、要多少钱、哪一条这版不做，回一封确认函","effects":{"jung_te":2,"jung_ne":-0.7,"big5_assert":1.3,"cog_speed":1},"social_desirability":3},{"key":"C","text":"从四百字里挑一句被浪费掉的话，顺着它想一个他自己也没想到的做法","effects":{"jung_ne":2,"jung_ti":-1,"cog_diverge":1.4,"big5_open":1.2},"social_desirability":2},{"key":"D","text":"翻出上个月那份几乎一样的文档，把当时怎么处理的步骤照着重走一遍","effects":{"jung_si":2,"jung_ne":-1.1,"cog_ambiguity":-1.1,"big5_order":1.2},"social_desirability":2}]},{"id":"v9_q11","type":"impulse_3s","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_si","is_sensitive":true,"weight":1.2,"context":"你隔了两年才回一次家。进门还没换鞋，你妈已经从厨房端出一碗汤：「还是照你小时候那样炖的。」汤面浮着几粒枸杞，味道和十岁那年一模一样。","prompt":"碗端在手里烫，那一刻最先涌上来的是什么？","options":[{"key":"A","text":"记忆整块回来了：午睡后的竹席、她喊你吃饭的声音、那只缺口的勺子","effects":{"jung_si":2,"jung_ne":-0.9,"big5_rumination":1.1,"mot_belonging":1.3},"social_desirability":2},{"key":"B","text":"有点想哭，因为她记得一件我自己都忘了的小事，而且记了二十年","effects":{"jung_fi":2,"big5_compassion":1.4,"att_anxiety":0.7,"jung_ti":-0.6},"social_desirability":2},{"key":"C","text":"先夸她一句「还是你炖得好」，让她高兴，把两年没说的话再往下压一压","effects":{"jung_fe":2,"jung_fi":-1.1,"big5_compliance":1.4},"social_desirability":3},{"key":"D","text":"太烫了，先放下，去厨房拿个碗分出一半给她，两个人在灶台边站着喝完","effects":{"jung_se":2,"jung_si":-0.8,"def_detach":0.6,"big5_compassion":0.9},"social_desirability":2}]},{"id":"v9_q12","type":"stealth_scale","stealth_mode":"normalization","layer":"explicit","mirror_key":"jung_te","is_sensitive":false,"weight":0.85,"context":"楼上漏水泡了你家天花板一角，物业说「得等业主回来确认」，已经拖了十一天。","prompt":"第三趟去物业办公室的路上，你脑子里那件事已经在往下推了。推到哪一步？","scale":{"left":"把每一步变成能追责的东西：拍照、留记录、给一个具体日期，到期就往上级递","right":"想想它到底卡在哪一环，有没有一个不用跟他们耗的入口，从别处绕过去","sdHigh":"left"},"effects":{"jung_te":[2,-2],"jung_ne":[-1.6,1.6],"big5_assert":[1.4,-0.8],"cog_logic":[1.2,-0.6]}},{"id":"v9_q13","type":"forced_choice","stealth_mode":"pressure","layer":"stealth","mirror_key":"jung_ti","is_sensitive":true,"weight":1.4,"context":"一个认识十年的朋友开口借八万，说母亲做手术，三个月内还。你知道他去年投资亏过一次，也知道他母亲确实在住院。","prompt":"对话框停在那儿，你没有立刻回，先在心里做了一件什么事？","options":[{"key":"A","text":"把他上一次借钱的时间和还款情况对一遍，数字核清楚了再往下谈","effects":{"jung_ti":2,"jung_fe":-1,"cog_logic":1.3,"big5_alert":1.1},"social_desirability":1},{"key":"B","text":"借，但写一条：金额、日期、怎么还，两个人各留一份，先把麻烦处理掉","effects":{"jung_te":2,"jung_fi":-0.8,"big5_order":1.3,"val_moral":0.9},"social_desirability":2},{"key":"C","text":"他人还在医院走廊，我先转三万过去，剩下的再想办法，别的以后再说","effects":{"jung_fe":2,"jung_te":-1.2,"big5_compassion":1.4,"mot_belonging":0.9},"social_desirability":2},{"key":"D","text":"我借钱只有一条标准：这笔钱回不来，我会不会因此看轻他。会，就不借","effects":{"jung_fi":2,"jung_fe":-1.1,"val_moral":1.4,"cog_independent":1.1},"social_desirability":3}]},{"id":"v9_q14","type":"stealth_scale","stealth_mode":"mirror","layer":"explicit","mirror_key":"jung_fe","is_sensitive":true,"weight":0.85,"context":"这周他说了两句话。周一：「你忙你的，我没事。」周五：「你这周一次都没问过我在忙什么。」现在他在厨房切菜，背对着你。","prompt":"你站在门口，手里还握着手机。下一步你怎么走进去？","scale":{"left":"把这两句话摆在一起看：哪句是真的，中间那四天到底发生了什么","right":"先不追逻辑，走过去站在他旁边，让他把话说完，让空气先软下来","sdHigh":"right"},"effects":{"jung_ti":[2,-2],"jung_fe":[-2,2],"big5_compassion":[-0.8,1.4],"att_avoidance":[0.8,-0.8]}},{"id":"v9_q15","type":"forced_choice","stealth_mode":"ipsative","layer":"stealth","mirror_key":"jung_ne","is_sensitive":false,"weight":1.4,"context":"年终奖到账那晚，你一个人坐在客厅，屏幕上的数字比预期多了两万三。这笔钱没有任何用途被指定。","prompt":"关掉手机之前，你心里已经把它安放好了。它被放在了哪一格？","options":[{"key":"A","text":"一个还没成形的念头：报那个一直没敢报的课，或者干脆摆个小摊试试","effects":{"jung_ne":2,"jung_si":-1,"big5_open":1.4,"cog_diverge":1.2},"social_desirability":3},{"key":"B","text":"一个更远的位置：这笔钱放在三年后的哪一格，才算真正没白来一趟","effects":{"jung_ni":2,"jung_se":-0.8,"cog_global":1.3,"mot_purpose":1.1},"social_desirability":2},{"key":"C","text":"一顿今晚就能约的饭、一双想了两年的鞋，让这个月有个能记住的日子","effects":{"jung_se":2,"jung_ni":-1,"mot_hedonism":1.3,"big5_aesthetic":0.9},"social_desirability":1},{"key":"D","text":"那个一直空着的应急账户，跟往年一样，先把它填到六个月的量","effects":{"jung_si":2,"jung_ne":-1.1,"mot_security":1.3,"big5_alert":1.2},"social_desirability":2}]},{"id":"v9_q16","type":"impulse_3s","stealth_mode":"impulse","layer":"stealth","mirror_key":"jung_ni","is_sensitive":true,"weight":1.25,"context":"在一起第二年，某个周三的晚饭吃到一半，对方放下筷子问你：「你到底想要什么？」抽油烟机还在响。","prompt":"在那三秒里，你身体比嘴先给出的答案是什么？","options":[{"key":"A","text":"一句很具体、可能有点难听但是真的话：我想被人当成第一顺位","effects":{"jung_fi":2,"jung_te":-0.7,"val_moral":1.2,"att_anxiety":0.9},"social_desirability":2},{"key":"B","text":"一串可以列出来的东西：住在哪、几年内要不要孩子、钱怎么管","effects":{"jung_te":2,"jung_fi":-1,"big5_order":1.3,"big5_assert":0.8},"social_desirability":2},{"key":"C","text":"忽然看清这个问题的来路：他问的不是未来，是我这两年一直没给的那个答复","effects":{"jung_ni":2,"jung_se":-0.9,"cog_global":1.3,"att_anxiety":0.7},"social_desirability":3},{"key":"D","text":"什么也没想，先伸手把他的碗挪开一点：「先吃饭，吃完再说」","effects":{"jung_se":2,"jung_ni":-1,"def_detach":0.9,"big5_compliance":0.8},"social_desirability":1}]},{"id":"v9_q17","type":"forced_choice","stealth_mode":"projection","layer":"stealth","mirror_key":"jung_si","is_sensitive":true,"weight":1.4,"context":"大年初二，饭桌上你妈第无数次提起你表哥：三十五岁，两套房，孩子进了最好的小学。说完她给你夹了一筷子鱼：「妈不是催你。」","prompt":"那口鱼放进嘴里，你心里最清楚的念头是哪一句？","options":[{"key":"A","text":"想起的是九几年这张桌子：那时谁也没什么钱，鱼是同一个做法，笑得却更响","effects":{"jung_si":2,"jung_ne":-0.9,"big5_rumination":1.3,"mot_belonging":1},"social_desirability":1},{"key":"B","text":"我知道她怕什么，也清楚这些不是我要的，两件事可以同时成立，不必争","effects":{"jung_fi":2,"jung_fe":-0.8,"val_moral":1.2,"cog_independent":1},"social_desirability":3},{"key":"C","text":"顺着她的话往下问：表哥现在几点下班、周末还有没有空陪孩子","effects":{"jung_fe":1.8,"jung_fi":-1.1,"covert_control":1,"big5_compliance":0.8},"social_desirability":2},{"key":"D","text":"忽然觉得这桌饭还能有别的过法：明年换我定地方，谁也别在家里吃","effects":{"jung_ne":2,"jung_si":-1.1,"cog_diverge":1.3,"big5_assert":1},"social_desirability":2}]},{"id":"v9_q18","type":"stealth_scale","stealth_mode":"mirror","layer":"explicit","mirror_key":"jung_fi","is_sensitive":true,"weight":0.85,"context":"凌晨一点，你在洗手间洗脸，抬头看见镜子里那张脸。今天没出什么大事，但一整天都不太对。","prompt":"水还在流，你看着镜子里的自己，心里跑的是什么？","scale":{"left":"我大概知道自己在难受什么，这件事没法向谁解释清楚，但对我而言是真的","right":"我给自己找一个说得通的原因：是没睡好，是今天那句话，还是这个月都这样","sdHigh":"left"},"effects":{"jung_fi":[2,-2],"jung_ti":[-1.8,1.8],"big5_rumination":[1.2,-0.6],"def_intellectual":[-0.8,1.2]}},{"id":"v9_q19","type":"pyramid_top3","stealth_mode":"ipsative","layer":"explicit","mirror_key":"jung_stack","is_sensitive":false,"weight":1.3,"context":"你在常去的那家面馆做了个梦：对面坐着一个人，把你脑子里处理世界的方式一样样摆上桌，说只能留下三样，其余的要收走。","prompt":"桌面上的八样东西，你最先留下的是哪三样？请按顺序点选。","values":[{"key":"te","label":"把混乱压成一张能执行的表","effects":{"jung_te":1.5,"big5_order":0.4}},{"key":"ti","label":"把一个说法抠到逻辑上站不住","effects":{"jung_ti":1.5,"cog_logic":0.4}},{"key":"fe","label":"先让在场的人都不那么难受","effects":{"jung_fe":1.5,"big5_compassion":0.4}},{"key":"fi","label":"守住心里那条不能越的线","effects":{"jung_fi":1.5,"val_moral":0.4}},{"key":"ne","label":"看见一条路长出五六条岔路","effects":{"jung_ne":1.5,"cog_diverge":0.4}},{"key":"ni","label":"从一堆事里看出同一个底下的东西","effects":{"jung_ni":1.5,"cog_global":0.4}},{"key":"se","label":"现在这一刻就动手、就尝到","effects":{"jung_se":1.5,"mot_hedonism":0.4}},{"key":"si","label":"回到熟悉的那条老路和那个味道","effects":{"jung_si":1.5,"mot_security":0.4}}]},{"id":"v9_q20","type":"budget_100","stealth_mode":"budget","layer":"explicit","mirror_key":"jung_energy","is_sensitive":false,"weight":1.3,"context":"你有一个完全没被安排的周六，从早上七点到晚上十一点，十六个小时归你自己。手机可以关掉，谁也不知道你在哪儿。","prompt":"把一百点精力分到这六件事上。分完之后，你才看得出自己到底靠什么充电。","items":[{"key":"fe","label":"约人：让屋子里有别人的声音和气味","dim":"jung_fe","base":0,"gain":1},{"key":"fi","label":"一个人把心里那点说不清的东西想清楚","dim":"jung_fi","base":0,"gain":1},{"key":"ne","label":"随手翻到点什么，让它长出一堆新念头","dim":"jung_ne","base":0,"gain":1},{"key":"ni","label":"把最近所有事连成一条线，看清它往哪儿去","dim":"jung_ni","base":0,"gain":1},{"key":"se","label":"出门，用手和身体去碰真的东西","dim":"jung_se","base":0,"gain":1},{"key":"si","label":"回到熟悉的地方，把旧的东西再过一遍","dim":"jung_si","base":0,"gain":1}]}]}};

export const MIRRORS = {"sin_pride":{"name":"傲慢驱力","volume":"vol1","category":"sin","high":{"label":"高门槛的孤傲主体","gift_title":"顶级审美与专业骨气","gift_desc":"绝不随波逐流，自带极高的自我标准与独立定力，往往能在深耕领域做出超越平庸的作品。","shadow_title":"孤岛效应与听不进劝","shadow_desc":"容易对他人产生隐秘轻视，遭遇瓶颈时因死要面子而拒绝求助，无形中错失外部杠杆。","alchemy_tip":"保留对事的极致挑剔，但练习对人保持好奇——把「他们不懂」切换为「我想看看他的视角漏了什么」。"},"low":{"label":"空杯姿态的温和兼容者","gift_title":"极强兼容性与吸纳力","gift_desc":"能毫无架子地向任何人汲取养分，人际摩擦极低，极易赢得他人信任与真诚扶持。","shadow_title":"易被权威压制与自我贬低","shadow_desc":"在强势者或宏大话术面前习惯退让，容易过度怀疑自身判断与真实筹码。","alchemy_tip":"谦逊是看清世界之大，而不是缩小自己；在核心利益与专业判断上，允许自己理直气壮地占据中心位。"}},"virtue_humility":{"name":"谦逊秩序","volume":"vol1","category":"virtue","high":{"label":"稳定收敛的自我校准者","gift_title":"可被迭代的认知系统","gift_desc":"愿意承认自己会错，因此你的判断能持续升级；这种开放度会让聪明人愿意把真话告诉你。","shadow_title":"过度自省导致行动迟滞","shadow_desc":"把大量能量花在「我是不是不够好」上，该出手时反复自我否决，机会在犹豫中流走。","alchemy_tip":"谦逊的落点应是「更快修正」，而不是「更慢出发」；给自己设一个必须做决定的时限。"},"low":{"label":"以自我为坐标的锚定者","gift_title":"不易被外界动摇的内核","gift_desc":"你不太需要他人的认可来确认自己的价值，因此在混乱与质疑中反而格外稳定。","shadow_title":"反馈回路关闭的盲区","shadow_desc":"当外界信号被系统性忽略，误差会累积到某天一次性爆发，代价往往比当初听一句真话更高。","alchemy_tip":"挑两三个你信任且敢说真话的人，把他们的批评设为定期检查项，而不是随机事件。"}},"sin_greed":{"name":"贪婪驱力","volume":"vol1","category":"sin","high":{"label":"永不满足的资源扩张者","gift_title":"强悍的原始驱动力","gift_desc":"对资源与机会的敏感度极高，永远比同侪早半步闻到风向，能在别人犹豫时率先下注。","shadow_title":"稀缺感驱动的无底洞","shadow_desc":"哪怕已经足够，仍会为「还不够厚」而焦虑；容易把关系也变成一种可计量的储备。","alchemy_tip":"给「足够」写一个具体数字与日期。数字之外的增长，改为投资体验与关系，而不是继续加高堤坝。"},"low":{"label":"低囤积倾向的流动者","gift_title":"轻盈的资源观与高信任度","gift_desc":"不被占有欲绑住，愿意分享也敢放手，这种松弛让你周围的关系与合作都更顺畅。","shadow_title":"抗风险缓冲不足","shadow_desc":"对底线风险缺乏准备，一旦遭遇突发断流，会迅速从从容变成被动。","alchemy_tip":"为自己设一条不可动用的安全线。真正的自由不是没有储备，而是储备足够时仍能安心地不扩张。"}},"virtue_charity":{"name":"慷慨流动","volume":"vol1","category":"virtue","high":{"label":"愿意先给出的资源枢纽","gift_title":"极高的人际资本复利","gift_desc":"你的给予通常不附带条件，因此会形成长期回流的信任网络，在关键时刻总有人愿意为你出手。","shadow_title":"无边界付出后的隐性怨怼","shadow_desc":"长期超额给予却不表达需求，容易在某个节点突然心冷，连自己都说不清为什么想退。","alchemy_tip":"把「我都可以」换成「这次我需要什么」。公平的给予包含让对方也有机会回报。"},"low":{"label":"边界清晰的自持者","gift_title":"守住自身资源的定力","gift_desc":"你清楚自己的容量，不轻易被情绪勒索或道德绑架拖走，因此很少因过度付出而透支。","shadow_title":"错失关系深化的窗口","shadow_desc":"过度谨慎的给予会让关系停在一个礼貌的距离，别人难以真正靠近你。","alchemy_tip":"定期做一次「没有回报预期」的给予，哪怕很小。关系的深度往往由这些不对称的时刻建立。"}},"sin_lust":{"name":"沉溺驱力","volume":"vol1","category":"sin","high":{"label":"高感官浓度的体验者","gift_title":"极强的生命浓度与感染力","gift_desc":"你能把一件事做到极致的投入与燃烧，那种浓度本身就有稀缺的吸引力。","shadow_title":"上头之后的方向失守","shadow_desc":"一旦被点燃就很难踩刹车，代价常常在第二天早上才出现，而那时已经无法回退。","alchemy_tip":"不要试图消灭那股火，只要给它加一道闸：把「现在就要」改成「明天这个时间还在，就去做」。"},"low":{"label":"低温运行的稳态者","gift_title":"不受即时诱惑牵引的清醒","gift_desc":"很少被一时冲动带走，能把注意力留给长期真正重要的事，判断也更少被欲望污染。","shadow_title":"生命感的稀薄","shadow_desc":"过度克制会让一切变得正确但乏味，久而久之失去那种让眼睛亮起来的东西。","alchemy_tip":"给自己留一块「合法失控区」——一段不必产出的时间，只用来尽情感受。"}},"virtue_chastity":{"name":"节制自持","volume":"vol1","category":"virtue","high":{"label":"能长期掌舵的自律者","gift_title":"罕见的多巴胺主权","gift_desc":"你的注意力不容易被劫持，因此能在别人疲于应付刺激时，安静地把一件难事推进很久。","shadow_title":"过度克制后的空转","shadow_desc":"把所有冲动都管住，容易让生活变成一套高效的流程，却少了让人愿意靠近的热度。","alchemy_tip":"节制是为了把能量留给更值得的事，不是为了让所有事都变得正确。允许自己偶尔只为了开心。"},"low":{"label":"顺流而下的感官派","gift_title":"对愉悦的高敏感度","gift_desc":"你能真切地享受当下，不易被「应该」压住，这种鲜活的感受力本身就是稀缺资源。","shadow_title":"被短期快感反复透支","shadow_desc":"重要的事经常被推到明天，而明天又会推到下一个明天，长期目标在温柔的下坠中被消耗。","alchemy_tip":"不必戒断，只要加一个「前置动作」：想打开它之前，先完成三分钟那件真正重要的事。"}},"sin_envy":{"name":"嫉妒雷达","volume":"vol1","category":"sin","high":{"label":"高精度横向比较者","gift_title":"精准的野心探测器","gift_desc":"那点酸涩总是准确地指向你真正渴望却还没拿到的东西，它是一份极诚实的需求清单。","shadow_title":"阴暗内耗与关系酸涩","shadow_desc":"过度比较会引发自我厌恶，甚至下意识贬低优秀者来维持平衡，最后损耗的是自己的能量与人缘。","alchemy_tip":"每次泛酸时，立刻写下「他做对了哪两件事」。把比较对象从人换成方法，酸就会变成燃料。"},"low":{"label":"低比较噪音的自在者","gift_title":"极度松弛的自我节奏","gift_desc":"能真心为他人鼓掌，内心清澈，自带让人愿意亲近的磁场，不必靠比较确认位置。","shadow_title":"缺乏参照系的钝感","shadow_desc":"有时对行业跃迁与竞争变化过于佛系，错过本该抓住的窗口期。","alchemy_tip":"松弛不等于没有坐标。每季度找一位你真心佩服的人，只研究方法，不做情绪比较。"}},"virtue_kindness":{"name":"欣赏能力","volume":"vol1","category":"virtue","high":{"label":"能看见他人高光的托举者","gift_title":"让人愿意袒露的信任场","gift_desc":"你真心欣赏别人的好，因此身边人不必在你面前缩小自己，这种安全感会带来极深的连接。","shadow_title":"过度体谅导致的自我隐形","shadow_desc":"习惯先看见别人的光，容易忽略自己的需求，久了会累积一种「没人在看我」的委屈。","alchemy_tip":"欣赏他人与主张自己并不冲突。练习在你夸完别人之后，加一句关于你自己的。"},"low":{"label":"标准优先的评价者","gift_title":"不被情感滤镜干扰的判断力","gift_desc":"你能就事论事地评估，不因喜欢而放宽标准，这在需要客观的场合极其珍贵。","shadow_title":"让人不敢靠近的冷感","shadow_desc":"习惯性指出不足，会让身边人逐渐减少分享，你也就失去了那些本可以很深的连接。","alchemy_tip":"在给出评价之前，先说一句具体的、真实的欣赏。同样的内容，接受度会完全不同。"}},"sin_gluttony":{"name":"放纵代偿","volume":"vol1","category":"sin","high":{"label":"用感官填补空洞的代偿者","gift_title":"对自己状态的敏锐体感","gift_desc":"你很早就能察觉「我需要被补偿了」，这份体感让你比多数人更懂得如何把自己捞回来。","shadow_title":"白天越顺从，夜里越失控","shadow_desc":"白天在关系与工作里压抑真实诉求，深夜就用熬夜、食物或消费抢回一点控制权。","alchemy_tip":"真正要修的不是夜里的手，是白天的嘴。白天多说出一次「我不太想」，夜里就会少一次报复。"},"low":{"label":"低代偿依赖的稳态者","gift_title":"不靠外物调节情绪的能力","gift_desc":"情绪低落时你有自己的恢复路径，不必依赖食物、购物或屏幕来把自己哄好。","shadow_title":"对身体信号的钝感","shadow_desc":"太能扛会让人忘记自己已经累了，直到身体用更激烈的方式让你停下来。","alchemy_tip":"把「我还能扛」换成「我现在的电量是多少」。定期问自己一次，比硬撑更可持续。"}},"virtue_temperance":{"name":"克制秩序","volume":"vol1","category":"virtue","high":{"label":"有闸门的高能量者","gift_title":"长期主义的稳定底盘","gift_desc":"你能把冲动转化为可持续的节奏，因此能在别人反复重启的地方走得更远。","shadow_title":"过度控制带来的僵硬","shadow_desc":"习惯性收紧会让你在需要即兴与放松的场合显得紧绷，也让身边人不易靠近。","alchemy_tip":"给自己留出不必高效的时间。真正的秩序包含休息，而不是把休息也排进任务表。"},"low":{"label":"弹性边界的随性者","gift_title":"对变化的天然适应力","gift_desc":"你不容易被计划绑住，遇到突发状况能迅速调整，这在动荡环境里是一种优势。","shadow_title":"慢性失控的累积成本","shadow_desc":"每一次「就这一次」都在悄悄降低底线，几年后会发现自己在很多事上已经无法自律。","alchemy_tip":"不要一次立十条规矩，只守住一条不可让的线。守住一条，其余的会慢慢跟上。"}},"sin_wrath":{"name":"愤怒烈度","volume":"vol1","category":"sin","high":{"label":"锋利边界的守卫者","gift_title":"掀翻不合理桌子的爆发力","gift_desc":"你对冒犯与不公绝不姑息，在需要有人站出来的时刻，你往往是那个真的开口的人。","shadow_title":"情绪劫持与事后懊悔","shadow_desc":"怒火上头时容易说出极具杀伤力的话，伤及无辜或误伤合作，代价常常远超当下那口气。","alchemy_tip":"把「说出来」推迟二十分钟，但不要取消它。怒火需要出口，只是不必在最高温的时候出口。"},"low":{"label":"高阈值的不动声色者","gift_title":"深海般的宽容与稳态","gift_desc":"极少被外界挑衅牵着走，总能用温和化解戾气，是混乱场合里让人安心的存在。","shadow_title":"隐性压抑与被动攻击","shadow_desc":"不敢表达正当怒火，委屈积压过久会演变成冷暴力、疏远或莫名的躯体不适。","alchemy_tip":"愤怒是边界被侵犯的信号，不是品格缺陷。练习在感到不舒服的当下就说一句「这样我不太舒服」。"}},"virtue_patience":{"name":"宽容稳态","volume":"vol1","category":"virtue","high":{"label":"能容纳复杂的长线者","gift_title":"极低的情绪摩擦成本","gift_desc":"你能把人和事分开看，因此不会因为一次冲突就断掉一段关系，这种容量会带来长期回报。","shadow_title":"该翻脸时的迟疑","shadow_desc":"过度宽容会让你在应该明确划线时继续退让，最终由对方来替你决定边界。","alchemy_tip":"宽容的前提是对方知道你在宽容。把「算了」换成「这次我理解，但下次不行」。"},"low":{"label":"不轻易原谅的记忆者","gift_title":"清楚的底线与自我保护","gift_desc":"你记得谁在什么时候做过什么，因此不容易在同一个地方被伤害两次。","shadow_title":"长期携带的旧账","shadow_desc":"未处理的旧账会占用大量心理内存，让你在新的关系里也带着防备。","alchemy_tip":"不必强迫自己原谅，但要区分「还没放下」和「还在等他付出代价」。前者可以慢慢来，后者要先停。"}},"sin_sloth":{"name":"逃避惯性","volume":"vol1","category":"sin","high":{"label":"高阻抗启动的省力派","gift_title":"反内卷直觉与捷径天赋","gift_desc":"痛恨无意义重复，天生擅长抓核心 20% 关键点，能用更少的动作拿到同样的结果。","shadow_title":"执行瘫痪与愧疚内耗","shadow_desc":"想得极美却迟迟不启动，陷入「拖延、自责、更逃避」的死循环，最后连想做的心情也被磨掉。","alchemy_tip":"把启动门槛降到荒谬的程度：只做两分钟。拖延怕的从来不是难度，而是开始。"},"low":{"label":"低阻力的行动者","gift_title":"恐怖的持续推进引擎","gift_desc":"耐得住枯燥，用高密度行动碾压焦虑，是团队里最可靠的那种人。","shadow_title":"战术勤奋掩盖战略迷茫","shadow_desc":"一旦停下来就充满罪恶感，容易陷入盲目瞎忙，用忙碌回避真正该做的选择。","alchemy_tip":"每季度留出一天完全不做事，只问一个问题：我现在忙的这件事，三年后还重要吗。"}},"virtue_diligence":{"name":"勤勉推进","volume":"vol1","category":"virtue","high":{"label":"能把事做完的可靠者","gift_title":"可信赖的交付信誉","gift_desc":"你答应的事会真的发生，这种确定性在长期协作里比任何才华都稀缺。","shadow_title":"用完成度换掉了可能性","shadow_desc":"过度执着于把事情做完，可能让你一直在做「该做的」，而不是「真正值得做的」。","alchemy_tip":"定期砍掉一件正在做但不重要的事。勤勉最大的浪费，是把力气用在对的方向之外。"},"low":{"label":"重选择轻执行的策略者","gift_title":"不被琐事吞掉的方向感","gift_desc":"你更愿意花时间判断值不值得，因此较少陷入低价值的苦劳，方向感往往不错。","shadow_title":"想得比做得多","shadow_desc":"判断做得很好，但落地经常掉链子，长期下来会让信任度打折。","alchemy_tip":"为每个决定配一个「最小可交付动作」，在 48 小时内必须完成。让判断长出腿。"}},"dd_order":{"name":"秩序倾向","volume":"vol10","category":"alignment","polar":true,"negLabel":"混沌","posLabel":"秩序","high":{"label":"把承诺当成承重墙的人","gift_title":"可以被依靠的稳定结构","gift_desc":"你在的地方，规则不只是纸上的字，而是别人能安心睡觉的东西。答应过的事会自动进入你的日程，一团乱麻到你手上会慢慢收成流程。这种可靠很稀缺，它让别人敢把重要的事交给你。","shadow_title":"把灵活读成失守","shadow_desc":"当规则和你真正在意的人撞在一起，你会先守规则，事后再发现代价落在了一个具体的人身上。你也容易把「没按流程」听成「不尊重你」，于是错过那些本来只需一句变通就能救回来的事。","alchemy_tip":"下次规则与人冲突时，先写一行字：这条规矩当初是为了保护谁。如果那个人此刻正被它伤到，就允许自己开一次例外，并把这个例外写进记录——秩序才不会变成石头。"},"low":{"label":"在规则缝隙里呼吸的人","gift_title":"对现场极其敏感的判断力","gift_desc":"你相信世界是靠人当下的判断撑住的，而不是靠条文。你反应快，能在别人还在找依据的时候先动起来，也极少被「一直都是这么办的」这类话唬住，很多僵局是被你这样的人推开的。","shadow_title":"每一次例外都在消耗信用","shadow_desc":"你心里清楚哪些规矩可以绕，但别人只看见结果不一致。临场改主意多了，别人会开始不敢跟你约远期的事；而你自己也会发现，那些「这次特殊」加起来，正是你生活里最乱的部分。","alchemy_tip":"挑出三件你绝对不临场改的事，写下来并提前告诉身边的人，其余的都留给自己灵活处理。有了这三根桩，你的自由才不会被人当成不靠谱。"}},"dd_good":{"name":"良善倾向","volume":"vol10","category":"alignment","polar":true,"negLabel":"自利","posLabel":"良善","high":{"label":"先看见具体那个人","gift_title":"让人愿意卸下防备的在场感","gift_desc":"你很难对眼前的具体痛苦保持抽象。别人跟你说话时会不自觉说多两句，因为你真的在听；你也不太需要理由才去帮人，那种「不忍」是你身上最原始的动力来源。","shadow_title":"被不忍慢慢耗尽","shadow_desc":"你的边界常被自己的善意先推倒。别人一句为难，你就把自己的计划往后挪；久了你会发现，被帮的人未必更亲近你，而你手里该留的那点力气，已经先给光了。","alchemy_tip":"帮忙前先报一个额度：这次能给出多少时间、多少钱、几次。说出口的额度比默默牺牲更能保护关系，也让你下次还能继续帮。"},"low":{"label":"先算清代价再伸手","gift_title":"不被情绪绑架的清醒","gift_desc":"你看得见人情的重量，也不会假装它不存在。别人用眼泪、用「就这一次」来借你的资源时，你能稳住不动，这种清醒让你很少被人当成提款机，也很少在事后恨自己心软。","shadow_title":"把关系都过成了账","shadow_desc":"长期按代价衡量之后，你会发现自己身边的关系都带上了刻度：谁值得、谁不值得。真正需要有人在场的时刻，你可能会先在脑子里算完一笔账才伸手，而那时门已经关了一半。","alchemy_tip":"每周做一件明确没有回报的小事，只记在私下的本子上不告诉对方。让「不必交换」这件事在你身上保留一点肌肉记忆。"}},"phil_stoic":{"name":"斯多葛底色","volume":"vol11","category":"philosophy","high":{"label":"把力气用在能改的那一半","gift_title":"在失控里保持体面的定力","gift_desc":"你能把事件和情绪拆开，先看清哪一部分真的归自己管。这让身边的人在混乱时愿意站到你旁边，你的判断也很少被一时的难受带偏，能撑很久。","shadow_title":"把「不在意」当成万能止血贴","shadow_desc":"过度克制会让你连该说的话也一起咽下去。别人看到的是冷静，你自己知道那是把感受提前判了无期，久了连高兴也会跟着一起变平，人还在，热度没了。","alchemy_tip":"下次难受时先说一句「我现在很不舒服」，再讲道理。给情绪三十秒发言权，克制才不会变成隔离。"},"low":{"label":"把感受放在第一位的人","gift_title":"不跟自己演戏的诚实","gift_desc":"你不会用道理压住真实的难受，该疼就疼，该高兴就高兴。这种诚实让你的关系有温度，也让你比别人更早知道自己真正的界限在哪里，不必靠猜。","shadow_title":"被第一波情绪带着走","shadow_desc":"事情刚发生时，你容易先被情绪推着反应。说出去的话、发出去的消息，往往要等到第二天才后悔，真正该处理的那部分反而被搁在后面，代价不小。","alchemy_tip":"给自己设一个二十四小时的延迟：不作决定、不发长消息，只记录。等情绪落下来再看，答案通常已经不一样。"}},"phil_existential":{"name":"存在主义","volume":"vol11","category":"philosophy","high":{"label":"自己给自己写剧本的人","gift_title":"把空白变成选择的能力","gift_desc":"你不指望世界先给出意义，遇到断掉的路会先问「那我现在想让它变成什么」。这种把主动权收回来的能力，让很多低谷反而成了你的转折点。","shadow_title":"把每件事都变成自我审判","shadow_desc":"所有结果都被你算成自己的选择，于是失败不只是失败，还变成「我不够」。这种全权负责有时会压得你不敢休息，也不敢承认有些事真的不由你决定。","alchemy_tip":"划一张纸：左边写「我选的」，右边写「不是我能定的」。每周填一次，你会松一口气，也不会失去主动权。"},"low":{"label":"顺着给定的路走的人","gift_title":"能在既有框架里活得踏实","gift_desc":"你不需要凡事重新发明意义，接住已有的角色与安排也能过得充实。这种稳定让你在变动的环境里成为别人的锚，事情交到你手上往往就能真正落地。","shadow_title":"很久没问过自己想要什么","shadow_desc":"习惯接受安排之后，你可能会在某个深夜突然答不上「我到底想怎么样」。不是没有欲望，是那份欲望太久没有被叫出来过，久到你已经不确定还在不在。","alchemy_tip":"挑一件完全没有理由、也不产出结果的小事，只因为你想做而做。一个月做三次，那点属于自己的手感会慢慢回来。"}},"phil_absurd":{"name":"荒诞主义","volume":"vol11","category":"philosophy","high":{"label":"笑着推石头的人","gift_title":"在无解里继续生活的幽默","gift_desc":"你看得清事情有多荒唐，却没有因此停下，还能在最难看的时候找到一点可笑的余地。这种幽默不是逃，是你把生活重新拿回手里的方式，也很难学。","shadow_title":"用玩笑绕开真正要处理的事","shadow_desc":"笑得太快，会让别人以为你没事，也会让你自己错过该处理的裂缝。有些事被反复讲成段子之后，就再也没有被认真谈过一次，连你自己都进不去了。","alchemy_tip":"把最近常拿来开玩笑的那件事写下来，问一句：除了好笑，我还在躲什么。找出一个具体动作，这周做掉。"},"low":{"label":"认真对待每件事的人","gift_title":"不靠反讽也能活下去的认真","gift_desc":"你不把生活当笑话，愿意正面接住每一件事的重量。这份认真让你做出来的东西有分量，也让身边的人敢把真正重要的部分交到你手上。","shadow_title":"把自己绷得太紧","shadow_desc":"什么都要有个说法、有个结果，会让一些本来可以放过的小事变成持续的消耗。你也需要允许世界荒谬一下，不必每一次都立刻去把它纠正过来。","alchemy_tip":"每周留一个「不计意义」的时段：散步、看一部烂片、做一件没用的事，不产出也不解释。"}},"phil_cynic":{"name":"犬儒底色","volume":"vol11","category":"philosophy","high":{"label":"先看穿，再决定要不要信","gift_title":"不被漂亮话带走的清醒","gift_desc":"你对动机有种近乎生理的敏感，能比别人早一步看见话术背后的算计。这让你少踩很多坑，也让你在关键时刻不被集体的热情裹着往前走。","shadow_title":"在事情发生之前就先不信","shadow_desc":"看穿得太快，会让你把还没展开的善意也一起挡在门外。久了你会发现，被你识破的人越来越多，愿意真的靠近你的人越来越少，而你并不想这样。","alchemy_tip":"把两件事分开：这一次他撒了谎，和他这个人永远不值得。每次下判断只针对这一件，不要顺手给人判终身。"},"low":{"label":"愿意先信一次的人","gift_title":"给关系留出开始的机会","gift_desc":"你倾向于先按善意理解别人，因此别人在你这里不必先证明自己。这种底色让很多本来会错过的关系真的开始了，也让你活得不那么费力、不那么冷。","shadow_title":"对隐性的算计反应偏慢","shadow_desc":"习惯把人往好处想，可能让你在被利用之后还在替对方找理由。你需要的不是变冷，而是留住那些让你反复不舒服的细节，让它们有机会说话。","alchemy_tip":"准备三行记录：时间、事情、我的感受。同样的不舒服出现三次，就不必再解释，直接调整距离。"}},"phil_pragmatic":{"name":"实用主义","volume":"vol11","category":"philosophy","high":{"label":"先看能不能用的人","gift_title":"把混乱整理成下一步的能力","gift_desc":"别人还在争论对错时，你已经在找最小可行的那个动作。这种务实让很多僵住的场面真的动起来，也让你在资源有限的时候依然拿得出结果，靠得住。","shadow_title":"把人也算进了成本表","shadow_desc":"凡事都问「这有什么用」，久了会连关系里那些没有产出的部分也一起省掉。你可能得到很多结果，却在某个夜里发现自己没什么想说的话，也没什么想见的人。","alchemy_tip":"每月做一件明确「没用」的事：陪人聊两小时不谈正事，或者修一件不打算再用的旧物。允许无效率，你才不会被效率反过来用。"},"low":{"label":"先问这件事对不对的人","gift_title":"守住那些不能拿来换的东西","gift_desc":"你不会因为有效就去做，也不会因为没用就不做。这种对原则的坚持让身边的人知道你的底线在哪里，也让你在利益面前不必事后解释自己为什么那样选。","shadow_title":"在需要变通的场合卡住","shadow_desc":"有时候坚持正确，会让你错过本可以两全的做法。很多问题没有干净的答案，只有更小的伤害，这时纯粹的对错会变成一种奢侈，也会让身边的人更累。","alchemy_tip":"遇到两难先问一句：这里最小的伤害是什么。把「正确」换成「更少人受伤」，你的原则反而能保住更多人。"}},"phil_epicurean":{"name":"伊壁鸠鲁","volume":"vol11","category":"philosophy","high":{"label":"会给自己日子的人","gift_title":"把普通一天过好的能力","gift_desc":"你知道怎么在一顿热饭、一段安静的下午里把电量补回来，不靠外部认可也能活得像样。这种自给自足的快乐，很多人到中年才勉强学会一点点。","shadow_title":"把舒服当成不出门的理由","shadow_desc":"太习惯待在舒适的一小块地方，会让一些本该去争、去试的事被一再推迟。舒服久了会变成一道很软的墙，你没觉得被困，但确实已经很久没往外走。","alchemy_tip":"每季度安排一次明确不舒服的事：一场陌生的场合、一次长途、一个你不擅长的挑战。让身体记住不适不会致命。"},"low":{"label":"停不下来的人","gift_title":"不靠安慰也能往前走的劲","gift_desc":"你不太需要额外的犒赏来支撑自己，目标本身就能推着你往前走。这种耐力让你在别人松懈的时候还在推进，也确实拿出了别人不容易拿出的东西。","shadow_title":"把休息也变成一项任务","shadow_desc":"连放松都要有理由，久了身体会用失眠、暴躁或者突然的空掉来提醒你。你可能已经很久没有真正什么都不做过了，也忘了那是什么感觉。","alchemy_tip":"每周固定一个「什么都不产出」的晚上，写进日程，像开会一样不可取消。休息要当成正事，你才会真的休息。"}},"phil_nihilism":{"name":"虚无底色","volume":"vol11","category":"philosophy","high":{"label":"看到底的人才敢轻装","gift_title":"不被虚假意义绑架的自由","gift_desc":"你很早就知道没有谁在终点等着给你打分，因此不太会被「应该」两个字吓住。这份底色让你活得比别人轻，也让你在旁人都慌的时候格外稳得住。","shadow_title":"提前撤掉了所有重量","shadow_desc":"「什么都无所谓」说久了，会连真正在意的东西也不敢承认。你用这句话提前挡住了失望，同时也挡住了那些本来能让你热起来、愿意早起的事。","alchemy_tip":"写下一件你其实很在乎、但从没承认过的事。不用为它找意义，只要承认它对你重要，就已经足够。"},"low":{"label":"需要意义才能呼吸的人","gift_title":"把在乎当成燃料的能力","gift_desc":"你需要一件事值得，才愿意把力气放进去。这种在乎让你的投入有分量，也让你在漫长而重复的日子里依然能找到继续下去的理由，不容易散掉。","shadow_title":"被意义绑架，一刻不敢停","shadow_desc":"一旦某件事显得没意义，你可能会整个人塌下去。这种结构让你很难经历空窗期，也容易在别人只是休息的时候，替自己判上一场不轻的刑。","alchemy_tip":"练习一件「没有意义但可以做」的事：浇水、擦桌子、走一段路。让手先动起来，意义可以晚一点到。"}},"phil_humanist":{"name":"人本浪漫","volume":"vol11","category":"philosophy","high":{"label":"还愿意为人留位置的人","gift_title":"能看见具体那个人的能力","gift_desc":"你不太会把人简化成标签或立场，遇到冲突时先想到对方也是个会疼的人。这种眼光让你成为很多人愿意讲真话的对象，你的判断也更少走偏。","shadow_title":"替别人的处境承担过头","shadow_desc":"太容易理解别人，会让你在明明该划界的时候继续退让。理解不等于接受，但你的身体常常来不及区分这两件事，最后累的是你，被怪的可能也是你。","alchemy_tip":"在理解对方之后加一句「但我不能接受这个」。共情之后仍然说出自己的位置，才是完整的善意。"},"low":{"label":"先看规则与结果的人","gift_title":"不被情绪裹住的判断力","gift_desc":"你能在别人都在讲感受的时候把标准摆出来，这让你处理事情干净、可预期。很多需要有人做恶人的场合，正因为你在，整件事才没有彻底烂掉。","shadow_title":"错过那些没说出口的部分","shadow_desc":"按规则办事很省力，但有些人真正想说的从来不在字面上。你可能站在完全正确的位置上，却让对方觉得从头到尾没有被看见，这比被反对更伤人。","alchemy_tip":"每次重要对话结束前多问一句「你还有别的想说的吗」。这一句常常比前面所有分析都有用。"}},"mft_care":{"name":"道德·关爱","volume":"vol11","category":"moralfound","high":{"label":"别人疼的时候你会先动","gift_title":"把别人的处境接进身体的能力","gift_desc":"你对痛苦的信号极其灵敏，别人还在犹豫要不要管的时候你已经站过去了。这不是软弱，是一种很硬的道德直觉，很多人正是靠它才熬过最难的那段。","shadow_title":"把所有人的重量都背在自己身上","shadow_desc":"管得太多，会让你在该退的场合继续承担，最后疲惫、怨气，以及那句说不出口的「那我呢」一起堆起来，反而把原本好好的关系伤到了。","alchemy_tip":"帮忙之前先问一句「你希望我做什么」。有时对方要的是被听见，不是被拯救，你的力气可以省下一半。"},"low":{"label":"先分清责任归属的人","gift_title":"不被情绪绑架的边界感","gift_desc":"你不会因为对方难受就立刻接手他的人生，这种清楚让你能长期待在一段关系里而不被耗空。你给的是一个位置，不是无限兜底，反而更持久。","shadow_title":"在该伸手的时刻慢了半拍","shadow_desc":"习惯先分清责任，可能让你在别人真正需要的时候显得冷淡。有些痛苦不管理由如何，都需要有一个人先过去，晚一步，门可能就关上了，而你不在场。","alchemy_tip":"给自己一条最小动作：看到有人明显撑不住时，先做一件小事，不必判断他是否值得，做完再谈责任。"}},"mft_fairness":{"name":"道德·公平","volume":"vol11","category":"moralfound","high":{"label":"对双标过敏的人","gift_title":"一视同仁的硬骨头","gift_desc":"同一件事对不同人用不同标准，会让你生理上不舒服。这种敏感让你在群体里成为那个把规则说清楚的人，也让别人知道在你这里走关系没有用。","shadow_title":"用公平的名义要求世界整齐","shadow_desc":"过分追求对等，可能让你忽略起点本来就不一样。有时候坚持「一人一份」，恰好是最不公的那一刀，还会让你以为自己站在了正确的一边。","alchemy_tip":"下次说「这不公平」之前，先问一句：他们的起点一样吗。公平有时是按需要分，不是按人头分。"},"low":{"label":"看情境决定标准的人","gift_title":"懂得为具体处境留余地","gift_desc":"你不迷信一套通用的尺子，愿意为眼前这个人破一次例。这种灵活让你在复杂的人情里游得动，也让你真的帮到过那些「按规矩不该帮」的人。","shadow_title":"标准随人而变，久了没人信你","shadow_desc":"每次都能找到理由通融，会让你的判断变得很难预期。别人不知道你的线在哪里，也就不会真的把重要的事交到你手上，哪怕你每次都出于好意。","alchemy_tip":"写下三条你不打算为任何人破的底线，其余都可以谈。有这一小块不动的，你的灵活才不会变成随意。"}},"mft_loyalty":{"name":"道德·忠诚","volume":"vol11","category":"moralfound","high":{"label":"认了就站到底的人","gift_title":"愿意为一段关系付代价","gift_desc":"你把人分得很清楚，自己人出事时不会先算划不划算。这种站队让身边的人有底气，也让你在这世上真的拥有几个可以托付的关系，不是通讯录。","shadow_title":"为了自己人把标准调低","shadow_desc":"护得太紧，会让你在该说真话的时候替他遮掩。久了你会发现，你护住的是这段关系的表面，输掉的是自己判断的准头，还有说真话的能力。","alchemy_tip":"给最亲近的人也说一次实话，哪怕会不舒服。真正的忠诚是让他不至于变成更糟的人，不是替他挡住所有后果。"},"low":{"label":"谁对就站谁的人","gift_title":"不被关系绑住的判断力","gift_desc":"你不会因为熟就改变结论，这种清楚让你在混乱的场合里可信。别人知道来问你会得到真话，而不是一句照顾面子的场面话，这本身就是稀缺资源。","shadow_title":"在最需要站队时缺席","shadow_desc":"每次都站在正确那一边，会让身边的人觉得你随时可以走。有些时刻人不需要判断，只需要知道你没有走，而你恰好在那时候讲了道理。","alchemy_tip":"在关系还没出事的时候，明确说一次「你出事我会在」。忠诚不必等到考验那天才表达。"}},"mft_authority":{"name":"道德·权威","volume":"vol11","category":"moralfound","high":{"label":"认秩序的人","gift_title":"让共同体转起来的那根梁","gift_desc":"你尊重位置、程序和前人留下的规矩，知道有些秩序不是用来限制人，而是让很多人能一起把事做成。这份可靠让你成为人群里被依赖的那一类。","shadow_title":"把「上面说了」当成理由","shadow_desc":"太习惯服从，会让你在规则明显不对的时候也继续执行。等到回头看，你会发现自己参与过一些当时根本没想清楚的事，而且没人替你担。","alchemy_tip":"遇到明显有问题的指令，先问一句「这条是为了解决什么」。不必对抗，但要保留一次属于自己的判断。"},"low":{"label":"不服就当场说的人","gift_title":"不给位置加光环的平等感","gift_desc":"你不太在意头衔，谁说得对就听谁的。这种平视让年轻人愿意在你面前开口，也让你不容易被一个身份唬住，能在关键处说出别人不敢说的那句。","shadow_title":"把一切规矩都当成压制","shadow_desc":"习惯性抵触权威，可能让你错过那些真正有用的经验。有些规矩背后，是别人付过很大代价才换来的答案，你的反抗可能刚好从它旁边绕过去，还浑然不觉。","alchemy_tip":"每次想反驳之前，先问一句「这条规矩解决过什么问题」。听懂之后再决定要不要反对，反抗会更有分量。"}},"mft_sanctity":{"name":"道德·圣洁","volume":"vol11","category":"moralfound","high":{"label":"有些东西不能拿来开玩笑","gift_title":"守得住底线的洁净感","gift_desc":"你心里有一小块不能碰的地方，它让你在什么都可被解构的年代仍然保有一点敬畏。这种坚持让你这个人有分量，也让一些界线在你这里真的守住了。","shadow_title":"用纯洁的名义把人分等级","shadow_desc":"太在意干净与不洁，容易让你对犯过错的人失去耐心。有些界线是为了保护人，有些只是为了让自已显得更高一点，这两件事很难自己分辨。","alchemy_tip":"下次觉得某人「脏」的时候，先问一句：他做了什么，还是他只是和我不同。把判断落在行为上，不落在人身上。"},"low":{"label":"什么都可谈的人","gift_title":"不设禁区的开放度","gift_desc":"你不容易被冒犯，也不太需要一块神圣的地方来安放自己。这种开放让你在陌生环境里适应得快，也让别人在你面前不必小心措辞，能松下来说话。","shadow_title":"没有一条线是不能退的","shadow_desc":"什么都不算越界，久了会发现自己也不知道在守什么。真正被踩到的那一刻，你可能连反应都慢了半拍，要过几天才慢慢明白哪里不对，那时已经晚了。","alchemy_tip":"写下三件「就算别人不理解，我也不会让步」的事。不必多，但要有，那是你在这个世界上站住的地方。"}},"mft_liberty":{"name":"道德·自由","volume":"vol11","category":"moralfound","high":{"label":"不许别人替我决定的人","gift_title":"把主权看得比方便重要","gift_desc":"你受不了被安排、被代表、被以「为你好」的名义推着走。这种反抗让很多不合理的事在你这里真的卡住了，也让你活得比多数人更接近自己。","shadow_title":"把任何约束都读成控制","shadow_desc":"反抗成了默认反应，会让你在该合作的时候也先竖一道墙。有些限制只是暂时的代价，不是永久的主权丧失，但你已经在门口先拒绝了。","alchemy_tip":"遇到约束先分两类：这条限制保护了谁。答得出来的先配合一次再谈改进，答不出来的再反对。"},"low":{"label":"能在框架里相处的人","gift_title":"不靠对抗也能守住自己","gift_desc":"你知道什么时候该让一步，也知道让步不等于失去自己。这种弹性让你在集体里过得下去，同时不必把每件小事都升级成一场关于主权的战争。","shadow_title":"一步步退到自己都不认识的地方","shadow_desc":"每次都想着「这次算了」，久了会发现真正决定你生活的人其实是别人。主权不是不争，是在还来得及的时候争那一次，而你总是等到来不及。","alchemy_tip":"挑一件你一直在忍的小事，这周明确说一次不同意见。不用赢，只要让「我的意思」重新出现在桌上。"}},"enn_1":{"name":"1号·完美者","volume":"vol12","category":"enneagram","high":{"label":"先把错处找在自己身上","gift_title":"替所有人守住最后一道工序","gift_desc":"你能在所有人都说可以了的时候，还看得见那处没对齐的地方。事情交到你手上很少出岔子，因为你替大家守住了最后一道工序，也替他们记住了那个容易被省掉的步骤。","shadow_title":"那把尺子最后总是先量自己","shadow_desc":"一句话发出去，你会把它拆成五种读法，然后在心里替对方也替自己各生一遍气。标准变成了不许出错，出错就等同于不配，于是你很少真的休息过。","alchemy_tip":"下次发完一段重要的话，把手机反扣在桌上，设一个二十分钟的计时器。响之前不修改、不补第二条，让它就那么待着。"},"low":{"label":"不靠反复核对也能做对","gift_title":"让事情先跑起来的松手能力","gift_desc":"你不必把每个细节磨到发亮才敢交出去，事情能先跑起来，错了再修。这让你比别人更早拿到真实反馈，也让你身边的人不必在你面前反复解释自己为什么没做到最好。","shadow_title":"标准松了，别人替你补","shadow_desc":"差不多就行这句话说得太顺，代价往往落在别处：一份要返工的文件，一个被你答应又忘掉的期限。别人不好意思提，你自己也不容易发现，直到某天有人不再把事情交给你。","alchemy_tip":"挑一件本周要交出去的东西，交付前问自己一句：这上面有没有一处，是我明知不对但懒得改的。有，就现在改掉那一处。"}},"enn_2":{"name":"2号·给予者","volume":"vol12","category":"enneagram","high":{"label":"先看见别人缺什么的人","gift_title":"在别人开口之前就递到","gift_desc":"你能从一句含糊的话里听出对方真正缺什么，不等他说完就已经在做。被照顾的人往往说不清为什么在你身边会松下来，只是知道你记得他的忌口、他的期限、他上次没说完的半句话。","shadow_title":"给出去的东西后面拖着账","shadow_desc":"你很少直接要，但你一直在记：谁在你最难的时候出现过，谁没有。账不平的时候你不说，只慢慢收回温度，对方只觉得你突然冷了，说不出是从哪一句开始冷的。","alchemy_tip":"想替别人做事之前，先在心里问一句：如果这个人永远不会知道是我做的，我还做吗。答案是否，就把这件事放下。"},"low":{"label":"不靠被需要来确认存在","gift_title":"不把帮忙变成交换","gift_desc":"你帮人的时候不预留回报，也不等对方回头记你一份好。这让你身边的人轻松，他们接受你的好意时不必先算一遍以后怎么还，关系因此干净，也经得起长时间不来往。","shadow_title":"把自己的需要藏得太深","shadow_desc":"你很少开口要什么，别人因此默认你什么都能自己扛。久了你会发现，那些围着你的人都在讲自己的事，没有一个人知道你这半年过得怎么样，而这部分是亲手关上的。","alchemy_tip":"这周找一个人，说一句能被执行的话：我这周很累，你能不能帮我做一件小事。说到具体那件事为止，不要只说最近有点难。"}},"enn_3":{"name":"3号·成就者","volume":"vol12","category":"enneagram","high":{"label":"把想法做成看得见的成果","gift_title":"让努力被看见的能力","gift_desc":"你不满足于把事情做完，你要它站起来、能被别人一眼看懂。提案、作品、一场汇报，你会替它挑最准的那个说法。很多人做的事并不比你少，差的就是这一步。","shadow_title":"一停下来就不知道我是谁","shadow_desc":"你的价值感挂在那份成绩上，成绩在就稳，成绩一撤就空。忙的时候感觉不到这个空，只有假期的第三天下午，或者被换掉的那个下午，它才整个露出来。","alchemy_tip":"每周留两小时做一件没有产出、也不能发出去的事，比如散步、煮一锅汤。做完不总结、不发出去，只记一句当时身体的感觉。"},"low":{"label":"不靠成绩单定位自己的人","gift_title":"做事不必被看见也成立","gift_desc":"你能在没有掌声的地方把事情做好，做完就放下，不需要谁盖章。这让你在没人注意的岗位上待得住，也让你更容易说实话，因为你不必为了保住形象而绕弯。","shadow_title":"好东西烂在自己手里","shadow_desc":"你不太愿意把自己推出去，觉得做过就够了，让别人去说。结果是同一件事，别人拿到了机会，你只留下过程。不是不会做，是不习惯在关键的那一刻替自己说一句。","alchemy_tip":"下次做完一件事，主动给能决定它的人发一条消息：我做完了，这是结果，以及我认为值得看的三点。不要等被发现。"}},"enn_4":{"name":"4号·独特者","volume":"vol12","category":"enneagram","high":{"label":"总在确认自己和别人不一样","gift_title":"能碰到别人绕开的那一层","gift_desc":"你对气氛里最细的那点变化有接近生理的反应，也愿意往别人绕开的地方看。因此你能说出一个房间里没人敢说的那句话，也能在别人只看到表面时，看见他真正在痛什么。","shadow_title":"把不一样当成了身份证","shadow_desc":"为了确认自己不是泛泛之一，你有时会拒绝那些真能让你好起来的东西：一份稳定的工作，一个不戏剧化的人。平淡被读成平庸，于是你反复回到熟悉的疼里，好证明自己是深的。","alchemy_tip":"发现自己因为某件事太平淡而不想开始时，先做十五分钟再评价。把评价往后放，让身体先接触到那件事本身。"},"low":{"label":"不靠独特来认领自己","gift_title":"把自己当普通人也能过","gift_desc":"你不必靠与众不同来确认自己存在，能安安稳稳做一个普通的人、做普通的事。这让你少了许多自我消耗，也更容易和别人站在一起，而不是站在旁边看他们。","shadow_title":"忽略了自己真正想要什么","shadow_desc":"你很少停下来问自己喜不喜欢，久了会发现对很多事都只有一个中性答案，说不上好也说不上坏。别人问起，你能说出应该想要的那个，说不出真正想要的那个。","alchemy_tip":"睡前写三行：今天哪一刻身体是松的，哪一刻是紧的，紧的那次旁边站着谁。只记录，不解释，第二天不用回看。"}},"enn_5":{"name":"5号·观察者","volume":"vol12","category":"enneagram","high":{"label":"先退到能看清的位置","gift_title":"在信息不足时保持清醒","gift_desc":"你习惯先把事情看清楚再表态，所以很少被气氛推着走。别人急着站队的时候，你还在核对前提。这种慢，让你在混乱里给出的判断往往比谁都快地站得住。","shadow_title":"看得清，却一直没进场","shadow_desc":"退后本来是为了看清楚，久了却变成不用被要求。电话让它响完，聚会找理由不去，等你想回到人群里，发现入口已经被自己收窄了，而你也说不清是从哪一次开始。","alchemy_tip":"那个四十分钟的电话，这周挑一次接起来，先不挂断，听到第二十分钟。如果实在撑不住，就说一句我二十分钟后要出门，把边界说出来而不是消失。"},"low":{"label":"随时可以被找到的人","gift_title":"不怕被打断的在场能力","gift_desc":"你能在被打断、被临时叫走、被别人的情绪占掉一个晚上之后，依然接得上自己。这种弹性让你在关系里显得靠得住，别人找你的时候不必先算你会不会嫌麻烦。","shadow_title":"把独处当成了浪费","shadow_desc":"你的时间总是留给别人，安静下来反而不知道做什么。久了会发现自己的判断越来越依赖别人的反应，因为那些本可以一个人想清楚的事，你一直没有给自己那个下午。","alchemy_tip":"这周在日程里先占掉两小时，写上一个具体的事（读一本、走一段路），在被别人占走之前先标成已定。"}},"enn_6":{"name":"6号·忠诚者","volume":"vol12","category":"enneagram","high":{"label":"先想最坏那一种可能","gift_title":"提前看见漏洞的本能","gift_desc":"你总比大家早一步想到会出什么事，所以很多麻烦根本没发生。团队里那个被嫌想太多的人往往是你，而被你拦下来的那次事故，没人知道它本来会发生。","shadow_title":"预案做完了，人还没开始过","shadow_desc":"你把大量力气花在预演失败上，真的走到那一步时反而没了力气。更常见的是，一件事还没开始，你已经因为设想中的反对而先放低了声音，最后真的没成。","alchemy_tip":"想完最坏情况后，加一步：写下它发生的具体概率和一个已经能做的准备。写完就停，不在同一个问题上想第二遍。"},"low":{"label":"先走一步再说的人","gift_title":"不靠保证也能往前","gift_desc":"你不需要先确定有人接着才敢跳，能带着不确定往前走。这让你比多数人更早开始，也少了很多在等待中消耗掉的年份，事情在你手里常常是先做起来再变清楚的。","shadow_title":"风险来的时候没有预警","shadow_desc":"你不太会提前想坏事，于是当它真的来了，你容易整个人被按在原地，第一反应是这不可能。不是承受力差，是从来没为它留过一个位置。","alchemy_tip":"重要的事动手之前，花五分钟写一句：如果三个月后它砸了，最可能是因为什么。只写这一句，然后开始。"}},"enn_7":{"name":"7号·活跃者","volume":"vol12","category":"enneagram","high":{"label":"总在给下一步留路口","gift_title":"把沉闷重新点亮的能力","gift_desc":"你能在一个已经僵住的场合里找到新的入口，让别人重新有兴趣说话。这种对可能性的敏感，让你在别人只看到一条路的时候，手里总是同时握着三四条。","shadow_title":"用新鲜感绕开还没消化的事","shadow_desc":"遇到不好受的部分，你的第一反应是换一个地方、换一批人、换一个计划。事情看上去都过去了，只有你自己知道，某个夜里它会从另一个入口回来。","alchemy_tip":"下次想马上换计划的时候，先把那件不舒服的事写在纸上，定一个具体时间处理它，再决定要不要换。"},"low":{"label":"守着一件事做很久的人","gift_title":"在一件事上待得住","gift_desc":"你不必靠不断换新的刺激才活得下去，能在一段关系、一份工作里待上很多年。时间因此在你这边积累，别人看到的是运气，其实是你没走。","shadow_title":"该走的时候还坐在原地","shadow_desc":"当一件事已经不再给你任何东西，你容易因为怕折腾而继续待着。日子不算坏，只是每年都差不多，而你把这叫做稳定，不再问自己还想要什么。","alchemy_tip":"给现在最熟悉的那件事设一个复查日期，写在日历上。到那天只回答一个问题：如果今天重新选，我还选它吗。"}},"enn_8":{"name":"8号·挑战者","volume":"vol12","category":"enneagram","high":{"label":"不等人来定规矩的人","gift_title":"在没人出头时站出去","gift_desc":"一个房间陷入沉默时，你通常是最先开口的那个。你不需要先获得允许才行动，也不怕把话说得直接。因此那些被默认掉的不公平，在你手上常常真的会改。","shadow_title":"把身体先顶在了前面","shadow_desc":"很多事你已经反应完了才想该不该反应。对方那句话可能只是累，你的音量已经上去了；事后你知道自己过了，但当时那一瞬间，退让看起来比冲上去危险得多。","alchemy_tip":"下次被撞、被冒犯的那三秒里，先做一个具体动作：把重心放回双脚，呼吸一次，再决定要不要开口。只给自己三秒，不要不给。"},"low":{"label":"不去打不必打的仗","gift_title":"把冲突成本算得很低","gift_desc":"你不会为了一个位置去挣得面红耳赤，能在一群人抢的时候先退到一边。这让你少了许多无谓的硬碰硬，也让你在需要合作的时候，比那些时刻要赢的人更容易被人靠近。","shadow_title":"该争的时候手是软的","shadow_desc":"有些东西不让就会被拿走：一个本来属于你的位置、一份应得的价钱。你心里明白，但开口那一刻总差一口气，最后看着它被别人理所当然地收走。","alchemy_tip":"把最常忍让的那件事写下来，包括具体金额或具体分工，然后发一句确认：这件事我需要按这个来。不解释理由。"}},"enn_9":{"name":"9号·调停者","volume":"vol12","category":"enneagram","high":{"label":"先让场面不要太难看的人","gift_title":"让两边都能下台的能力","gift_desc":"你有种罕见的本事：能让两个已经快吵起来的人重新坐下来。你知道什么时候不说话，什么时候递一句台阶，一个房间里因为你少了很多真的碎掉的东西。","shadow_title":"把自己的意见也埋了","shadow_desc":"说不清从哪一年开始，你都行变成了默认答案。等着等着，那个最想说话的人一直不是你，到最后你也不太确定自己到底想去哪里、想和谁去。","alchemy_tip":"下次四人站在路口时，你先说一句具体的：我想吃那家。不必说服任何人，只把你的那一个选项放到桌上。"},"low":{"label":"不怕把话讲明的人","gift_title":"不让事情无辜地拖着","gift_desc":"你不需要用沉默去维持表面的和平，能直接把分歧说出来。这让你身边的人不用猜你在想什么，也让你手上的事情很少因为没人拍板而烂在原地。","shadow_title":"赢了道理，凉了气氛","shadow_desc":"你只关心事情对不对，容易忽略在场的人已经不舒服了。有些关系不是因为分歧断的，而是在你把一件小事抬到很高的时候，对方默默不说话了。","alchemy_tip":"说不同意见前，先加一句具体的承认：你说的这一点我听到了，然后再说你的。只多这一句，不删后面的内容。"}},"inst_sp":{"name":"自保本能","volume":"vol12","category":"instinct","high":{"label":"先确认退路在不在","gift_title":"把生活的地基钉得牢固","gift_desc":"你对钱、身体、住处这些底层条件有一种近乎本能的心里有数，知道每个月多少钱能站住，也记得自己上一次体检是什么时候。台风来的那天，你家有蜡烛、有水、有现金。","shadow_title":"把安全存成了不敢花","shadow_desc":"存款够两年了，你还在一笔一笔对着账看，好像任何一个数字的缺口都意味着坠落。钱和体力变成了只能存不能用的东西，而身体的紧绷并不因为你存得多就松下来。","alchemy_tip":"设一个具体数字：当存款超过这个数时，当月必须花一笔在只能让身体舒服的事上，例如按摩、一双好鞋。把它们写在同一张纸上。"},"low":{"label":"注意力不在退路上","gift_title":"不被匮乏锁死的行动力","gift_desc":"你不会先把所有退路堵好了才敢往前走，能为了一个机会把钱、把安稳先放一边。这让你敢做那些必须冒一点险才能做成的事，也让你不被一个数字绑住二十年。","shadow_title":"身体先报警，账才发现","shadow_desc":"体检报告上的箭头、信用卡账单、房东发来的消息，常常都是最后才被你看到。不是不在乎，是这些事在你视野里本来就不占位置，直到它们大到无法不看。","alchemy_tip":"在手机日历里固定两个日期：每月发薪后第二天看一次账单，每半年一次体检。只做这两件事，不要求自己变成会算账的人。"}},"inst_sx":{"name":"一对一冲动","volume":"vol12","category":"instinct","high":{"label":"一个晚上只装得下一个人","gift_title":"把一个人看到底的能力","gift_desc":"你能把全部注意力放在一个人身上，听他说话时手机反扣、眼睛不漂。被这样对待的人会记得很久，因为大多数人一辈子很少被真正地看进去一次，而你可以。","shadow_title":"浓到对方接不住","shadow_desc":"你给出的浓度常常超过对方准备好的位置，于是同一段关系里，你已经开始想下周，他还在考虑要不要回消息。你不是太粘，只是把全部筹码放到了一张桌子上。","alchemy_tip":"下次想说下次什么时候见之前，先问一句你现在方便安排吗。把节奏交给对方一次，然后真的等他的回答。"},"low":{"label":"注意力是铺开的","gift_title":"不被一个人掏空的稳定","gift_desc":"你的注意力不会被某一个人全部占走，能在几段关系、几件事之间保持均衡。这让你不会因为一个人的冷淡就整个人塌下去，也让你在别人烧得最旺的时候依然是那个稳的。","shadow_title":"很少有人真的进来过","shadow_desc":"你很少让自己真的掉进一个人里面，所以很多关系停在很舒服、但也很浅的地方。不是不真诚，是那个可以一次聊到凌晨两点的位置，你一直没留给谁。","alchemy_tip":"这周约一个你在意的人单独吃一次饭，不看手机，不问工作，只聊你们各自最近真正在想的那件事。"}},"inst_so":{"name":"社交本能","volume":"vol12","category":"instinct","high":{"label":"进门先看自己在哪个位置","gift_title":"让一群人愿意聚到你身边","gift_desc":"你能记住谁和谁熟、谁上次没被叫、谁这阵子在忙什么，然后把人放到合适的位置上。很多后来成了事的关系，最早都是因为你在中间递了一句话。","shadow_title":"被漏掉一次就记很久","shadow_desc":"那个没被叫上的聚会，会在你心里待上很久。你不会直接问，只在群里发一个笑脸，然后真的不再主动开口。被漏掉的不是一顿饭，是那个位置。","alchemy_tip":"下次发现自己被漏掉，直接问一句：你们上周聚了？怎么没叫我。问完就去做别的事，不要看他的回复时间。"},"low":{"label":"不靠位置确认存在","gift_title":"不被圈子裹着的自由","gift_desc":"你不需要在一个圈子里有位置才能安心，被叫上就去，没被叫上也不往心里放。这让你少了许多看人脸色的力气，也让你在需要说真话时不至于先掂量会不会被排挤。","shadow_title":"圈子里的人已经走远了","shadow_desc":"你不在意那些细微的邀请和回访，久了很多本来能走得深的人就慢慢淡了。不是谁的错，只是关系需要有人反复推一下，而你几乎没有推过那一下。","alchemy_tip":"每月挑一个人，发一条与事情无关的消息，只问一句最近怎么样，不提任何需求，发完就把手机放下。"}},"schema_abandonment":{"name":"被抛弃图式","volume":"vol13","category":"schema","high":{"label":"总在等第二只靴子落下的人","gift_title":"对关系里每一次偏移的敏锐","gift_desc":"你能在对方语气差半度的时候就听出变化，因此很少错过真正需要回应的时刻。这种敏锐让你总是最先伸手的那一个，也让你在一段关系里格外用力，几乎从不让自己松懈下来。","shadow_title":"用反复确认把对方推到门外","shadow_desc":"一点点延迟就被你读成撤离的前兆，于是你查、你问、你先一步难过起来。对方要应付的其实不是你的需要，而是那份随时可能到来的恐慌，时间久了谁都会累，也谁都不敢走得太近。","alchemy_tip":"下次心里升起「他要走了」时，先做一件具体的事：把「你是不是不想理我」换成「今晚能不能给我打个电话」。要一个可执行的动作，不要一个保证。"},"low":{"label":"不靠确认也能待在关系里的人","gift_title":"给关系留出呼吸的余量","gift_desc":"对方晚回消息、临时改计划，你不会立刻把它翻译成抛弃。这份从容让关系留出了呼吸的余量，也让对方不必时时自证忠诚，亲密反而因此更能持续下去。","shadow_title":"错过别人正在发出的求救","shadow_desc":"你的稳定有时会让对方的失落无处安放：他已经在往后退，你却以为一切如常。等到你终于察觉的时候，两个人之间已经隔了很远，中间那段路谁都没有走过。","alchemy_tip":"每周主动问一次「最近有没有什么事你没跟我说」。不必追问，只要把那扇门打开着，让对方知道说了也不会被嫌麻烦。"}},"schema_deprivation":{"name":"情感剥夺图式","volume":"vol13","category":"schema","high":{"label":"习惯自己消化的人","gift_title":"极强的自我照料与不添麻烦","gift_desc":"你很早就学会一个人把难处处理完，不给任何人添负担。这种自足让你在混乱里格外稳，也让你成为别人可以放心依靠的那一个，只是很少有人问过你自己靠什么撑着。","shadow_title":"把「没人会来」当成事实","shadow_desc":"你不是没有需要，而是提前把需要收了起来。久了连你自己都分不清是「真的不需要」还是「不敢开口要」，关系里于是总差着那一口该说却没有说出来的话。","alchemy_tip":"挑一个具体的人，练一句话：「我现在不太好，你能不能听我说十分钟。」说之前不要先替对方拒绝你，也不要补一句「不方便就算了」。"},"low":{"label":"会开口要的人","gift_title":"让关心有地方落下","gift_desc":"你相信自己的需要值得被回应，所以别人帮得上忙。这份直白让关系里有来有往，而不是一个人在最难的那几天里独自硬扛，扛完了还要装作什么都没发生。","shadow_title":"把被照顾当成默认配置","shadow_desc":"习惯被接住之后，容易忽略对方也有耗尽的时候。你需要的那双手偶尔也需要有人扶一把，只是他不会自己说，而你常常要等到事情过去之后才想起来问。","alchemy_tip":"每次被照顾之后，问一句「你今天还好吗」。让流动是双向的，关系才不会在不知不觉里被压向一边。"}},"schema_defect":{"name":"缺陷羞耻图式","volume":"vol13","category":"schema","high":{"label":"总觉得自己有一处见不得光","gift_title":"极高的自我要求与体面感","gift_desc":"你对自己的挑剔，让你极少失态，呈现出来的部分总是干净、可靠、经得起细看。这种自律在专业场合里本身就是一种说服力，别人愿意把重要的事交到你手上。","shadow_title":"把被看见等同于被审判","shadow_desc":"你藏起来的东西其实不是缺点，而是「我本来就不够好」这个早已写好的结论。于是夸奖进不来，亲近也进不来，谁靠得近一点，你的第一反应是先紧张起来。","alchemy_tip":"找一件你一直遮着的小事，对一个安全的人说出口，说完什么都不解释。你会发现天没有塌，对方看你的眼神也没有变。"},"low":{"label":"允许自己有瑕疵的人","gift_title":"不靠完美换取位置","gift_desc":"你能在别人面前承认不会、承认自己搞砸了，因此关系里少了一层表演。别人靠近你时不必先通过一道审核，也不必担心哪句话说错就被你记很久。","shadow_title":"对分寸的钝感","shadow_desc":"不太在意外界眼光是一种自由，偶尔也会让你错过那些本该郑重一点的场合。这不是错，只是需要有人提醒你把音量调回来，而那个人往往不好意思开口。","alchemy_tip":"重要场合之前问自己一句：「这里有没有一件事，值得我多花十分钟认真对待。」只挑一件，做完就好。"}},"schema_mistrust":{"name":"不信任图式","volume":"vol13","category":"schema","high":{"label":"先留退路的人","gift_title":"极强的风险嗅觉与自保能力","gift_desc":"你不太会被漂亮话带走，总能比别人早半步看见裂缝。很多坑是你提前绕开的，只是绕开这件事从来不出现在任何人的账面上，也没有人会为此谢你一句。","shadow_title":"把每份好意都过一遍秤","shadow_desc":"你在保护自己的同时，也把真心挡在了门外。对方递过来的东西，你先想的是「他到底要什么」，这样问过几次之后，就没有人愿意再递第二次了。","alchemy_tip":"选一个已经通过时间检验的人，做一次小额度的托付：借一次钱，或者交出去一件私事，然后什么都不查、不旁敲侧击地打听。"},"low":{"label":"愿意先给出信任的人","gift_title":"让人放松的敞亮","gift_desc":"你不预设别人有企图，因此别人在你面前也不必设防。很多关系之所以能变深，只因为先迈出那一步的人是你，而且迈得自然，没有一点试探的痕迹。","shadow_title":"在需要设防时慢半拍","shadow_desc":"善意解读是你的底色，也是你最大的漏洞。有些人正是顺着这份底色进来的，等你看清的时候，成本已经付了出去，退也退不回来，只能自己慢慢消化。","alchemy_tip":"不必变冷，只加一条：把让你反复不舒服的三件事写下来。同一件事出现三次以上，就不是误会，是模式。"}},"schema_isolation":{"name":"社交疏离图式","volume":"vol13","category":"schema","high":{"label":"在人群里独自站着的人","gift_title":"不依附群体的独立判断","gift_desc":"你不需要被圈子认证也能确认自己是谁，因此不太会为了合群去说违心的话。这种清醒在人人都怕掉队的场合里相当稀缺，也让你成为少数几个说真话的人。","shadow_title":"把「不属于」提前变成事实","shadow_desc":"你常常还没被拒绝就先退出了，于是每一次都是你先离席。孤独有一半是别人给的，另一半是你自己先关上的那扇门，而这两半在深夜里长得一模一样。","alchemy_tip":"这一周由你发起一次见面，时间地点你定。不用等被邀请——「被邀请」这件事，本来就轮不到你决定。"},"low":{"label":"能自然嵌进人群的人","gift_title":"把陌生变熟的社交天赋","gift_desc":"你在任何一张桌上都能找到话说，别人也愿意把手上的事托给你。这种连接力让你的人生里很少出现真正的空场，也很少需要一个人熬过什么难关。","shadow_title":"把热闹当成归属","shadow_desc":"被需要的感觉有时会盖过「这真的是我想要的关系吗」这个问题。热闹并不等于被看见，散场之后那种空落，常常被你自己用下一场约填过去。","alchemy_tip":"每月留一个只和自己过的晚上，不社交。用它校准一件事：我留下这些关系，是因为想要，还是因为怕空。"}},"schema_std":{"name":"严苛标准图式","volume":"vol13","category":"schema","high":{"label":"永远差一点的人","gift_title":"极高的完成度与专业骨气","gift_desc":"你对自己下手比对谁都狠，因此交付出去的东西经得起翻检。很多别人做不到的水准，是你不肯放过自己换来的；代价则是那些交不出去的夜晚，和几次本该高兴却高兴不起来的时刻。","shadow_title":"用「还不够」取消了所有庆祝","shadow_desc":"标准本该指向事情，久了却指向你这个人。成绩出来那天你只看见缺口，于是日子成了一场永远到不了终点、也发不出奖的考试，考卷还是你自己出的。","alchemy_tip":"每完成一件事，先写下三条「这次做到了的」，再去改。顺序一旦反过来，你才会记得自己究竟走过哪些地方。"},"low":{"label":"对自己宽容的人","gift_title":"不被标准绑架的自由","gift_desc":"你能接受「够用就好」，因此不容易被无止境的自我要求吞掉。该享受的时候你是真的在享受，而不是一边吃一边在心里算今天到底有没有辜负。","shadow_title":"标准调低之后没人再替你抬","shadow_desc":"没人催的地方，你也就顺势放下了。一些本来可以走得更远的事停在「还行」那一格，几年之后再想起来会有一点可惜，但也说不上后悔。","alchemy_tip":"挑一件你真正在意的事，给它设一条比「够用」高一点点、但明确写下来的线。只高一点点，高太多你会直接放弃。"}},"schema_sacrifice":{"name":"自我牺牲图式","volume":"vol13","category":"schema","high":{"label":"先照顾别人的人","gift_title":"极强的照料能力与被信赖感","gift_desc":"你能提前想到别人的需要，把场面照顾得妥帖。很多人正是因为你在，才没有在某个时刻塌下去，这份功劳却常常记不到你头上，你也不习惯开口去要，好像一提就成了计较。","shadow_title":"用付出换取留下的资格","shadow_desc":"你把「有用」当成被爱的前提，于是很难说出「我不想」。久了别人只记得你能扛，没有人问过你累不累，你偶尔说出来，语气也像在撒娇，于是没人当真。","alchemy_tip":"这一周做一次不解释的拒绝：「这次我不参加。」不补理由，不补一句抱歉，也不在事后偷偷观察对方的脸色。"},"low":{"label":"先照顾好自己的人","gift_title":"清楚自己边界的稳","gift_desc":"你知道自己的余量在哪里，因此不会用透支去换关系。这种清楚让亲密能够长久，而不是靠一个人不断消耗自己维持下去，最后两个人都觉得委屈。","shadow_title":"在别人最需要时显得冷","shadow_desc":"你守住了自己，也可能错过了对方开口的那一刻。不是不爱，只是回应来得太晚，晚到他已经决定把话收回去，不再指望你会先问那一句。","alchemy_tip":"在说「我也没办法」之前，多问一句「你现在最需要我做什么」。一句话，代价很小，却能改写整件事的走向。"}},"schema_approval":{"name":"寻求认可图式","volume":"vol13","category":"schema","high":{"label":"靠别人的眼睛确认自己的人","gift_title":"极高的场合感与被喜欢的本事","gift_desc":"你读得懂气氛，知道什么时候该说什么，因此几乎在任何场合都不会让人不适。这种分寸感是天生的社交资本，也最容易被低估，因为它是看不见的。","shadow_title":"把评价权交到所有人手里","shadow_desc":"一句无心的比较就能改写你一整天。你努力的方向常常不是「我想要」，而是「别让人失望」，久了自己都听不见自己的声音，只剩下别人的表情。","alchemy_tip":"每次发出一条消息、交出一件东西之前，问自己一句：「如果没有人夸我，我还做不做？」答案会告诉你，你站在谁的位置上。"},"low":{"label":"不太需要掌声的人","gift_title":"稳定的内在坐标","gift_desc":"你做的事不必被看见才算数，因此不太会因为别人一句话就改道。这种稳定让人放心，也让人不敢在你面前随口许诺，因为他们知道你会当真。","shadow_title":"错过该争取的注视","shadow_desc":"不主动也不表现，有些机会就落到了更会开口的人手里。不是你不够好，只是没有人知道你做成了什么，也没有机会知道，最后连你自己都记不清了。","alchemy_tip":"一年里至少两次，把做成的事明确讲给能给你机会的人听。不是炫耀，是让事实被知道——沉默不会替你转达。"}},"schema_entitlement":{"name":"权利夸大图式","volume":"vol13","category":"schema","high":{"label":"对自己那一份格外敏感的人","gift_title":"极强的边界感与不吃亏的清醒","gift_desc":"你清楚什么该是自己的，因此不容易被人糊弄。在规则常被人情稀释的场合，你往往是那个把尺子重新摆回桌上的人，只是这份较真不太讨人喜欢。","shadow_title":"把「我应得」修成了默认条款","shadow_desc":"规则顺你时你引用规则，不顺时你引用交情。你可能真的没占过便宜，但身边的人开始学着防你，一些原本一定会叫上你的事，后来也就不叫了。","alchemy_tip":"下次觉得「这本来就该给我」时，先把同一把尺子用在别人身上量一次。量得出一致，那才叫原则；量不出，那就是偏好。"},"low":{"label":"容易让出自己那份的人","gift_title":"极低的摩擦与体面的退让","gift_desc":"你不爱争，很多小事你都愿意让一步。这种不计较让关系顺畅，也让你在人群里显得松弛，谁都愿意跟你坐在同一桌，不必担心哪句话惹到你。","shadow_title":"把自己该得的也让掉了","shadow_desc":"你退得太自然，别人就默认你不需要。长期下来，你会在某个深夜忽然把那笔账算清，然后一个人难受很久，却已经找不出一个合适的机会把话说完。","alchemy_tip":"找一件具体的小事把话说完：「这次按人头分，我那份请算清楚。」不必生气，也不必长篇解释，说完就过去。"}},"schema_negativity":{"name":"灾难预期图式","volume":"vol13","category":"schema","high":{"label":"先想到最坏那种的人","gift_title":"极强的风险预演与兜底能力","gift_desc":"你会在事情发生之前把最坏的情况走一遍，因此很少被打个措手不及。很多灾难是被你提前想出来的那套方案挡在门外的，没有人知道它曾经差点进来。","shadow_title":"把预演当成已经发生","shadow_desc":"大脑分不清推演和现实，你在还没出事的时候就已经付过一次代价。长期下来身体先替你记账：睡不好只是最早的一条，后面还有别的，只是你已经习惯了，不再当成问题。","alchemy_tip":"担忧升起时写两行：最坏是什么，我现在能做的最小一步是什么。写完只做那一步，剩下的今晚不许再想。"},"low":{"label":"先假设没事的人","gift_title":"不被想象消耗的当下","gift_desc":"你不会提前替未来受苦，因此当下的力气都还留在手上。这种松弛让身边的人也跟着放松，很多难事在你这里没有那么吓人，也真的就过去了。","shadow_title":"对真实的风险反应偏慢","shadow_desc":"有些信号本来值得多看一眼，你却习惯把它归到「应该没事」。耽误的那几天有时候就是全部的差别，事后回想很难不后悔，也很难说清是哪一步慢的。","alchemy_tip":"给重要的事设一个「最晚检查日」，写进日历并设提醒。不焦虑，但也不靠运气，让该看的那一眼准时发生。"}},"money_avoid":{"name":"金钱回避","volume":"vol14","category":"money","high":{"label":"让账单在门外过夜的人","gift_title":"不被数字追着跑的松弛","gift_desc":"你不把每一笔钱都换算成安全感，也不会睁眼就去查余额。这份松弛让你在所有人被账单追着跑的时候还睡得着，也让你更愿意把钱花在人和经历上，而不是攒成一个不敢碰的数字。","shadow_title":"把不知道当成没事","shadow_desc":"「不看就不算发生过」曾经真的管用，可越堆越厚的账单不会因为没人打开就变小。等到必须面对的那天，你要处理的不只是数字，还有被推迟的整整一年，和那句「我怎么又拖到现在」。","alchemy_tip":"发薪日当晚设一个十五分钟的闹钟，只做一件事：把本月三笔最大的支出抄在同一张纸上。不做预算、不设目标，写完就把纸收起来。"},"low":{"label":"当天就把数字看清的人","gift_title":"把不确定变成可处理","gift_desc":"账单来了你会当场打开，数字难看也先看清楚。这种对现实的正面接触，让你很少被复利式的麻烦追上，也让你在别人慌成一团的时候，手里已经有一张写好的清单。","shadow_title":"把生活过成一张未闭合的表","shadow_desc":"每一笔都要对上、每一件都要归档，久了你会发现自己很难真正花掉一笔钱。原本用来减少焦虑的习惯，慢慢变成了必须时刻在线的值班，连休个假都要先把账算一遍才敢出门。","alchemy_tip":"这个月挑一笔两百块以内的支出，故意不记账、不核对，月底只看总额。用一次可控的不核对，验证「不查也没有出事」。"}},"money_worship":{"name":"金钱崇拜","volume":"vol14","category":"money","high":{"label":"认钱是硬通货的人","gift_title":"对真实规则的不装","gift_desc":"你不太信漂亮话，知道很多事最后都要落到资源上。这份清醒让你少走许多靠情怀硬撑的弯路，也让你在别人还在等一个说法的时候，已经开始攒能换回选择权的东西。","shadow_title":"把值得换算成价格","shadow_desc":"当钱成了唯一的尺，你会不自觉地把人也放上去称：这场聚会值不值、这段关系有没有回报。算得越准，越难遇到那种说不出好处、却让人愿意留下来的时刻。","alchemy_tip":"这周做一件明确没有回报的事：帮一个不会给你带来资源的人一次，事后一句也不提。做完在日历上打一个点，看看你难受了多久才过去。"},"low":{"label":"钱够用就回头过日子","gift_title":"把注意力还给生活本身","gift_desc":"你不会把每一分力气都换成账户里的数字，更愿意把时间放在没法折现的地方。这让你身上有一种不紧的味道，也让身边的人不必时时掂量自己值多少才配坐在这张桌上。","shadow_title":"用「算了」代替算账","shadow_desc":"不在意钱听起来洒脱，但它也可能是一种回避：不查、不比、不问，于是该谈的薪水没谈、该收的钱没收。等到真需要用钱的那天，你才发现自己在这些事上一直没在场。","alchemy_tip":"下次有人问期望薪资或报价，先别说「都行」，给出一个具体数字，然后闭嘴十秒，让沉默留在对方那边。"}},"money_status":{"name":"金钱地位","volume":"vol14","category":"money","high":{"label":"心里有一杆秤的人","gift_title":"对等与体面的分寸感","gift_desc":"你记得谁请过什么，也懂得用相当的分量还回去。这种分寸让关系里的往来不失衡，别人跟你相处不必担心占了便宜或吃了亏，人情因此能长久地转下去。","shadow_title":"吃一顿饭也要把账平掉","shadow_desc":"被请一次就欠下一笔，于是你急着回请、急着抹平，连别人的好意都变成了一件待办。收不下那份不求对等的心意，日子久了，身边的人会觉得自己给不了你什么。","alchemy_tip":"下次被人请客，只说一句「谢谢，这顿我记着」，其余什么都不做。把回请推到一个月以后，让那笔没结清的账在身上多待一会儿。"},"low":{"label":"不看价签看人","gift_title":"能把好意原样收下","gift_desc":"别人请你，你能安心道谢；礼物贵贱也不太影响你对一个人的判断。这种不设秤的相处，让靠近你的人不必先掂量自己的分量，关系因此轻得多，也真得多。","shadow_title":"把场面上该有的分寸丢了","shadow_desc":"不在意排场是好事，但完全不看场合，容易在需要表示重视的时刻显得随意：该到场的没到、该回的话没回。你不是不重视，只是从没让对方看出来你在重视。","alchemy_tip":"挑一件对方真正在意的小事（不是价格），下次见面带上：他提过的那本书、他家里人的近况，问得具体一点。"}},"money_vigilance":{"name":"金钱警觉","volume":"vol14","category":"money","high":{"label":"找零不对会当场数的人","gift_title":"很难被占便宜的清醒","gift_desc":"数目对不对，你几乎本能地知道。这份警觉让你躲过许多小额、累积起来却不小的损失，也让你在合作里成为那个会去核对条款的人，账目上少有说不清的地方。","shadow_title":"把每个人都当成潜在错账","shadow_desc":"警觉一旦过了头，交易就变成了提防：多找的二十要还、少给的一块要问，连朋友的客气都想验一遍。省下的是钱，耗掉的是那种不必设防的相处，和几句本来能说出口的闲话。","alchemy_tip":"给自己定一条线：单笔五十元以下的差错，不追问、不纠正、不记账。把这条额度写在钱包的便签上，超过了才开口。"},"low":{"label":"多找了也懒得回头","gift_title":"对交易不设防的从容","gift_desc":"你不会在每一笔买卖里假设对方要占你便宜，因此很少被小钱牵动情绪。这份从容让你在人群里显得大方好相处，也让你省下了大量本该花在别处的注意力。","shadow_title":"合同签完才想起没看条款","shadow_desc":"不当回事的性子，在小事上是美德，在金额大的地方就是漏洞：分期的手续费、自动续费、朋友之间的口头借款。等发现的时候，往往已经过了还能改的那一步。","alchemy_tip":"把手机里所有自动续费列一遍，只留还在用的三个，其余当场取消；再加一条：超过月收入一成的支出，隔一晚再签字。"}},"time_past_neg":{"name":"消极过去时间观","volume":"vol14","category":"time","high":{"label":"把旧事翻了很多遍","gift_title":"不会重复同一个坑","gift_desc":"你记得那些难堪的细节，也记得自己当时错在哪一步。这份记忆让你比同龄人更早学会避开某些人和某些局面；代价之外，它确实替你挡过很多次，只是当年没人教你怎么放下。","shadow_title":"用旧伤口解释今天","shadow_desc":"过去的事在你这里不会自然褪色，于是今天一句普通的话，也可能被听成当年的语气。你不是敏感，只是那套反应还留在岗位上，把新的关系当成了旧的现场来处理。","alchemy_tip":"挑一件反复回想的事，写成三行：当时发生了什么、当时的我能做什么、现在的我能做什么。第三行必须落到本周能做完的一件具体事上。"},"low":{"label":"不把旧账带进今天","gift_title":"让过去真的过去","gift_desc":"你能把不愉快留在它发生的年份，不用它来解释眼前的人。这种能力让关系有重新开始的机会，也让你不必每隔几年就回去和同一件事再打一遍，打完还要重新收拾自己。","shadow_title":"同一个地方摔第二次","shadow_desc":"不回头看，有时是真的放下了，有时只是懒得看。于是同样的模式换个面孔又来一次：相似的合伙人、相似的争执，而你依然觉得这一次不一样，直到它再一次走到同一个结局。","alchemy_tip":"把最近三次让你后悔的决定摆在一起，只找共同点：发生的时间、对方的样子、你当时的状态。找出一条规律，就只改那一件事。"}},"time_past_pos":{"name":"积极过去时间观","volume":"vol14","category":"time","high":{"label":"记得从前温度的人","gift_title":"把关系和根脉留住","gift_desc":"你对旧人旧地有真实的牵挂，会记得谁在你最难的时候出现过。这份念旧让你身上有连续性，也让那些和你走散多年的人，仍愿意在需要的时候回头找你一次。","shadow_title":"把从前住成了现在的家","shadow_desc":"回忆太暖，今天的普通日子就容易显得寡淡。你会在比较里悄悄给现在扣分：那时候的朋友更真、那时候的自己更敢。久了，眼前的一切都在和一个已经不存在的版本竞争。","alchemy_tip":"翻出一段你反复回看的旧时光，把它接到今天：约那位老友吃一顿现在的饭，不谈当年，只谈各自眼下在忙什么。"},"low":{"label":"不回头看的人","gift_title":"轻装往前走的自由","gift_desc":"你不太翻旧照片，也不靠回忆取暖，注意力基本都在眼前。这让你不容易被过去绑住，换城市、换行业、换一段关系，都比别人快一些，也少了许多临行前的拉扯。","shadow_title":"把来路一起丢了","shadow_desc":"不念旧的好处是轻，代价是薄：老朋友的电话越来越像打扰，家里的旧事一问三不知。等你真的想回头找点什么，会发现能证明你从哪里来的东西已经所剩无几。","alchemy_tip":"这个月给一个两年没联系、你却真心感激过的人发条消息，只说一件具体的小事：他当年哪句话、哪个动作帮到了你。"}},"time_present_hed":{"name":"享乐当下时间观","volume":"vol14","category":"time","high":{"label":"今晚还没散的人","gift_title":"把日子过成当下的能力","gift_desc":"你能真的坐在一顿饭里，不去想明天的会。这种在场的本事，让你比别人更常尝到生活的好，也让你成为那个能把一桌人的疲惫重新调暖的人。","shadow_title":"用开心盖住没处理的事","shadow_desc":"享受本身没有问题，问题在于它有时被用来顶替难做的事：该拒的局照去，该算的账明天再说。开心的次数越来越密，需要的剂量也跟着变大，安静下来的那半小时反而最难熬。","alchemy_tip":"下次想说「今晚先不管了」之前，先花十分钟把最不想碰的那件事做出一个开头，再出门。玩的时候不把它带在身上。"},"low":{"label":"先想后果再举杯","gift_title":"不被即时快乐牵走","gift_desc":"你能把快乐往后排，先把该做的事处理掉。这份自制让你在别人还在为周末兴奋时已经推进了正事，也让你的生活有一种稳稳的、不容易塌下来的节奏。","shadow_title":"把享受留到以后再说","shadow_desc":"你总在等一个更合适的时机：忙完这阵、存够那笔、等孩子大一点。可合适的时机很少自己走到门口，等你回头看，那些本该庆祝的日子一个都没有留下来，连照片都没拍。","alchemy_tip":"在日历上锁死一个具体时段（比如下周三晚），写上一个纯粹为了享受的安排，先付钱或先约人，让它不能被工作顶掉。"}},"time_present_fate":{"name":"宿命当下时间观","volume":"vol14","category":"time","high":{"label":"认命但日子照过","gift_title":"对不可控事物的平静","gift_desc":"你知道有些事不由自己，因此不会在摇号、行情、别人的选择上耗尽力气。这份认，让你比别人少了很多无用的较劲，也让你在真正的坏消息面前撑得更稳、睡得更沉。","shadow_title":"还没试就先说了看明白","shadow_desc":"把「不由我」用得太早，会变成一种提前投降：还没问就断定对方不会答应，还没改就说这行没机会。省下的是失望，交出去的却是本来还能动的那一格。","alchemy_tip":"挑一件你已经判定「没办法」的事，做一次低成本试探：发一封邮件、问一个人、递一份申请。把它当实验，结果不写进自我评价。"},"low":{"label":"不信命只信下一步","gift_title":"把结果从别人手里拿回来","gift_desc":"你默认事情可以靠动作改变，所以卡住时会先找可控的那一格。这份不信让你比别人多试了几次，也多拿到几次本来轮不到你的机会，代价是很少有机会真正松手。","shadow_title":"把每件不顺都记在自己账上","shadow_desc":"既然一切都能改，那没改好就只能是自己的问题。你很少允许自己说「这件事本来就难」，于是失败不只带来损失，还带来一场对自己的长时间审问，问到最后只剩疲惫。","alchemy_tip":"一件没成的事，写下两栏：我能改的三件事、我改不了的三件事。第二栏写满三条才准收笔，写的过程中不许出现「还不够努力」。"}},"time_future":{"name":"未来导向时间观","volume":"vol14","category":"time","high":{"label":"总在准备下一件事","gift_title":"提前把路铺好的能力","gift_desc":"你习惯提前想三步，存钱、练身体、学新东西都从很远的地方开始算。这份长线让你在别人被突发状况打乱时手里仍有缓冲，也让你确实走到了当初说要去的地方。","shadow_title":"永远活在「等这阵过去」","shadow_desc":"目标一个接一个，每个完成都只是下一段的入场券。你很少停下来验收自己已经走了多远，于是日子变成一条走廊，尽头那扇门总在你快走到时又往前挪了一米。","alchemy_tip":"每完成一个阶段目标，强制安排一件与下一个目标无关的事：休两天、吃一顿贵的、告诉一个人。让「到达」有一次具体的样子。"},"low":{"label":"先过好这一周","gift_title":"不被计划绑住的适应力","gift_desc":"你不太做五年规划，遇到变化却能很快调整方向。这份灵活让你在环境突然改规则时比别人少受折磨，也让你更早看见那些原本不在计划里、却真能走通的出路。","shadow_title":"钱和时间都没有留出余地","shadow_desc":"只顾眼前不全是洒脱，也可能是没给未来的自己留位置：没有应急的钱，也没有能换赛道的技能。等事情真的压过来，你能选的选项会比想象中少很多，而且每一个都很贵。","alchemy_tip":"开一个只进不出的账户，设成发薪日自动转出固定一笔（一百也行），此后不看余额，每月只确认一次转出成功。"}},"tki_competing":{"name":"竞争型","volume":"vol15","category":"conflict","high":{"label":"先把立场摆到桌上","gift_title":"敢在僵局里先开口","gift_desc":"你能在所有人绕圈子的时候把话说到明处：我要这个，不要那个。僵局因此有了一个可以推的着力点，也省下了别人反复猜你意思的那几个小时。","shadow_title":"把人说停了，事还悬着","shadow_desc":"争到最后对方不说话了，你以为事情解决了，其实他只是把账收进心里。久了你会发现，赢下来的每一场都还站着，愿意当面反对你的人却越来越少。","alchemy_tip":"把立场说完之后加一句：「我想听你反对的部分，你最不同意哪一点。」然后在他说话时不要打断，让他把话说完再开口。"},"low":{"label":"不抢那口气的余地","gift_title":"不争也能让场子稳住","gift_desc":"你不必每件事都赢，也不必让每句话都落在自己这边。别人在你面前不用先掂量会不会被顶回来，那些本来不敢说的小意见，反而愿意在你这里先说出来。","shadow_title":"你的那份从没上过桌","shadow_desc":"你把它让过去了，可没有一次是真的不在意。你的要求从没被摆到桌面，别人按他们的方案安排你，然后你怪他们不懂你。那份没说出口的版本，一直只有你自己看过。","alchemy_tip":"这周挑一件你本来会点头的事，回一句：「这个我不行，我要先按我的来。」只说这一件，不解释理由，也不用先道歉。"}},"tki_collaborating":{"name":"协作型","volume":"vol15","category":"conflict","high":{"label":"先摸出两边卡在哪","gift_title":"听得见要求背后的东西","gift_desc":"你不满足于听对方要求什么，你想知道他要的东西后面还压着什么。别人被你的问题问得慢下来，第一次把自己真正的顾虑说全，然后你们找到的那个办法，通常比双方原来提的都好。","shadow_title":"每件小事都开成会谈","shadow_desc":"不是每件事都值得开一场深谈。对方只想快点了结，你却要摸清来龙去脉，于是一个十分钟能散的分歧，被你留成了三小时的会。有人说你难缠，其实你只是舍不得放手。","alchemy_tip":"开口深谈前先问一句：「这件事你今晚想解决，还是想聊透。」他说今晚，就只谈今晚能定的那一版，剩下的写下来留到下次。"},"low":{"label":"容得下没谈完的分歧","gift_title":"让分歧先悬着也不慌","gift_desc":"你能让一部分分歧就那样悬着，不急着给它一个说法。不是每句话都要谈到底，也不是每个不舒服都要立刻交代来历。这份松弛让关系有了余地，谁也不必随时准备接受审问。","shadow_title":"用算了代替说清楚","shadow_desc":"你把不追究当成了处理。话题绕过去，事情留在原地，一次两次看不出来，第三十次它会自己找上来，而且带着前面二十九次的份量。对方以为你不在意，其实你在意得很。","alchemy_tip":"找一件搁置超过两个月的事，今晚说一句话：「这件事我一直没提，但我心里有它。」说完先停住，不急着给方案。"}},"tki_compromising":{"name":"妥协型","volume":"vol15","category":"conflict","high":{"label":"各退一步先把今晚过完","gift_title":"找得出今晚能过的那版","gift_desc":"你擅长在两个人都不肯动的时候找出一个今晚能过下去的版本。它不漂亮，但能让饭吃完、觉睡下、第二天还愿意坐下来。很多关系靠的正是这种把僵局折成可行的能力。","shadow_title":"各退一步，谁都没要到","shadow_desc":"太早折价，两个人都没拿到真正要的东西，只是各自少说了几句。表面成交，底下留着一笔谁都没认的账，下次同一件事再吵，你会发现谈的其实是上次那笔没结完的账。","alchemy_tip":"下次说各退一步之前，先让两个人各说一句：「如果只能保住一样，我最想保住哪一样。」把这个说出来，再谈退哪一步。"},"low":{"label":"不为省事把价折掉","gift_title":"不肯把一个中间数当答案","gift_desc":"你不肯把没弄清的事匆匆折成一个中间数。宁可这一场谈得久一点、难看一点，也不愿意两个人握完手各自后悔。你相信有些东西一旦被折价，就再也不好按原价摆回来了。","shadow_title":"什么都得对，日子变硬","shadow_desc":"你守的那条线，有时自己也说不清是从哪来的。小事被抬成原则，谁提折中就像在侮辱你，日子于是变硬，能商量的地方越来越少，最后连亲近的人也开始绕开你走。","alchemy_tip":"下次争到一半，问自己一句：「这条线是我今天要保的，还是我三年前就摆在那儿的。」答不上来，就先让一步试试。"}},"tki_avoiding":{"name":"回避型","volume":"vol15","category":"conflict","high":{"label":"认得出哪一仗不该打","gift_title":"退开半步，保住后路","gift_desc":"你知道哪一仗不值得打。有些话不必在气头上说，有些人不必当场驳倒，有些场面退开半步反而保住了后面的余地。这份判断替你省下过很多本来会留下的伤口。","shadow_title":"那件事一直留在房间里","shadow_desc":"那件事并没有因为你不说而消失，它在房间里待着，每次你路过都得绕一下。对方慢慢学会了不指望你出面，等你想谈的时候，已经没有人相信你会真的坐下来。","alchemy_tip":"把你要回避的那件事写在一张纸上，只写一句：「我需要二十分钟，二十分钟后我回来谈这件事。」说完真的回到桌边。"},"low":{"label":"不让话在心里过夜","gift_title":"有事当场说掉","gift_desc":"有事你更愿意当面说掉，不让它在心里过夜。该问的当场问，该表的拖不到明天，别人跟你相处省掉了大量猜测。很多被你及时说出来的一句话，本来会长成半年的隔阂。","shadow_title":"小事也要当场掀开","shadow_desc":"不是所有不适都需要当场处理。你把可以自然淡掉的事掀开来，把一次沉默读成一次立场，情绪跟着被反复点着。到最后累的是你，被追着解释的却是身边的人。","alchemy_tip":"下次想立刻追问时，把要问的那句话写在备忘录里，设一个明早九点的提醒。第二天还觉得要说，再说。"}},"tki_accommodating":{"name":"迁就型","volume":"vol15","category":"conflict","high":{"label":"先把对面的人顺过来","gift_title":"能把场面从爆点拉回来","gift_desc":"你懂得在火上浇一点水。对方正在往上冲的时候，你先让半步，把语气放软，让这一场不至于烧掉后面还能谈的东西。有人靠这份退让把火压下去，也有人因此没丢掉一段本来会断的关系。","shadow_title":"让出去的分都记着账","shadow_desc":"让的时候你没说什么，只是记了一笔。攒到某个时刻，你用疲倦、冷淡、拖延去收这笔利息，对方只觉得你忽然变了，说不出是哪一天开始的，你自己也未必说得清。","alchemy_tip":"答应的那一刻加一句具体条件：「这次可以，但下次提前一天跟我说。」把让出去的东西，换成一个能被记住的说法。"},"low":{"label":"说得出那句不","gift_title":"好意后来变成真心的","gift_desc":"你说得出那句不。不必先把场面弄僵，也不用事后解释半小时，一句这次不行就够了。因为你的同意不是默认设置，所以你真的点头时，别人才知道那是有分量的。","shadow_title":"把体贴当成示弱","shadow_desc":"你把让步看成输，把体贴看成示弱，于是每一件小事都守着。身边的人在你面前不敢松、不敢软、不敢先低头，一段本来可以有来有回的关系，被守成了一条单行道。","alchemy_tip":"这周主动让一次，并且说出口：「这次按你的来。」不要补任何条件或解释，让这句话就停在那里。"}},"pac_parent":{"name":"父母自我态","volume":"vol15","category":"pac","high":{"label":"乱起来的时候有个顺序","gift_title":"慌乱的场合有人定调","gift_desc":"乱起来的时候，你的声音能让事情有个先后的顺序。谁该做什么、什么时候做、底线在哪里，你一句话就摆出来了。慌乱的场合里总有人需要这个，也常常是你在扮演它。","shadow_title":"为你好变成替你活","shadow_desc":"为你好这三个字，用久了会替别人做决定。你替他判断什么该难过、什么不值得、该怎么做才对，他一开口就先听到评判。于是有的人变小了，有的人掉头就走。","alchemy_tip":"下次给建议前先问一句：「你是想让我听，还是想让我出主意。」他说想让你听，就只问问题，把建议留到明天。"},"low":{"label":"不急着替人下定义","gift_title":"把答案留给对方自己摸","gift_desc":"你不急着替别人定义他的处境，也不抢着给一个正确说法。对方在你面前可以自己慢慢摸到答案，说错也不被你纠正。这种不介入，让很多人第一次把话讲完整。","shadow_title":"该定调时你退在后面","shadow_desc":"该有人站出来的时候，你退在后面。规矩没人定，调子没人收，混乱里每个人都在等别人先说。你把不评判当成尊重，可有些场面需要的恰恰是一句就按这个来。","alchemy_tip":"下次一群人卡在没人拍板的地方，你直接说一句：「先按这个做，周五再看要不要改。」给出日子，不留活口。"}},"pac_adult":{"name":"成人自我态","volume":"vol15","category":"pac","high":{"label":"只说这一次，这一件事","gift_title":"把语气拉平还能把话说完","gift_desc":"你能把语气拉平，只说这一次、这一件事。对方拿旧账来翻，你会把它放回去，然后接着谈眼前这口碗。这种能力让吵架有终点，也让两个人不至于把十年的账一次算完。","shadow_title":"永远冷静，像在开会","shadow_desc":"永远冷静也会伤人。你把情绪挡在门外，把每一次冲突开成会议，对方递过来的难受总被你转成一条待办。久了他会觉得跟你说话要提交材料，而不是在跟一个人相处。","alchemy_tip":"下次谈完正事，补一句没有信息量的话：「刚才那几句我听着也不舒服。」不给方案，不分析，说完就停。"},"low":{"label":"身上还留着热的反应","gift_title":"不必每句话都过筛子","gift_desc":"你允许自己有反应，不必每句话都经过过滤器。高兴就笑，不服就顶回去，难受写在脸上。别人因此知道你在哪里，也知道哪句话真的碰到了你，不用靠猜。","shadow_title":"话先出口，理由后补","shadow_desc":"你说完那句话才想它落在哪里，然后花更多时间收拾残局。有些关系不是被大事弄坏的，是被几句来不及想的话一句一句磨薄的，等你看出来，已经薄得透光。","alchemy_tip":"下次回消息前，把要发的那段先打在备忘录里读一遍，再决定要不要复制过去。只加这一步，不改内容。"}},"pac_child":{"name":"儿童自我态","volume":"vol15","category":"pac","high":{"label":"说不愿意说得直接","gift_title":"反应是真的，不掺水","gift_desc":"你的反应是真的。高兴是真的，不愿意也是真的，别人不用费力猜你的脸色。很多僵住的场面，是被一句直白的我不愿意推动的，那句话你说得出来，而且说得不假。","shadow_title":"难受成了通行证","shadow_desc":"难受一旦变成通行证，别人就得先处理你的情绪，才有资格谈事情。一不顺就翻脸或用受伤说话，久了大家学会绕着你走，你想被听见，反而越来越难被听见。","alchemy_tip":"下次难受上来时，先说一句：「我现在情绪很大，给我十分钟。」十分钟后回来，只说这件事里最具体的那一项。"},"low":{"label":"委屈不靠情绪去说","gift_title":"难受着也把事情说完","gift_desc":"你不靠情绪去表达需要。难受的时候仍能把事情说完，把要求说清楚，不用等人来猜，也不用先哭一场才被当回事。这让你的话在着急的场合里依然能被听见。","shadow_title":"难过被你说成了道理","shadow_desc":"委屈被你说成了道理。你把所有的难受翻译成逻辑，讲得越清楚，别人越不知道你其实很难过。他们只看见一个有道理的你在辩论，看不见那个坐在对面需要被安慰的人。","alchemy_tip":"下次讲完道理，加一句：「这件事让我有点难过。」不要接着解释为什么，也不要马上补一条更完整的论证。"}},"hsp_sensory":{"name":"感官高敏","volume":"vol16","category":"neuro","high":{"label":"随身带着一台放大器","gift_title":"一台高分辨率的接收器","gift_desc":"你能分出空调的低频、隔壁的键盘、窗帘漏进来的那点光，也能尝出一杯咖啡里多放了半勺糖。别人自动滤掉的东西，在你这里是一条完整的信息流。对质地、分寸和节奏的直觉，就是这样一点点长出来的。","shadow_title":"一天结束，你已经被声音用完了","shadow_desc":"对别人而言正常的一天，对你是持续的消耗：地铁轰鸣、超市顶灯、连着三场会。你不是不想撑，是系统一直没关过机。最后常被读成矫情或玻璃心，其实只是电用完了。","alchemy_tip":"把「我是不是太敏感」换成「这个环境的分贝对我的系统而言太高」，然后立刻改一个参数：换座位、戴降噪耳机、把顶灯关掉只留一盏侧灯。先承认是环境的问题，再动手动它。"},"low":{"label":"在嘈杂里也能睡着的人","gift_title":"天生的滤噪本领","gift_desc":"你能在开着电视的客厅里读完一章书，也能在硬座上睡着。多数环境对你只是背景，不会长期占住注意力的带宽。这份钝感让你在混乱的现场比别人更能干活，也更少被拖垮。","shadow_title":"身体报警，你总是最后一个听见","shadow_desc":"你对细微信号不敏感，饿了、困了、肩颈僵了都能被忽略很久；对面那个人语气里的退让，也容易漏掉。不是不在乎，是接收阈值高，等你察觉，往往已经晚了一步。","alchemy_tip":"每天设两个固定闹钟，标注「查体」，响的时候只回答三件事：现在渴不渴、身上哪块最紧、上一句话有没有让我不舒服。各写一行字，不用当场处理。"}},"hsp_emotional":{"name":"情绪高敏","volume":"vol16","category":"neuro","high":{"label":"一进门就收到全场情绪","gift_title":"能读到没有说出口的那半句","gift_desc":"别人还在客套，你已经听出那句玩笑底下的失落。你能分辨一个人是真松弛还是在硬撑，因此常常是第一个给出准确回应的人。这种精度不是学来的，是你一直在实时接收。","shadow_title":"别人淋了一场雨，你湿了两天","shadow_desc":"一场别人的坏情绪会整晚留在你身上，第二天开会你还在替他难受。你分不清哪些是共情、哪些是被灌进来的，久了会出现一种说不清来源的疲惫，和没来由的烦躁。","alchemy_tip":"情绪从别人那里涌来时，先做一个身体动作：站起来，脚掌压地十秒，然后问「这份情绪里，哪一部分是我的」。答不上来的部分写在一张纸上，写完撕掉，不带走。"},"low":{"label":"不容易被情绪卷走的人","gift_title":"在风眼里保持常温","gift_desc":"身边的人炸了，你的心率仍然稳。你可以在别人的情绪风暴里继续把事说清楚，不跟着一起沉下去。危机现场最稀缺的往往不是共情，而是这种不跟着乱的人。","shadow_title":"看上去什么都无所谓","shadow_desc":"你不是没有感受，只是它在内部走得很慢、很轻，别人等不到那个回应就先失望了。亲近的人会说「跟你说没用」，而这句话本身，你也常常要过很久才觉得疼。","alchemy_tip":"对方在说难受的事时，不要急着给方案。先照着说一句「听起来你这周挺难的」，然后停三秒，不补话、不解释。练的就是这三秒的空白。"}},"hss_novelty":{"name":"新奇寻求","volume":"vol16","category":"neuro","high":{"label":"总想打开下一扇门","gift_title":"在陌生里快速上手","gift_desc":"换城市、换工具、换行业，你比别人少一层恐惧。陌生对你是燃料：新环境会让注意力瞬间变亮，学得快、上手快，也因此常常比别人更早看见新的可能。","shadow_title":"抽屉里全是开了头的计划","shadow_desc":"新鲜感一退，你就想去找下一个入口。真正难受的不是没能力，而是每件事进入重复期，你就本能地离开。几年过去，手上有很多漂亮的开始，很少有能交出去的完成。","alchemy_tip":"同一时间只允许两个新项目在跑；想开第三个时，先给手上这个写一份「别人能接手」的说明。写不出来，就说明它还没到可以离开的时候。"},"low":{"label":"同一条路越走越顺的人","gift_title":"低功耗也能跑很久","gift_desc":"你不需要靠新鲜感供电，熟悉的路对你不是无聊，是省电。你能在同一套流程里待很久，把它磨到别人做不到的细度，长期积累下来，复利很惊人。","shadow_title":"局面已经变了，你还在按老办法","shadow_desc":"环境换了规则，你的第一反应是加倍认真地做原来那件事。守成本身没错，麻烦的是把「不想折腾」说成「这样最稳」，于是窗口在你想清楚之前就关上了。","alchemy_tip":"每季度挑一件正在做的事，只改一个变量试两周：换工具、换顺序，或者换一个渠道。两周后写三行——哪里变好、哪里变差、留还是撤。"}},"hss_intensity":{"name":"强度寻求","volume":"vol16","category":"neuro","high":{"label":"要很响才觉得活着","gift_title":"敢把油门踩到底","gift_desc":"别人退后半步的时候，你会把自己整个投进去：通宵赶一个项目、全力打一场球、爱一个人不留余地。高强度的时刻是你最清醒的时候，很多别人做不到的事就是这样被做成的。","shadow_title":"用更猛的刺激压住空","shadow_desc":"一安静下来你就不舒服，于是不断加码：更多酒、更快的节奏、更剧烈的情绪。恢复被一再往后推，身体最后用失眠、心悸和一次突然的垮掉，替你把账要回来。","alchemy_tip":"每次高强度体验出发前，先在日历上把恢复日写好：通宵后的第二天不排任何会议，只留睡觉和走路。是提前写进日历，而不是等崩溃后再补。"},"low":{"label":"把音量调低也能满意","gift_title":"在低刺激里待得住","gift_desc":"你不需要把音量调到最大才有感觉：一顿家常饭、一段安静的散步就能把电充满。这让你的消耗更低、恢复更快，也不容易被那些成瘾性的东西拽住。","shadow_title":"把「想要」也一起调成了静音","shadow_desc":"长期低功耗有个代价：你容易把「我不需要那么多」和「我不敢要」混成一件事。当真正想要的东西出现，你可能连伸手都省了，只告诉自己现在这样也挺好。","alchemy_tip":"每月写下一件「其实我想要，但觉得太麻烦」的事，然后只做它的最小版本：想学琴就先约一节体验课，想出门就先订一晚住宿。"}},"big5_open":{"name":"概念探索欲","volume":"vol2","category":"big5","high":{"label":"被未知持续吸引的探索者","gift_title":"跨界联想与第一性原理","gift_desc":"你习惯把陌生的东西拆开来看，因此总能在两个看似无关的领域之间发现可迁移的结构。","shadow_title":"广度过剩而深度不足","shadow_desc":"不断被新的可能性吸引，容易在每个领域都停在入门层，缺少一件真正做完的作品。","alchemy_tip":"给自己的好奇心设一个「封顶项目」：每年必须有一件事，从好奇做到交付。"},"low":{"label":"深挖既有领域的守成型","gift_title":"极高的领域纵深与稳定性","gift_desc":"你不被新鲜感牵着走，能在一条线上反复打磨，最终形成别人难以复制的专业手感。","shadow_title":"对范式转移的迟钝","shadow_desc":"当环境规则已经变了，你仍倾向于用旧的地图走路，容易在转折点被甩下。","alchemy_tip":"每半年主动读一篇完全在你的领域之外的东西，只为了检查自己脚下这块地还在不在。"}},"big5_aesthetic":{"name":"审美体验敏锐","volume":"vol2","category":"big5","high":{"label":"被质感击中的人","gift_title":"极高的美学分辨率","gift_desc":"你能感知到别人忽略的光线、比例与语气，这种敏锐让作品有质感，也让人愿意待在你身边。","shadow_title":"对粗糙环境的高痛感","shadow_desc":"当周围的一切都「不够对」时，你会明显消耗，这种敏感有时会变成对现实的不耐。","alchemy_tip":"把审美从「忍受不了」转成「可以创造」。看到不对的地方，试着动手改一点，而不是转身走开。"},"low":{"label":"功能优先的实用主义者","gift_title":"不被形式消耗的效率","gift_desc":"你不为氛围所动，能直接抓住功能与结果，因此在需要落地时格外干脆。","shadow_title":"缺少让人记住的那一层","shadow_desc":"东西都对，但没有让人愿意多看一眼的部分，长期下来会影响你被记住的概率。","alchemy_tip":"在每个交付物里，只加一处「不必要但让人喜欢」的细节。一处就够。"}},"big5_order":{"name":"秩序与计划感","volume":"vol2","category":"big5","high":{"label":"把混乱压缩成流程的架构者","gift_title":"极强的系统化能力","gift_desc":"你能把混沌变成步骤，让别人接得住你的工作，这种可复制性是团队最缺的东西。","shadow_title":"对意外的低容忍","shadow_desc":"计划被打乱时的烦躁，有时会超出事情本身的严重性，也会让身边的人感到压力。","alchemy_tip":"在计划里主动留出百分之二十的空档，不是为了更高效，而是为了让意外有一个合法位置。"},"low":{"label":"与不确定共处的即兴者","gift_title":"在混乱中依然能行动的弹性","gift_desc":"你不必先有完整的计划才能开始，因此在真正动荡的环境里往往比计划派走得更远。","shadow_title":"重复犯同一类错误","shadow_desc":"因为不留记录、不做复盘，同样的坑会以不同形式反复出现。","alchemy_tip":"不必建立复杂系统，只做一个极简记录：每次踩坑写一行。一行，就足够避免重复。"}},"big5_industry":{"name":"目标韧性与自律","volume":"vol2","category":"big5","high":{"label":"能长期对抗枯燥的推进者","gift_title":"把长期主义变成日常","gift_desc":"你不需要每次都靠激情启动，靠机制就能把自己带到终点，这是极少数人才有的能力。","shadow_title":"用忙碌回避停工焦虑","shadow_desc":"一旦停下来就觉得自己在退步，休息反而变成了另一种消耗。","alchemy_tip":"把休息也当成一项有截止时间的工作。做完就真的结束，而不是心虚地继续。"},"low":{"label":"靠热情驱动的爆发型","gift_title":"在真正感兴趣的事上的超高产出","gift_desc":"被点燃时你能在短时间内达到别人几个月的量，这种爆发力很难被训练出来。","shadow_title":"热情退潮后的长期停摆","shadow_desc":"一旦新鲜感消失，进度会迅速冻结，很多事停在 60% 就再也没有回去。","alchemy_tip":"把 60% 的事集中列出来，只挑一件，用最短路径推到 100%。完成感比新刺激更能续命。"}},"big5_social":{"name":"社交充能倾向","volume":"vol2","category":"big5","high":{"label":"在人群中充电的连接者","gift_title":"天然的场域激活能力","gift_desc":"你能让一屋子人放松下来，这种能力在需要协作、需要破冰的场合极其稀缺。","shadow_title":"独处能力的退化","shadow_desc":"长时间独处时会明显不安，容易用社交填满空白，从而回避真正需要面对的事。","alchemy_tip":"每周留一段完全不社交的时间。不是为了效率，是为了确认你一个人时也站得住。"},"low":{"label":"低耗能的独立观察者","gift_title":"深度独处带来的思考密度","gift_desc":"你能在自己的世界里待很久而不焦虑，因此能产生别人在噪音里想不出来的东西。","shadow_title":"关键场合的存在感流失","shadow_desc":"你的判断很准，但因为不主动表达，很多机会会落到声音更大的人手里。","alchemy_tip":"不需要变成外向的人，只需要在关键的三次场合里，让自己被完整地听见。"}},"big5_assert":{"name":"表达主导与存在感","volume":"vol2","category":"big5","high":{"label":"愿意占据中心的位置","gift_title":"把观点变成共识的推动力","gift_desc":"你敢于在不确定时先开口，因此很多事因你而启动，团队也因你而有了方向。","shadow_title":"无意中挤压他人的表达空间","shadow_desc":"你的存在感太强时，安静的人会越来越少说话，你会因此失去一半的信息。","alchemy_tip":"在每次会议里，刻意留一次不发言的机会，并点名问一个平时不开口的人。"},"low":{"label":"安静但不缺判断的观察者","gift_title":"低噪音下的高信息密度","gift_desc":"你不急着表达，因此能看到更多细节，说出口的话往往比别人的更有分量。","shadow_title":"被误读为没有想法","shadow_desc":"沉默在别人眼里常常等于「没意见」，你的判断可能在你不在场时被替代。","alchemy_tip":"把「等我想清楚再说」改成「我先说一个粗的版本」。粗糙的表达也比沉默更容易被记住。"}},"big5_compassion":{"name":"情绪共情力","volume":"vol2","category":"big5","high":{"label":"能接住他人情绪的人","gift_title":"极高的情绪托底能力","gift_desc":"你不需要别人解释就能感受到他的难受，这种能力让很多人愿意把最脆弱的部分交给你。","shadow_title":"情绪边界被反复穿透","shadow_desc":"长期承接他人的情绪会让你分不清哪些是自己的，容易疲惫、失控或突然想逃。","alchemy_tip":"共情不等于吸收。练习在心里加一句「这是他的，不是我的」，然后只做能做的部分。"},"low":{"label":"情绪低干扰的理性派","gift_title":"高压下的清醒与稳定","gift_desc":"当所有人被情绪裹挟时，你还能处理事情本身，这在危机里是极稀缺的能力。","shadow_title":"难以被感知的在乎","shadow_desc":"你其实在乎，但表达方式让人感觉不到，容易在最亲近的关系里被误解为冷漠。","alchemy_tip":"情绪不需要你解决，只需要你在场。练习先说「我在」，再谈怎么办。"}},"big5_compliance":{"name":"冲突妥协倾向","volume":"vol2","category":"big5","high":{"label":"优先维系关系的协调者","gift_title":"让合作得以持续的润滑能力","gift_desc":"你能在冲突里先退一步，因此很多本会破裂的关系被你保住了。","shadow_title":"边界长期失守","shadow_desc":"你把和平放在自己前面，久了会累积一种说不清的委屈，最后在某个小事上突然爆发。","alchemy_tip":"先练习小范围的不同意。在无关紧要的事上说不，才能在大事上说得出口。"},"low":{"label":"坚持立场的直行派","gift_title":"清楚可预期的立场","gift_desc":"别人知道你在哪、不会变，这种可预期性在长期合作里极其宝贵。","shadow_title":"赢了道理输了关系","shadow_desc":"你常在事实层面正确，但让对方感到被压过，关系会在一次次正确中慢慢变冷。","alchemy_tip":"在表达不同意见之前，先确认对方要的是解决方案还是被理解。顺序反了，正确也会伤人。"}},"big5_alert":{"name":"风险预警敏感","volume":"vol2","category":"big5","high":{"label":"提前嗅到危险的雷达","gift_title":"超前的风险识别能力","gift_desc":"你总能比别人早一点看到那个会出问题的环节，因此少踩很多本可以避免的坑。","shadow_title":"把可能性当成事实","shadow_desc":"长期处于预警状态会让身体一直紧绷，很多灾难只发生在你的脑子里，但成本是真的。","alchemy_tip":"给每个担心加一个概率和一个应对方案。担心一旦具象，就不再有那么大的体积。"},"low":{"label":"低焦虑的行动者","gift_title":"不被预演消耗的行动力","gift_desc":"你不会在事情发生之前先受一遍苦，因此能在别人犹豫时直接出手。","shadow_title":"风险识别滞后","shadow_desc":"有些坑本可以提前看到，但你倾向于「到时候再说」，代价有时不可逆。","alchemy_tip":"对不可逆的事（健康、信任、法律）单独提高一级警惕，其余的事继续允许自己大胆。"}},"big5_rumination":{"name":"情绪反刍与波动","volume":"vol2","category":"big5","high":{"label":"高分辨率的情感处理器","gift_title":"极深的感受与创造力","gift_desc":"你能捕捉到别人略过的情绪层次，这种分辨率是许多创作与深度关系的基础。","shadow_title":"灾难化反刍与精神内耗","shadow_desc":"把小失误放大成全面崩盘，深夜反复咀嚼他人一句无心之言，第二天带着疲惫继续。","alchemy_tip":"给反刍设一个容器：写在纸上，写完合上。让它在纸上转，而不是在脑子里转。"},"low":{"label":"情绪底盘极稳的定海者","gift_title":"泰山崩于前而不乱的稳盘","gift_desc":"你的情绪很少失控，是团队与家庭在危机里最可靠的那根柱子。","shadow_title":"对隐性裂痕的察觉偏晚","shadow_desc":"因为你不太起伏，容易忽略别人已经积累很久的不满，等到发现时往往已经很深。","alchemy_tip":"定期主动问一句「最近有没有什么事让你不太舒服」。你的稳定不该成为别人不敢开口的理由。"}},"dark_mach":{"name":"马基雅维利谋略","volume":"vol3","category":"dark","high":{"label":"读懂牌桌的清醒策略家","gift_title":"顶级局势洞察与风控智谋","gift_desc":"你能一眼看穿利益链与潜规则，不当冤大头，在复杂博弈里为团队和自己争取到真正的空间。","shadow_title":"信任荒漠与关系工具化","shadow_desc":"过度算计防备，很难体验毫无保留的松弛亲密；你会发现自己总是被需要，却很少被真正爱着。","alchemy_tip":"为一两个关系设立「免算计区」：在这几个人面前，允许自己不算收益、不留后手。"},"low":{"label":"直来直去的坦荡者","gift_title":"赤诚透明的信任磁铁","gift_desc":"你说话算数、动机清楚，因此能吸引到同样重情义的人，活得更轻盈、负担更少。","shadow_title":"复杂博弈中易吃暗亏","shadow_desc":"容易把客套当承诺，缺乏利益隔离与识人防备，在真正复杂的局面里可能被利用而不自知。","alchemy_tip":"不必变得狡猾，但要有识人的功课：把重要的口头承诺，改成一次书面确认。"}},"dark_narc":{"name":"自恋光环渴求","volume":"vol3","category":"dark","high":{"label":"需要被看见的发光体","gift_title":"极具感染力的自我表达","gift_desc":"你相信自己值得被看见，这种确信会推着你站到更亮的地方，也真的能带动一群人往前走。","shadow_title":"掌声断供时的坍塌","shadow_desc":"当外部认可突然消失，你会经历超出事情本身的失落，容易做出为了被看见而损耗长期价值的决定。","alchemy_tip":"建立一处只有你自己的评价体系：每季度写一次「我为自己骄傲的一件小事」，不给任何人看。"},"low":{"label":"低调的自持者","gift_title":"不被虚荣牵动的判断力","gift_desc":"你的选择很少被掌声影响，因此在需要冷静取舍的场合，不容易为了体面做出错误决定。","shadow_title":"本该被看见时后退","shadow_desc":"好东西被你自己藏起来，别人无法评估你，很多机会因此落到表达更积极的人手上。","alchemy_tip":"让作品替你说话。不需要自我吹捧，只需要把做好的东西放在看得见的地方。"}},"dark_psycho":{"name":"冷酷果决","volume":"vol3","category":"dark","high":{"label":"高压下的外科医生","gift_title":"切断无效情绪的止损能力","gift_desc":"关键时刻你能把情绪放到一边，快速判断、快速拍板，抗压上限远高于常人。","shadow_title":"共情冰点与关系疏离","shadow_desc":"在亲密关系里显得过于理性冷硬，容易让在乎你的人感到不被接住，久了就不再来找你。","alchemy_tip":"把「处理问题」和「接住人」拆成两步。先花三分钟只做第二步，再进入你的效率模式。"},"low":{"label":"重情重感的柔软者","gift_title":"温润细腻的情感雷达","gift_desc":"你能敏锐觉察他人微小的痛点，给出极高浓度的情绪托底，这种能力让很多人愿意把真心交给你。","shadow_title":"决策拖泥带水","shadow_desc":"因为过度顾忌他人感受或心软，难以在止损节点果断切割，小问题拖成了大问题。","alchemy_tip":"给难以决断的事设一个「最晚决定日」。到那天无论情绪如何，都必须做一个选择。"}},"light_humanism":{"name":"人本主义","volume":"vol3","category":"light","high":{"label":"尊重每个个体尊严的人","gift_title":"让人不必缩小自己的场域","gift_desc":"你发自内心地认为每个人都有其价值，因此别人在你面前不必表演，也不必防御。","shadow_title":"在需要取舍时的迟疑","shadow_desc":"过度体谅每个人的处境，会让你该做减法时下不了手，最后由更狠的人替你决定。","alchemy_tip":"尊重人不等于回避决策。把「我不忍心」换成「我怎么做，才是对他最诚实的安排」。"},"low":{"label":"结果导向的现实主义者","gift_title":"不被情绪成本拖住的执行效率","gift_desc":"你能把人和事分开处理，因此不会因为某个人难受就让整件事停摆。","shadow_title":"被记住的是冷而不是对","shadow_desc":"你的判断常常正确，但方式让人感到被当成工具，长期会损耗你的支持网络。","alchemy_tip":"在做出正确的决定之后，多做一步：亲自告诉那个人你为什么这么做。"}},"light_kant":{"name":"康德式正直","volume":"vol3","category":"light","high":{"label":"不把人当工具的守线者","gift_title":"罕见的原则一致性","gift_desc":"哪怕对自己不利，你也不愿在关键处含糊，这种一致性让别人敢把重要的事交给你。","shadow_title":"道德洁癖带来的孤立","shadow_desc":"对不体面的低容忍，有时会让你在现实灰度里显得难以合作，甚至被贴上不好相处的标签。","alchemy_tip":"把「这件事不对」换成「我可以做哪一部分」。原则不必让你退出所有牌桌。"},"low":{"label":"灵活务实的灰度操作者","gift_title":"在复杂现实里把事推动的能力","gift_desc":"你理解世界不是非黑即白，因此能在多方利益中找出可行路径，比纯粹的人更能成事。","shadow_title":"底线在一次次例外里后退","shadow_desc":"每一次「这次特殊」都在悄悄移动你的标准，几年后回头看，可能已经不在原来的位置。","alchemy_tip":"写下三条你绝不越过的线，贴在能看见的地方。灰度可以很大，但底线必须是硬的。"}},"light_faith":{"name":"人性信仰","volume":"vol3","category":"light","high":{"label":"相信善意值得先给出的信任者","gift_title":"低成本建立深度合作的能力","gift_desc":"你愿意先给出信任，因此常常换来别人对你加倍的坦率，很多合作因你而变得简单。","shadow_title":"被反复透支的善意","shadow_desc":"默认他人善意会让你在真正该设防的时候反应偏慢，代价有时需要很久才能收回。","alchemy_tip":"保持先给出的习惯，但给自己加一条：同一个人透支两次之后，把信任降级为观察。"},"low":{"label":"审慎的验证者","gift_title":"极强的风险隔离能力","gift_desc":"你不会因为客气就交付底牌，因此很少在关系与合作中被真正伤到。","shadow_title":"错过本可以很深的关系","shadow_desc":"长期处于验证状态，会让愿意靠近你的人也慢慢收回手，最后你身边只剩下交易。","alchemy_tip":"给少数人一次「先信任」的机会。深度关系从来不是验证出来的，是先给出来的。"}},"covert_control":{"name":"隐性掌控欲","volume":"vol3","category":"dark","high":{"label":"不显山露水的局势操盘手","gift_title":"让人舒服地被安排的能力","gift_desc":"你不需要用命令就能让事情朝你要的方向走，这种柔和的影响力在复杂组织里极其有效。","shadow_title":"不敢直说的关系疲劳","shadow_desc":"长期用安排代替请求，会让你在关系里始终留着一层看不见的手，对方会觉得累却说不出原因。","alchemy_tip":"每周至少有一次，把「安排」换成「直接说我要什么」。坦白比技巧更省力。"},"low":{"label":"愿意放手的信任者","gift_title":"让别人真正成长的空间","gift_desc":"你能把事交出去而不反复插手，因此身边的人在你这里长得出能力，也长得出忠诚。","shadow_title":"关键处失焦","shadow_desc":"该盯的细节没有盯，问题往往在最不该出的时候冒出来，你才知道自己松得太早。","alchemy_tip":"为自己列三个「必须亲手确认」的关键点，其余全部放手。放手不等于失明。"}},"wv_nature":{"name":"人性预设","volume":"vol4","category":"worldview","polar":true,"negLabel":"审慎防备","posLabel":"善意信任","high":{"label":"相信善意的先行者","gift_title":"让关系变简单的信任红利","gift_desc":"你愿意先把人当成善的，因此别人在你这里不必先证明自己，关系能更快进入深处。","shadow_title":"在真正的恶意面前反应偏慢","shadow_desc":"默认善意会让你在该设防时迟钝，被利用之后还容易先怀疑是自己多心。","alchemy_tip":"保留先给信任的习惯，但加上一条：「两次之后降级」。善意不该是一次性的。"},"low":{"label":"先把世界看清楚的审慎者","gift_title":"极强的风险隔离能力","gift_desc":"你不因客气就交付底牌，因此极少在关系与合作里被真正伤到。","shadow_title":"把人推在门外的疲惫","shadow_desc":"长期验证状态会让愿意靠近的人慢慢收回手，你最后留下的是安全，也只剩下安全。","alchemy_tip":"给三个人一次「先信任」的额度。深度关系从来不是验证出来的。"}},"wv_causal":{"name":"因果归因","volume":"vol4","category":"worldview","polar":true,"negLabel":"顺应随机","posLabel":"长期掌控","high":{"label":"相信选择的掌控者","gift_title":"把命运握在手里的行动力","gift_desc":"你相信事情的结果多半来自选择，因此不会长期停在抱怨里，总能找到自己能改的那一部分。","shadow_title":"把不可控也算成自己的错","shadow_desc":"过强的掌控感会在运气不好时变成自责，明明不是你的问题，也会被算进你的账上。","alchemy_tip":"每次复盘分两栏：我造成的、不是我造成的。第二栏必须真的写下东西。"},"low":{"label":"与随机共处的顺应者","gift_title":"对无常的高容忍与松弛","gift_desc":"你不强求掌控一切，因此更少被挫败击穿，也更容易在变化里找到新的可能。","shadow_title":"把主动让给环境的惯性","shadow_desc":"把太多事归因于时代与运气，会让你在能改变的地方也停止用力。","alchemy_tip":"每周找一件「我完全能决定」的小事，认真做完。掌控感需要被重新训练。"}},"wv_social":{"name":"社会逻辑","volume":"vol4","category":"worldview","polar":true,"negLabel":"现实博弈","posLabel":"契约规则","high":{"label":"相信规则值得守的契约派","gift_title":"可预期的可靠人格","gift_desc":"你不因别人都在破例就跟着破，这种一致性会让你在长期博弈里被当成真正的对手与伙伴。","shadow_title":"被不守规则的人反复消耗","shadow_desc":"你守规则，但环境未必，容易出现你在原地讲道理、别人已经绕过你的局面。","alchemy_tip":"守规则的同时，也要会保护守规则的人。把「我不做」升级为「我要求这条对所有人成立」。"},"low":{"label":"看懂现实棋盘的博弈派","gift_title":"在真实世界里把事做成的能力","gift_desc":"你理解规则背后的动机与现实，因此不会因为教条而错过真正可行的解法。","shadow_title":"标准随场合漂移","shadow_desc":"习惯性按具体情况调整底线，久了别人无法预期你的行为，信任成本会显著上升。","alchemy_tip":"灰度可以有，但要让别人知道你的灰度在哪。公开你的判断标准，比反复解释更有效。"}},"lv_happiness":{"name":"幸福取向","volume":"vol4","category":"lifeview","polar":true,"negLabel":"体验主义","posLabel":"实现主义","high":{"label":"从创造里获得满足的人","gift_title":"能穿过枯燥的长期动力","gift_desc":"你能从「做成了一件事」里获得真实的满足，因此不会在无聊期就放弃，长期复利明显。","shadow_title":"把享受当成浪费","shadow_desc":"很难允许自己只是快乐而不产出，休息时也在隐隐觉得自己在浪费时间。","alchemy_tip":"把「享受」列入正式日程，并给它一个不产出任何东西的名字。它同样是生活的一部分。"},"low":{"label":"从体验里活着的人","gift_title":"极高的生命浓度与感受力","gift_desc":"你能真切地品尝当下的滋味，这种鲜活是很多人努力半生也换不回来的。","shadow_title":"长期项目的中途放弃","shadow_desc":"当一件事开始变得重复，你的投入就迅速衰减，几年下来可能留下很多开头。","alchemy_tip":"为一件事设置「有趣的里程碑」，让过程本身持续有新鲜感，而不是靠意志硬撑。"}},"lv_suffering":{"name":"苦难态度","volume":"vol4","category":"lifeview","polar":true,"negLabel":"拒绝内耗","posLabel":"意义转化","high":{"label":"能从痛里取出东西的人","gift_title":"极强的意义转化能力","gift_desc":"苦难在你这里不会白白发生，你能从中提炼出别人拿不到的东西，也会慢慢长出厚度。","shadow_title":"给痛苦附加过多的正当性","shadow_desc":"习惯从难里找意义，可能让你在该离开的时候继续忍受，把消耗误认为成长。","alchemy_tip":"先问一句「这件事值得我付出这个代价吗」，再问「它能给我什么」。顺序不能反。"},"low":{"label":"拒绝自找苦吃的清醒者","gift_title":"不把消耗浪漫化的判断力","gift_desc":"你不会为了「成长」而主动承受本可以避免的痛，因此能守住自己的能量。","shadow_title":"略过必要的不适","shadow_desc":"有些成长确实必须经过不舒服，过度回避会让你在很多事上停在浅层。","alchemy_tip":"区分「可避免的痛」与「必经的不适」。前者果断离开，后者主动穿过。"}},"lv_anchor":{"name":"存在锚点","volume":"vol4","category":"lifeview","polar":true,"negLabel":"向外建构","posLabel":"向内自洽","high":{"label":"向内的自洽者","gift_title":"不依赖外部确认的内核","gift_desc":"即使没有掌声，你也知道自己在做什么，这种稳定让你在长期无人喝彩的阶段也能坚持。","shadow_title":"与真实世界失去校准","shadow_desc":"过度向内会让你错过外部的真实反馈，可能在自己满意的方向上走偏很久而不自知。","alchemy_tip":"定期让三个你信任的人评价你正在做的事。内耗要靠自洽解决，偏差要靠外部校准。"},"low":{"label":"向外建构的行动者","gift_title":"把自我放进世界的勇气","gift_desc":"你愿意让世界看见你、评价你，因此成长速度快，也更容易抓住真实的机会。","shadow_title":"外部反馈断供时的坍塌","shadow_desc":"当认可消失，你会经历超出事情本身的失落，容易为了被看见而牺牲长期价值。","alchemy_tip":"建立一处不给任何人看的评价体系。你需要一个不依赖观众的存在理由。"}},"val_moral":{"name":"道德算法","volume":"vol4","category":"value","polar":true,"negLabel":"结果优先","posLabel":"原则底线","high":{"label":"以原则为坐标的人","gift_title":"在压力下也不变形的底线","gift_desc":"你的行为有高度可预期性，因此别人敢把真正重要的事交给你，这是一种极贵的信任。","shadow_title":"在灰度里显得不够灵活","shadow_desc":"坚持原则有时会让你错过本可双赢的解法，也会让务实的人觉得你不好合作。","alchemy_tip":"守住原则的目标，但放开路径。同样的底线，可以有很多种实现方式。"},"low":{"label":"以结果为坐标的务实者","gift_title":"把复杂局面推向前的能力","gift_desc":"你能权衡代价与收益，因此能在原则派卡住的地方找到真正可行的路。","shadow_title":"底线在例外中悄悄后退","shadow_desc":"每一次「这次特殊」都在移动标准，几年后你可能已经不在自己以为的位置上。","alchemy_tip":"写下三条绝不超过的线，让它们不参与任何权衡。其余的事，尽情务实。"}},"val_boundary":{"name":"边界重心","volume":"vol4","category":"value","polar":true,"negLabel":"归属稳定","posLabel":"自由独立","high":{"label":"以自由为主权的人","gift_title":"不被安排的完整人格","gift_desc":"你可以独自撑起自己的生活，不会因为害怕孤单而留在一段不合适的关系或工作里。","shadow_title":"把退路走成孤岛","shadow_desc":"过度强调独立，会在需要依靠别人时说不出口，最后连本可以获得的帮助也推掉了。","alchemy_tip":"自由的核心是「我可以选择依靠」，而不是「我不能依靠任何人」。练一次主动求助。"},"low":{"label":"以归属为锚的人","gift_title":"能建立长期深度连接的能力","gift_desc":"你愿意为一段关系让渡一部分自由，因此能拥有那种别人羡慕的、真正稳的归属。","shadow_title":"在关系里失去自己的声音","shadow_desc":"过度以关系为重，会让你长期忽略自己的需求，直到某天突然想全部推翻。","alchemy_tip":"每季度问自己一次：如果这段关系明天结束，我还剩下什么。答案要有内容。"}},"val_standard":{"name":"评判标尺","volume":"vol4","category":"value","polar":true,"negLabel":"效率务实","posLabel":"真诚公平","high":{"label":"以干净为准绳的人","gift_title":"让人放心的做事方式","gift_desc":"你在意过程是否干净，因此你的成功可以被公开讲述，这种体面本身就是长期资产。","shadow_title":"因讲究而错过窗口","shadow_desc":"对「方式对不对」的高要求有时会让你在需要快速出手时犹豫，机会窗口很短。","alchemy_tip":"把「怎么做得干净」拆成可执行的检查项，而不是无限的标准讨论。干净也可以很快。"},"low":{"label":"以有效为准绳的人","gift_title":"极高的落地能力","gift_desc":"你不被形式绑住，能在最短时间拿到结果，这种务实是很多团队真正缺的东西。","shadow_title":"被记住的只是效率","shadow_desc":"事情做成了，但过程中的人被忽略，长期会损耗愿意与你共事的人。","alchemy_tip":"在交付结果的同时，多花五分钟告诉参与者他们做对了什么。效率不该以人为代价。"}},"cog_global":{"name":"全局抽象","volume":"vol5","category":"cognitive","polar":true,"negLabel":"细节实证","posLabel":"全局抽象","high":{"label":"一眼看穿结构的架构师","gift_title":"第一性原理的穿透力","gift_desc":"你能把杂乱的现象压缩成一个底层模型，因此在信息不足时也能做出方向大致正确的判断。","shadow_title":"眼高手低与细节漏勺","shadow_desc":"对琐碎落地缺乏耐心，容易因忽略某个微小执行环节而整体翻车。","alchemy_tip":"给每个宏大判断配一个可验证的最小动作。模型再漂亮，也需要一次地面的确认。"},"low":{"label":"尊重一手事实的落地专家","gift_title":"极高的交付质量","gift_desc":"你相信具体的数据与真实的细节，因此做出来的东西经得起检查，从不画空饼。","shadow_title":"只见树木不见森林","shadow_desc":"长期沉浸细节，容易在局部做到最优，却错过整个方向的范式转移。","alchemy_tip":"每季度抬头看一次：我现在优化的这件事，在整个大盘里还重要吗。"}},"cog_diverge":{"name":"发散破局","volume":"vol5","category":"cognitive","polar":true,"negLabel":"收敛风控","posLabel":"发散破局","high":{"label":"先想十种可能的破局者","gift_title":"打破僵局的创造力","gift_desc":"面对死局，你能想到别人不敢想的路，很多真正的新机会都诞生在这种发散里。","shadow_title":"想法很多，落地很少","shadow_desc":"不断生成新的可能，容易让团队跟不上节奏，也让自己的注意力反复被切碎。","alchemy_tip":"每想十个，强行选一个并给它一个交付日期。发散的价值在于那一个被做出来的。"},"low":{"label":"先把最坏情况堵上的风控派","gift_title":"极低的翻车概率","gift_desc":"你在动手之前就排掉大部分风险，因此做出来的东西稳定、可预期、能承压。","shadow_title":"错过真正的新机会","shadow_desc":"过度收敛会让你在需要颠覆的节点继续优化旧路径，最后被别人绕过。","alchemy_tip":"每半年做一件「没有把握但值得试」的小事。风控是必要的，但不必覆盖全部人生。"}},"cog_logic":{"name":"逻辑抽离","volume":"vol5","category":"cognitive","polar":true,"negLabel":"直觉共振","posLabel":"逻辑抽离","high":{"label":"依赖结构判断的冷静者","gift_title":"不被情绪污染的判断力","gift_desc":"你能把问题拆成可比较的部分，因此在混乱与压力中依然能做出清楚的决定。","shadow_title":"漏掉那个说不清的东西","shadow_desc":"过度依赖可测量的部分，会让你错过那些无法量化、却真正决定成败的信号。","alchemy_tip":"每个重要决定，在算完所有数据之后，加问一句：我心里那点说不清的感觉在指向哪。"},"low":{"label":"依赖直觉与人的感受的人","gift_title":"极高的关系与情境分辨力","gift_desc":"你能读出数据覆盖不到的东西，因此常常在别人还在算的时候就已经知道答案。","shadow_title":"被个人偏好悄悄带偏","shadow_desc":"直觉没有校准机制，容易把喜欢当成正确，把不舒服当成不对。","alchemy_tip":"把你的直觉写下来，一个月后回头看命中率。直觉值得信任，但它需要被记录。"}},"cog_ambiguity":{"name":"高模糊容忍","volume":"vol5","category":"cognitive","polar":true,"negLabel":"确定性偏好","posLabel":"高模糊容忍","high":{"label":"在信息残缺时如鱼得水的人","gift_title":"在不确定中先行一步","gift_desc":"你能在没有清晰规则的情况下行动，因此往往比需要确定性的人更早拿到机会。","shadow_title":"用「先做起来」掩盖了没想清楚","shadow_desc":"高容忍有时会变成对混乱的纵容，方向长期不定，团队跟着反复折腾。","alchemy_tip":"给模糊加一个截止日：到这个日期必须收敛成一个决定，否则就变成漂移。"},"low":{"label":"需要清楚结构的执行者","gift_title":"把混乱变成秩序的能力","gift_desc":"你要求清晰，因此会主动把模糊的事理出头绪，团队因你而能真正跑起来。","shadow_title":"在真正的未知前停住","shadow_desc":"当环境本身无法提供结构时，你会明显不适甚至瘫痪，错过了只能边做边看清的窗口。","alchemy_tip":"练习「七成信息就出发」。有些结构不是你等来的，是你走进去之后才长出来的。"}},"cog_independent":{"name":"独立反叛思考","volume":"vol5","category":"cognitive","polar":true,"negLabel":"共识校准","posLabel":"独立反叛","high":{"label":"不轻易接受共识的质疑者","gift_title":"看见集体盲区的眼力","gift_desc":"你不因多数人同意就相信，因此常常是最早发现方向错误的那一个。","shadow_title":"为反对而反对的惯性","shadow_desc":"长期站在少数一侧，会让你错过群体智慧里真正有价值的部分，也容易孤立。","alchemy_tip":"每次反对之前，先完整复述对方的逻辑。确认你真的理解了，再决定要不要逆着走。"},"low":{"label":"善于提炼群体智慧的人","gift_title":"把共识变成行动的能力","gift_desc":"你能听懂一群人在说什么，并把它整合成一个可执行的方案，这是极稀缺的组织能力。","shadow_title":"在群体错误里一起沉没","shadow_desc":"过度校准共识，会在所有人都错的时候也跟上去，且事后很难说清自己的立场。","alchemy_tip":"在集体决定之前，私下写下自己的原始判断。至少你知道，当时你是怎么想的。"}},"cog_speed":{"name":"快决策迭代","volume":"vol5","category":"cognitive","polar":true,"negLabel":"慢决策求全","posLabel":"快决策迭代","high":{"label":"先做起来再修的迭代者","gift_title":"极高的试错速度","gift_desc":"你不等完美才开始，因此能在同样的时间里试掉更多可能，也更快知道自己要什么。","shadow_title":"把成本推给未来","shadow_desc":"快速出手常常留下需要别人收拾的尾巴，长期会损耗信任与质量。","alchemy_tip":"把决定分成可逆与不可逆两类。可逆的尽管快，不可逆的必须先慢下来。"},"low":{"label":"谋定而后动的求全者","gift_title":"一次做对的定力","gift_desc":"你愿意花时间想清楚，因此做出来的决定质量高，返工少，长期成本更低。","shadow_title":"窗口在思考中关闭","shadow_desc":"等你想清楚时，机会常常已经属于先动手的人；过度求全也会让你长期不开始。","alchemy_tip":"给自己设决策时限，到点必须出结论，哪怕只是「先试一个月」。完美是迭代出来的。"}},"mot_autonomy":{"name":"主权引擎","volume":"vol6","category":"motive","high":{"label":"以自我主权为燃料的人","gift_title":"不被定义的人生主导权","gift_desc":"你能在任何处境里保住自己说了算的那块地方，这种完整感是很多人终其一生都换不来的。","shadow_title":"把依赖当成失败","shadow_desc":"过度强调自主会让你在该求助时说不出口，把本可以得到的力量推远。","alchemy_tip":"真正的主权包含「选择依靠谁」。主动开口一次，你会发现那不比独自撑着更不安全。"},"low":{"label":"在结构中如鱼得水的人","gift_title":"极强的协作与承压能力","gift_desc":"你能在清晰的框架里高效运转，因此常是组织里最可靠、最被需要的那种人。","shadow_title":"把「有人安排」误认为安心","shadow_desc":"长期交出决定权，会在某天突然发现自己已经不知道真正想要什么。","alchemy_tip":"每年至少做一个完全由自己决定、不由任何人评估的选择。主权需要被练习。"}},"mot_mastery":{"name":"跨越引擎","volume":"vol6","category":"motive","high":{"label":"被更高的天花板召唤的人","gift_title":"极强的向上突破能力","gift_desc":"你对「还不够好」有生理级的不适，这股力会让你在别人停下的地方继续往上走。","shadow_title":"永远差一点的空洞","shadow_desc":"把自我价值绑在结果上，会让你每次抵达后只短暂满足，很快又被下一个目标掏空。","alchemy_tip":"在每个目标达成后，强制停留三天不做下一件事。你需要练习「已经够了」的感觉。"},"low":{"label":"在当下就能满足的人","gift_title":"不被成就绑架的自由","gift_desc":"你不需要不断证明自己才能安心，因此活得更松弛，也更少因为焦虑做出错误决定。","shadow_title":"把机会让给了更想要的人","shadow_desc":"缺少向上力时，很多本该属于你的位置会因为你不争而落到别人手上。","alchemy_tip":"找一件你愿意为之吃点苦的事。野心不必很大，但需要有一个。"}},"mot_belonging":{"name":"羁绊引擎","volume":"vol6","category":"motive","high":{"label":"被深度连接驱动的人","gift_title":"能建立命运共同体般的连接","gift_desc":"你愿意把自己真正交给一段关系，因此能拥有那种别人羡慕的、可以托付的深度。","shadow_title":"把「被需要」当成存在的证明","shadow_desc":"当重要的人把注意力移开，你会经历超出事情本身的失重，容易用讨好换回连接。","alchemy_tip":"建立一处不依赖任何人的价值来源。当你有第二个支点，关系才不会变成唯一的地基。"},"low":{"label":"自给自足的独立者","gift_title":"不被关系牵动的高稳定性","gift_desc":"你不会因为谁的离开而塌掉，因此在关系里反而更能保持尊严与清醒。","shadow_title":"错过了被深深理解的滋味","shadow_desc":"过度自给自足会让关系停在表面，你可能被很多人喜欢，却没有人真的知道你。","alchemy_tip":"对一个人多交付一点不该说的东西。深度不是靠时间自动产生的，是靠破例。"}},"mot_security":{"name":"秩序引擎","volume":"vol6","category":"motive","high":{"label":"需要退路稳固的人","gift_title":"极强的风险控制与长期稳定","gift_desc":"你很少把自己推到悬崖边，因此人生的大起大落远少于同侪，底盘极稳。","shadow_title":"用「再等等」推迟了整个人生","shadow_desc":"永远在准备、永远还没准备好，很多本可以改变处境的机会被安全地错过了。","alchemy_tip":"每年做一次「可控的冒险」，风险上限写清楚。安全需要被扩展，而不是被无限加固。"},"low":{"label":"敢于把桥烧掉的人","gift_title":"极强的行动魄力","gift_desc":"你敢在没有退路时往前跳，因此常能拿到那些需要孤注一掷才能得到的东西。","shadow_title":"一次失败就无处可退","shadow_desc":"缺少缓冲会让某次判断失误变成不可逆的代价，恢复期可能长达数年。","alchemy_tip":"留一条只用来活着、不用来选择的底线。冒险可以大胆，生存必须留有余地。"}},"mot_purpose":{"name":"意义引擎","volume":"vol6","category":"motive","high":{"label":"需要事情有回响的人","gift_title":"能穿越长期无回报的信念","gift_desc":"你能在没有掌声的阶段持续投入，因为你要的不是认可，而是那件事真的发生了。","shadow_title":"被宏大叙事拖住日常","shadow_desc":"过度追求意义，会让你对身边具体的人和具体的小事失去耐心。","alchemy_tip":"把意义拉回到半径一米内：今天你让谁的具体处境变好了一点。"},"low":{"label":"把日子过好的实在派","gift_title":"不被宏大叙事绑架的清醒","gift_desc":"你关心具体的生活质量，因此很少为了一个抽象目标牺牲真实的幸福。","shadow_title":"在某个深夜突然的空","shadow_desc":"当物质与体验都到位，仍可能遇到那个问题：这些到底为了什么。","alchemy_tip":"不必急着找宏大答案。先做一件对别人有具体用处的事，意义常常在那之后出现。"}},"mot_hedonism":{"name":"丰盈引擎","volume":"vol6","category":"motive","high":{"label":"被鲜活体验驱动的人","gift_title":"极高的生活感受力","gift_desc":"你能把普通的下午过得有滋味，这种能力是多数成功学永远教不会的。","shadow_title":"用体验回避需要面对的事","shadow_desc":"不断追逐新鲜感，容易让重要但不有趣的事长期搁置，代价在几年后集中出现。","alchemy_tip":"每周留一天给「不好玩但重要」的事，其余六天尽情活得有滋味。"},"low":{"label":"延迟满足的克制者","gift_title":"极强的长期投入能力","gift_desc":"你能为更远的目标放弃当下的愉快，这种能力是复利的前提。","shadow_title":"把享受推迟到永远不会到来","shadow_desc":"一直在为以后准备，可能到了有能力享受的时候，已经失去了感受的能力。","alchemy_tip":"把享受设成一项不可取消的固定支出，每月一次，不需要理由。"}},"att_anxiety":{"name":"依恋焦虑轴","volume":"vol7","category":"attachment","high":{"label":"需要确定被选择的人","gift_title":"极深的投入与关系敏锐度","gift_desc":"你在意得非常真，能第一时间察觉到关系里的细微变化，这种投入本身就是稀有品质。","shadow_title":"用反复确认消耗掉那份爱","shadow_desc":"不确定会让你反复测试对方，久了对方会累，你会更不安，形成加速下沉的循环。","alchemy_tip":"把「他是不是不在乎」换成「我现在需要一个具体的回应」。要具体的东西，比要安心更有效。"},"low":{"label":"关系里的稳定底盘","gift_title":"不靠确认也能安心","gift_desc":"你能在不被回应的时候依然稳得住，因此不会因为一点距离就毁掉一段本来很好的关系。","shadow_title":"对伴侣的焦虑不够敏感","shadow_desc":"你的稳定在对方眼里有时等于「你根本不在意」，容易被误读成冷淡。","alchemy_tip":"主动给一次具体而明确的表达。你觉得不必说的话，往往正是对方最需要听到的。"}},"att_avoidance":{"name":"依恋回避轴","volume":"vol7","category":"attachment","high":{"label":"需要呼吸空间的人","gift_title":"极致的精神主权与自我修复力","gift_desc":"你不依附任何人也能活得丰盈体面，独立人格极强，独处时反而更接近真实的自己。","shadow_title":"亲密恐惧与推开真爱","shadow_desc":"关系越走近越想逃，用冷淡和忙于工作掩饰内心对失控的恐惧，最后推走的往往是最对的人。","alchemy_tip":"在想退的时候先说一句「我需要一点时间，不是不要你」。给退后加上一句说明，关系就不会断裂。"},"low":{"label":"愿意把自己交出去的人","gift_title":"毫无保留的深度连接力","gift_desc":"你敢于敞开软肋去爱与被爱，能营造极富温度的归属感，这是很多人学不会的能力。","shadow_title":"过度融合与边界模糊","shadow_desc":"容易把伴侣的情绪波动当成自己的全部世界，一旦关系动摇，整个人的地基也会跟着摇。","alchemy_tip":"保留一件只属于你、与关系无关的事。亲密是两个完整的人靠近，不是两块泥融成一团。"}},"def_intellectual":{"name":"理智化防御","volume":"vol7","category":"defense","high":{"label":"用结构消化痛苦的人","gift_title":"极高的情绪稳定与洞察力","gift_desc":"你能把混乱的感受翻译成清楚的语言，因此在危机里格外可靠，也常成为别人的定海神针。","shadow_title":"把感受也变成了待分析的材料","shadow_desc":"过度分析会让你离真实的痛越来越远，久了会发现自己什么都能解释，却什么都感觉不到。","alchemy_tip":"在分析之前，先允许自己难受十分钟，什么都不解释。感受需要被经历，不是被理解。"},"low":{"label":"直接感受的人","gift_title":"不被道理绕开真实情绪","gift_desc":"你不会用逻辑把自己从痛里救出来，因此你的情绪是真的，你的关系也是真的。","shadow_title":"在混乱里缺少抓手","shadow_desc":"当情绪过强时容易整个人被卷走，缺少一个能把自己拉回来的结构。","alchemy_tip":"给自己准备一套极简的情绪处理流程（写下来、散步、找人）。不必分析，但需要一个出口。"}},"def_detach":{"name":"情感隔离防御","volume":"vol7","category":"defense","high":{"label":"能瞬间拔掉情绪插头的人","gift_title":"危机中的绝对清醒","gift_desc":"在别人崩溃时你能继续把事情处理完，这种能力让很多灾难被及时止住。","shadow_title":"连快乐也一起被关掉了","shadow_desc":"抽离是全域的，你在关掉痛的同时也关掉了热度，久了会觉得生活像隔着一层玻璃。","alchemy_tip":"在安全的关系里，练习让情绪停留超过三分钟。抽离是技能，但不必全天开启。"},"low":{"label":"情绪随时在线的人","gift_title":"极高的情绪真实度与连接力","gift_desc":"你不会假装没事，因此别人能真的知道你发生了什么，关系也因此真实。","shadow_title":"被情绪淹没而无法处理事情","shadow_desc":"在真正需要冷静的时刻，情绪会先把你冲走，导致该做的事没做成。","alchemy_tip":"练习一个「先处理事情三十分钟」的动作。情绪不会消失，只是稍后才处理。"}},"def_sublimate":{"name":"升华转化防御","volume":"vol7","category":"defense","high":{"label":"把痛变成作品的人","gift_title":"极强的自我转化能力","gift_desc":"你能把最难的部分变成手艺、作品或身体的力量，这种转化是许多人一生学不会的。","shadow_title":"用产出回避真正的面对","shadow_desc":"把所有情绪都投进工作，可能会让你在专业上很强，却在关系里始终缺席。","alchemy_tip":"定期确认一件事：除了产出，你还有没有别的方式处理难过。"},"low":{"label":"痛的时候无法运转的人","gift_title":"不把情绪工具化的诚实","gift_desc":"你不会拿痛苦去换效率，因此你的感受是完整的，也不会把关系变成项目。","shadow_title":"在低谷时产出全面停摆","shadow_desc":"情绪来了就什么也做不了，长期可能造成实际损失与机会流失。","alchemy_tip":"准备一个极低门槛的「维持动作」：哪怕每天只做十分钟。它能在低谷时保住连续性。"}},"def_attack":{"name":"先发反击防御","volume":"vol7","category":"defense","high":{"label":"被侵犯时立刻还手的人","gift_title":"极强的边界保护力","gift_desc":"你不允许自己被踩，因此很少有人敢在你身上试第二次，这在复杂环境里是硬实力。","shadow_title":"误伤与关系的高损耗","shadow_desc":"反应快过判断，容易在还没弄清对方意图时就先伤回去，冤枉了不少本无恶意的人。","alchemy_tip":"把「立刻反击」改成「先问一句」。问完再决定要不要动手，你的力量一点不会减少。"},"low":{"label":"把攻击性收起来的人","gift_title":"极低的关系摩擦","gift_desc":"你很少让人难堪，因此身边的人在你这里感到安全，愿意靠近。","shadow_title":"该还手时手抬不起来","shadow_desc":"长期不反击，会让某些人得寸进尺，最后由别人来替你划那条线。","alchemy_tip":"练习一句固定的句式：「这句话我不接受」。不需要愤怒，只需要说出来。"}},"def_fawn":{"name":"讨好安抚防御","volume":"vol7","category":"defense","high":{"label":"能读出空气的人","gift_title":"极高的情境感知力","gift_desc":"你能在别人开口前就知道他需要什么，这种能力让你在关系与协作里极其被需要。","shadow_title":"用顺从来换取安全","shadow_desc":"长期优先安抚他人，会让你自己的需求被系统性地忽略，最后连你都说不清自己想要什么。","alchemy_tip":"每天练习一次「不解释的拒绝」。一句话就够，不必给理由。"},"low":{"label":"不靠讨好生存的人","gift_title":"清楚的需求与边界","gift_desc":"你不会为了让人舒服而变形，因此你的关系更真，也更少积累隐性的怨。","shadow_title":"错过关系里那些细微的讯号","shadow_desc":"不太读空气，可能让你在别人已经很难受时还继续推进自己的事。","alchemy_tip":"在每次重要对话里，多问一句「你现在是什么感觉」。一句话就能修复很多错位。"}},"def_project":{"name":"反向投射防御","volume":"vol7","category":"defense","high":{"label":"先假定别人有意图的人","gift_title":"极高的防备与识人敏锐度","gift_desc":"你不太会被表象骗，能比别人更早感觉到那层没说出口的动机。","shadow_title":"把自己的阴影分给别人","shadow_desc":"把自己难以承认的部分归因于外界的恶意，会让你在无害的场合也保持戒备，越活越孤。","alchemy_tip":"当判断「他在针对我」时，先问一句：这会不会是我自己也在想的事。"},"low":{"label":"先按善意理解别人的人","gift_title":"让人放松的信任底色","gift_desc":"你不把自己的阴影分给别人，因此别人在你这里不需要过度防御，关系能更快变深。","shadow_title":"对隐性敌意的察觉偏迟","shadow_desc":"习惯善意解读，可能让你在被算计之后仍然替对方找理由。","alchemy_tip":"保留善意，但也保留记录。把让你反复不舒服的事写下来，事实会告诉你答案。"}},"jung_te":{"name":"外倾思维","volume":"vol9","category":"jung","high":{"label":"把混乱压成清单的人","gift_title":"把想法变成能交付的现实","gift_desc":"你天生会把散乱的信息压成目标、期限和责任人。别人还在讨论要不要做，你已经写出了第一步。团队里最稀缺的从来不是点子，而是这种把想法变成日期的能力。","shadow_title":"把人也当成了流程里的一格","shadow_desc":"效率和可衡量会悄悄吃掉别的东西：一句没有产出的倾诉、一个暂时无用的念头，都被你判为浪费。久了你会发现自己很能干，但身边的人只敢向你汇报，不敢对你说真话。","alchemy_tip":"每周留一次三十分钟的对话，全程只提问、不给方案；对方说完之后，先把他的原话复述一遍，再开口。"},"low":{"label":"不靠排序也能安身的人","gift_title":"对过程本身的信任","gift_desc":"你不需要把一切排成表才敢开始，也能容忍一件事暂时没有结论。这让你在混乱里比别人松弛，更容易看见那些无法被量化、却真正重要的东西。","shadow_title":"该拍板的时候一直在准备","shadow_desc":"当事情需要一个明确的决定、一个日期、一次拒绝，你容易继续搜集信息。不是不会，是不喜欢承担那句「就按这个办」的重量，于是决定权被别人替你做了。","alchemy_tip":"遇到悬了一个月还没定的事，强制写下：最晚本周五给出答复，哪怕答案是「先不做」。"}},"jung_ti":{"name":"内倾思维","volume":"vol9","category":"jung","high":{"label":"非把道理抠到底的人","gift_title":"不被行话说服的判断力","gift_desc":"你对一个说法是否自洽有近乎生理的不适感。别人靠资历和气氛推动结论，你能指出中间断掉的那一环。这种能力让你很难被骗，也很难被漂亮话收买。","shadow_title":"想明白了，事情已经过去","shadow_desc":"内部推演的收益只有你自己看得见。等你把逻辑理清、漏洞补齐，窗口可能已经关了。更麻烦的是，别人听到的往往不是严谨，而是「你为什么总在挑刺」。","alchemy_tip":"下一次把分析压成三句话加一个建议，先说结论后说理由，限时两分钟讲完，讲完就停。"},"low":{"label":"可以先走再想的人","gift_title":"不被逻辑卡住的行动力","gift_desc":"你不需要把每一步想通才敢迈出去，能在信息不全时先动起来，靠真实反馈修正方向。这让你比很多人更早拿到世界给出的答案，也少了许多原地打转。","shadow_title":"被一句顺耳的话带走","shadow_desc":"当一个说法讲得足够流畅、说话的人足够可信，你容易跳过验证。不是偷懒，而是逐条拆解让你疲惫，代价是有时会为一个站不住的判断付出很久。","alchemy_tip":"在重要决定上固定加一句自问：「如果这句话是错的，我最早能在什么时候发现？」把答案写下来。"}},"jung_fe":{"name":"外倾情感","volume":"vol9","category":"jung","high":{"label":"先看屋里气氛的人","gift_title":"让一个房间变暖的能力","gift_desc":"你进门三十秒内就知道谁不自在、谁在硬撑。你能把话递到该说的人嘴边，让一场快要冷掉的饭重新热起来。这种社交温度，很多人一辈子学不会。","shadow_title":"把自己排在了名单最后","shadow_desc":"长期优先照顾在场每个人的感受，你会慢慢分不清哪些是自己真的想要，哪些只是不想让人失望。累到某个点，你会突然对所有人升起一股说不出口的怨。","alchemy_tip":"每次聚会回家路上写一句「今天我真正想要的是___」，不分享、不解释，写满十分钟就合上。"},"low":{"label":"不替所有人收拾气氛的人","gift_title":"不被群体情绪牵着走","gift_desc":"别人的脸色不会轻易改写你的判断。你能在一个都在附和的房间里保持自己的节奏，也因此少做了许多违心的妥协，和事后不得不反悔的承诺。","shadow_title":"被读成了冷淡","shadow_desc":"你只是没把注意力放在气氛上，别人收到的却是「他不在乎」。很多关系的裂缝不是因为冲突，而是因为你没听懂那些没有说出口的暗示。","alchemy_tip":"记住一件具体的事：在场有人明显沉下去时，说一句「你今天好像不太一样」，只这一句就够。"}},"jung_fi":{"name":"内倾情感","volume":"vol9","category":"jung","high":{"label":"心里有一把私秤的人","gift_title":"不被说服的价值坐标","gift_desc":"你对「这件事对不对」有一手判断，且不需要别人同意。这让你在所有人都往一个方向走时，能停下来问一句这是不是我要的，也因此很难被收买。","shadow_title":"把感受存成了沉默的账","shadow_desc":"你的在意很少说出口，只在心里记。等到某天绷不住，对方听到的是突然的爆发，而你听到的是攒了很久的一笔旧账。中间那些本可以早说的话全都没有说。","alchemy_tip":"把「我不舒服」改写成一句具体请求，例如「你刚才那句话我不接受，我需要你先听完我再回应」。"},"low":{"label":"不急着表态的人","gift_title":"能容纳模糊立场的余地","gift_desc":"你不急着给每件事贴一个对错，能接受自己暂时没有立场。这让你在复杂处境里不轻易伤人，也给彼此留出了后来改变、慢慢靠近的空间。","shadow_title":"把别人的期待当成了自己的","shadow_desc":"因为不常回到自己的感受，你容易照着外部标准回答「我想要什么」。几年后回头看，会发现自己过得很体面，却很少有哪一段是真正为自己选的。","alchemy_tip":"每周找一个不会被任何人评价的时刻，回答一个问题：如果没人会知道，我还会做这件事吗？"}},"jung_ne":{"name":"外倾直觉","volume":"vol9","category":"jung","high":{"label":"一眼看见五六条岔路","gift_title":"把可能性提前打开的能力","gift_desc":"别人看见一条路，你看见它分出的五六条岔路。你擅长在毫无关联的东西之间搭桥，很多别人想不到的入口，都是你先看见、先试过的。","shadow_title":"开了太多头，很少收口","shadow_desc":"可能性本身就会给你快感，于是你不断开新坑，在最需要枯燥推进的那一段失去兴趣。三年后手上有很多漂亮的开始，很少有一个能拿出手的完成。","alchemy_tip":"同一时间最多允许两个新项目；想开第三个之前，先把其中一个推进到能给别人看的程度。"},"low":{"label":"走一条路就走到底的人","gift_title":"把一件事做深的定力","gift_desc":"你不被新鲜的岔路带走，能在同一条路上反复打磨，直到它真的成形。这种专注本身就是稀缺品，很多真正的专业度只能这样一寸一寸长出来。","shadow_title":"对已经变了的局面反应慢","shadow_desc":"当环境悄悄换了规则，你会继续按原来那条路走，因为换路看起来成本太高。真正危险的不是守旧，而是没意识到自己已经在守旧，还把它叫作坚持。","alchemy_tip":"每季度找一个完全不在你这行的人聊半小时，只问一句：你最近看到我这个行业哪里变了？"}},"jung_ni":{"name":"内倾直觉","volume":"vol9","category":"jung","high":{"label":"从碎片里看见一条线","gift_title":"提前看见结局的洞察","gift_desc":"你能把散落很久的线索收成一句话，往往在事情发生前就隐约知道它会往哪走。这种预感不神秘，它来自你一直在后台默默整合的那些东西。","shadow_title":"把结论当成了事实","shadow_desc":"因为那条线在你脑内太清晰，你容易跳过验证直接按它行动，也很难向别人解释自己依据什么。当判断落空时，代价往往比你预想的要大。","alchemy_tip":"每个重要的预感都写成一句可被证伪的话，标上验证日期；到期回看，只记它中了几次。"},"low":{"label":"更信手里的具体证据","gift_title":"贴着现实走的清醒","gift_desc":"你不太相信没有证据的预感，更愿意看具体的数字和当下的反应。这让你很少被宏大的叙事带跑，判断通常更贴着地面、更经得起追问。","shadow_title":"到最后一刻才看见全局","shadow_desc":"好处是踏实，代价是常在处理已经发生的麻烦。因为你只在细节冒头时才拼图，那些本可以提前绕开的坑，往往要等整个人掉进去才被看见。","alchemy_tip":"做每个决定时加一句推演：照现在的走法继续三年会变成什么样。写三行，不必给谁看。"}},"jung_se":{"name":"外倾感觉","volume":"vol9","category":"jung","high":{"label":"先动手再说的人","gift_title":"把想法按进现实的手感","gift_desc":"你相信身体和现场，不靠纸上推演。你能在一件事还模糊的时候先做出来，用手感替代空想，这种落地的能力让很多东西真的被你做成过。","shadow_title":"用刺激盖住难受","shadow_desc":"当不舒服的情绪上来，你容易用更快、更满、更强烈的感官把它盖过去：喝酒、刷手机、立刻出门。盖得住当下那一阵，盖不住累积下来的东西。","alchemy_tip":"情绪最催你「马上做点什么」的那十五分钟，只做一件不带刺激的事：走一段路，或者洗一次碗。"},"low":{"label":"让身体先等一等的人","gift_title":"不被当下牵着走的定力","gift_desc":"你不会被眼前的强烈感官牵走，能为了更远的东西忍受此刻的枯燥。这让你在很多需要熬的阶段比别人稳，也少做了许多事后后悔的冲动决定。","shadow_title":"活在了脑子里","shadow_desc":"当身体长期只被当作运载工具，你会慢慢失去对真实生活的触感：吃什么无所谓，去哪儿都行。日子过得正确，却很少有哪一刻是活生生被记住的。","alchemy_tip":"每周安排两小时只跟身体有关的事：走路、游泳、做饭，全程不戴耳机、不设任何目的。"}},"jung_si":{"name":"内倾感觉","volume":"vol9","category":"jung","high":{"label":"记得那碗汤的味道","gift_title":"把经验存成可用的底本","gift_desc":"你记得很多别人早就忘掉的细节：一句话的语气、某年冬天的温度。这些记忆在你身上沉淀成可靠的参照，让你在相似的处境里比谁都稳。","shadow_title":"用过去解释现在","shadow_desc":"熟悉会让你安心，也会让你把新的处境继续按旧剧本读。当一个人已经变了、一件事已经不同，你可能还在用三年前的解法，回应今天的他。","alchemy_tip":"在熟悉的关系里每季度问一次：现在的你和去年比，哪里不一样了。听完先不要反驳，也不要补充。"},"low":{"label":"不被过去拽住的人","gift_title":"轻装往前走的能力","gift_desc":"你不会被旧账和旧习惯绑住，能干脆地放下已经不适合的东西。这种轻装让你换城市、换行业、换关系时都比别人快，也更少被旧事拖住脚。","shadow_title":"把重要的东西也一起丢了","shadow_desc":"习惯性向前看，会让你忽略身体早就在报警、关系早就在变薄。等到某天回头看，才发现有些东西不是被谁拿走的，是你在路上一点点丢掉的。","alchemy_tip":"每月固定一天写下三件「还在，但很久没管」的事：一个人、一个习惯、一处身体的不适。"}}};

export const ARCHETYPES = {"archetypes":[{"id":"AR01","name":"古典守门人","latin":"The Classical Gatekeeper","keywords":["原则一致","愤怒有据","体面刚硬"],"verdict":"你的锋芒极少为了私利出鞘，几乎全部来自对双标与恃强凌弱的不可容忍。你相信世界至少应该讲道理，并且愿意为这句话付出代价。","weights":{"light_kant":1.4,"val_moral":1.3,"sin_wrath":1.1,"wv_social":1,"light_humanism":0.8},"negWeights":{"dark_mach":-0.6},"psych_tag":"高原则底线 × 义愤驱动型"},{"id":"AR02","name":"丝绒棋手","latin":"The Velvet Strategist","keywords":["温和外壳","局势洞察","不动声色"],"verdict":"你的善意是真的，你的计算也是真的。你懂得用体面降低摩擦，同时在没人注意的地方把局势推向自己需要的位置。","weights":{"dark_mach":1.4,"covert_control":1.3,"big5_compliance":1,"light_faith":0.6},"negWeights":{"big5_assert":-0.3},"psych_tag":"高谋略 × 高妥协表象协同型"},{"id":"AR03","name":"精密发条","latin":"The Precision Clockwork","keywords":["极高可靠","提前预演","长期绷紧"],"verdict":"你是那种让人放心到忘记说谢谢的人。代价是你几乎从未真正松开过，连休息时都在核对有没有漏掉什么。","weights":{"big5_order":1.4,"big5_industry":1.3,"big5_alert":1.2,"big5_rumination":0.8},"negWeights":{"sin_sloth":-0.5},"psych_tag":"高秩序 × 高反刍的过载自驱型"},{"id":"AR04","name":"旷野旅人","latin":"The Open-Field Wanderer","keywords":["主权优先","留有余地","不被定义"],"verdict":"你极度渴望不被安排，但绝不做毫无退路的裸奔。你会默默把底牌攒够，只为买断自己人生的选择权。","weights":{"mot_autonomy":1.5,"val_boundary":1.3,"mot_security":0.9,"cog_ambiguity":0.7},"negWeights":{"big5_compliance":-0.6},"psych_tag":"高自主 × 高安全需求的双锚型"},{"id":"AR05","name":"玻璃罩观察者","latin":"The Bell-Jar Observer","keywords":["滴水不漏","情绪自持","深处封锁"],"verdict":"在绝大多数场合你都是最冷静体面的成年人。但越是滴水不漏的外壳，越说明你把真实的部分锁在了极深的地方。","weights":{"def_intellectual":1.4,"def_detach":1.3,"big5_rumination":0.6,"att_avoidance":1},"negWeights":{"big5_compassion":-0.4},"psych_tag":"理智隔离 × 情感疏离的旁观型"},{"id":"AR06","name":"深夜补偿者","latin":"The Nocturnal Compensator","keywords":["白昼顺从","夜间夺权","感官代偿"],"verdict":"白天你在关系与工作里过度配合，到了深夜，大脑会通过熬夜、食物或消费，把你白天让出去的控制权抢回来一点。","weights":{"sin_gluttony":1.3,"def_fawn":1.4,"mot_autonomy":0.9,"virtue_temperance":-1},"psych_tag":"高放纵代偿 × 高讨好白昼割裂型"},{"id":"AR07","name":"酸质攀登者","latin":"The Ascetic Climber","keywords":["横向敏感","野心精准","转化力强"],"verdict":"每次看到同龄人跃迁时泛起的不甘，其实是你潜能发出的警报。把视线从对方身上拉回自己的清单，这股能量会让你跑得很快。","weights":{"sin_envy":1.2,"mot_mastery":1.4,"def_sublimate":1.2,"big5_industry":0.9},"psych_tag":"高比较敏感 × 高成就驱动型"},{"id":"AR08","name":"门廊观望者","latin":"The Porch Watcher","keywords":["珍视深度","畏惧束缚","留一盏灯"],"verdict":"你内心无比珍视灵魂共振的关系，却又极度畏惧被束缚与受伤。你理想的爱人不是藤蔓，而是各具风骨、始终为你留灯的人。","weights":{"att_avoidance":1.4,"mot_belonging":1.2,"def_detach":0.9,"light_faith":0.5},"psych_tag":"高回避依恋 × 高归属渴求型"},{"id":"AR09","name":"敏感刺猬","latin":"The Sensitive Hedgehog","keywords":["标准极高","渴望被看见","嘴硬心软"],"verdict":"理性上你觉得多数人配不上你的标准，情感上却极度渴望被某个人毫无保留地偏爱。这份拉扯是你最高频的内耗源。","weights":{"sin_pride":1.4,"att_anxiety":1.3,"dark_narc":0.8,"big5_rumination":0.7},"psych_tag":"高焦虑 × 高先发反击型"},{"id":"AR10","name":"优雅省力者","latin":"The Elegant Minimalist","keywords":["厌恶重复","抓核心","点燃即爆发"],"verdict":"你并非能力不足，而是对低水平重复存在生理排斥。碰到真正点燃你好奇心的难题，你能爆发出常人难以企及的巧劲。","weights":{"sin_sloth":1.2,"cog_global":1.3,"big5_open":1.1,"cog_diverge":0.8},"psych_tag":"高全局抽象 × 低勤勉投入型"},{"id":"AR11","name":"临床手术刀","latin":"The Clinical Scalpel","keywords":["果断止损","外冷内热","长痛不如短痛"],"verdict":"你做决定干脆冷峻，甚至显得不近人情。但你相信长痛不如短痛，用果断止损保护更大的善意。","weights":{"dark_psycho":1.4,"light_humanism":1.1,"cog_logic":1.2,"def_detach":0.8},"psych_tag":"低共情 × 高人性信念的矛盾型"},{"id":"AR12","name":"清醒享乐派","latin":"The Lucid Hedonist","keywords":["坦荡谈钱","体验至上","用资源换自由"],"verdict":"你毫不羞于谈论资源积累，但终极目的绝非守财。你要的是用厚实的物质底盘，把时间与审美自由赎回来。","weights":{"sin_greed":1.2,"mot_hedonism":1.4,"mot_mastery":0.9,"big5_aesthetic":0.8},"psych_tag":"高贪婪驱力 × 低幸福取向型"},{"id":"AR13","name":"可能性成瘾者","latin":"The Possibility Addict","keywords":["概念饥饿","跨界联想","广度优先"],"verdict":"你被陌生事物持续吸引，因此总能在两个看似无关的领域之间找到可迁移的结构。问题是，你很少把其中一件做到能被别人看见。","weights":{"big5_open":1.5,"cog_diverge":1.2,"cog_ambiguity":1,"big5_aesthetic":0.7},"psych_tag":"高开放性 × 高发散破局型"},{"id":"AR14","name":"证据匠人","latin":"The Evidence Artisan","keywords":["细节精度","交付可靠","不画空饼"],"verdict":"你相信具体的数据与真实的细节，因此做出来的东西经得起检查。你唯一的风险是：世界有时会因为方向错了，而让完美的工艺白费。","weights":{"cog_global":-1.2,"big5_order":1.3,"big5_industry":1.3,"cog_logic":1},"psych_tag":"高秩序 × 高勤勉的实证型"},{"id":"AR15","name":"带刺理想者","latin":"The Thorned Idealist","keywords":["对不公过敏","当场开口","不肯犬儒"],"verdict":"你的怒火很少来自私利，几乎全被双标与虚伪瞬间点燃。你骨子里住着一个不肯向现实低头的古典侠客。","weights":{"sin_wrath":1.4,"val_standard":1.2,"big5_assert":1.1,"light_kant":1},"psych_tag":"高道德底线 × 高易怒张力型"},{"id":"AR16","name":"深海稳压器","latin":"The Deep Stabilizer","keywords":["情绪极稳","危机定盘","低戏剧性"],"verdict":"你的情绪底盘极稳，是危机中最可靠的那根柱子。你的盲区在于：稳定有时会让别人不敢告诉你，他们其实已经很痛。","weights":{"big5_rumination":-1.4,"def_detach":1.1,"big5_alert":-0.9,"mot_security":0.8},"psych_tag":"低反刍 × 高情感隔离的稳态型"},{"id":"AR17","name":"灰度务实者","latin":"The Grey Pragmatist","keywords":["灰度操作","结果优先","效率极高"],"verdict":"你理解世界不是非黑即白，因此能在多方利益中找出可行路径。你唯一需要警惕的，是底线在一次次「这次特殊」里悄悄后退。","weights":{"wv_social":-1.3,"val_moral":-1.2,"cog_speed":1.1,"val_standard":-1},"psych_tag":"低社会契约 × 低道德绝对型"},{"id":"AR18","name":"先予者","latin":"The First-Giver","keywords":["善意默认","低防备","关系简单"],"verdict":"你愿意先把人当成善的，因此别人在你这里不必先证明自己。你的代价是，在被真正伤害时会先怀疑是不是自己想多了。","weights":{"light_faith":1.5,"wv_nature":1.2,"big5_compassion":1,"def_project":-1},"psych_tag":"高善意 × 高妥协顺从型"},{"id":"AR19","name":"顺流读风者","latin":"The Air Reader","keywords":["情境敏锐","先安抚","自己最后"],"verdict":"你能在别人开口前就知道他需要什么，这种能力让你被深深需要。代价是你自己的需求，被系统性地排在了最后一位。","weights":{"def_fawn":1.5,"big5_compliance":1.2,"att_anxiety":0.9,"big5_assert":-0.8},"psych_tag":"高服从 × 高共情的接应型"},{"id":"AR20","name":"主权者","latin":"The Self-Sovereign","keywords":["不依附","自我修复","随时能走"],"verdict":"你不依附任何人也能活得体面，这种完整感极其稀有。你需要留意的是，独立有时会变成一面你不敢让人翻过来的墙。","weights":{"mot_autonomy":1.5,"att_avoidance":1.2,"val_boundary":1.2,"big5_social":-0.6},"psych_tag":"高自主 × 高回避的独立型"},{"id":"AR21","name":"长程苦行者","latin":"The Long-Haul Ascetic","keywords":["延迟满足","耐受枯燥","复利信仰"],"verdict":"你能穿过别人熬不过的枯燥期，因此复利会在你身上显现。风险在于，你可能把享受无限推迟到永远不会到来的那一天。","weights":{"big5_industry":1.5,"mot_hedonism":-1.2,"virtue_temperance":1.1,"lv_suffering":0.9},"psych_tag":"高勤勉 × 低享乐的自律型"},{"id":"AR22","name":"重建者","latin":"The Rebuilder","keywords":["创伤转化","意义炼金","厚度"],"verdict":"苦难在你这里不会白发生，你从中提取出了别人拿不到的东西。你要小心的是，不要把痛苦误认成成长的唯一路径。","weights":{"lv_suffering":1.4,"def_sublimate":1.3,"mot_purpose":1.1,"big5_rumination":0.7},"psych_tag":"高升华转化 × 低逃避倾向型"},{"id":"AR23","name":"静默引擎","latin":"The Quiet Engine","keywords":["低噪音","持续交付","不争名"],"verdict":"你不靠外放证明自己，只靠一次次真的做成。你需要练的只有一件事：在关键场合让自己被完整地听见。","weights":{"big5_assert":-1.1,"big5_industry":1.4,"virtue_diligence":1.1,"big5_social":-0.7},"psych_tag":"低表达 × 高勤勉的内驱型"},{"id":"AR24","name":"棋局野心家","latin":"The Ambitious Player","keywords":["向上驱动","结果导向","需要被看见"],"verdict":"你对更高位置有真实的渴望，也愿意为此付出代价。你需要区分清楚：你想要的到底是那件事，还是那件事带来的注视。","weights":{"mot_mastery":1.5,"dark_narc":1.1,"dark_psycho":0.9,"covert_control":0.8},"psych_tag":"高自尊 × 高成就渴求型"},{"id":"AR25","name":"危机制图师","latin":"The Crisis Cartographer","keywords":["高压下最清醒","预演最坏","替人兜底"],"verdict":"别人在压力里崩塌的时候，你的脑子反而第一次彻底安静下来。你不是喜欢危机，你只是在危机里才终于知道该做什么——这让你的日常显得有点松散，也让所有人在关键时刻第一个想到你。","weights":{"jung_te":1.2,"dd_order":1.1,"hsp_emotional":0.9,"enn_6":1},"negWeights":{"time_present_fate":-0.7},"psych_tag":"高压秩序 × 高情绪高敏型"},{"id":"AR26","name":"静默调停者","latin":"The Quiet Arbiter","keywords":["不站队","气氛优先","自己的立场最晚出现"],"verdict":"你能同时听懂两边在气什么，于是两边都愿意跟你讲。你的代价是：在一屋子人里，你永远是最后一个被问到'你自己想怎样'的人——有时候你自己也想不起来了。","weights":{"enn_9":1.3,"tki_accommodating":1.1,"pac_child":0.8,"jung_fe":1},"negWeights":{"big5_assert":-0.8},"psych_tag":"高避冲突 × 高外倾情感型"},{"id":"AR27","name":"量化守夜人","latin":"The Quantified Watchman","keywords":["记账即安心","风险先算","不轻易欠人情"],"verdict":"你把世界翻译成一张可以核对的表：余额、进度、还剩多少天。这不是贪，这是你唯一信得过的安慰剂。当数字健康时你几乎无所不能，当数字失控时你会整夜睡不着。","weights":{"money_vigilance":1.4,"mot_security":1.2,"time_future":1,"enn_6":0.9},"negWeights":{"time_present_hed":-0.7},"psych_tag":"高金钱警觉 × 未来秩序锚定型"},{"id":"AR28","name":"引擎型","latin":"The Engine","keywords":["耐受极高","越闹越清醒","恢复期全靠硬扛"],"verdict":"你几乎是靠肾上腺素运行的：陌生、嘈杂、高压的场景不会让你退，只会把你调到一个更快的档位。你唯一需要警惕的不是崩溃，而是你太擅长在崩溃前把事做完。","weights":{"hss_intensity":1.3,"hss_novelty":1.2,"pac_child":0.8,"sin_gluttony":0.8},"negWeights":{"hsp_sensory":-0.9},"psych_tag":"高刺激耐受 × 高新奇寻求型"},{"id":"AR29","name":"深海接收器","latin":"The Deep Receiver","keywords":["细节极清","需要安静","被说太敏感"],"verdict":"你能接收到别人根本不知道存在的信号：一句语气里的偏移、房间里灯光的色温。这让你判断极准，也让你在普通的一天里就被消耗掉别人一周的量。","weights":{"hsp_sensory":1.4,"hsp_emotional":1.2,"big5_aesthetic":0.9,"def_detach":0.7},"negWeights":{"hss_novelty":-0.6},"psych_tag":"高感官高敏 × 高情绪高敏型"},{"id":"AR30","name":"旧图守持者","latin":"The Map Keeper","keywords":["经验即锚","很少重复犯错","环境一变就慢半拍"],"verdict":"你记得住所有先例：上次那件事是怎么成的、哪句话在哪个场合说错过。这套庞大的经验库让你稳，也让你在一个规则全换掉的地方显得过分谨慎。","weights":{"jung_si":1.4,"enn_6":1.1,"money_vigilance":0.8,"big5_order":0.9},"negWeights":{"jung_ne":-0.7},"psych_tag":"高经验内倾 × 高忠诚恐惧型"},{"id":"AR31","name":"自撰者","latin":"The Self-Author","keywords":["自己定义意义","讨厌被安排","没有下班时间"],"verdict":"任何别人递过来的活法，你都会先拆开看看是不是真的适合自己。这让你活得比多数人自由，也让你必须不停地为自己的选择重新找理由——包括已经做过一百次的选择。","weights":{"phil_existential":1.4,"mot_autonomy":1.2,"enn_4":1,"mft_liberty":0.9},"negWeights":{"dd_order":-0.6},"psych_tag":"高存在主义 × 高自主反对安排型"},{"id":"AR32","name":"无证圣徒","latin":"The Unlicensed Saint","keywords":["不信流程","私下守得很严","自己扛"],"verdict":"你不太相信制度会替你办好一件事，但你对自己的要求比任何制度都严。于是你常常在一堆人分工不清的烂摊子里，独自承担了那个没人认领的责任。","weights":{"val_moral":1.3,"light_kant":1.1,"tki_competing":0.7},"negWeights":{"dark_mach":-1},"psych_tag":"低制度信任 × 高道德严格型"},{"id":"AR33","name":"转译者","latin":"The Translator","keywords":["先降噪","只谈事实","不喜欢情绪推拉"],"verdict":"一屋子人在互相指责的时候，你已经把问题拆成了三件可执行的事。你救了很多人，也常常被误解成冷漠——因为你给出的从来不是安慰，是出口。","weights":{"pac_adult":1.4,"tki_collaborating":1.2,"jung_te":0.9,"cog_logic":0.9},"negWeights":{"pac_child":-0.7},"psych_tag":"高成人自我态 × 高协作冲突型"},{"id":"AR34","name":"不服管者","latin":"The Unruled","keywords":["反感被安排","反抗很快","把小事推成对立"],"verdict":"你对'有人替你决定'的敏感度远超常人，哪怕那条指令本身完全合理。你不是难搞，你只是必须先确认这件事是'我选的'，才愿意去做。","weights":{"mft_liberty":1.3,"mot_autonomy":1.3,"sin_wrath":0.8},"negWeights":{"big5_compliance":-1.1},"psych_tag":"高自由道德 × 高自主反对管控型"},{"id":"AR35","name":"高电压者","latin":"The Voltage Seeker","keywords":["安静即失重","情绪浓度要高","长期透支"],"verdict":"你需要很强的信号才能确定自己在线：激烈的对话、通宵的项目、让人心跳加速的决定。平静对你不是休息，是一种'我是不是不在了'的错觉。","weights":{"hss_intensity":1.3,"sin_gluttony":1,"time_present_hed":1,"mot_hedonism":0.9},"negWeights":{"virtue_temperance":-0.9},"psych_tag":"高强度寻求 × 高放纵代偿型"},{"id":"AR36","name":"预演室","latin":"The Rehearsal Room","keywords":["预演最坏","风险雷达永远开着","没事也紧绷"],"verdict":"任何一件悬而未决的事，在你脑内都已经被推到最坏的结果，并且演练过三套应对。这份能力真的救过你，代价是你几乎没有'事情还没发生'的那段时间。","weights":{"schema_negativity":1.3,"hsp_emotional":1,"big5_alert":1.1,"enn_6":0.9},"negWeights":{"phil_epicurean":-0.6},"psych_tag":"高灾难预期 × 高情绪高敏型"}]};

export const CROSS_RULES = [{"id":"CR_01","required_volumes":["vol2","vol3"],"conditions":[{"dim":"dark_mach","op":">=","val":62},{"dim":"big5_compliance","op":">=","val":62}],"title":"丝绒手套里的棋手","tag":"表里策略协同","insight":"外表极其温和体面，从不轻易得罪人；但内心对每一场人际博弈的利益脉络都门清。你是最高级的温和策略家——用善意做盾，用智谋破局，很多局面在你手里是被无声推动的。","advice":"警惕长期维持温和表象带来的隐性情绪积压。在真正信赖的人面前，允许自己偶尔露出锋芒，否则你会发现自己被所有人喜欢，却没人真的认识你。"},{"id":"CR_02","required_volumes":["vol1","vol7"],"conditions":[{"dim":"sin_pride","op":">=","val":62},{"dim":"att_anxiety","op":">=","val":62}],"title":"敏感的孤傲刺猬","tag":"自尊与渴望的拉扯","insight":"理性上觉得大多数人都配不上你的标准，情感上却极度渴望被某个人毫无保留地偏爱和看见。嘴硬心软是你最高频的内耗源——你会用推开的方式测试对方会不会留下。","advice":"把测试的次数减半，把直接说出口的次数加倍。真正愿意留下的人，不需要被推开那么多次来证明。"},{"id":"CR_03","required_volumes":["vol1","vol5"],"conditions":[{"dim":"sin_sloth","op":">=","val":58},{"dim":"cog_global","op":">=","val":62}],"title":"高维度的优雅偷懒者","tag":"拒绝低水平重复","insight":"你并不是能力不足，而是对低价值重复劳动存在生理级排斥。一旦碰到真正点燃好奇心的难题，你能爆发出远超常人的创造力与巧劲。你的问题从来不是懒，而是没有被值得的事点燃。","advice":"与其逼自己变勤快，不如把手上那件枯燥的事重新设计一次：找出真正决定结果的 20%，其余尽量简省或交出去。"},{"id":"CR_04","required_volumes":["vol1","vol4"],"conditions":[{"dim":"sin_wrath","op":">=","val":58},{"dim":"val_moral","op":">=","val":60}],"title":"带刺的理想主义守门人","tag":"愤怒的纯度高","insight":"你的怒火极少源于私人小便宜，几乎全部被「双标、虚伪、恃强凌弱」瞬间点燃。你骨子里住着一位不肯向犬儒低头的古典侠客，你的攻击性其实是你的道德感在发烫。","advice":"你的愤怒是对的，但表达方式会决定它被听见还是被误解。把「你怎么能这样」换成「这件事违反了哪条规则」，你的力量会翻倍。"},{"id":"CR_05","required_volumes":["vol2"],"conditions":[{"dim":"big5_industry","op":">=","val":65},{"dim":"big5_rumination","op":">=","val":60}],"title":"永不停歇的精密发条","tag":"可靠的代价","insight":"靠谱到让所有人放心，代价是自己长期绷紧神经。你总在提前预演所有可能出错的细节，连休息时都在隐隐觉得「是不是漏了什么」。","advice":"给自己设一个「无法被推翻的休息时段」，并把它写进日程。你的崩溃不会来自外部压力，只会来自从不承认自己累。"},{"id":"CR_06","required_volumes":["vol4","vol6"],"conditions":[{"dim":"mot_autonomy","op":">=","val":68},{"dim":"mot_security","op":">=","val":60}],"title":"带降落伞的旷野旅人","tag":"自由与退路并存","insight":"你极度渴望不被定义、随时说走就走，但绝不做毫无退路的裸奔冒险。你会默默攒足底牌和存款，只为买断自己人生的选择权。真正的自由对你来说是「随时可以走」，而不是「已经走了」。","advice":"你的策略是对的，只是要留意别把「准备」变成新的牢笼。给「出发」设一个具体日期，而不是一个条件。"},{"id":"CR_07","required_volumes":["vol7"],"conditions":[{"dim":"def_intellectual","op":">=","val":62},{"dim":"def_detach","op":">=","val":58}],"title":"玻璃罩里的观察者","tag":"情绪的双重隔离","insight":"在绝大多数场合你都是最冷静体面的成年人，情绪从不失控。但越是滴水不漏的外壳，越说明你把真实的委屈锁进了极深的地下室——你甚至已经习惯到不觉得它在那里。","advice":"每周留一次「不加分析」的时间：只说发生了什么、我感觉到什么，不允许自己解释原因。感受需要被经过，不是被理解。"},{"id":"CR_08","required_volumes":["vol1","vol7"],"conditions":[{"dim":"sin_gluttony","op":">=","val":58},{"dim":"def_fawn","op":">=","val":58}],"title":"白昼乖巧、深夜失控的补偿者","tag":"控制权的夜间回收","insight":"白天在职场和关系里过度顺从、压抑真实诉求，到了深夜独处时，大脑就会通过报复性熬夜、美食或消费，疯狂抢回对身体的控制权。那不是意志力问题，而是白天让出去的主权在夜里索要利息。","advice":"别先改夜里的手，先改白天的嘴。每天多说一次「这个我不太想」，夜里的失控会自动减轻。"},{"id":"CR_09","required_volumes":["vol1","vol4"],"conditions":[{"dim":"sin_greed","op":">=","val":60},{"dim":"lv_happiness","op":"<=","val":45}],"title":"清醒的享乐务实家","tag":"用资源赎回时间","insight":"你毫不羞于谈论搞钱与资源积累，但你的终极目的绝非当守财奴——你要用充沛的物质底盘，把时间与审美自由赎回来尽情体验人间。你赚钱是为了不必再为钱做选择。","advice":"每隔一段时间问自己：我现在攒的这个数字，对应的是哪一种自由？如果答不上来，那个数字就只是焦虑的形状。"},{"id":"CR_10","required_volumes":["vol3"],"conditions":[{"dim":"dark_psycho","op":">=","val":60},{"dim":"light_humanism","op":">=","val":62}],"title":"外冷内热的现实手术刀","tag":"果断与善意的共存","insight":"你做决定极度干脆冷峻，甚至显得不近人情。但你内心其实深切关怀人的尊严——你相信「长痛不如短痛」，用果断止损保护更大的善意。被你切掉的人常常很久以后才明白你在保护什么。","advice":"决定可以冷，说明必须热。在你拍板之后，花三分钟告诉那个人你为什么这么做——不然你的善意永远只有你自己知道。"},{"id":"CR_11","required_volumes":["vol1","vol6"],"conditions":[{"dim":"sin_envy","op":">=","val":58},{"dim":"mot_mastery","op":">=","val":65}],"title":"以酸涩为燃料的攀登者","tag":"比较能量的正向转化","insight":"每次看到同龄人跃迁时泛起的不甘，其实是你内在潜能发出的警报——它在告诉你「那个东西你也想要」。只要把视线从对方身上拉回自己的行动清单，这股能量会让你进步神速。","advice":"给「酸」设一个转化动作：泛酸的当天，必须为那个渴望做一件具体的小事。情绪不转化就会变成内耗。"},{"id":"CR_12","required_volumes":["vol6","vol7"],"conditions":[{"dim":"att_avoidance","op":">=","val":62},{"dim":"mot_belonging","op":">=","val":58}],"title":"站在门廊上的深情观望者","tag":"渴望与恐惧并存","insight":"你内心无比珍视灵魂共振的深厚关系，却又极度畏惧被束缚与受伤。你理想中的爱人不是时刻黏连的藤蔓，而是各具风骨、却始终为你留一盏灯的同行者。你站在门口，是因为门里太重要。","advice":"在想退的那一刻，先说出那句「我需要一点空间，不是不要你」。很多关系的断裂不是因为距离，而是因为距离没有被解释。"},{"id":"CR_13","required_volumes":["vol3","vol4"],"conditions":[{"dim":"dark_mach","op":">=","val":60},{"dim":"wv_social","op":"<=","val":45}],"title":"规则之外的现实主义者","tag":"灰度操作者","insight":"你不相信纸面规则能解决问题，更相信真实的人性与利益结构。你能在别人还在讲道理的时候，直接找到那个真正能推动事情的支点。这是一种很硬的能力，也是一种很重的责任。","advice":"把自己当成那个「有能力绕过规则的人」时，务必同时成为那个「最不愿意滥用它的人」。否则你最终会失去所有愿意相信你的人。"},{"id":"CR_14","required_volumes":["vol2","vol5"],"conditions":[{"dim":"big5_open","op":">=","val":65},{"dim":"cog_diverge","op":">=","val":60}],"title":"可能性成瘾者","tag":"广度过剩的代价","insight":"你被新的可能持续吸引，脑子里同时在跑五个项目，每一个都足够精彩。你的问题从来不是没有想法，而是没有一个想法被完整地做到能被别人看见。","advice":"给自己立一条铁律：任何时刻只允许三个进行中的项目。想开第四个，必须先关掉一个。"},{"id":"CR_15","required_volumes":["vol4","vol6"],"conditions":[{"dim":"lv_anchor","op":"<=","val":45},{"dim":"mot_security","op":">=","val":62}],"title":"向外建构的稳固者","tag":"以成就换安全感","insight":"你的安全感建立在外部的稳定结构上：位置、收入、被认可的身份。这让你非常可靠，也让你在结构动摇时，动摇的不只是生活，而是整个自我。","advice":"在外部成就之外，建立一处完全不需要任何人评价的价值来源。它不必宏大，但必须是你的。"},{"id":"CR_16","required_volumes":["vol7"],"conditions":[{"dim":"att_anxiety","op":">=","val":62},{"dim":"def_attack","op":">=","val":58}],"title":"用愤怒索要靠近的人","tag":"攻击性下的依恋","insight":"你的怒火很多时候不是真的在生气，而是在说「你为什么不看我」。攻击是你最快能引起对方反应的方式，也是最容易把对方推远的方式。","advice":"在发火之前，试着说出下面这句更难的话：「我现在有点怕你不理我。」它比任何一句指责都更有力量。"},{"id":"CR_17","required_volumes":["vol3","vol7"],"conditions":[{"dim":"light_faith","op":"<=","val":42},{"dim":"def_project","op":">=","val":58}],"title":"先假定恶意的防御者","tag":"投射回路","insight":"你习惯先假设别人有意图，因此在无害的场合也保持戒备。这套系统确实保护过你，但它也在持续筛掉那些本来真的没有恶意的人。","advice":"当判断「他在针对我」时，加一个动作：把这件事讲给一个旁观者听。第三方视角能校正大部分投射。"},{"id":"CR_18","required_volumes":["vol1","vol2"],"conditions":[{"dim":"virtue_kindness","op":">=","val":62},{"dim":"big5_compliance","op":">=","val":60}],"title":"把世界让给别人的好人","tag":"善意与失语的合流","insight":"你能真心为别人鼓掌，也习惯把自己的位置往后挪。这两件事叠加，会让你在很多场合成为那个「很好，但没人记得」的人。","advice":"欣赏别人和主张自己并不冲突。练习在你夸完别人之后，补一句关于你自己的。世界不会因为你要位置就讨厌你。"},{"id":"CR_19","required_volumes":["vol5","vol7"],"conditions":[{"dim":"cog_logic","op":">=","val":62},{"dim":"def_intellectual","op":">=","val":60}],"title":"把心装进分析框架的人","tag":"理解的替代","insight":"你处理情绪的方式是理解它。这套系统让你在很多场合极其稳，但也让你的痛被处理得太干净——干净到你根本不知道自己其实一直在痛。","advice":"在解释之前，先允许自己什么都不懂地难受十分钟。理解是后来的事，感受必须先发生。"},{"id":"CR_20","required_volumes":["vol6","vol2"],"conditions":[{"dim":"mot_hedonism","op":">=","val":65},{"dim":"big5_industry","op":"<=","val":45}],"title":"把日子过成假期的人","tag":"体验优先的代价","insight":"你的感受力极高，能把普通的日子过得有滋味，这是很多人努力半生也换不回来的。但那些不好玩却重要的事，正在你的清单上静静堆积。","advice":"每周固定一天处理「不好玩但重要」的事，其余六天尽情活得有滋味。两件事不冲突，只是需要被分开安排。"},{"id":"CR_21","required_volumes":["vol1","vol3"],"conditions":[{"dim":"virtue_patience","op":">=","val":62},{"dim":"covert_control","op":">=","val":58}],"title":"不动声色的温和操盘手","tag":"以柔代刚","insight":"你很少发火，也很少真的放手。你用耐心和分寸把局面引向你要的方向，别人甚至感觉不到被推动。这是极高段位的软实力，也是一种别人说不清为什么的疲惫感来源。","advice":"每周至少有一次，把「安排」换成「直接说我要什么」。坦白比技巧更省力，也更让人愿意长期待在你身边。"},{"id":"CR_22","required_volumes":["vol2","vol7"],"conditions":[{"dim":"big5_alert","op":">=","val":62},{"dim":"att_avoidance","op":">=","val":58}],"title":"提前离场的人","tag":"风险预演与抽离","insight":"你会在关系里提前看到所有可能出问题的地方，于是先一步抽身。你把它叫做理性，但很多时候，那是害怕在同一个人身上再输一次。","advice":"在决定离开之前，把「可能发生的坏事」写下来，并标注概率。你会发现大部分恐惧，只存在于你的预演里。"},{"id":"CR_23","required_volumes":["vol4","vol7"],"conditions":[{"dim":"val_boundary","op":">=","val":62},{"dim":"att_avoidance","op":">=","val":60}],"title":"以自由为名的守门人","tag":"独立的双重动机","insight":"你说是为了自由，其实有一半是为了安全。真正的独立是「我可以选择依靠」，而你的版本更像「我不能依靠任何人」——前者是力量，后者是伤口。","advice":"对一个人主动求助一次，只一件小事。你会发现依赖不会让你失去自己，只会让你多一个支点。"},{"id":"CR_24","required_volumes":["vol1","vol6"],"conditions":[{"dim":"sin_pride","op":">=","val":60},{"dim":"mot_mastery","op":">=","val":62}],"title":"不允许自己平庸的人","tag":"高标准驱动","insight":"你对自己的要求远高于对别人的，因此你的成就往往很好，你的疲惫也往往很深。你最大的敌人不是竞争者，是那个永远觉得「还不够」的自己。","advice":"每完成一件事，强制停留三天再开始下一件。你需要练习「已经够了」的感觉，否则抵达永远不会带来满足。"},{"id":"CR_25","required_volumes":["vol5","vol2"],"conditions":[{"dim":"cog_speed","op":">=","val":62},{"dim":"big5_order","op":"<=","val":45}],"title":"先跑起来再修路的人","tag":"迭代优先","insight":"你不等条件齐备就出发，因此比别人更早拿到真实的反馈。代价是，你留下的一些尾巴，需要别人替你收拾。","advice":"把手上的决定分成可逆与不可逆两类。可逆的尽管快，不可逆的必须先慢下来——这是唯一需要你破例的地方。"},{"id":"CR_26","required_volumes":["vol4","vol3"],"conditions":[{"dim":"wv_nature","op":">=","val":62},{"dim":"light_faith","op":">=","val":62}],"title":"愿意先给出信任的人","tag":"善意的复利与风险","insight":"你默认人是善的，因此别人在你这里不必先证明自己。这种低成本建立关系的能力极其稀有，代价是你在真正的恶意面前反应偏慢。","advice":"保留先给信任的习惯，但给自己加一条规则：同一个人透支两次之后，把信任降级为观察。善意不必是一次性的。"},{"id":"CR_27","required_volumes":["vol6","vol1"],"conditions":[{"dim":"mot_purpose","op":">=","val":62},{"dim":"virtue_charity","op":">=","val":58}],"title":"把意义放在别人身上的人","tag":"利他的双刃","insight":"你的意义感来自「我所做的事对别人有用」。这让你非常有温度，也让你在没人需要你的时候，突然不知道自己是谁。","advice":"建立一件只对你自己有意义的事。它不该被任何人需要，也不该被任何人评价。"},{"id":"CR_28","required_volumes":["vol3","vol5"],"conditions":[{"dim":"covert_control","op":">=","val":62},{"dim":"cog_global","op":">=","val":60}],"title":"在结构层面下棋的人","tag":"系统级影响力","insight":"你不太争一时的对错，你改的是规则本身。你能看到一件事背后的结构，然后悄悄把那个结构挪到你希望的方向。这种能力很少被看见，却决定了大部分结果。","advice":"结构性的影响力需要透明来托底。让别人知道你在改什么，否则你会在某天发现所有人都在防着你。"},{"id":"CR_29","required_volumes":["vol7","vol1"],"conditions":[{"dim":"def_sublimate","op":">=","val":60},{"dim":"sin_sloth","op":"<=","val":42}],"title":"把痛烧成燃料的人","tag":"创伤的升华","insight":"你的难过几乎不会白费，它会变成作品、手艺或身体的力量。这是一种被很多人羡慕的能力，但它也可能让你在关系里始终缺席——因为你总是在处理，而不是在经历。","advice":"定期确认一件事：除了产出，你还有没有别的方式处理难过。人需要被接住，不是只需要被转化。"},{"id":"CR_30","required_volumes":["vol2","vol6"],"conditions":[{"dim":"big5_social","op":"<=","val":42},{"dim":"mot_belonging","op":">=","val":58}],"title":"要很少的人，要得很深","tag":"低数量高浓度","insight":"你不需要很多朋友，但你需要有几个人是真的懂你。你的人际圈很小，密度却极高——一旦有人被你放进内圈，你会给出远超平均的忠诚。","advice":"主动维护那几个人。高浓度的关系最怕的不是冲突，而是长期没人先开口。"},{"id":"CR_31","required_volumes":["vol8"],"conditions":[{"dim":"mask","op":">=","val":60}],"title":"精密防卫层的建造者","tag":"面具厚度校准","insight":"你在高压下与常态下的选择出现了明显落差。这不一定意味着你在骗人——更可能意味着你早已学会：真实的那一面，只在极少数人面前才安全地拿出来。","advice":"面具本身不是问题，只有一副面具才是问题。为自己找一个可以摘下来的房间，哪怕只有一个人在里面。"},{"id":"CR_32","required_volumes":["vol8","vol7"],"conditions":[{"dim":"mask","op":">=","val":55},{"dim":"def_intellectual","op":">=","val":58}],"title":"连崩溃都要体面的人","tag":"高压下的自我管理","insight":"你连在最难受的时候，都还在管理自己的形象。外人看到的是稳定，你自己知道那是一场持续的、从不被看见的维持工作。","advice":"找一个人，允许自己在他面前不体面一次。你会发现天没有塌，而那个人反而更靠近你了。"},{"id":"CR_33","required_volumes":["vol4","vol5"],"conditions":[{"dim":"cog_independent","op":">=","val":62},{"dim":"wv_social","op":">=","val":58}],"title":"讲原则的异见者","tag":"双重少数","insight":"你既坚持规则，又不肯随大流。这让你在大多数群体里都显得有点不好相处，也让你成为那种在关键时刻唯一说真话的人。","advice":"你的价值需要被理解才能生效。把「我不同意」升级为「我不同意，因为这样会伤到谁」——同样的立场，接受度完全不同。"},{"id":"CR_34","required_volumes":["vol2","vol7"],"conditions":[{"dim":"big5_compassion","op":">=","val":62},{"dim":"def_fawn","op":">=","val":58}],"title":"天生的情绪承接地","tag":"共情与讨好的重叠","insight":"你能第一时间感觉到别人的难受，并且下意识地去安抚。这两件事叠在一起，会让你长期成为所有人的情绪出口，而没有人问过你今天怎么样。","advice":"共情不等于负责。练习在心里加一句「这是他的，不是我的」，然后只做你能做的那一部分。"},{"id":"CR_35","required_volumes":["vol3","vol1"],"conditions":[{"dim":"dark_narc","op":">=","val":60},{"dim":"sin_envy","op":">=","val":55}],"title":"需要被看见的竞争者","tag":"光环与比较","insight":"你既需要站在中心，又对别人的高光格外敏感。这两件事同时运转时，你会活得很累——因为总有人在某个地方比你更亮。","advice":"把「他凭什么」换成「我要什么」。前者永远有答案，后者才是你能改变的部分。"},{"id":"CR_36","required_volumes":["vol9","vol2"],"conditions":[{"dim":"jung_ni","op":">=","val":60},{"dim":"jung_ne","op":">=","val":58}],"title":"两条直觉并线跑的人","tag":"功能栈内部冲突","insight":"Ni 与 Ne 同时偏高是罕见配置：你既会被一个'终将收束成一条主线'的预感驱动，又忍不住同时向五个方向发散。你脑子里常常同时存在一个长远隐喻和七八条支线，它们互不承认对方。","advice":"给每一次直觉冲动贴一个标签：这是'收束型'还是'发散型'。发散型只允许记录，不许立刻行动；收束型才配得上你的执行力。"},{"id":"CR_37","required_volumes":["vol9","vol5"],"conditions":[{"dim":"jung_ti","op":">=","val":60},{"dim":"cog_ambiguity","op":">=","val":62}],"title":"要求逻辑闭环的模糊耐受者","tag":"认知风格张力","insight":"你能忍受大量未确定的信息，却无法接受其中出现一个没拧紧的螺丝。这让你成为很好的探索者，同时很难成为让人放松的合作者——你能一边说'先别急着定',一边在心里给每句话打分。","advice":"把'这里逻辑不通'延后 24 小时再说。你会发现大部分漏洞在你重新看的时候已经自己闭合了。"},{"id":"CR_38","required_volumes":["vol10","vol3"],"conditions":[{"dim":"dd_order","op":">=","val":58},{"dim":"dark_mach","op":">=","val":60}],"title":"把规则当杠杆的人","tag":"秩序 × 策略","insight":"你尊重规则，但你更清楚规则的确切边界在哪里——因为你要在边界内侧把事办成。这种组合在组织里极其有效，也极其容易让人在你背后议论'他太会了'。","advice":"每季度主动放弃一次'技术上完全站得住'的便利。信任的账户需要定期存入，而不是只取不存。"},{"id":"CR_39","required_volumes":["vol10","vol4"],"conditions":[{"dim":"dd_order","op":"<=","val":45},{"dim":"val_moral","op":">=","val":60}],"title":"不信任制度的好人","tag":"混沌 × 原则","insight":"你对机构与流程高度怀疑，却在私人道德上极其严格。你宁愿自己扛下麻烦，也不愿把判断权交给一个你不认识的体系——这在很多时刻是对的，也让你长期处于'没人替我兜底'的疲惫里。","advice":"挑一件风险极低的小事，完整地交给流程走完。不是为了相信制度，是为了让身体知道：不是每件事都必须你亲自盯着。"},{"id":"CR_40","required_volumes":["vol11","vol13"],"conditions":[{"dim":"phil_stoic","op":">=","val":60},{"dim":"schema_deprivation","op":">=","val":58}],"title":"用哲学缝合早年缺口的人","tag":"意义 × 图式","insight":"你有一套非常成熟的自我解释系统：不可控的事不归我管，我只负责自己的姿态。但在这套系统底层，有一处'我的情感需求本来就不该被满足'的旧设定，它让克制看起来像美德。","advice":"练习一次不体面的需要：明确告诉某个人'我今天想被陪一下'。不带理由，不带交换条件。"},{"id":"CR_41","required_volumes":["vol11","vol15"],"conditions":[{"dim":"phil_cynic","op":">=","val":58},{"dim":"tki_avoiding","op":">=","val":58}],"title":"看透了所以懒得吵","tag":"犬儒 × 回避","insight":"你的沉默不是软弱，而是一种判断：这场对话不会有结果，说下去只是消耗。问题在于，对方接收到的信号永远是'他不在乎'，于是误会一层层加厚。","advice":"把'懒得说'换成一句极短的实话：'这件事我有不同看法，今天不想展开。'让沉默有主语。"},{"id":"CR_42","required_volumes":["vol12","vol7"],"conditions":[{"dim":"enn_4","op":">=","val":58},{"dim":"att_anxiety","op":">=","val":58}],"title":"要独特，又要被确认","tag":"九型 × 依恋","insight":"你希望自己是不可替代的那一个，同时又需要有人反复确认你没有被替换掉。这两个需求会互相拆台：越想独特，越难开口要确认；越缺确认，越把独特演成一种防御。","advice":"把'他是不是觉得我谁都可以'翻译成'我需要一次具体的、被选中的证据'。要证据，不要情绪。"},{"id":"CR_43","required_volumes":["vol12","vol2"],"conditions":[{"dim":"enn_5","op":">=","val":58},{"dim":"big5_social","op":"<=","val":45}],"title":"靠撤退充电的观察者","tag":"九型 × 大五","insight":"你的能量来自观察而不是参与。人多时你不是不喜欢那些人，只是每一句对话都在消耗你的处理带宽。你不讨厌热闹，你只是需要一个不必回应的位置。","advice":"把'我需要先走一下'提前说出来，而不是等到电量耗尽才消失。提前告知比事后解释便宜得多。"},{"id":"CR_44","required_volumes":["vol13","vol12"],"conditions":[{"dim":"schema_sacrifice","op":">=","val":58},{"dim":"enn_2","op":">=","val":58}],"title":"先把自己给出去的人","tag":"图式 × 九型","insight":"你习惯在别人开口之前就替他想到，并且把这当成一种能力而不是负担。长期下来，你会发现自己的人际关系里有一种奇怪的失衡：你给了很多，却很少真正被照顾。","advice":"下次想主动帮忙前，先等对方开口一次。允许自己成为那个'没被请求就不出手'的人。"},{"id":"CR_45","required_volumes":["vol14","vol6"],"conditions":[{"dim":"money_vigilance","op":">=","val":60},{"dim":"mot_security","op":">=","val":62}],"title":"把安全感存成数字的人","tag":"金钱脚本 × 动机","insight":"数字对你不是欲望的度量，而是风险的度量。你存下的不是钱，是一种'万一出事我还有退路'的确定感。代价是：你可能永远觉得不够，因为风险永远算不完。","advice":"给储蓄设一个明确的'够了'阈值，写下来。达到以后，把增量专门花在让自己开心的东西上。"},{"id":"CR_46","required_volumes":["vol14","vol4"],"conditions":[{"dim":"time_present_hed","op":">=","val":60},{"dim":"lv_happiness","op":">=","val":58}],"title":"把钱换成当下的体验派","tag":"时间观 × 人生观","insight":"你更愿意把资源换成此刻的鲜活，而不是账户里一个更大的数字。这不是短视——你只是很早就发现，很多体验过期不再补发。需要留意的是那些真正有复利的东西，它们恰好都不够刺激。","advice":"每月固定一笔'无聊但会复利'的投入（体检、学习、关系维护），金额可以很小，但要自动扣款。"},{"id":"CR_47","required_volumes":["vol15","vol3"],"conditions":[{"dim":"pac_adult","op":">=","val":58},{"dim":"covert_control","op":">=","val":58}],"title":"用理性完成掌控的人","tag":"PAC × 隐性掌控","insight":"冲突里你几乎不提高音量，你只把事实摆到对方无法反驳的位置。这种方式极有效，也极容易让人感到'被处理了'——因为他们确实是被处理了。","advice":"在把事实摆完以后，多问一句'你怎么看'。给对方一个真实的输入口，而不是一个形式上的。"},{"id":"CR_48","required_volumes":["vol15","vol1"],"conditions":[{"dim":"pac_child","op":">=","val":58},{"dim":"sin_wrath","op":">=","val":58}],"title":"一生气就变回小孩","tag":"PAC × 情绪","insight":"你的愤怒来得快、去得也快，但说出口的话往往留下了不可回收的痕迹。那不是你真实的立场，那是一个被踩到的人在用最原始的方式喊停。","advice":"把'你根本…'换成'我现在很生气，需要十分钟'。把情绪命名出来，比把情绪扔出去有效。"},{"id":"CR_49","required_volumes":["vol16","vol2"],"conditions":[{"dim":"hsp_sensory","op":">=","val":58},{"dim":"big5_social","op":">=","val":58}],"title":"在人群里最敏锐，也最耗电","tag":"神经边缘 × 大五","insight":"你在社交里表现得很自如，甚至比多数人更会读空气——因为你的接收器一直开在最灵敏档。代价是散场后需要一整段无人打扰的时间，才能把自己收回来。","advice":"把'散场后的独处时间'写进日程，像会议一样不可挪用。提前安排，比临时崩溃便宜。"},{"id":"CR_50","required_volumes":["vol16","vol6"],"conditions":[{"dim":"hss_novelty","op":">=","val":58},{"dim":"hsp_sensory","op":">=","val":58}],"title":"既想冲又怕吵的矛盾体","tag":"HSP × HSS","insight":"你的神经系统同时对'新鲜'和'过载'敏感：未知让你兴奋，噪音让你崩溃。所以你最容易在热闹现场的电量断崖式归零，然后在黑暗的房间里躺两天。","advice":"给任何高强度体验预留'恢复日'。不是事后补救，是出发前就写进计划。"},{"id":"CR_51","required_volumes":["vol13","vol1"],"conditions":[{"dim":"schema_approval","op":">=","val":58},{"dim":"virtue_kindness","op":">=","val":60}],"title":"用好人身份换安全的人","tag":"图式 × 美德","insight":"你的体贴是真的，但其中有一部分来自一个旧设定：只要我是好人，就不会被丢下。这让你的善意带上了隐隐的紧绷——你其实一直在等一句'你很好'。","advice":"做一件不被任何人知道的好事，并且不给它任何解释。练习一次不领报酬的善。"},{"id":"CR_52","required_volumes":["vol11","vol1"],"conditions":[{"dim":"mft_liberty","op":">=","val":60},{"dim":"sin_wrath","op":">=","val":55}],"title":"被管着就浑身难受的人","tag":"道德基础 × 情绪","insight":"你对'被别人替你决定'有近乎生理性的反感。这种反感让你反抗得很快，也让你在很多时候把一个本可以协商的小事直接推到对立面。","advice":"在发火前先试着提一次反建议。不是为了赢，是为了让对抗变成谈判。"},{"id":"CR_53","required_volumes":["vol9","vol7"],"conditions":[{"dim":"jung_fe","op":">=","val":58},{"dim":"def_fawn","op":">=","val":58}],"title":"把气氛当成自己的责任","tag":"Fe × 防御","insight":"你一进门就能读出房间的温度，并且会自动开始调温。这套能力让你在哪儿都被喜欢，也让你把'别人不舒服'默认记在自己账上。","advice":"在一次聚会里刻意不调温：允许场面尴尬三分钟，什么都不做，看会发生什么。"},{"id":"CR_54","required_volumes":["vol9","vol3"],"conditions":[{"dim":"jung_te","op":">=","val":58},{"dim":"dark_psycho","op":">=","val":58}],"title":"只看结果的执行者","tag":"Te × 黑暗三角","insight":"你判断一件事的标准极其干净：它有没有成。这套标准让你效率惊人，也让你在需要照顾情绪的时刻显得格外冷——不是你不懂，是你觉得那不是重点。","advice":"在每一次给出结论前，加一句'我知道这对你来说不容易'。不改变结论，只改变它被接收的方式。"},{"id":"CR_55","required_volumes":["vol10","vol16"],"conditions":[{"dim":"dd_order","op":">=","val":58},{"dim":"hsp_sensory","op":">=","val":58}],"title":"需要确定性的高敏者","tag":"秩序 × 神经边缘","insight":"你的秩序需求有一半来自神经系统：不可预测的环境对你是真实的生理消耗，而不只是心理不适。所以你提前规划，常常不是控制欲，是自我保护。","advice":"把'计划'与'必须'分开。保留一件完全不确定的小事在日程里，练一次不被变化整垮。"},{"id":"CR_56","required_volumes":["vol12","vol15"],"conditions":[{"dim":"enn_9","op":">=","val":58},{"dim":"tki_accommodating","op":">=","val":58}],"title":"用让步换取平静的人","tag":"九型 × 冲突","insight":"你退让的速度快到别人来不及察觉，连你自己也常以为'我本来就无所谓'。但那些没有说出口的立场不会消失，它们会变成一种长期的低烧式疲惫。","advice":"每周挑一件小事，明确说出'我更想这样'。从不需要辩论的小事开始练。"},{"id":"CR_57","required_volumes":["vol14","vol13"],"conditions":[{"dim":"money_avoid","op":">=","val":58},{"dim":"schema_defect","op":">=","val":55}],"title":"不敢谈钱的人","tag":"金钱脚本 × 图式","insight":"你不查账、不谈价、不问欠款，因为一旦把数字摆到桌面上，你就得面对'我是不是不值得这么多'的旧问题。回避钱，其实是在回避那个问题。","advice":"做一件极小的、与钱有关的正面动作：查一次账单、问一次报价。让数字回到数字。"},{"id":"CR_58","required_volumes":["vol16","vol1"],"conditions":[{"dim":"hss_intensity","op":">=","val":58},{"dim":"sin_gluttony","op":">=","val":55}],"title":"靠高强度确认自己还活着","tag":"刺激寻求 × 欲望","insight":"你需要强刺激才能感到'在线'：熬夜、极限运动、情绪浓烈的对话。安静对你不是休息，是失重。代价是身体长期在透支模式下运转。","advice":"给自己安排一次'低强度但有质感'的体验：一顿慢饭、一段长途步行。让身体重新认识平静。"},{"id":"CR_59","required_volumes":["vol11","vol12"],"conditions":[{"dim":"phil_existential","op":">=","val":58},{"dim":"enn_4","op":">=","val":58}],"title":"靠自我定义活着的人","tag":"哲学 × 九型","insight":"你不接受任何现成的人生剧本，也正因为如此，你必须不停地为自己造意义——这件事既是你最迷人的部分，也是最耗人的部分，因为它没有下班时间。","advice":"给自己留一块不需要被赋予意义的地方：一件纯粹消磨时间的事。允许自己无意义地待着。"},{"id":"CR_60","required_volumes":["vol10","vol11"],"conditions":[{"dim":"dd_order","op":">=","val":58},{"dim":"mft_sanctity","op":">=","val":58}],"title":"守着某种不可让渡的人","tag":"秩序 × 圣洁","insight":"你相信有些东西不该被交易、被讨论、被'务实处理'。这套底线让你在很多场合显得不合时宜，也让你在最难的时候仍然认得自己。","advice":"把这条底线明确写成一句话。写下来以后你会发现，真正需要它的时候并不多，但每次都很关键。"},{"id":"CR_61","required_volumes":["vol9","vol12"],"conditions":[{"dim":"jung_si","op":">=","val":58},{"dim":"enn_6","op":">=","val":58}],"title":"靠旧经验站稳的人","tag":"Si × 九型","insight":"你对'上次是怎么做的'有极强的记忆，并把它当作抵御不确定的锚。这让你很少犯同样的错，也让你在环境彻底换掉时适应得比别人慢。","advice":"每季度主动做一件'没有先例'的事。小到换一条通勤路线，大到换一种工作方式。"},{"id":"CR_62","required_volumes":["vol15","vol13"],"conditions":[{"dim":"tki_competing","op":">=","val":58},{"dim":"schema_mistrust","op":">=","val":55}],"title":"先假定要打，再决定要不要谈","tag":"冲突 × 图式","insight":"你在冲突开始前就已经进入备战状态：先想清楚对方的弱点，再决定要不要给台阶。这套反应来自一个旧结论——示弱会被利用。","advice":"在一次低风险的分歧里，先说出自己的真实需求，而不是先摆阵。看一次不设防会发生什么。"},{"id":"CR_63","required_volumes":["vol14","vol15"],"conditions":[{"dim":"money_worship","op":">=","val":58},{"dim":"pac_parent","op":">=","val":58}],"title":"用资源说话的人","tag":"金钱 × PAC","insight":"你习惯用'我能提供什么'来确立自己在关系里的位置，语气里常带着一种不自觉的居高。那不是傲慢，那是你唯一学会的、可靠的表达关心的方式。","advice":"试着用一次不花钱的方式表达在意：一句具体的关心，一次纯粹的陪伴。"},{"id":"CR_64","required_volumes":["vol13","vol16"],"conditions":[{"dim":"schema_negativity","op":">=","val":58},{"dim":"hsp_emotional","op":">=","val":58}],"title":"提前把最坏演一遍的人","tag":"图式 × 神经边缘","insight":"你的预演能力极强：任何一件事在你脑内都会先跑一遍最坏版本。这在真正出事时救过你，也让你在没事的时候照样紧绷。","advice":"给每一次预演加一个收尾动作：写下'如果真的发生，我第一步做什么'。有了第一步，脑子就肯停。"},{"id":"CR_65","required_volumes":["vol12","vol13","vol7"],"conditions":[{"dim":"enn_1","op":">=","val":58},{"dim":"schema_std","op":">=","val":58}],"title":"对自己最严的那位审查官","tag":"九型 × 图式","insight":"你对自己的标准高到连自己都很少达标。别人看到的自律，其实是一套随时在扣分的内部审查系统——它让你优秀，也让你几乎没有真正放松的时刻。","advice":"每天记录一件'做到 70 分就交出去'的事。练习一次不完美地完成。"}];

export const PAIR_RULES = {"coreDims":["wv_nature","wv_causal","wv_social","val_moral","val_boundary","val_standard","light_humanism","light_kant","light_faith","dark_mach","lv_happiness","lv_anchor","jung_ni","jung_fi","phil_stoic","phil_existential","mft_care","mft_fairness","money_vigilance","time_future","dd_order","dd_good"],"complementDims":["big5_open","big5_order","big5_social","big5_assert","big5_industry","big5_compassion","cog_global","cog_diverge","cog_logic","cog_ambiguity","cog_independent","cog_speed","jung_ne","jung_te","jung_fe","hsp_sensory","hss_novelty","tki_collaborating","pac_adult","schema_std"],"resonance":[{"id":"RS_01","dims":["wv_nature","light_faith"],"op":"bothHigh","threshold":60,"title":"同一种世界观底色","text":"你们都默认人是善的，都愿意先给出信任。这段关系最舒服的地方是：谁都不必先证明自己，防御成本极低。"},{"id":"RS_02","dims":["val_moral"],"op":"bothHigh","threshold":60,"title":"共享同一套底线","text":"你们对「什么不能做」有一致的答案。这意味着你们即使吵架，也不会在价值观层面互相否定。"},{"id":"RS_03","dims":["lv_suffering"],"op":"bothHigh","threshold":58,"title":"都能从难里取出东西","text":"你们都不把痛苦浪漫化，但都相信它值得被转化。因此你们在低谷期不会互相拖入抱怨，而会一起想办法。"},{"id":"RS_04","dims":["att_anxiety"],"op":"bothLow","threshold":45,"title":"谁都不需要反复确认","text":"你们在关系里都不焦虑，不需要对方持续证明在乎。这让你们能各自忙很久，见面时依然自然。"},{"id":"RS_05","dims":["def_detach"],"op":"bothHigh","threshold":58,"title":"冷静的双人组","text":"你们都能在情绪上来时先抽离，因此几乎不会互相情绪绑架。代价是，问题可能被同时搁置，很久都没有人真的去处理。"},{"id":"RS_06","dims":["mot_autonomy"],"op":"bothHigh","threshold":62,"title":"两座互不吞并的岛","text":"你们都需要自己的空间，也都尊重对方的。这段关系不会因为黏得太紧而窒息，只需要注意别在自由里慢慢走散。"},{"id":"RS_07","dims":["big5_order"],"op":"bothHigh","threshold":62,"title":"同步的秩序感","text":"你们对生活的处理方式接近：有计划、有预期、讨厌临时变卦。日常摩擦极少，但一起遇到突发时会同时烦躁。"},{"id":"RS_08","dims":["cog_speed"],"op":"bothHigh","threshold":60,"title":"两个都先做再说的人","text":"你们的决策节奏一致，都更愿意先做起来再修。好处是不会互相拖，风险是没人在关键时刻踩刹车。"},{"id":"RS_09","dims":["mot_belonging"],"op":"bothHigh","threshold":62,"title":"把彼此放进内圈","text":"你们都需要深度关系，并且都愿意为此投入。这段关系对双方来说都是少数的、真正重要的那一种。"},{"id":"RS_10","dims":["jung_ni","jung_ti"],"op":"bothHigh","threshold":58,"title":"同一个频道的两个人","text":"你们不需要把话说完就能对上。这种默契很罕见，也很容易被误认为'他本来就懂'，从而省掉所有必要的确认。"},{"id":"RS_11","dims":["phil_stoic"],"op":"bothHigh","threshold":58,"title":"两份不动声色的克制","text":"你们都倾向于把情绪自己消化掉。这段关系会非常安静、非常有分寸，也可能非常久地不去碰那些真正要紧的事。"},{"id":"RS_12","dims":["money_vigilance"],"op":"bothHigh","threshold":58,"title":"两本都记得很清楚的账","text":"你们都不会让对方在钱上吃亏，也都不太会开口要。这很体面，但体面攒久了会变成一间越来越小的房间。"},{"id":"RS_13","dims":["hsp_sensory"],"op":"bothHigh","threshold":56,"title":"两个都听得见电流声的人","text":"你们能一起享受别人觉得'没什么'的细节，也能一起被同一个环境弄垮。找到彼此是运气，但要小心一起过载。"},{"id":"RS_14","dims":["hss_novelty"],"op":"bothHigh","threshold":56,"title":"一起把计划表撕掉的人","text":"你们能随时启动一场临时的出走。这段关系永远不缺新鲜感，需要留意的是那些必须有人去做、但一点都不刺激的事。"},{"id":"RS_15","dims":["enn_9","tki_accommodating"],"op":"bothHigh","threshold":56,"title":"两个人一起把话咽下去","text":"你们都很擅长让步，于是冲突会消失得很快——消失，而不是解决。这会让关系异常平和，也会让真正的问题长期停在地下。"},{"id":"RS_16","dims":["jung_fe"],"op":"bothHigh","threshold":56,"title":"都负责给房间调温的人","text":"你们都会自动照顾场上的气氛。好处是几乎不会有尴尬，风险是没人负责说真话——因为说真话会让温度掉下来。"}],"collisions":[{"id":"SC_01","a":[{"dim":"att_anxiety","op":">=","val":62},{"dim":"sin_wrath","op":">=","val":55}],"b":[{"dim":"att_avoidance","op":">=","val":62},{"dim":"def_detach","op":">=","val":55}],"severity":"high","title":"追逃死循环","text":"一方越焦虑越靠近，另一方越靠近越想退。你们不是不爱，而是被同一个开关触发了两套完全相反的程序。","guide":"约定一个「暂停词」：任何一方说出它，双方同时停十五分钟，之后由提出暂停的一方在二十四小时内主动重启对话。不要让沉默替你们做决定。"},{"id":"SC_02","a":[{"dim":"def_attack","op":">=","val":60},{"dim":"sin_wrath","op":">=","val":55}],"b":[{"dim":"def_attack","op":">=","val":60}],"severity":"high","title":"双刃对撞","text":"两个人的第一反应都是还手，于是每一次小摩擦都会迅速升级成互相伤害。真正的问题不是谁对，而是没人先停下来。","guide":"吵架时强制使用「事实、感受、请求」三段式，每段不超过两句话。把攻击性从人身转向具体事件，冲突才有出口。"},{"id":"SC_03","a":[{"dim":"def_intellectual","op":">=","val":60}],"b":[{"dim":"big5_compassion","op":">=","val":62},{"dim":"att_anxiety","op":">=","val":55}],"severity":"high","title":"分析者与感受者","text":"一方在解释，一方在等被接住。你们说的都不是同一种语言，因此越努力沟通，越觉得对方不在乎。","guide":"约定顺序：先有十分钟只做情绪确认（「我知道你很难受」），十分钟后再进入分析。顺序反了，再对的道理也听不进去。"},{"id":"SC_04","a":[{"dim":"def_fawn","op":">=","val":60}],"b":[{"dim":"covert_control","op":">=","val":58}],"severity":"high","title":"顺从者与操盘手","text":"一方用顺从换安全，一方用安排换掌控。表面看这段关系没有冲突，实际上所有决定都在同一侧完成，另一侧的怨在慢慢积。","guide":"每个月做一次「真话时间」：由习惯配合的一方先说需求，另一侧只允许听和复述，不允许当场解决。"},{"id":"SC_05","a":[{"dim":"big5_order","op":">=","val":65}],"b":[{"dim":"cog_ambiguity","op":">=","val":62},{"dim":"big5_order","op":"<=","val":45}],"severity":"mid","title":"计划者与即兴者","text":"一个人需要提前知道所有安排，一个人觉得那样很闷。这是日常摩擦最高频的组合，也最容易被误读成「不在乎」。","guide":"把生活分成两栏：必须提前确定的事（时间、钱、重要决定）走计划者的规则；其余时间交给即兴者安排。"},{"id":"SC_06","a":[{"dim":"val_moral","op":"<=","val":42}],"b":[{"dim":"val_moral","op":">=","val":62},{"dim":"light_kant","op":">=","val":58}],"severity":"mid","title":"底线刻度不同","text":"一方认为规则可以商量，一方认为有些事不能商量。分歧通常不发生在小事上，而是会突然在某件大事上集中爆发。","guide":"提前把各自的「绝对不可交易项」写成清单交换一次。不是为了让对方改变，而是为了让彼此知道哪里不能踩。"},{"id":"SC_07","a":[{"dim":"sin_envy","op":">=","val":58},{"dim":"mot_mastery","op":">=","val":62}],"b":[{"dim":"mot_mastery","op":">=","val":62}],"severity":"mid","title":"同一条赛道上的两个人","text":"你们都在往上走，也都在意结果。这种关系能互相推着跑得很快，但也容易在某一方更快时，悄悄长出比较与不甘。","guide":"把「谁更好」换成「我们各自的目标是什么」。定期交换进展而不是交换排名，比较才不会伤到关系。"},{"id":"SC_08","a":[{"dim":"def_detach","op":">=","val":62}],"b":[{"dim":"big5_compassion","op":">=","val":65},{"dim":"mot_belonging","op":">=","val":58}],"severity":"mid","title":"冷处理与热需求","text":"一个人难受时会先关掉，一个人难受时必须马上被接住。你们最容易在对方最难的时候，刚好错过彼此。","guide":"约定「关掉之前先说一句」：哪怕只说「我现在需要两个小时，晚点我会来找你」。这一句话能救下很多误会。"},{"id":"SC_09","a":[{"dim":"dark_mach","op":">=","val":62},{"dim":"covert_control","op":">=","val":58}],"b":[{"dim":"wv_nature","op":">=","val":62},{"dim":"light_faith","op":">=","val":60}],"severity":"high","title":"策略与坦诚的错位","text":"一方习惯先算一轮再行动，一方习惯把话直接摊开。前者觉得后者太天真，后者觉得前者不真诚。","guide":"把「我在算」和「我在瞒」分开。策略可以保留，但涉及双方利益的决定必须全部摊开讲。"},{"id":"SC_10","a":[{"dim":"big5_rumination","op":">=","val":62}],"b":[{"dim":"big5_rumination","op":">=","val":62}],"severity":"mid","title":"两台同时反刍的机器","text":"你们都会在深夜复盘同一件事，都会把对方一句无心的话反复咀嚼。误会因此被迅速放大，而没人真的去确认。","guide":"建立一条规则：任何超过二十四小时的不舒服，必须当面问一次。猜测永远比事实更伤人。"},{"id":"SC_11","a":[{"dim":"dd_order","op":"<=","val":42}],"b":[{"dim":"dd_order","op":">=","val":62}],"severity":"high","title":"一个看规则，一个看情况","text":"你们对'什么算数'的判断标准根本不同：一方要的是可预期的秩序，另一方要的是当下的合理。","guide":"不要争论谁对。先把分歧翻译成具体场景：这件事上，你希望按哪种方式走？一次只谈一件事。"},{"id":"SC_12","a":[{"dim":"hsp_sensory","op":">=","val":60}],"b":[{"dim":"hss_intensity","op":">=","val":60}],"severity":"high","title":"一个怕吵，一个嫌静","text":"同一场聚会，一方在硬扛，一方在充电。谁都没有错，但双方都会觉得对方不理解自己的感受。","guide":"约定'离场信号'：任一方可以随时说我需要出去一下，另一方不追问、不记账。"},{"id":"SC_13","a":[{"dim":"enn_4","op":">=","val":58}],"b":[{"dim":"enn_3","op":">=","val":58}],"severity":"mid","title":"要独特 vs. 要结果","text":"一方需要被看见'我是唯一的'，另一方需要被看见'我做成了'。两种认可无法互相替代。","guide":"分别告诉对方：你希望被夸的具体是哪一件事。不要用自己的标准去猜对方的需求。"},{"id":"SC_14","a":[{"dim":"tki_avoiding","op":">=","val":58}],"b":[{"dim":"tki_competing","op":">=","val":58}],"severity":"high","title":"一个要马上说清，一个要先离开","text":"冲突刚起，一方需要立刻把话讲透，另一方需要先退出场景。两个动作都会被对方读成最坏的意思。","guide":"约定暂停机制：先说'我需要二十分钟'，并明确给出回来的时间。定时比消失安全。"},{"id":"SC_15","a":[{"dim":"money_status","op":">=","val":58}],"b":[{"dim":"money_avoid","op":">=","val":58}],"severity":"mid","title":"谈钱时的两种失语","text":"一方把钱当作尊严的度量，一方一谈钱就想逃。这段关系里，钱会成为一个越来越大的沉默。","guide":"把金额与感受分开说：先说数字，再说我因此不舒服的地方。一次只说一层。"},{"id":"SC_16","a":[{"dim":"schema_approval","op":">=","val":58}],"b":[{"dim":"schema_mistrust","op":">=","val":58}],"severity":"mid","title":"一直给 vs. 一直验","text":"一方靠不断示好换取安全，一方靠不断试探确认安全。两个人会陷入一场谁也停不下来的消耗。","guide":"把'你信不信我'换成'我需要你做什么具体的事'。把抽象的安全感变成可执行的动作。"}]};

export const EXPRESS = {"id":"express","title":"初见微光","subtitle":"28 题 · 约 4 分钟 · 关系核心轴速写","intro":"这不是完整档案，只是一次快照。二十八道题，覆盖关系里最要紧的那几条轴：你怎么看世界、怎么靠人、怎么冲突、怎么花钱、被压力压到时会变成什么形状。做完你会立刻拿到一份简报和一个可以发给别人的存档码；之后想继续做完整十六卷，这二十八题不会让你重复作答。","estimated_minutes":4,"questions":["v1_q02","v2_q04","v2_q18","v3_q05","v3_q15","v4_q04","v4_q12","v5_q04","v5_q16","v6_q06","v6_q11","v7_q09","v7_q16","v8_q01","v9_q13","v10_q01","v10_q08","v11_q01","v11_q14","v12_q01","v13_q04","v13_q13","v14_q01","v14_q05","v15_q04","v15_q10","v16_q01","v16_q08"],"note":"键为原卷题目 id 的直接引用，不复制题干、不改权重。scorePool() 会按原卷归属把作答写进 answersByVolume，因此与十六卷完整模式完全互通。"};

export const DIM_ORDER = DIMENSIONS.dims.map((d) => d.id);
export const DIM_MAP = Object.fromEntries(DIMENSIONS.dims.map((d) => [d.id, d]));
